def _grad_rel_l2(
    grad_error: dict[str, dict[str, float | list[int]] | str] | None,
    name: str,
) -> float | None:
    if grad_error is None:
        return None
    entry = grad_error.get(name)
    if not isinstance(entry, dict):
        return None
    value = entry.get("rel_l2")
    if isinstance(value, (int, float)) and math.isfinite(value):
        return float(value)
    return None


def _no_global_ds_dk_candidate_guard(
    rec: dict[str, Any] | None,
    grad_error: dict[str, dict[str, float | list[int]] | str] | None,
) -> dict[str, Any]:
    threshold = _NO_GLOBAL_DS_DK_REJECT_REL_L2_THRESHOLD
    schedule = "" if rec is None else str(rec.get("schedule_status") or "")
    schedule_tokens = ("dq_dk", "key_owned", "pair", "recompute")
    no_global_ds_dk_candidate = bool(
        rec is not None
        and "no_global_ds" in schedule
        and (
            rec.get("dk_live_recompute_enabled", False)
            or rec.get("dk_recompute_fused_enabled", False)
            or any(token in schedule for token in schedule_tokens)
        )
    )
    dk_rel_l2 = _grad_rel_l2(grad_error, "dk")
    rejected = bool(
        no_global_ds_dk_candidate
        and dk_rel_l2 is not None
        and dk_rel_l2 >= threshold
    )
    reason = None
    if rejected:
        reason = (
            "no-global-dS dK candidate rejected: dK rel_l2 "
            f"{dk_rel_l2:.6g} >= {threshold:.6g}; current pair/recompute route "
            "does not provide a proven dS^T @ Q consumer"
        )
    elif no_global_ds_dk_candidate and dk_rel_l2 is None:
        reason = "no-global-dS dK candidate needs BF16 dK error validation"
    return {
        "enabled": True,
        "candidate": bool(no_global_ds_dk_candidate),
        "rejected": bool(rejected),
        "threshold": float(threshold),
        "dk_rel_l2": dk_rel_l2,
        "reason": reason,
    }


def _bf16_grad_candidate_guard(
    grad_error: dict[str, dict[str, float | list[int]] | str] | None,
) -> dict[str, Any]:
    threshold = _FULL_BACKWARD_CANDIDATE_GRAD_REL_L2_THRESHOLD
    if grad_error is None:
        return {
            "enabled": True,
            "checked": False,
            "rejected": False,
            "threshold": float(threshold),
            "rel_l2": {},
            "reason": None,
        }

    rel_l2: dict[str, float | None] = {}
    failures: list[str] = []
    for name in ("dq", "dk", "dv"):
        entry = grad_error.get(name)
        if not isinstance(entry, dict):
            rel_l2[name] = None
            failures.append(f"{name} missing BF16 comparison metrics")
            continue
        value = entry.get("rel_l2")
        if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
            rel_l2[name] = None
            failures.append(f"{name} rel_l2 is non-finite")
            continue
        value_f = float(value)
        rel_l2[name] = value_f
        if value_f > threshold:
            failures.append(f"{name} rel_l2 {value_f:.6g} > {threshold:.6g}")

    reason = None
    if failures:
        reason = "BF16 gradient comparison failed: " + "; ".join(failures)
    return {
        "enabled": True,
        "checked": True,
        "rejected": bool(failures),
        "threshold": float(threshold),
        "rel_l2": rel_l2,
        "reason": reason,
    }


def _resolve_mxfp4_fwd_launch_mode(seqlen: int, heads: int, launch_mode: str) -> str:
    if launch_mode not in ("auto", "persistent", "fullgrid"):
        raise ValueError("launch_mode must be 'auto', 'persistent', or 'fullgrid'")
    if launch_mode != "auto":
        return launch_mode
    if heads <= 4:
        if int(seqlen) >= _MXFP4_FWD_H4_FULLGRID_AUTO_MIN_SEQ:
            return "fullgrid"
        return "persistent"
    return "fullgrid" if int(seqlen) >= _MXFP4_FWD_FULLGRID_AUTO_MIN_SEQ else "persistent"


