def _select_mxfp4_fwd_config_for_shape(seqlen: int, heads: int) -> str:
    seqlen_i = int(seqlen)
    heads_i = int(heads)
    if heads_i == 1:
        return _MXFP4_P_BYPASS_MATERIALIZATION_CONFIG
    if heads_i > 1:
        if seqlen_i == 2048 and 8 <= heads_i <= 16:
            return _MXFP4_QKSCFIX_VTMA_VSTMA_CLC_FULLVSC_ONEVPUB_CONFIG
        if heads_i >= 32 and seqlen_i == 2048:
            return _MXFP4_QKSCFIX_VTMA_VSTMA_CLC_SCHEDWG4_FULLVSC_ONEVPUB_CONFIG
        if heads_i >= 32 and seqlen_i == 4096:
            return _MXFP4_QKSCFIX_VTMA_VSTMA_CLC_FULLVSC_ONEVPUB_CONFIG
        if heads_i >= 16 and seqlen_i == 4096:
            return _MXFP4_QKSCFIX_VTMA_VSTMA_CLC_SCHEDWG4_FULLVSC_ONEVPUB_CONFIG
        return _MXFP4_QKSCFIX_VTMA_VSTMA_CONFIG
    if seqlen_i >= 16384:
        return "dualaccum_directrescale_decoupled_prescaled_pstage4_q208_p96_o48"
    if seqlen_i >= 8192 and seqlen_i < 16384:
        if heads_i <= 4:
            return "dualaccum_directrescale_decoupled_prescaled_pstage4_q208_p96_o48"
        return "dualaccum_directrescale_decoupled_prescaled_pstage6_q208_p96_o48_splitk64"
    if seqlen_i >= 4096:
        if heads_i <= 4:
            return "dualaccum_directrescale_decoupled_prescaled_pstage4_q208_p96_o48"
        return "dualaccum_directrescale_decoupled_prescaled_pstage6_q208_p96_o48_splitk64"
    if seqlen_i >= 2048:
        if heads_i <= 4:
            return "dualaccum_directrescale_decoupled_prescaled_pstage4_q208_p96_o48_splitk64"
        return "dualaccum_forcespare_streamscore_q208_o72"
    if heads_i <= 4:
        return "dualaccum_directrescale_localmax_split2wg_q152_p104_o48"
    return "dualaccum_directrescale_q208_p96_o48"


def _resolve_mxfp4_fwd_config_for_run(
    seqlen: int,
    heads: int,
    requested_config: str | None,
) -> tuple[str, str | None]:
    if requested_config is not None:
        return requested_config, requested_config
    env_config = os.environ.get("TK_FA4_FP4PV_FWD_CONFIG")
    if env_config:
        return env_config, None
    selected = _select_mxfp4_fwd_config_for_shape(seqlen, heads)
    return selected, selected


def _mxfp4_fwd_config_uses_mb64(config: str | None) -> bool:
    return config is not None and "_mb64_" in config


def _prepare_mxfp4_fwd_inputs_for_config(
    fp4_inputs: tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor],
    *,
    seqlen: int,
    config: str | None,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    if not _mxfp4_fwd_config_uses_mb64(config):
        return fp4_inputs
    q, q_sc, q_sg, k, k_sc, k_sg, v_fp4, v_sc = fp4_inputs
    expected_rows_128 = int(seqlen) // _TILE
    expected_rows_64 = int(seqlen) // 64
    if q_sc.shape[1] == expected_rows_128:
        q_sc = q_sc.repeat_interleave(2, dim=1).contiguous()
    if q_sc.shape[1] != expected_rows_64:
        raise ValueError(
            f"Mb64 MXFP4 forward config expects q_sc scale rows {expected_rows_64}, got {q_sc.shape[1]}"
        )
    return q, q_sc, q_sg, k, k_sc, k_sg, v_fp4, v_sc


def _mxfp4_grouped_config_id_for(
    name: str,
    *,
    op: str | None = None,
    batch: int | None = None,
    heads: int | None = None,
    m: int | None = None,
    n: int | None = None,
    red: int | None = None,
) -> int:
    if name != "dK":
        return _MXFP4_PV_GROUPED_CONFIG_ID
    value = os.environ.get("TK_FA4_MXFP4_BWD_DK_GROUPED_CONFIG_ID")
    if value is None:
        if (
            op == "atbt"
            and batch == 1
            and heads == 16
            and m == 512
            and n == _D_QK_GEMM_PAD
            and red == 512
        ):
            return 7
        return _MXFP4_BWD_DK_GROUPED_CONFIG_ID
    try:
        config_id = int(value)
    except ValueError as exc:
        raise ValueError("TK_FA4_MXFP4_BWD_DK_GROUPED_CONFIG_ID must be an integer in [0, 7]") from exc
    if config_id < 0 or config_id > 7:
        raise ValueError("TK_FA4_MXFP4_BWD_DK_GROUPED_CONFIG_ID must be in [0, 7]")
    return config_id
