def _clear_mxfp4_bwd_producer_subbucket_profile() -> None:
    global _LAST_MXFP4_BWD_PRODUCER_SUBBUCKET_PROFILE_RAW
    _LAST_MXFP4_BWD_PRODUCER_SUBBUCKET_PROFILE_RAW = None


def _record_mxfp4_bwd_producer_subbucket_profile(
    cycles: torch.Tensor,
    counts: torch.Tensor,
) -> None:
    global _LAST_MXFP4_BWD_PRODUCER_SUBBUCKET_PROFILE_RAW
    cycles_cpu = [int(v) for v in cycles.detach().cpu().to(torch.int64).tolist()]
    counts_cpu = [int(v) for v in counts.detach().cpu().to(torch.int64).tolist()]
    bucket_count = min(
        len(_MXFP4_BWD_PRODUCER_SUBBUCKET_NAMES),
        len(cycles_cpu),
        len(counts_cpu),
    )
    cycles_by_bucket = {
        _MXFP4_BWD_PRODUCER_SUBBUCKET_NAMES[i]: cycles_cpu[i]
        for i in range(bucket_count)
    }
    counts_by_bucket = {
        _MXFP4_BWD_PRODUCER_SUBBUCKET_NAMES[i]: counts_cpu[i]
        for i in range(bucket_count)
    }
    _LAST_MXFP4_BWD_PRODUCER_SUBBUCKET_PROFILE_RAW = {
        "bucket_names": list(_MXFP4_BWD_PRODUCER_SUBBUCKET_NAMES[:bucket_count]),
        "cycles_by_bucket": cycles_by_bucket,
        "counts_by_bucket": counts_by_bucket,
        "profiled_cycle_sum_excluding_total": int(
            sum(
                value
                for name, value in cycles_by_bucket.items()
                if name != "total"
            )
        ),
        "diagnostic_only": True,
    }


def _consume_mxfp4_bwd_producer_subbucket_profile(
    component_ms: float | None,
) -> dict[str, Any] | None:
    global _LAST_MXFP4_BWD_PRODUCER_SUBBUCKET_PROFILE_RAW
    raw = _LAST_MXFP4_BWD_PRODUCER_SUBBUCKET_PROFILE_RAW
    _LAST_MXFP4_BWD_PRODUCER_SUBBUCKET_PROFILE_RAW = None
    if raw is None:
        return None
    cycles_by_bucket = dict(raw["cycles_by_bucket"])
    total_cycles = int(raw.get("profiled_cycle_sum_excluding_total", 0))
    component_ms_f = float(component_ms) if component_ms is not None else float("nan")
    normalized_ms_by_bucket: dict[str, float] = {}
    cycle_fraction_by_bucket: dict[str, float] = {}
    if total_cycles > 0 and math.isfinite(component_ms_f):
        for name, cycles in cycles_by_bucket.items():
            if name == "total":
                continue
            fraction = float(cycles) / float(total_cycles)
            cycle_fraction_by_bucket[name] = fraction
            normalized_ms_by_bucket[name] = component_ms_f * fraction
    ranked_subbuckets = [
        {
            "bucket": name,
            "cycles": int(cycles_by_bucket.get(name, 0)),
            "counts": int(raw["counts_by_bucket"].get(name, 0)),
            "cycle_fraction": float(cycle_fraction_by_bucket.get(name, 0.0)),
            "normalized_ms": float(normalized_ms_by_bucket.get(name, float("nan"))),
        }
        for name in _MXFP4_BWD_PRODUCER_SUBBUCKET_NAMES
        if name != "total"
    ]
    ranked_subbuckets.sort(
        key=lambda item: (
            -1.0 if math.isnan(item["normalized_ms"]) else -item["normalized_ms"],
            -item["cycles"],
        )
    )
    return {
        **raw,
        "component_ms_reference": component_ms_f,
        "normalization_method": (
            "Kernel clock64 cycle sums are accumulated over elected producer lanes and CTAs, "
            "so they are used for sub-bucket ranking and normalized to the measured "
            "dq_ds_col_live_dp component wall time rather than interpreted as wall-clock time."
        ),
        "normalized_ms_by_bucket": normalized_ms_by_bucket,
        "cycle_fraction_by_bucket": cycle_fraction_by_bucket,
        "ranked_subbuckets": ranked_subbuckets,
    }


