def list_qkv_distribution_presets() -> tuple[str, ...]:
    return _QKV_DISTRIBUTION_PRESETS


def _resolve_qkv_distributions(
    *,
    distribution: str = "gaussian",
    q_distribution: str | None = None,
    k_distribution: str | None = None,
    v_distribution: str | None = None,
) -> tuple[str, str, str]:
    base = distribution
    _check_choice("distribution", base, _QKV_DISTRIBUTION_PRESETS)
    q_dist = base if q_distribution is None else q_distribution
    k_dist = base if k_distribution is None else k_distribution
    v_dist = base if v_distribution is None else v_distribution
    _check_choice("q_distribution", q_dist, _QKV_DISTRIBUTION_PRESETS)
    _check_choice("k_distribution", k_dist, _QKV_DISTRIBUTION_PRESETS)
    _check_choice("v_distribution", v_dist, _QKV_DISTRIBUTION_PRESETS)
    return q_dist, k_dist, v_dist


def _sample_cpu_distribution(
    shape: tuple[int, ...],
    *,
    gen: torch.Generator,
    distribution: str,
) -> torch.Tensor:
    _check_choice("distribution", distribution, _QKV_DISTRIBUTION_PRESETS)
    tiny = torch.finfo(torch.float32).tiny
    eps = torch.finfo(torch.float32).eps
    if distribution == "gaussian":
        x = torch.randn(shape, generator=gen, dtype=torch.float32)
    elif distribution == "uniform":
        x = (torch.rand(shape, generator=gen, dtype=torch.float32) * 2.0 - 1.0) * math.sqrt(3.0)
    elif distribution == "laplace":
        u = torch.rand(shape, generator=gen, dtype=torch.float32).clamp_(eps, 1.0 - eps)
        centered = u - 0.5
        x = -torch.sign(centered) * torch.log1p(-2.0 * centered.abs())
        x = x / math.sqrt(2.0)
    elif distribution == "student_t3":
        z = torch.randn(shape, generator=gen, dtype=torch.float32)
        chi2 = torch.randn((*shape, 3), generator=gen, dtype=torch.float32).square().sum(dim=-1)
        x = z / torch.sqrt((chi2 / 3.0).clamp_min(tiny))
        x = x / math.sqrt(3.0)
    elif distribution == "student_t5":
        z = torch.randn(shape, generator=gen, dtype=torch.float32)
        chi2 = torch.randn((*shape, 5), generator=gen, dtype=torch.float32).square().sum(dim=-1)
        x = z / torch.sqrt((chi2 / 5.0).clamp_min(tiny))
        x = x / math.sqrt(5.0 / 3.0)
    elif distribution == "signed_lognormal":
        z = torch.randn(shape, generator=gen, dtype=torch.float32)
        signs = torch.where(
            torch.rand(shape, generator=gen, dtype=torch.float32) < 0.5,
            -torch.ones_like(z),
            torch.ones_like(z),
        )
        x = signs * torch.exp((0.9 * z).clamp(min=-80.0, max=80.0))
    elif distribution == "gaussian_spikes":
        x = torch.randn(shape, generator=gen, dtype=torch.float32)
        spike_mask = torch.rand(shape, generator=gen, dtype=torch.float32) < 0.01
        spike_vals = torch.randn(shape, generator=gen, dtype=torch.float32) * 12.0
        x = torch.where(spike_mask, spike_vals, x)
    else:  # pragma: no cover - guarded above
        raise ValueError(f"unsupported distribution {distribution!r}")
    x = torch.nan_to_num(x, nan=0.0, posinf=0.0, neginf=0.0)
    rms = x.square().mean().sqrt()
    if float(rms.item()) > 0.0 and math.isfinite(float(rms.item())):
        x = x / rms
    return x


def _prepend_sys_path(path: Path) -> None:
    path_str = str(path)
    if path_str not in sys.path:
        sys.path.insert(0, path_str)


def _load_experiments_ext():
    try:
        from . import _C_b300_causal_fp4_experiments
    except ImportError:
        _prepend_sys_path(_ROOT.parent)
        _prepend_sys_path(_ROOT)
        for mod_name in ("tk_fa4._C_b300_causal_fp4_experiments", "_C_b300_causal_fp4_experiments"):
            try:
                return importlib.import_module(mod_name)
            except ImportError:
                pass
        raise ImportError(
            f"tk_fa4 FP4 PV experiments extension is not built. Run `make -C {_ROOT / 'b300_causal_fp4_experiments'}`."
        )
    except Exception as exc:  # pragma: no cover - surfaced when called without the build artifact.
        raise ImportError(
            f"tk_fa4 FP4 PV experiments extension is not built. Run `make -C {_ROOT / 'b300_causal_fp4_experiments'}`."
        ) from exc
    return _C_b300_causal_fp4_experiments


