def _loaded_extension_identity(ext: Any) -> dict[str, Any]:
    path_raw = getattr(ext, "__file__", None)
    path = None if path_raw is None else Path(path_raw)
    identity: dict[str, Any] = {
        "file": None if path is None else str(path.resolve()),
        "mtime_ns": None,
        "size": None,
        "sha256_prefix": None,
    }
    if path is None:
        return identity
    stat = path.stat()
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    identity.update(
        {
            "mtime_ns": int(stat.st_mtime_ns),
            "size": int(stat.st_size),
            "sha256_prefix": h.hexdigest()[:16],
        }
    )
    return identity


