def _load_tk_mxfp4_gemm():
    global _TK_MXFP4_GEMM_MODULE, _TK_MXFP4_GEMM_MODULE_PATH
    if _TK_MXFP4_GEMM_MODULE is not None:
        return _TK_MXFP4_GEMM_MODULE
    candidates = sorted(
        _TK_MXFP4_GEMM_ROOT.glob("_C_mx*.so"),
        key=lambda p: (p.name.startswith("_C_mx_cce"), p.name),
    )
    if not candidates:
        raise ImportError(
            f"Could not find TK MXFP4 GEMM extension under {_TK_MXFP4_GEMM_ROOT}. "
            f"Run `make -C {_TK_MXFP4_GEMM_ROOT}`."
        )
    torch_lib = Path(torch.__file__).resolve().parent / "lib" / "libtorch_python.so"
    ctypes.CDLL(str(torch_lib), mode=ctypes.RTLD_GLOBAL)
    module_name = "_C_mx"
    old_mod = sys.modules.pop(module_name, None)
    try:
        spec = importlib.util.spec_from_file_location(module_name, candidates[0])
        if spec is None or spec.loader is None:
            raise ImportError(f"Could not load TK MXFP4 GEMM extension from {candidates[0]}")
        module = importlib.util.module_from_spec(spec)
        sys.modules[module_name] = module
        spec.loader.exec_module(module)
        _TK_MXFP4_GEMM_MODULE = module
        _TK_MXFP4_GEMM_MODULE_PATH = candidates[0]
        return module
    finally:
        sys.modules.pop(module_name, None)
        if old_mod is not None:
            sys.modules[module_name] = old_mod


def _tk_mxfp4_grouped_gemm_supports_k_offset() -> bool:
    gemm = _load_tk_mxfp4_gemm()
    fn = getattr(gemm, "mxfp4_grouped_gemm_strided", None)
    return "b_k_offset" in str(getattr(fn, "__doc__", ""))


def _mxfp4_grouped_dv_default_chunk_cols(seqlen: int, num_gemms: int) -> int:
    cap = _MXFP4_GROUPED_DV_CHUNK_COLS if int(num_gemms) <= 2 else 8192
    return min(int(seqlen), cap)


def _load_localcta_gemm():
    _prepend_sys_path(_LOCALCTA_GEMM_ROOT)
    return importlib.import_module("_C_nv_localcta_gemm")


def _load_nvfp4_utils():
    candidates = sorted(_NVFP4_UTILS_ROOT.glob("_C*.so"))
    if not candidates:
        raise ImportError(f"Could not find NVFP4 utils extension under {_NVFP4_UTILS_ROOT}")
    module_name = candidates[0].stem.split(".", 1)[0]
    if module_name in sys.modules:
        return sys.modules[module_name]
    spec = importlib.util.spec_from_file_location(module_name, candidates[0])
    if spec is None or spec.loader is None:
        raise ImportError(f"Could not load NVFP4 utils extension from {candidates[0]}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[module_name] = module
    spec.loader.exec_module(module)
    return module


def _load_nvfp4_legacy_gemm():
    return _load_nvfp4_utils()


def _check_cuda_contiguous(x: torch.Tensor, name: str) -> None:
    if not x.is_cuda:
        raise ValueError(f"{name} must be a CUDA tensor")
    if not x.is_contiguous():
        raise ValueError(f"{name} must be contiguous")


def _require_finite_tensor(x: torch.Tensor, name: str) -> None:
    if (x.is_floating_point() or x.is_complex()) and bool((~torch.isfinite(x)).any().item()):
        raise ValueError(f"{name} must contain only finite values")


def _check_fp4_attention_inputs(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    *,
    q_scale_tile: int = _TILE,
) -> tuple[int, int, int]:
    for name, tensor in (
        ("q", q),
        ("q_sc", q_sc),
        ("q_sg", q_sg),
        ("k", k),
        ("k_sc", k_sc),
        ("k_sg", k_sg),
    ):
        _check_cuda_contiguous(tensor, name)

    if q.dtype != torch.float4_e2m1fn_x2:
        raise ValueError("q must have dtype torch.float4_e2m1fn_x2")
    if k.dtype != torch.float4_e2m1fn_x2:
        raise ValueError("k must have dtype torch.float4_e2m1fn_x2")
    if q_sc.dtype != torch.float8_e4m3fn:
        raise ValueError("q_sc must have dtype torch.float8_e4m3fn")
    if k_sc.dtype != torch.float8_e4m3fn:
        raise ValueError("k_sc must have dtype torch.float8_e4m3fn")
    if q_sg.dtype != torch.float32:
        raise ValueError("q_sg must have dtype torch.float32")
    if k_sg.dtype != torch.float32:
        raise ValueError("k_sg must have dtype torch.float32")
    if q.ndim != 4 or k.ndim != 4:
        raise ValueError("q and k must have shape (batch, heads, seqlen, packed_dim)")
    if q.shape != k.shape:
        raise ValueError("q and k must have identical shapes")

    batch, heads, seqlen, packed_dim = q.shape
    if packed_dim != _Q_PACKED_DIM:
        raise ValueError(f"q/k packed dim must be {_Q_PACKED_DIM}")
    if seqlen % _TILE != 0:
        raise ValueError("sequence length must be divisible by 128")
    if q_scale_tile not in (64, _TILE):
        raise ValueError("q_scale_tile must be 64 or 128")
    if q_sc.shape != (batch, seqlen // q_scale_tile, heads * (_D_QK // 64), 512):
        raise ValueError(
            f"q_sc must have shape {(batch, seqlen // q_scale_tile, heads * (_D_QK // 64), 512)}"
        )
    if k_sc.shape != (batch, seqlen // 64, heads * (_D_QK // 64), 512):
        raise ValueError(
            f"k_sc must have shape {(batch, seqlen // 64, heads * (_D_QK // 64), 512)}"
        )
    if q_sg.shape != (batch, heads):
        raise ValueError(f"q_sg must have shape {(batch, heads)}")
    if k_sg.shape != (batch, heads):
        raise ValueError(f"k_sg must have shape {(batch, heads)}")
    return batch, heads, seqlen


def _check_prequantized_v(v_fp4: torch.Tensor, v_sc_prepared: torch.Tensor, batch: int, heads: int, seqlen: int) -> None:
    _check_cuda_contiguous(v_fp4, "v_fp4")
    _check_cuda_contiguous(v_sc_prepared, "v_sc_prepared")
    if v_fp4.dtype != torch.float4_e2m1fn_x2:
        raise ValueError("v_fp4 must have dtype torch.float4_e2m1fn_x2")
    if v_sc_prepared.dtype != torch.float8_e4m3fn:
        raise ValueError("v_sc_prepared must have dtype torch.float8_e4m3fn")
    if v_fp4.ndim != 4 or v_sc_prepared.ndim != 5:
        raise ValueError("v_fp4/v_sc_prepared must have shapes (B,H,Dvo,K/2) and (B,H,Dvo/128,K/64,512)")
    if v_fp4.size(0) != batch or v_fp4.size(1) != heads or v_fp4.size(3) != seqlen // 2:
        raise ValueError(f"v_fp4 must have shape (batch={batch}, heads={heads}, dvo, packed_seqlen={seqlen // 2})")
    dvo = v_fp4.size(2)
    if dvo % _TILE != 0:
        raise ValueError("v_fp4 head dim must be divisible by 128")
    if v_sc_prepared.shape != (batch, heads, dvo // 128, seqlen // 64, 512):
        raise ValueError(f"v_sc_prepared must have shape {(batch, heads, dvo // 128, seqlen // 64, 512)}")


def _streaming_num_blocks(seqlen: int) -> int:
    tiles_m = seqlen // _TILE
    tiles_per_cluster = 2  # NUM_SOFTMAXXERS=1, CLUSTER_SIZE=2 for the B300 FP4PV path.
    return (tiles_m + tiles_per_cluster - 1) // tiles_per_cluster


def _streaming_total_bids(batch: int, heads: int, seqlen: int) -> int:
    return batch * heads * _streaming_num_blocks(seqlen) * 2


def _resolve_streaming_live_dv_launch_mode(mode: str, batch: int, heads: int, seqlen: int) -> str:
    if mode not in ("auto", "persistent", "fullgrid"):
        raise ValueError("launch_mode must be 'auto', 'persistent', or 'fullgrid'")
    total_bids = _streaming_total_bids(batch, heads, seqlen)
    if mode == "fullgrid":
        return "fullgrid"
    if mode == "persistent" and total_bids <= _FP4PV_PERSISTENT_GRID_CAP:
        return "persistent"
    if mode == "persistent":
        return "fullgrid"
    return "persistent" if total_bids <= _FP4PV_PERSISTENT_GRID_CAP else "fullgrid"


def _streaming_fullgrid_max_bids(seqlen: int) -> int:
    if seqlen <= _STREAMING_FULLGRID_MAX_BIDS_BOOSTED_MAX_SEQ:
        return _STREAMING_FULLGRID_MAX_BIDS_BOOSTED
    return _STREAMING_FULLGRID_MAX_BIDS


def _streaming_head_chunk_size(batch: int, heads: int, seqlen: int) -> int:
    bids_per_head = _streaming_total_bids(batch, 1, seqlen)
    max_bids = _streaming_fullgrid_max_bids(seqlen)
    max_heads = max(1, max_bids // max(bids_per_head, 1))
    return min(heads, max_heads)


def _mxfp4_dv_fullgrid_head_chunk_size(batch: int, heads: int, seqlen: int) -> int:
    head_chunk_size = _streaming_head_chunk_size(batch, heads, seqlen)
    if seqlen >= _MXFP4_DV_VERY_LONG_FULLGRID_CHUNK_SEQ:
        return min(head_chunk_size, _MXFP4_DV_VERY_LONG_FULLGRID_HEAD_CHUNK_SIZE)
    return head_chunk_size


def _resolve_mxfp4_dv_production_rewrite_mode(seqlen: int) -> int:
    if seqlen <= 1024:
        return 128
    if seqlen <= 2048:
        return 128
    if seqlen <= 4096:
        return 390
    if seqlen <= 8192:
        return 393
    if seqlen <= 16384:
        return 247
    return 247


def _resolve_mxfp4_dv_structural_fused_mode(seqlen: int) -> int:
    """Measured structural candidates that reduce P feed overhead where viable.

    Keep this separate from production auto routing. These modes are useful for
    the softmax-to-PV rewrite work, but are not uniformly faster yet.
    """
    if seqlen <= 1024:
        return 128
    if seqlen <= 2048:
        return 128
    if seqlen <= 4096:
        return 390
    if seqlen <= 8192:
        return 393
    if seqlen <= 16384:
        return 247
    return 247


def _mxfp4_dv_pv_issue_plan_name(pv_issue_mode: int | str | None) -> str:
    if pv_issue_mode is None:
        return "production"
    if isinstance(pv_issue_mode, str):
        key = pv_issue_mode.lower()
        if key in ("auto", "production"):
            return "production"
        if key in ("fused", "structural"):
            return "structural_fused_experimental"
        if key == "rewrite":
            return "legacy_hardcoded_rewrite"
        return key
    mode = int(pv_issue_mode)
    return "production" if mode == 0 else "explicit"


def _is_streaming_localcta_variant(variant: str) -> bool:
    return variant in _STREAMING_LIVE_VARIANTS


def _streaming_persistent_head_chunk_size(batch: int, heads: int, seqlen: int) -> int:
    bids_per_head = _streaming_total_bids(batch, 1, seqlen)
    max_heads = max(1, _FP4PV_PERSISTENT_GRID_CAP // max(bids_per_head, 1))
    return min(heads, max_heads)


def _streaming_variant_launch_plan(
    *,
    batch: int,
    heads: int,
    seqlen: int,
    variant: str,
    launch_mode: str,
) -> dict[str, Any]:
    requested_launch_mode = launch_mode
    effective_launch_mode = launch_mode
    total_bids = _streaming_total_bids(batch, heads, seqlen)
    persistent_cap_limited = bool(total_bids > _FP4PV_PERSISTENT_GRID_CAP)
    head_chunk_size = heads
    max_bids_cap: int | None = None
    launch_fallback_reason: str | None = None

    if launch_mode == "fullgrid":
        head_chunk_size = _streaming_head_chunk_size(batch, heads, seqlen)
        max_bids_cap = _streaming_fullgrid_max_bids(seqlen)
    elif (
        variant == "qk_pv_nvfp4_production"
        and seqlen >= _FP4PV_FULLGRID_SEQ_THRESHOLD
    ):
        effective_launch_mode = "fullgrid"
        head_chunk_size = _streaming_head_chunk_size(batch, heads, seqlen)
        max_bids_cap = _streaming_fullgrid_max_bids(seqlen)
        launch_fallback_reason = "production_kernel_uses_fullgrid_seq_threshold"
    elif _is_streaming_localcta_variant(variant) and persistent_cap_limited:
        head_chunk_size = _streaming_persistent_head_chunk_size(batch, heads, seqlen)
        max_bids_cap = _FP4PV_PERSISTENT_GRID_CAP
        if _streaming_total_bids(batch, head_chunk_size, seqlen) > _FP4PV_PERSISTENT_GRID_CAP:
            effective_launch_mode = "fullgrid"
            head_chunk_size = _streaming_head_chunk_size(batch, heads, seqlen)
            max_bids_cap = _streaming_fullgrid_max_bids(seqlen)
            launch_fallback_reason = "persistent_localcta_bids_per_head_exceeds_grid_cap"

    head_chunks = (heads + head_chunk_size - 1) // head_chunk_size
    bids_per_launch = _streaming_total_bids(batch, head_chunk_size, seqlen)
    if requested_launch_mode == "persistent":
        if effective_launch_mode == "fullgrid":
            launch_execution_mode = "persistent_fallback_fullgrid"
        elif head_chunks > 1:
            launch_execution_mode = "persistent_chunked"
        else:
            launch_execution_mode = "persistent_single_launch"
    else:
        launch_execution_mode = "fullgrid_chunked" if head_chunks > 1 else "fullgrid_single_launch"
    return {
        "requested_launch_mode": requested_launch_mode,
        "effective_launch_mode": effective_launch_mode,
        "launch_execution_mode": launch_execution_mode,
        "head_chunk_size": int(head_chunk_size),
        "head_chunks": int(head_chunks),
        "max_bids_cap": int(max_bids_cap) if max_bids_cap is not None else None,
        "total_bids": int(total_bids),
        "bids_per_launch": int(bids_per_launch),
        "persistent_cap_limited": persistent_cap_limited,
        "launch_fallback_reason": launch_fallback_reason,
    }


def _slice_fp4_attention_inputs_by_head(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
    *,
    head_start: int,
    head_end: int,
) -> tuple[torch.Tensor, ...]:
    scale_chunks_per_head = _D_QK // 64
    sc_start = head_start * scale_chunks_per_head
    sc_end = head_end * scale_chunks_per_head
    return (
        q[:, head_start:head_end].contiguous(),
        q_sc[:, :, sc_start:sc_end, :].contiguous(),
        q_sg[:, head_start:head_end].contiguous(),
        k[:, head_start:head_end].contiguous(),
        k_sc[:, :, sc_start:sc_end, :].contiguous(),
        k_sg[:, head_start:head_end].contiguous(),
        v_fp4[:, head_start:head_end].contiguous(),
        v_sc_prepared[:, head_start:head_end].contiguous(),
    )


def _slice_fp4_qk_inputs_by_head(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    *,
    head_start: int,
    head_end: int,
) -> tuple[torch.Tensor, ...]:
    scale_chunks_per_head = _D_QK // 64
    sc_start = head_start * scale_chunks_per_head
    sc_end = head_end * scale_chunks_per_head
    return (
        q[:, head_start:head_end].contiguous(),
        q_sc[:, :, sc_start:sc_end, :].contiguous(),
        q_sg[:, head_start:head_end].contiguous(),
        k[:, head_start:head_end].contiguous(),
        k_sc[:, :, sc_start:sc_end, :].contiguous(),
        k_sg[:, head_start:head_end].contiguous(),
    )


def _check_bf16_sandbox_qkv(
    q_bf16: torch.Tensor,
    k_bf16: torch.Tensor,
    v_bf16: torch.Tensor,
) -> tuple[int, int, int, int, int]:
    for name, tensor in (("q_bf16", q_bf16), ("k_bf16", k_bf16), ("v_bf16", v_bf16)):
        _check_cuda_contiguous(tensor.contiguous(), name)
        if tensor.ndim != 4:
            raise ValueError(f"{name} must have shape (batch, seqlen, heads, dim)")
        if not tensor.dtype.is_floating_point:
            raise ValueError(f"{name} must have a floating dtype")
    if q_bf16.device != k_bf16.device or q_bf16.device != v_bf16.device:
        raise ValueError("q_bf16, k_bf16, and v_bf16 must be on the same device")

    batch, seqlen, heads, d_qk = q_bf16.shape
    if k_bf16.shape != (batch, seqlen, heads, d_qk):
        raise ValueError(f"k_bf16 must have shape {(batch, seqlen, heads, d_qk)}")
    if v_bf16.shape[:3] != (batch, seqlen, heads):
        raise ValueError(f"v_bf16 must have shape {(batch, seqlen, heads, 'd_vo')}")
    return batch, seqlen, heads, d_qk, v_bf16.shape[3]


def _check_stored_p(p_bf16: torch.Tensor) -> tuple[int, int, int]:
    _check_cuda_contiguous(p_bf16, "p_bf16")
    if p_bf16.dtype != torch.bfloat16:
        raise ValueError("p_bf16 must have dtype torch.bfloat16")
    if p_bf16.ndim != 4:
        raise ValueError("p_bf16 must have shape (batch, heads, seqlen_q, seqlen_k)")
    batch, heads, rows, cols = p_bf16.shape
    if rows != cols:
        raise ValueError("only square stored-P tensors are supported in this sidecar")
    if rows % _TILE != 0:
        raise ValueError("stored P sequence length must be divisible by 128")
    return batch, heads, rows


def _next_multiple(value: int, multiple: int) -> int:
    if multiple <= 0:
        raise ValueError("multiple must be positive")
    return ((value + multiple - 1) // multiple) * multiple


def _first_cuda_device(obj: Any) -> torch.device | None:
    if isinstance(obj, torch.Tensor):
        return obj.device if obj.is_cuda else None
    if isinstance(obj, dict):
        for value in obj.values():
            device = _first_cuda_device(value)
            if device is not None:
                return device
        return None
    if isinstance(obj, (tuple, list)):
        for value in obj:
            device = _first_cuda_device(value)
            if device is not None:
                return device
        return None
    return None


def _cuda_device_ctx(device: torch.device):
    if device.type != "cuda" or device.index is None:
        return nullcontext()
    if torch.cuda.current_device() == device.index:
        return nullcontext()
    return torch.cuda.device(device)


def _normalize_cuda_device(device: str | torch.device) -> torch.device:
    resolved = torch.device(device)
    if resolved.type != "cuda":
        return resolved
    if resolved.index is not None:
        return resolved
    return torch.device("cuda", torch.cuda.current_device())


def _benchmark_cuda_preflight(
    device: str | torch.device,
    *,
    what: str,
    timeout_ms: float | None = _CUDA_EVENT_TIMEOUT_MS,
) -> torch.device:
    resolved = _normalize_cuda_device(device)
    if resolved.type != "cuda":
        raise ValueError(f"{what} requires a CUDA device, got {resolved}")
    last_exc: Exception | None = None
    wait_timeout_ms = _CUDA_EVENT_TIMEOUT_MS if timeout_ms is None else float(timeout_ms)
    for attempt in range(3):
        try:
            # Avoid entering torch.cuda.device(...) here: on this runtime, that
            # context manager intermittently trips CUDA init error 304 even when a
            # direct allocation on the same explicit device succeeds.
            probe = torch.empty((1,), dtype=torch.float32, device=resolved)
            del probe
            _wait_for_current_stream(resolved, timeout_ms=wait_timeout_ms, what=f"{what} preflight")
            return resolved
        except Exception as exc:
            last_exc = exc
            if attempt == 2:
                break
            time.sleep(0.25)
    raise RuntimeError(f"CUDA preflight failed for {what} on {resolved}: {last_exc}") from last_exc


def _benchmark_cuda_preflight_with_fallback(
    device: str | torch.device,
    *,
    what: str,
    fallback_devices: tuple[str | torch.device, ...] = ("cuda:1", "cuda:2", "cuda:3"),
    timeout_ms: float | None = _CUDA_EVENT_TIMEOUT_MS,
) -> torch.device:
    tried: list[tuple[torch.device, Exception]] = []
    seen: set[tuple[str, int | None]] = set()
    candidates = (device, *fallback_devices)
    for candidate in candidates:
        resolved = _normalize_cuda_device(candidate)
        key = (resolved.type, resolved.index)
        if key in seen:
            continue
        seen.add(key)
        try:
            return _benchmark_cuda_preflight(resolved, what=what, timeout_ms=timeout_ms)
        except Exception as exc:
            tried.append((resolved, exc))
    tried_msg = "; ".join(f"{dev}: {exc}" for dev, exc in tried)
    raise RuntimeError(f"CUDA preflight failed for {what} on all candidates: {tried_msg}")


_MXFP4_BWD_OVERLAP_STREAMS: dict[int, torch.cuda.Stream] = {}
_MXFP4_BWD_HEAD_STREAMS: dict[int, list[torch.cuda.Stream]] = {}


def _mxfp4_bwd_overlap_stream(device: torch.device) -> torch.cuda.Stream:
    resolved = _normalize_cuda_device(device)
    if resolved.type != "cuda":
        raise ValueError(f"MXFP4 backward overlap stream requires CUDA, got {resolved}")
    index = torch.cuda.current_device() if resolved.index is None else int(resolved.index)
    stream = _MXFP4_BWD_OVERLAP_STREAMS.get(index)
    if stream is None:
        with _cuda_device_ctx(torch.device("cuda", index)):
            stream = torch.cuda.Stream(device=torch.device("cuda", index))
        _MXFP4_BWD_OVERLAP_STREAMS[index] = stream
    return stream


def _mxfp4_bwd_head_streams(device: torch.device, count: int) -> list[torch.cuda.Stream]:
    resolved = _normalize_cuda_device(device)
    if resolved.type != "cuda":
        raise ValueError(f"MXFP4 backward head streams require CUDA, got {resolved}")
    index = torch.cuda.current_device() if resolved.index is None else int(resolved.index)
    streams = _MXFP4_BWD_HEAD_STREAMS.get(index)
    if streams is None:
        streams = []
        _MXFP4_BWD_HEAD_STREAMS[index] = streams
    if len(streams) < count:
        with _cuda_device_ctx(torch.device("cuda", index)):
            streams.extend(torch.cuda.Stream(device=torch.device("cuda", index)) for _ in range(count - len(streams)))
    return streams[:count]


def _run_with_ms(fn, *args, timeout_ms: float | None = None, **kwargs):
    device = _first_cuda_device(args)
    if device is None:
        device = _first_cuda_device(kwargs)
    start = torch.cuda.Event(enable_timing=True)
    end = torch.cuda.Event(enable_timing=True)
    stream = torch.cuda.current_stream(device=device) if device is not None else None
    start.record(stream)
    out = fn(*args, **kwargs)
    end.record(stream)
    _wait_for_event(
        end,
        timeout_ms=_CUDA_EVENT_TIMEOUT_MS if timeout_ms is None else float(timeout_ms),
        what=f"{getattr(fn, '__name__', 'cuda_op')} timing",
    )
    return out, float(start.elapsed_time(end))


def _run_cuda_graph_replay_with_ms(
    fn,
    *,
    device: torch.device,
    warmup: int,
    iters: int,
    timeout_ms: float | None = None,
):
    if warmup < 0:
        raise ValueError("warmup must be >= 0")
    if iters < 1:
        raise ValueError("iters must be >= 1")
    timeout = _CUDA_EVENT_TIMEOUT_MS if timeout_ms is None else float(timeout_ms)
    stream = torch.cuda.current_stream(device=device)
    for _ in range(warmup):
        fn()
    _wait_for_current_stream(device, timeout_ms=timeout, what=f"{getattr(fn, '__name__', 'cuda_op')} graph warmup")

    graph = torch.cuda.CUDAGraph()
    with torch.cuda.graph(graph):
        out = fn()
    for _ in range(warmup):
        graph.replay()
    _wait_for_current_stream(device, timeout_ms=timeout, what=f"{getattr(fn, '__name__', 'cuda_op')} graph replay warmup")

    samples: list[float] = []
    for _ in range(iters):
        start = torch.cuda.Event(enable_timing=True)
        end = torch.cuda.Event(enable_timing=True)
        start.record(stream)
        graph.replay()
        end.record(stream)
        _wait_for_event(end, timeout_ms=timeout, what=f"{getattr(fn, '__name__', 'cuda_op')} graph replay timing")
        samples.append(float(start.elapsed_time(end)))
    return out, samples


def _run_with_host_ms(fn, *args, **kwargs):
    kwargs.pop("timeout_ms", None)
    device = _first_cuda_device(args)
    if device is None:
        device = _first_cuda_device(kwargs)
    if device is not None:
        torch.cuda.synchronize(device=device)
    start = time.perf_counter()
    out = fn(*args, **kwargs)
    if device is not None:
        torch.cuda.synchronize(device=device)
    return out, float((time.perf_counter() - start) * 1000.0)


def _wait_for_event(event: torch.cuda.Event, *, timeout_ms: float, what: str) -> None:
    deadline = time.monotonic() + max(timeout_ms, 0.0) / 1000.0
    while not event.query():
        if time.monotonic() >= deadline:
            raise TimeoutError(f"Timed out while waiting for {what} to complete after {timeout_ms:.0f} ms")
        time.sleep(_CUDA_EVENT_POLL_SLEEP_S)


def _wait_for_current_stream(
    device: torch.device,
    *,
    timeout_ms: float,
    what: str,
) -> None:
    event = torch.cuda.Event()
    stream = torch.cuda.current_stream(device=device)
    event.record(stream)
    _wait_for_event(event, timeout_ms=timeout_ms, what=what)


def _fp4pv_l2_swizzle(seqlen: int) -> int:
    size_one_head = seqlen * (_D_QK + _D_VO) * 2
    size_l2 = 50 * 1024 * 1024
    if size_l2 < size_one_head:
        return 1
    return 1 << ((size_l2 // size_one_head).bit_length() - 1)


def _validate_live_kernel_range(seqlen: int, *, allow_unsafe_live: bool) -> None:
    if allow_unsafe_live:
        return
    if seqlen <= _LIVE_KERNEL_MAX_STABLE_SEQLEN:
        return
    swizzle = _fp4pv_l2_swizzle(seqlen)
    raise ValueError(
        "live_kernel mode is currently only treated as stable up to "
        f"seqlen={_LIVE_KERNEL_MAX_STABLE_SEQLEN}. "
        f"Observed issues beyond that include data-dependent NaNs at seqlen=2560 and hangs at seqlen>=2688 "
        f"(current estimated L2 swizzle={swizzle}). "
        "Pass allow_unsafe_live=True if you want to probe that regime intentionally."
    )


def _validate_live_quant_dump_range(seqlen: int, *, allow_unsafe_live: bool) -> None:
    if allow_unsafe_live:
        return
    if seqlen <= _LIVE_QUANT_DUMP_MAX_STABLE_SEQLEN:
        return
    raise ValueError(
        "dump_live_quant_p_from_scores is currently only treated as stable up to "
        f"seqlen={_LIVE_QUANT_DUMP_MAX_STABLE_SEQLEN}. "
        "Current observed behavior is healthy again at seqlen=512 after the dump-consumer fixes, but "
        "the raw dump kernel still stalls for larger probes such as seqlen=1024 and seqlen=2048. "
        "Pass allow_unsafe_live=True if you want to probe that regime intentionally."
    )


def _require_live_quant_dump_pv_enabled() -> None:
    if not _LIVE_QUANT_DUMP_PV_ENABLED:
        raise RuntimeError(_LIVE_QUANT_DUMP_PV_DISABLE_REASON)


def _require_streaming_live_localcta_enabled() -> None:
    if not _STREAMING_LIVE_LOCALCTA_ENABLED:
        raise RuntimeError(_STREAMING_LIVE_LOCALCTA_DISABLE_REASON)


def _unit_sg_chunks(rows: int, cols: int, device: torch.device) -> torch.Tensor:
    key = (device.index if device.index is not None else -1, rows, cols)
    cached = _UNIT_SG_CACHE.get(key)
    if cached is None or cached.device != device:
        cached = torch.ones((rows // 128, cols // 128), dtype=torch.float32, device=device)
        _UNIT_SG_CACHE[key] = cached
    return cached


def _contiguous_fp4_lastdim_slice(x: torch.Tensor, start: int, length: int) -> torch.Tensor:
    if x.dtype != torch.float4_e2m1fn_x2:
        raise ValueError("expected float4_e2m1fn_x2 tensor")
    return x.view(torch.uint8).narrow(x.ndim - 1, start, length).contiguous().view(torch.float4_e2m1fn_x2)


def _contiguous_fp4_row_slice(x: torch.Tensor, start: int, length: int) -> torch.Tensor:
    if x.dtype != torch.float4_e2m1fn_x2:
        raise ValueError("expected float4_e2m1fn_x2 tensor")
    return x.view(torch.uint8).narrow(0, start, length).contiguous().view(torch.float4_e2m1fn_x2)


def _make_identity_value_probe(batch: int, seqlen: int, heads: int, device: torch.device) -> tuple[torch.Tensor, torch.Tensor]:
    probe = torch.zeros((batch, seqlen, heads, _D_VO), dtype=torch.bfloat16, device=device)
    eye = torch.eye(_D_VO, dtype=torch.bfloat16, device=device).view(1, _D_VO, 1, _D_VO)
    return probe, eye


def _zeros_fp4(shape: tuple[int, ...], device: torch.device) -> torch.Tensor:
    return torch.zeros(shape, device=device, dtype=torch.uint8).view(torch.float4_e2m1fn_x2)


def _copy_fp4_tensor_(dst: torch.Tensor, src: torch.Tensor) -> None:
    if dst.dtype != torch.float4_e2m1fn_x2:
        raise ValueError("_copy_fp4_tensor_ expects a float4_e2m1fn_x2 destination tensor")
    if src.dtype == torch.float4_e2m1fn_x2:
        src_u8 = src.view(torch.uint8)
    elif src.dtype == torch.uint8:
        src_u8 = src
    else:
        raise ValueError("_copy_fp4_tensor_ expects a float4_e2m1fn_x2 or uint8 source tensor")
    dst.view(torch.uint8).copy_(src_u8)


def _apply_scalar_sg_to_prepared_scales(scales: torch.Tensor, sg_scalar: torch.Tensor | float) -> torch.Tensor:
    if isinstance(sg_scalar, torch.Tensor):
        sg = sg_scalar.reshape(1).to(device=scales.device, dtype=torch.float32)
    else:
        sg = torch.tensor([float(sg_scalar)], device=scales.device, dtype=torch.float32)
    return (scales.float() * sg.view(1, 1, 1)).to(torch.float8_e4m3fn).contiguous()


def _quantize_v_prepared_localcta(v_bf16: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
    _require_finite_tensor(v_bf16, "v_bf16")
    local_q = _load_localcta_quant()
    batch, seqlen, heads, dvo = v_bf16.shape
    if dvo % _TILE != 0:
        raise ValueError("V last dim must be divisible by 128 for the localCTA PV sandbox")
    v_2d = v_bf16.permute(0, 2, 3, 1).contiguous().view(batch * heads * dvo, seqlen)
    with _cuda_device_ctx(v_bf16.device):
        v_fp4_2d, v_sc_2d, _, _, _, _ = local_q.tk_localcta_quantize_for_gemm_prepared(v_2d, False, True)
    v_fp4 = v_fp4_2d.view(batch, heads, dvo, seqlen // 2).contiguous()
    v_sc = v_sc_2d.view(batch, heads, dvo // 128, seqlen // 64, 512).contiguous()
    return v_fp4, v_sc


def _quantize_v_prepared_v5(v_bf16: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
    _require_finite_tensor(v_bf16, "v_bf16")
    batch, seqlen, heads, dvo = v_bf16.shape
    if dvo % _TILE != 0:
        raise ValueError("V last dim must be divisible by 128 for the v5 PV sandbox")
    v_fp4 = _zeros_fp4((batch, heads, dvo, seqlen // 2), v_bf16.device)
    v_sc = torch.empty((batch, heads, dvo // 128, seqlen // 64, 512), device=v_bf16.device, dtype=torch.float8_e4m3fn)
    for b in range(batch):
        for h in range(heads):
            rec = _quantize_rows_2d_v5(v_bf16[b, :, h, :].permute(1, 0).contiguous())
            _copy_fp4_tensor_(v_fp4[b, h], rec["fp4"])
            v_sc[b, h].copy_(_apply_scalar_sg_to_prepared_scales(rec["scales"], rec["sg_scalar"]))
    return v_fp4.contiguous(), v_sc.contiguous()


def _quantize_v_prepared(v_bf16: torch.Tensor, *, backend: str = "localcta") -> tuple[torch.Tensor, torch.Tensor]:
    _check_choice("backend", backend, _LIVE_V_QUANT_BACKENDS)
    if backend == "localcta":
        return _quantize_v_prepared_localcta(v_bf16)
    if backend == "v5":
        return _quantize_v_prepared_v5(v_bf16)
    raise ValueError("unreachable V backend branch")


def _make_zero_qk_random_v_inputs(
    seqlen: int,
    *,
    seed: int = 0,
    batch: int = 1,
    heads: int = 16,
    device: str | torch.device = "cuda",
) -> tuple[torch.Tensor, ...]:
    if seqlen % _TILE != 0:
        raise ValueError("sequence length must be divisible by 128")
    device = torch.device(device)
    q = _zeros_fp4((batch, heads, seqlen, _Q_PACKED_DIM), device)
    k = _zeros_fp4((batch, heads, seqlen, _Q_PACKED_DIM), device)
    q_sc = torch.ones((batch, seqlen // _TILE, heads * (_D_QK // 64), 512), device=device, dtype=torch.float8_e4m3fn)
    k_sc = torch.ones((batch, seqlen // 64, heads * (_D_QK // 64), 512), device=device, dtype=torch.float8_e4m3fn)
    q_sg = torch.ones((batch, heads), device=device, dtype=torch.float32)
    k_sg = torch.ones((batch, heads), device=device, dtype=torch.float32)

    gen = _cpu_seeded_generator(seed)
    v_bf16 = torch.randn((batch, seqlen, heads, _D_VO), generator=gen, dtype=torch.float32).to(
        device=device, dtype=torch.bfloat16
    )
    v_fp4, v_sc_prepared = _quantize_v_prepared(v_bf16)
    return q, q_sc, q_sg, k, k_sc, k_sg, v_fp4, v_sc_prepared


def _make_live_bf16_source_inputs(
    seqlen: int,
    *,
    seed: int = 0,
    batch: int = 1,
    heads: int = 16,
    device: str | torch.device = "cuda",
    zero_qk: bool = False,
    distribution: str = "gaussian",
    q_distribution: str | None = None,
    k_distribution: str | None = None,
    v_distribution: str | None = None,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    if seqlen % _TILE != 0:
        raise ValueError("sequence length must be divisible by 128")
    device = torch.device(device)
    gen = _cpu_seeded_generator(seed)
    q_dist, k_dist, v_dist = _resolve_qkv_distributions(
        distribution=distribution,
        q_distribution=q_distribution,
        k_distribution=k_distribution,
        v_distribution=v_distribution,
    )
    if zero_qk:
        q_bf16 = torch.zeros((batch, seqlen, heads, _D_QK), device=device, dtype=torch.bfloat16)
        k_bf16 = torch.zeros_like(q_bf16)
    else:
        q_src = _sample_cpu_distribution((batch, seqlen, heads, _D_QK), gen=gen, distribution=q_dist)
        k_src = _sample_cpu_distribution((batch, seqlen, heads, _D_QK), gen=gen, distribution=k_dist)
        q_bf16 = (q_src / (_D_QK ** 0.25)).to(
            device=device, dtype=torch.bfloat16
        )
        k_bf16 = (k_src / (_D_QK ** 0.25)).to(
            device=device, dtype=torch.bfloat16
        )
    v_src = _sample_cpu_distribution((batch, seqlen, heads, _D_VO), gen=gen, distribution=v_dist)
    v_bf16 = (v_src / (_D_VO ** 0.25)).to(
        device=device, dtype=torch.bfloat16
    )
    return q_bf16.contiguous(), k_bf16.contiguous(), v_bf16.contiguous()


def _quantize_rows_2d_v5(
    x_2d: torch.Tensor,
    *,
    encode_centric: bool = True,
) -> dict[str, Any]:
    x_2d = x_2d.to(torch.bfloat16).contiguous()
    _require_finite_tensor(x_2d, "x_2d")
    tk = _load_v5_quant()
    with _cuda_device_ctx(x_2d.device):
        row_fp4, row_sc, _, _, row_sg, _ = tk.tk_quantize_for_gemm(x_2d, False, encode_centric)
    return {
        "backend": "v5",
        "format": "nvfp4_v5",
        "fp4": row_fp4.contiguous(),
        "scales": row_sc.contiguous(),
        "sg_scalar": row_sg.reshape(1).float().contiguous(),
        "rows": int(x_2d.shape[0]),
        "cols": int(x_2d.shape[1]),
    }


def _pack_live_fp4_qk_v5_from_bf16(x_bhsd: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    _check_cuda_contiguous(x_bhsd, "x_bhsd")
    _require_finite_tensor(x_bhsd, "x_bhsd")
    if x_bhsd.dtype not in (torch.bfloat16, torch.float16, torch.float32):
        raise ValueError("x_bhsd must be BF16/FP16/FP32")
    if x_bhsd.ndim != 4 or x_bhsd.shape[-1] != _D_QK:
        raise ValueError(f"x_bhsd must have shape (batch, heads, seqlen, {_D_QK})")
    if x_bhsd.shape[2] % _TILE != 0:
        raise ValueError("sequence length must be divisible by 128")

    batch, heads, seqlen, _ = x_bhsd.shape
    tk = _load_v5_quant()
    packed = _zeros_fp4((batch, heads, seqlen, _Q_PACKED_DIM), x_bhsd.device)
    scales = torch.empty((batch, seqlen // _TILE, heads * (_D_QK // 64), 512), device=x_bhsd.device, dtype=torch.float8_e4m3fn)
    sg = torch.empty((batch, heads), device=x_bhsd.device, dtype=torch.float32)

    for b in range(batch):
        for h in range(heads):
            x_2d = x_bhsd[b, h].contiguous()
            amax = x_2d.float().abs().amax().reshape(1).float()
            with _cuda_device_ctx(x_bhsd.device):
                row_fp4, row_sc_u8, _, _ = tk.tk_quantize_transpose(x_2d, amax, amax, False)
            _copy_fp4_tensor_(packed[b, h], row_fp4)
            scales[b, :, h * (_D_QK // 64):(h + 1) * (_D_QK // 64), :].copy_(
                row_sc_u8.view(torch.float8_e4m3fn).view(seqlen // _TILE, _D_QK // 64, 512)
            )
            sg[b, h] = amax[0] / 2688.0
    return packed, scales.contiguous(), sg.contiguous()


def _expand_live_k_sc_depth(sc_qstyle: torch.Tensor) -> torch.Tensor:
    _check_cuda_contiguous(sc_qstyle, "sc_qstyle")
    if sc_qstyle.dtype != torch.float8_e4m3fn:
        raise ValueError("sc_qstyle must have dtype torch.float8_e4m3fn")
    if sc_qstyle.ndim != 4 or sc_qstyle.shape[-1] != 512:
        raise ValueError("sc_qstyle must have shape (batch, seqlen/128, heads*chunks, 512)")
    return sc_qstyle.repeat_interleave(2, dim=1).contiguous()


def _fold_localcta_row_sg_into_qk_scales(
    sc_prepared: torch.Tensor,
    row_sg: torch.Tensor,
    *,
    keep_groups: int,
) -> torch.Tensor:
    sc_rowmajor = _inverse_prepared_scale_swizzle(sc_prepared).float()
    _, _, rows, total_groups = sc_rowmajor.shape
    m_blocks = rows // _TILE
    k128_blocks = row_sg.shape[1]
    if row_sg.shape[0] != m_blocks:
        raise ValueError("row_sg first dim must match M/128")
    expected_groups = k128_blocks * 8
    if total_groups != expected_groups:
        raise ValueError(f"prepared scales imply {total_groups} groups, but row_sg implies {expected_groups}")
    sg_groups = row_sg.to(device=sc_prepared.device, dtype=torch.float32).repeat_interleave(8, dim=1)
    sg_rows = sg_groups.repeat_interleave(_TILE, dim=0)
    folded = sc_rowmajor[:, :, :, :keep_groups] * sg_rows.view(1, 1, rows, total_groups)[:, :, :, :keep_groups]
    return _forward_prepared_scale_swizzle(folded.to(torch.float8_e4m3fn).contiguous())


def _pack_live_fp4_qk_localcta_from_bf16(x_bhsd: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    _check_cuda_contiguous(x_bhsd, "x_bhsd")
    _require_finite_tensor(x_bhsd, "x_bhsd")
    if x_bhsd.dtype not in (torch.bfloat16, torch.float16, torch.float32):
        raise ValueError("x_bhsd must be BF16/FP16/FP32")
    if x_bhsd.ndim != 4 or x_bhsd.shape[-1] != _D_QK:
        raise ValueError(f"x_bhsd must have shape (batch, heads, seqlen, {_D_QK})")
    if x_bhsd.shape[2] % _TILE != 0:
        raise ValueError("sequence length must be divisible by 128")

    batch, heads, seqlen, _ = x_bhsd.shape
    padded_d = _TILE * 2
    padded_packed_dim = padded_d // 2
    qk_chunks = _D_QK // 64
    qk_groups = _D_QK // 16
    local_q = _load_localcta_quant()
    packed = _zeros_fp4((batch, heads, seqlen, _Q_PACKED_DIM), x_bhsd.device)
    scales = torch.empty((batch, seqlen // _TILE, heads * qk_chunks, 512), device=x_bhsd.device, dtype=torch.float8_e4m3fn)
    sg = torch.ones((batch, heads), device=x_bhsd.device, dtype=torch.float32)

    for b in range(batch):
        for h in range(heads):
            x_work = torch.zeros((seqlen, padded_d), device=x_bhsd.device, dtype=torch.bfloat16)
            x_work[:, :_D_QK] = x_bhsd[b, h].to(torch.bfloat16)
            with _cuda_device_ctx(x_bhsd.device):
                row_fp4, row_sc_prepared, _, _, row_sg, _ = local_q.tk_localcta_quantize_for_gemm_prepared(x_work, False, True)
            packed[b, h].view(torch.uint8).copy_(row_fp4.view(torch.uint8)[:, :_Q_PACKED_DIM].contiguous())
            folded_sc = _fold_localcta_row_sg_into_qk_scales(
                row_sc_prepared.view(1, 1, seqlen // _TILE, padded_d // 64, 512),
                row_sg.view(seqlen // _TILE, padded_d // _TILE),
                keep_groups=qk_groups,
            )
            if x_bhsd[b, h].float().abs().amax().item() > 0.0 and folded_sc.float().abs().amax().item() == 0.0:
                raise ValueError(
                    "localcta live QK packing underflowed all prepared scales to zero; "
                    "this backend is not a valid nonzero live-QK control for the current input"
                )
            scales[b, :, h * qk_chunks:(h + 1) * qk_chunks, :].copy_(
                folded_sc.view(seqlen // _TILE, qk_chunks, 512)
            )
    return packed.contiguous(), scales.contiguous(), sg.contiguous()


def _fp4_inputs_from_bf16_source(
    q_bf16: torch.Tensor,
    k_bf16: torch.Tensor,
    v_bf16: torch.Tensor,
    *,
    qk_quant_backend: str = "v5",
    v_quant_backend: str = "localcta",
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    _check_choice("qk_quant_backend", qk_quant_backend, _LIVE_QK_QUANT_BACKENDS)
    _check_choice("v_quant_backend", v_quant_backend, _LIVE_V_QUANT_BACKENDS)
    if q_bf16.shape != k_bf16.shape:
        raise ValueError("q_bf16 and k_bf16 must have the same shape")
    if q_bf16.ndim != 4 or v_bf16.ndim != 4:
        raise ValueError("BF16 source tensors must have shape (batch, seqlen, heads, head_dim)")
    if q_bf16.shape[:3] != v_bf16.shape[:3]:
        raise ValueError("q_bf16/k_bf16/v_bf16 must agree on batch, seqlen, and heads")
    if q_bf16.shape[3] != _D_QK or k_bf16.shape[3] != _D_QK:
        raise ValueError(f"q_bf16 and k_bf16 head_dim must be {_D_QK}")
    if v_bf16.shape[3] != _D_VO:
        raise ValueError(f"v_bf16 head_dim must be {_D_VO}")
    if q_bf16.shape[1] % _TILE != 0:
        raise ValueError("sequence length must be divisible by 128")

    batch, seqlen, heads, _ = q_bf16.shape
    device = q_bf16.device
    q_bhsd = q_bf16.permute(0, 2, 1, 3).contiguous()
    k_bhsd = k_bf16.permute(0, 2, 1, 3).contiguous()
    if qk_quant_backend == "v5":
        q, q_sc, q_sg = _pack_live_fp4_qk_v5_from_bf16(q_bhsd)
        k, k_sc_base, k_sg = _pack_live_fp4_qk_v5_from_bf16(k_bhsd)
        k_sc = _expand_live_k_sc_depth(k_sc_base)
    elif qk_quant_backend == "localcta":
        q, q_sc, q_sg = _pack_live_fp4_qk_localcta_from_bf16(q_bhsd)
        k, k_sc_base, k_sg = _pack_live_fp4_qk_localcta_from_bf16(k_bhsd)
        k_sc = _expand_live_k_sc_depth(k_sc_base)
    elif qk_quant_backend == "toy":
        q, q_sg = _pack_live_fp4_qk_from_bf16(q_bhsd)
        k, k_sg = _pack_live_fp4_qk_from_bf16(k_bhsd)
        q_sc = torch.ones((batch, seqlen // _TILE, heads * (_D_QK // 64), 512), device=device, dtype=torch.float32).to(torch.float8_e4m3fn).contiguous()
        k_sc = torch.ones((batch, seqlen // 64, heads * (_D_QK // 64), 512), device=device, dtype=torch.float32).to(torch.float8_e4m3fn).contiguous()
    else:
        raise ValueError("unreachable qk_quant_backend branch")
    v_fp4, v_sc_prepared = _quantize_v_prepared(v_bf16, backend=v_quant_backend)
    return q, q_sc, q_sg.float().contiguous(), k, k_sc, k_sg.float().contiguous(), v_fp4, v_sc_prepared


def _fp4_qk_inputs_from_bf16_source(
    q_bf16: torch.Tensor,
    k_bf16: torch.Tensor,
    *,
    qk_quant_backend: str = "v5",
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    _check_choice("qk_quant_backend", qk_quant_backend, _LIVE_QK_QUANT_BACKENDS)
    if q_bf16.shape != k_bf16.shape:
        raise ValueError("q_bf16 and k_bf16 must have the same shape")
    if q_bf16.ndim != 4:
        raise ValueError("q_bf16 and k_bf16 must have shape (batch, seqlen, heads, head_dim)")
    if q_bf16.shape[3] != _D_QK or k_bf16.shape[3] != _D_QK:
        raise ValueError(f"q_bf16 and k_bf16 head_dim must be {_D_QK}")
    if q_bf16.shape[1] % _TILE != 0:
        raise ValueError("sequence length must be divisible by 128")

    batch, seqlen, heads, _ = q_bf16.shape
    device = q_bf16.device
    q_bhsd = q_bf16.permute(0, 2, 1, 3).contiguous()
    k_bhsd = k_bf16.permute(0, 2, 1, 3).contiguous()
    if qk_quant_backend == "v5":
        q, q_sc, q_sg = _pack_live_fp4_qk_v5_from_bf16(q_bhsd)
        k, k_sc_base, k_sg = _pack_live_fp4_qk_v5_from_bf16(k_bhsd)
        k_sc = _expand_live_k_sc_depth(k_sc_base)
    elif qk_quant_backend == "localcta":
        q, q_sc, q_sg = _pack_live_fp4_qk_localcta_from_bf16(q_bhsd)
        k, k_sc_base, k_sg = _pack_live_fp4_qk_localcta_from_bf16(k_bhsd)
        k_sc = _expand_live_k_sc_depth(k_sc_base)
    elif qk_quant_backend == "toy":
        q, q_sg = _pack_live_fp4_qk_from_bf16(q_bhsd)
        k, k_sg = _pack_live_fp4_qk_from_bf16(k_bhsd)
        q_sc = torch.ones((batch, seqlen // _TILE, heads * (_D_QK // 64), 512), device=device, dtype=torch.float32).to(torch.float8_e4m3fn).contiguous()
        k_sc = torch.ones((batch, seqlen // 64, heads * (_D_QK // 64), 512), device=device, dtype=torch.float32).to(torch.float8_e4m3fn).contiguous()
    else:
        raise ValueError("unreachable qk_quant_backend branch")
    return q, q_sc, q_sg.float().contiguous(), k, k_sc, k_sg.float().contiguous()


def _pack_live_fp4_qk_from_bf16(x_bhsd: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
    _check_cuda_contiguous(x_bhsd, "x_bhsd")
    if x_bhsd.dtype not in (torch.bfloat16, torch.float16, torch.float32):
        raise ValueError("x_bhsd must be BF16/FP16/FP32")
    if x_bhsd.ndim != 4 or x_bhsd.shape[-1] != _D_QK:
        raise ValueError(f"x_bhsd must have shape (batch, heads, seqlen, {_D_QK})")
    if x_bhsd.shape[2] % _TILE != 0:
        raise ValueError("sequence length must be divisible by 128")

    amax = x_bhsd.float().abs().amax(dim=(-1, -2))
    sg = torch.where(amax > 0, amax / 6.0, torch.ones_like(amax))
    norm = x_bhsd.float() / sg.view(*sg.shape, 1, 1)
    table = _FP4_DECODE_TABLE.to(device=x_bhsd.device).view(1, 1, 1, 1, 16)
    idx = (norm.unsqueeze(-1) - table).abs().argmin(dim=-1).to(torch.uint8)
    packed_u8 = (idx[..., 0::2] | (idx[..., 1::2] << 4)).contiguous()
    return packed_u8.view(torch.float4_e2m1fn_x2), sg.contiguous()


def make_random_live_fp4_attention_inputs(
    seqlen: int,
    *,
    seed: int = 0,
    batch: int = 1,
    heads: int = 16,
    device: str | torch.device = "cuda",
    zero_qk: bool = False,
    qk_quant_backend: str = "v5",
    v_quant_backend: str = "localcta",
    distribution: str = "gaussian",
    q_distribution: str | None = None,
    k_distribution: str | None = None,
    v_distribution: str | None = None,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    if seqlen % _TILE != 0:
        raise ValueError("sequence length must be divisible by 128")
    device = torch.device(device)
    if zero_qk:
        return _make_zero_qk_random_v_inputs(
            seqlen,
            seed=seed,
            batch=batch,
            heads=heads,
            device=device,
        )
    q_bf16, k_bf16, v_bf16 = _make_live_bf16_source_inputs(
        seqlen,
        seed=seed,
        batch=batch,
        heads=heads,
        device=device,
        zero_qk=False,
        distribution=distribution,
        q_distribution=q_distribution,
        k_distribution=k_distribution,
        v_distribution=v_distribution,
    )
    return _fp4_inputs_from_bf16_source(
        q_bf16,
        k_bf16,
        v_bf16,
        qk_quant_backend=qk_quant_backend,
        v_quant_backend=v_quant_backend,
    )


def make_paired_bf16_fp4_attention_inputs(
    seqlen: int,
    *,
    seed: int = 0,
    batch: int = 1,
    heads: int = 16,
    device: str | torch.device = "cuda",
    zero_qk: bool = False,
    qk_quant_backend: str = "v5",
    v_quant_backend: str = "localcta",
    distribution: str = "gaussian",
    q_distribution: str | None = None,
    k_distribution: str | None = None,
    v_distribution: str | None = None,
) -> dict[str, tuple[torch.Tensor, ...]]:
    q_bf16, k_bf16, v_bf16 = _make_live_bf16_source_inputs(
        seqlen,
        seed=seed,
        batch=batch,
        heads=heads,
        device=device,
        zero_qk=zero_qk,
        distribution=distribution,
        q_distribution=q_distribution,
        k_distribution=k_distribution,
        v_distribution=v_distribution,
    )
    return {
        "bf16": (q_bf16, k_bf16, v_bf16),
        "fp4": _fp4_inputs_from_bf16_source(
            q_bf16,
            k_bf16,
            v_bf16,
            qk_quant_backend=qk_quant_backend,
            v_quant_backend=v_quant_backend,
        ),
    }


def make_random_bf16_sandbox_inputs(
    seqlen: int,
    *,
    d_qk: int = _D_QK,
    d_vo: int = _D_VO,
    seed: int = 0,
    batch: int = 1,
    heads: int = 16,
    device: str | torch.device = "cuda",
    dtype: torch.dtype = torch.bfloat16,
    zero_qk: bool = False,
    distribution: str = "gaussian",
    q_distribution: str | None = None,
    k_distribution: str | None = None,
    v_distribution: str | None = None,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor | None]:
    device = torch.device(device)
    if d_qk <= 0 or d_vo <= 0:
        raise ValueError("d_qk and d_vo must be positive")
    gen = _cpu_seeded_generator(seed)
    q_dist, k_dist, v_dist = _resolve_qkv_distributions(
        distribution=distribution,
        q_distribution=q_distribution,
        k_distribution=k_distribution,
        v_distribution=v_distribution,
    )
    if zero_qk:
        q_bf16 = torch.zeros((batch, seqlen, heads, d_qk), device=device, dtype=dtype)
        k_bf16 = torch.zeros((batch, seqlen, heads, d_qk), device=device, dtype=dtype)
    else:
        q_src = _sample_cpu_distribution((batch, seqlen, heads, d_qk), gen=gen, distribution=q_dist)
        k_src = _sample_cpu_distribution((batch, seqlen, heads, d_qk), gen=gen, distribution=k_dist)
        q_bf16 = (q_src / (d_qk ** 0.25)).to(
            device=device, dtype=dtype
        )
        k_bf16 = (k_src / (d_qk ** 0.25)).to(
            device=device, dtype=dtype
        )
    v_src = _sample_cpu_distribution((batch, seqlen, heads, d_vo), gen=gen, distribution=v_dist)
    v_bf16 = (v_src / (max(d_vo, 1) ** 0.25)).to(
        device=device, dtype=dtype
    )
    return q_bf16.contiguous(), k_bf16.contiguous(), v_bf16.contiguous()


def _median(values: list[float]) -> float:
    ordered = sorted(float(v) for v in values)
    return ordered[len(ordered) // 2]


def _median_breakdown(samples: list[dict[str, float]]) -> dict[str, float]:
    if not samples:
        return {}
    keys = sorted(samples[0].keys())
    return {key: _median([float(sample[key]) for sample in samples]) for key in keys}


def _compare_outputs(out: torch.Tensor, lse: torch.Tensor, ref_out: torch.Tensor, ref_lse: torch.Tensor) -> dict[str, Any]:
    delta = out.float() - ref_out.float()
    out_delta = delta.abs()
    ref_abs = ref_out.float().abs()
    mse = float(delta.square().mean().item())
    rmse = math.sqrt(mse)
    ref_abs_mean = float(ref_abs.mean().item())
    ref_rms = math.sqrt(float(ref_out.float().square().mean().item()))
    max_rel_diff = float((out_delta / ref_abs.clamp_min(1e-3)).max().item())
    lse_delta = (lse.float() - ref_lse.float()).abs()
    output_has_nonfinite = bool((~torch.isfinite(out)).any().item())
    reference_has_nonfinite = bool((~torch.isfinite(ref_out)).any().item())
    lse_has_nonfinite = bool((~torch.isfinite(lse)).any().item())
    reference_lse_has_nonfinite = bool((~torch.isfinite(ref_lse)).any().item())
    return {
        "max_abs_diff": float(out_delta.max().item()),
        "mean_abs_diff": float(out_delta.mean().item()),
        "mse": mse,
        "rmse": rmse,
        "normalized_mean_abs_diff": float(out_delta.mean().item() / max(ref_abs_mean, 1e-6)),
        "normalized_rmse": float(rmse / max(ref_rms, 1e-6)),
        "max_rel_diff": max_rel_diff,
        "lse_max_abs_diff": float(lse_delta.max().item()),
        "output_has_nan": bool(torch.isnan(out).any().item()),
        "reference_has_nan": bool(torch.isnan(ref_out).any().item()),
        "lse_has_nan": bool(torch.isnan(lse).any().item()),
        "reference_lse_has_nan": bool(torch.isnan(ref_lse).any().item()),
        "output_has_nonfinite": output_has_nonfinite,
        "reference_has_nonfinite": reference_has_nonfinite,
        "lse_has_nonfinite": lse_has_nonfinite,
        "reference_lse_has_nonfinite": reference_lse_has_nonfinite,
    }


def _compare_output_only(out: torch.Tensor, ref_out: torch.Tensor) -> dict[str, Any]:
    delta = out.float() - ref_out.float()
    out_delta = delta.abs().flatten()
    ref_abs = ref_out.float().abs()
    mse = float(delta.square().mean().item())
    rmse = math.sqrt(mse)
    ref_abs_mean = float(ref_abs.mean().item())
    ref_rms = math.sqrt(float(ref_out.float().square().mean().item()))
    p99 = float(torch.quantile(out_delta, 0.99).item()) if out_delta.numel() else 0.0
    return {
        "max_abs_diff": float(out_delta.max().item()) if out_delta.numel() else 0.0,
        "mean_abs_diff": float(out_delta.mean().item()) if out_delta.numel() else 0.0,
        "p99_abs_diff": p99,
        "mse": mse,
        "rmse": rmse,
        "normalized_mean_abs_diff": float(out_delta.mean().item() / max(ref_abs_mean, 1e-6)) if out_delta.numel() else 0.0,
        "normalized_rmse": float(rmse / max(ref_rms, 1e-6)),
        "max_rel_diff": float((out_delta.view_as(out) / ref_abs.clamp_min(1e-3)).max().item()) if out_delta.numel() else 0.0,
        "nonzero_diff_fraction": float((out_delta > 0).float().mean().item()) if out_delta.numel() else 0.0,
        "output_has_nan": bool(torch.isnan(out).any().item()),
        "reference_has_nan": bool(torch.isnan(ref_out).any().item()),
        "output_has_nonfinite": bool((~torch.isfinite(out)).any().item()),
        "reference_has_nonfinite": bool((~torch.isfinite(ref_out)).any().item()),
    }


def _assess_pv_precision_result(
    out: torch.Tensor,
    ref_out: torch.Tensor,
    *,
    pv_execution_mode: str,
) -> dict[str, Any]:
    pv_execution_mode = _normalize_pv_execution_mode(pv_execution_mode)
    out_abs = out.float().abs()
    ref_abs = ref_out.float().abs()
    output_abs_max = float(out_abs.max().item()) if out.numel() > 0 else 0.0
    output_abs_mean = float(out_abs.mean().item()) if out.numel() > 0 else 0.0
    reference_abs_max = float(ref_abs.max().item()) if ref_out.numel() > 0 else 0.0
    reference_abs_mean = float(ref_abs.mean().item()) if ref_out.numel() > 0 else 0.0
    finite_out = bool(torch.isfinite(out).all().item())
    if not finite_out:
        return {
            "kernel_status": "nonfinite",
            "row_valid_for_ranking": False,
            "output_abs_max": output_abs_max,
            "output_abs_mean": output_abs_mean,
            "reference_abs_max": reference_abs_max,
            "reference_abs_mean": reference_abs_mean,
        }
    if pv_execution_mode == "real_kernel" and output_abs_max <= 1e-30 and reference_abs_max > 1e-6:
        return {
            "kernel_status": "all_zero",
            "row_valid_for_ranking": False,
            "output_abs_max": output_abs_max,
            "output_abs_mean": output_abs_mean,
            "reference_abs_max": reference_abs_max,
            "reference_abs_mean": reference_abs_mean,
        }
    output_to_reference_max_ratio = (
        float(output_abs_max / reference_abs_max) if reference_abs_max > 0.0 else float("inf")
    )
    output_to_reference_mean_ratio = (
        float(output_abs_mean / reference_abs_mean) if reference_abs_mean > 0.0 else float("inf")
    )
    if (
        pv_execution_mode == "real_kernel"
        and reference_abs_max > 1e-4
        and reference_abs_mean > 1e-5
        and output_to_reference_max_ratio < 0.05
        and output_to_reference_mean_ratio < 0.05
    ):
        return {
            "kernel_status": "collapsed_scale",
            "row_valid_for_ranking": False,
            "output_abs_max": output_abs_max,
            "output_abs_mean": output_abs_mean,
            "reference_abs_max": reference_abs_max,
            "reference_abs_mean": reference_abs_mean,
            "output_to_reference_max_ratio": output_to_reference_max_ratio,
            "output_to_reference_mean_ratio": output_to_reference_mean_ratio,
        }
    if (
        pv_execution_mode == "real_kernel"
        and reference_abs_max > 1e-4
        and reference_abs_mean > 1e-5
        and (
            output_to_reference_max_ratio > 8.0
            or output_to_reference_mean_ratio > 8.0
        )
    ):
        return {
            "kernel_status": "exploded_scale",
            "row_valid_for_ranking": False,
            "output_abs_max": output_abs_max,
            "output_abs_mean": output_abs_mean,
            "reference_abs_max": reference_abs_max,
            "reference_abs_mean": reference_abs_mean,
            "output_to_reference_max_ratio": output_to_reference_max_ratio,
            "output_to_reference_mean_ratio": output_to_reference_mean_ratio,
        }
    return {
        "kernel_status": "proxy" if pv_execution_mode == "qdq_proxy" else "ok",
        "row_valid_for_ranking": True,
        "output_abs_max": output_abs_max,
        "output_abs_mean": output_abs_mean,
        "reference_abs_max": reference_abs_max,
        "reference_abs_mean": reference_abs_mean,
        "output_to_reference_max_ratio": output_to_reference_max_ratio,
        "output_to_reference_mean_ratio": output_to_reference_mean_ratio,
    }


def _flatten_output_compare(prefix: str, compare: dict[str, Any] | None) -> dict[str, Any]:
    if compare is None:
        return {}
    return {
        f"{prefix}_max_abs": compare["max_abs_diff"],
        f"{prefix}_mean_abs": compare["mean_abs_diff"],
        f"{prefix}_mse": compare["mse"],
        f"{prefix}_rmse": compare["rmse"],
        f"{prefix}_max_rel": compare["max_rel_diff"],
        f"{prefix}_lse_max_abs": compare["lse_max_abs_diff"],
        f"{prefix}_output_has_nan": compare["output_has_nan"],
        f"{prefix}_lse_has_nan": compare["lse_has_nan"],
        f"{prefix}_output_has_nonfinite": compare["output_has_nonfinite"],
        f"{prefix}_lse_has_nonfinite": compare["lse_has_nonfinite"],
        f"{prefix}_finite_out": (not compare["output_has_nonfinite"]) and (not compare["reference_has_nonfinite"]),
        f"{prefix}_finite_lse": (not compare["lse_has_nonfinite"]) and (not compare["reference_lse_has_nonfinite"]),
    }


def _expand_forward_distribution_study_cases(
    *,
    input_families: tuple[str, ...],
    controls: tuple[str, ...],
) -> list[dict[str, Any]]:
    cases: list[dict[str, Any]] = []
    seen: set[str] = set()
    for family in input_families:
        _check_choice("input_families", family, _QKV_DISTRIBUTION_PRESETS)
        if family in seen:
            continue
        seen.add(family)
        cases.append(
            {
                "study_case": family,
                "study_case_kind": "family",
                "input_mode": "random_live_fp4",
                "distribution": family,
            }
        )
    for control in controls:
        _check_choice("controls", control, _FORWARD_DISTRIBUTION_STUDY_CONTROLS)
        if control in seen:
            continue
        seen.add(control)
        if control == "random_gaussian_control":
            cases.append(
                {
                    "study_case": control,
                    "study_case_kind": "control",
                    "input_mode": "random_live_fp4",
                    "distribution": "gaussian",
                }
            )
        elif control == "zero_qk_gaussian_control":
            cases.append(
                {
                    "study_case": control,
                    "study_case_kind": "control",
                    "input_mode": "zero_qk_random_v",
                    "distribution": "gaussian",
                }
            )
        else:  # pragma: no cover - guarded above
            raise ValueError(f"unsupported control {control!r}")
    return cases


def _filter_forward_distribution_candidate_rows(
    rows: list[dict[str, Any]],
    *,
    full_candidates: tuple[tuple[str, str, str], ...],
) -> list[dict[str, Any]]:
    candidate_set = {
        (
            _normalize_forward_matrix_backend(qk_backend),
            p_mode,
            _normalize_forward_matrix_backend(pv_backend),
        )
        for qk_backend, p_mode, pv_backend in full_candidates
    }
    filtered: list[dict[str, Any]] = []
    for row in rows:
        if row.get("variant") == "regular_fa4_bf16":
            continue
        key = (
            _normalize_forward_matrix_backend(str(row["qk_backend"])),
            str(row["p_mode"]),
            _normalize_forward_matrix_backend(str(row["pv_backend"])),
        )
        if key in candidate_set:
            filtered.append(row)
    return filtered


def _metric_sort_key(row: dict[str, Any]) -> tuple[float, float, float]:
    def _clean(value: Any) -> float:
        try:
            value_f = float(value)
        except Exception:
            return float("inf")
        if math.isnan(value_f):
            return float("inf")
        return value_f

    return (
        _clean(row.get("median_mean_abs_diff_vs_bf16")),
        _clean(row.get("median_max_abs_diff_vs_bf16")),
        _clean(row.get("median_lse_max_abs_diff_vs_bf16")),
    )


def _aggregate_distribution_study_rows(
    rows: list[dict[str, Any]],
    *,
    combo_fields: tuple[str, ...],
) -> list[dict[str, Any]]:
    grouped: dict[tuple[Any, ...], list[dict[str, Any]]] = {}
    for row in rows:
        key = (
            row["study_case"],
            row["study_case_kind"],
            row["input_mode"],
            row["distribution"],
            row["q_distribution"],
            row["k_distribution"],
            row["v_distribution"],
            row["seqlen"],
            *(row[field] for field in combo_fields),
        )
        grouped.setdefault(key, []).append(row)

    summaries: list[dict[str, Any]] = []
    for _, group_rows in grouped.items():
        first = group_rows[0]
        successful_rows = [
            row
            for row in group_rows
            if "error" not in row and bool(row.get("finite_out", True)) and bool(row.get("finite_lse", True))
        ]
        mean_vals = [float(row["mean_abs_diff_vs_bf16"]) for row in successful_rows]
        max_vals = [float(row["max_abs_diff_vs_bf16"]) for row in successful_rows]
        mse_vals = [float(row["mse_vs_bf16"]) for row in successful_rows]
        rmse_vals = [float(row["rmse_vs_bf16"]) for row in successful_rows]
        max_rel_vals = [float(row["max_rel_diff_vs_bf16"]) for row in successful_rows]
        lse_vals = [float(row["lse_max_abs_diff_vs_bf16"]) for row in successful_rows]
        ratio_vals = [float(row["ratio_vs_bf16_baseline"]) for row in successful_rows]
        bf16_vals = [float(row["bf16_baseline_ms"]) for row in successful_rows if "bf16_baseline_ms" in row]
        timing_vals = [float(row["timing_ms"]) for row in successful_rows if "timing_ms" in row]
        candidate_output_nonfinite_count = sum(bool(row.get("output_has_nonfinite", False)) for row in group_rows if "error" not in row)
        candidate_lse_nonfinite_count = sum(bool(row.get("lse_has_nonfinite", False)) for row in group_rows if "error" not in row)
        reference_output_nonfinite_count = sum(bool(row.get("reference_has_nonfinite", False)) for row in group_rows if "error" not in row)
        reference_lse_nonfinite_count = sum(bool(row.get("reference_lse_has_nonfinite", False)) for row in group_rows if "error" not in row)
        summaries.append(
            {
                "study_case": first["study_case"],
                "study_case_kind": first["study_case_kind"],
                "input_mode": first["input_mode"],
                "distribution": first["distribution"],
                "q_distribution": first["q_distribution"],
                "k_distribution": first["k_distribution"],
                "v_distribution": first["v_distribution"],
                "seqlen": int(first["seqlen"]),
                **{field: first[field] for field in combo_fields},
                "seed_count": len(group_rows),
                "successful_seed_count": len(successful_rows),
                "error_count": sum("error" in row for row in group_rows),
                "candidate_output_nonfinite_count": candidate_output_nonfinite_count,
                "candidate_lse_nonfinite_count": candidate_lse_nonfinite_count,
                "reference_output_nonfinite_count": reference_output_nonfinite_count,
                "reference_lse_nonfinite_count": reference_lse_nonfinite_count,
                "all_seeds_finite": len(successful_rows) == len(group_rows),
                "experimental": bool(first.get("experimental", False)),
                "uses_real_qk_backend": bool(first.get("uses_real_qk_backend", False)),
                "uses_real_pv_backend": bool(first.get("uses_real_pv_backend", False)),
                "median_mean_abs_diff_vs_bf16": _median(mean_vals) if mean_vals else float("nan"),
                "max_over_seeds_mean_abs_diff_vs_bf16": max(mean_vals) if mean_vals else float("nan"),
                "median_max_abs_diff_vs_bf16": _median(max_vals) if max_vals else float("nan"),
                "median_mse_vs_bf16": _median(mse_vals) if mse_vals else float("nan"),
                "median_rmse_vs_bf16": _median(rmse_vals) if rmse_vals else float("nan"),
                "median_max_rel_diff_vs_bf16": _median(max_rel_vals) if max_rel_vals else float("nan"),
                "median_lse_max_abs_diff_vs_bf16": _median(lse_vals) if lse_vals else float("nan"),
                "median_ratio_vs_bf16_baseline": _median(ratio_vals) if ratio_vals else float("nan"),
                "median_bf16_baseline_ms": _median(bf16_vals) if bf16_vals else float("nan"),
                "median_timing_ms": _median(timing_vals) if timing_vals else float("nan"),
            }
        )

    grouped_case: dict[tuple[str, int], list[dict[str, Any]]] = {}
    for row in summaries:
        row["rank_within_case"] = None
        row["rank_within_case_nonexperimental"] = None
        row["best_overall_for_case"] = False
        row["best_nonexperimental_for_case"] = False
        row["best_reported_for_case"] = False
        grouped_case.setdefault((str(row["study_case"]), int(row["seqlen"])), []).append(row)

    for _, case_rows in grouped_case.items():
        ordered = sorted(case_rows, key=_metric_sort_key)
        for idx, row in enumerate(ordered, start=1):
            row["rank_within_case"] = idx
            row["best_overall_for_case"] = idx == 1
        nonexperimental = [row for row in ordered if not bool(row.get("experimental", False))]
        if nonexperimental:
            for idx, row in enumerate(nonexperimental, start=1):
                row["rank_within_case_nonexperimental"] = idx
                row["best_nonexperimental_for_case"] = idx == 1
            best_nonexperimental = nonexperimental[0]
        else:
            best_nonexperimental = None
        best_overall = ordered[0]
        use_overall = (not bool(best_overall.get("experimental", False))) or bool(best_overall.get("all_seeds_finite", False))
        reported = best_overall if use_overall else best_nonexperimental
        if reported is not None:
            reported["best_reported_for_case"] = True
    return sorted(
        summaries,
        key=lambda row: (
            str(row["study_case"]),
            int(row["seqlen"]),
            _metric_sort_key(row),
        ),
    )


def _compare_p_and_lse(
    p_bf16: torch.Tensor,
    lse: torch.Tensor,
    ref_p_bf16: torch.Tensor,
    ref_lse: torch.Tensor,
) -> dict[str, Any]:
    p_delta = (p_bf16.float() - ref_p_bf16.float()).abs()
    lse_delta = (lse.float() - ref_lse.float()).abs()
    return {
        "p_max_abs_diff": float(p_delta.max().item()),
        "p_mean_abs_diff": float(p_delta.mean().item()),
        "lse_max_abs_diff": float(lse_delta.max().item()),
        "p_has_nan": bool(torch.isnan(p_bf16).any().item()),
        "reference_p_has_nan": bool(torch.isnan(ref_p_bf16).any().item()),
        "lse_has_nan": bool(torch.isnan(lse).any().item()),
        "reference_lse_has_nan": bool(torch.isnan(ref_lse).any().item()),
    }


def _row_block_drift_summary(out: torch.Tensor, ref_out: torch.Tensor, *, block_rows: int = _TILE) -> list[dict[str, float]]:
    diff = (out.float() - ref_out.float()).abs()
    seqlen = diff.shape[1]
    summary = []
    for row_start in range(0, seqlen, block_rows):
        row_end = min(row_start + block_rows, seqlen)
        block = diff[:, row_start:row_end]
        summary.append(
            {
                "row_start": float(row_start),
                "row_end": float(row_end - 1),
                "max_abs_diff": float(block.max().item()),
                "mean_abs_diff": float(block.mean().item()),
            }
        )
    return summary


def _head_scale_diff_summary(
    dump_scales: torch.Tensor,
    ref_scales: torch.Tensor,
) -> list[dict[str, float | int | bool]]:
    if dump_scales.shape != ref_scales.shape:
        raise ValueError("dump/ref scale shapes must match")
    if dump_scales.ndim != 5:
        raise ValueError("expected (B, H, M/128, K/64, 512) scale tensors")

    batch, heads = dump_scales.shape[:2]
    dump_f = dump_scales.float()
    ref_f = ref_scales.float()
    summary: list[dict[str, float | int | bool]] = []
    for b in range(batch):
        for h in range(heads):
            delta = (dump_f[b, h] - ref_f[b, h]).abs()
            summary.append(
                {
                    "batch": b,
                    "head": h,
                    "max_abs_diff": float(delta.max().item()),
                    "mean_abs_diff": float(delta.mean().item()),
                    "dump_max": float(dump_f[b, h].max().item()),
                    "ref_max": float(ref_f[b, h].max().item()),
                    "dump_has_nan": bool(torch.isnan(dump_f[b, h]).any().item()),
                    "ref_has_nan": bool(torch.isnan(ref_f[b, h]).any().item()),
                }
            )
    return summary


def _live_dump_repeatability_summary(
    dump_runs: list[torch.Tensor],
    lse_runs: list[torch.Tensor],
) -> dict[str, Any]:
    if len(dump_runs) < 2 or len(lse_runs) != len(dump_runs):
        raise ValueError("repeatability summary expects >=2 dump runs plus matching LSE runs")

    ref_dump = dump_runs[0].float()
    ref_lse = lse_runs[0].float()
    scale_max_diffs: list[float] = []
    scale_mean_diffs: list[float] = []
    lse_max_diffs: list[float] = []
    per_run_head_summary: list[list[dict[str, float | int | bool]]] = []

    for idx in range(1, len(dump_runs)):
        cur_dump = dump_runs[idx].float()
        cur_lse = lse_runs[idx].float()
        dump_delta = (cur_dump - ref_dump).abs()
        lse_delta = (cur_lse - ref_lse).abs()
        scale_max_diffs.append(float(dump_delta.max().item()))
        scale_mean_diffs.append(float(dump_delta.mean().item()))
        lse_max_diffs.append(float(lse_delta.max().item()))
        per_run_head_summary.append(_head_scale_diff_summary(cur_dump, ref_dump))

    return {
        "iters": len(dump_runs),
        "max_abs_diff_vs_run0": max(scale_max_diffs),
        "mean_abs_diff_vs_run0": max(scale_mean_diffs),
        "lse_max_abs_diff_vs_run0": max(lse_max_diffs),
        "scale_has_nan_runs": [bool(torch.isnan(run).any().item()) for run in dump_runs],
        "per_run_head_diff_vs_run0": per_run_head_summary,
    }


def _variant_supports_debug(variant: str) -> bool:
    return bool(_VARIANT_META[variant]["supports_debug"])


def _variant_is_live(variant: str) -> bool:
    return bool(_VARIANT_META[variant]["is_live"])


def _allow_unsafe_live_for_seqlen(seqlen: int, unsafe_live_seqlens: tuple[int, ...]) -> bool:
    return seqlen in set(int(s) for s in unsafe_live_seqlens)


def list_variants() -> list[str]:
    return list(_VARIANT_META.keys())


def list_bf16_sandbox_pv_variants() -> list[str]:
    return list(_SANDBOX_PV_VARIANTS)


def _run_fp4pv_baseline(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
):
    ext = _load_forward_experiments_ext()
    batch, heads, seqlen = _check_fp4_attention_inputs(q, q_sc, q_sg, k, k_sc, k_sg)
    _check_prequantized_v(v_fp4, v_sc_prepared, batch, heads, seqlen)

    out = torch.empty((batch, seqlen, heads, _D_VO), dtype=torch.bfloat16, device=q.device)
    lse = torch.empty((batch, heads, 1, seqlen), dtype=torch.float32, device=q.device)
    with _cuda_device_ctx(q.device):
        ext.forward_fp4pv(q, q_sc, q_sg, k, k_sc, k_sg, v_fp4, v_sc_prepared, out, lse)
    return out, lse[:, :, 0, :]


def _run_fp4pv_fullgrid(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
):
    prod_ext = _load_production_causal_ext()
    batch, heads, seqlen = _check_fp4_attention_inputs(q, q_sc, q_sg, k, k_sc, k_sg)
    _check_prequantized_v(v_fp4, v_sc_prepared, batch, heads, seqlen)

    out = torch.empty((batch, seqlen, heads, _D_VO), dtype=torch.bfloat16, device=q.device)
    lse = torch.empty((batch, heads, 1, seqlen), dtype=torch.float32, device=q.device)
    with _cuda_device_ctx(q.device):
        if hasattr(prod_ext, "forward_fp4pv_fullgrid"):
            prod_ext.forward_fp4pv_fullgrid(q, q_sc, q_sg, k, k_sc, k_sg, v_fp4, v_sc_prepared, out, lse)
        else:
            exp_ext = _load_forward_experiments_ext()
            exp_ext.forward_fp4pv_fullgrid(q, q_sc, q_sg, k, k_sc, k_sg, v_fp4, v_sc_prepared, out, lse)
    return out, lse[:, :, 0, :]


def _fp4_qk_mxfp4_v_inputs_from_bf16_source(
    q_bf16: torch.Tensor,
    k_bf16: torch.Tensor,
    v_bf16: torch.Tensor,
    *,
    qk_quant_backend: str = "v5",
    v_quant_mode: str | None = None,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    q, q_sc, q_sg, k, k_sc, k_sg = _fp4_qk_inputs_from_bf16_source(
        q_bf16,
        k_bf16,
        qk_quant_backend=qk_quant_backend,
    )
    v_fp4, v_sc = _mxfp4_quantize_v_for_gemm(
        v_bf16,
        quant_mode=v_quant_mode,
        pad_dvo_to_256=False,
        pad_scale_rows_for_grouped=True,
    )
    quant_scale_rows = v_bf16.shape[3] // _TILE
    if v_sc.shape[2] > quant_scale_rows:
        v_sc[:, :, quant_scale_rows:].zero_()
    return q, q_sc, q_sg, k, k_sc, k_sg, v_fp4, v_sc


def _run_forward_streaming_live_mxfp4(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc: torch.Tensor,
    *,
    p_quant_mode: str | None = None,
    launch_mode: str = "auto",
    output_only: bool = False,
):
    ext = _load_forward_experiments_ext()
    active_fwd_config = os.environ.get("TK_FA4_FP4PV_FWD_CONFIG")
    q_scale_tile = 64 if _mxfp4_fwd_config_uses_mb64(active_fwd_config) else _TILE
    batch, heads, seqlen = _check_fp4_attention_inputs(
        q, q_sc, q_sg, k, k_sc, k_sg, q_scale_tile=q_scale_tile
    )
    runtime_fwd_config = None
    if not active_fwd_config:
        active_fwd_config = _select_mxfp4_fwd_config_for_shape(seqlen, heads)
        runtime_fwd_config = active_fwd_config
    _check_cuda_contiguous(v_fp4, "v_fp4")
    _check_cuda_contiguous(v_sc, "v_sc")
    if v_fp4.dtype != torch.float4_e2m1fn_x2:
        raise ValueError("MXFP4 V payload must have dtype torch.float4_e2m1fn_x2")
    if v_sc.dtype != torch.uint8:
        raise ValueError("MXFP4 V scales must have dtype torch.uint8")
    if v_fp4.ndim != 4 or v_fp4.shape[:2] != (batch, heads) or v_fp4.shape[3] != seqlen // 2:
        raise ValueError(f"v_fp4 must have shape {(batch, heads, 'dvo', seqlen // 2)}")
    dvo = int(v_fp4.shape[2])
    if dvo % _TILE != 0:
        raise ValueError("MXFP4 V head dim must be divisible by 128")
    expected_scale_rows = dvo // _TILE
    if v_sc.shape[:2] != (batch, heads) or v_sc.shape[3:] != (seqlen // _TILE, 32, 16):
        raise ValueError("MXFP4 V scales must have shape (B,H,scale_rows,S/128,32,16)")
    if int(v_sc.shape[2]) < expected_scale_rows:
        raise ValueError("MXFP4 V scales do not cover the V head dimension")

    out = torch.empty((batch, seqlen, heads, _D_VO), dtype=torch.bfloat16, device=q.device)
    lse = torch.empty((batch, heads, 1, seqlen), dtype=torch.float32, device=q.device)
    launch_mode = _resolve_mxfp4_fwd_launch_mode(seqlen, heads, launch_mode)
    persistent_launch = launch_mode != "fullgrid"
    fn = ext.forward_streaming_live_mxfp4_output_only if output_only else ext.forward_streaming_live_mxfp4
    fwd_config_env = (
        _temporary_environ({"TK_FA4_FP4PV_FWD_CONFIG": runtime_fwd_config})
        if runtime_fwd_config is not None
        else nullcontext()
    )
    with _cuda_device_ctx(q.device), fwd_config_env:
        fn(
            q,
            q_sc,
            q_sg,
            k,
            k_sc,
            k_sg,
            v_fp4,
            v_sc,
            out,
            lse,
            _mxfp4_quant_mode_to_int(p_quant_mode),
            persistent_launch,
        )
    return out, lse[:, :, 0, :]


def _run_mxfp4_saved_forward_for_backward(
    q_bf16: torch.Tensor,
    k_bf16: torch.Tensor,
    v_bf16: torch.Tensor,
    *,
    qk_quant_backend: str = "v5",
    p_quant_mode: str | None = None,
    launch_mode: str = "auto",
) -> tuple[torch.Tensor, torch.Tensor, str]:
    """Run the MXFP4 forward path used to provide saved BWD out/LSE.

    The older local FP4PV wrapper can leave whole output row tiles unwritten for
    H=1/S>=512 while still producing usable LSE.  BWD needs saved output for
    delta, so use the streaming MXFP4 forward route that matches the current
    MXFP4 V artifact path instead of the legacy local PV smoke wrapper.
    """
    if q_bf16.shape != k_bf16.shape:
        raise ValueError("q_bf16 and k_bf16 must have the same shape")
    if q_bf16.ndim != 4 or v_bf16.ndim != 4:
        raise ValueError("BF16 source tensors must have shape (B,S,H,D)")
    if q_bf16.shape[:3] != v_bf16.shape[:3]:
        raise ValueError("q_bf16/k_bf16/v_bf16 must agree on B,S,H")
    batch, seqlen, heads, _ = q_bf16.shape
    del batch
    effective_config, runtime_config = _resolve_mxfp4_fwd_config_for_run(
        int(seqlen),
        int(heads),
        None,
    )
    mxfp4_inputs = _fp4_qk_mxfp4_v_inputs_from_bf16_source(
        q_bf16,
        k_bf16,
        v_bf16,
        qk_quant_backend=qk_quant_backend,
    )
    mxfp4_inputs = _prepare_mxfp4_fwd_inputs_for_config(
        mxfp4_inputs,
        seqlen=int(seqlen),
        config=effective_config,
    )
    fwd_config_env = (
        _temporary_environ({"TK_FA4_FP4PV_FWD_CONFIG": runtime_config})
        if runtime_config is not None
        else nullcontext()
    )
    with fwd_config_env:
        out, lse = _run_forward_streaming_live_mxfp4(
            *mxfp4_inputs,
            p_quant_mode=p_quant_mode,
            launch_mode=launch_mode,
            output_only=False,
        )
    return out, lse, f"mxfp4_streaming_live_forward:{effective_config}"


def benchmark_forward_streaming_live_mxfp4_vs_bf16(
    *,
    seqlen: int = 4096,
    seed: int = 0,
    batch: int = 1,
    heads: int = 16,
    device: str | torch.device = "cuda",
    warmup: int = 2,
    iters: int = 5,
    zero_qk: bool = False,
    qk_quant_backend: str = "v5",
    v_quant_mode: str | None = None,
    p_quant_mode: str | None = None,
    mxfp4_fwd_config: str | None = None,
    launch_mode: str = "auto",
    bf16_launch_mode: str = "auto",
    bf16_baseline: str = "both",
    include_output_only: bool = True,
    timeout_ms: float | None = _CUDA_EVENT_TIMEOUT_MS,
) -> dict[str, Any]:
    if warmup < 0:
        raise ValueError("warmup must be >= 0")
    if iters < 1:
        raise ValueError("iters must be >= 1")
    if launch_mode not in ("auto", "persistent", "fullgrid"):
        raise ValueError("launch_mode must be 'auto', 'persistent', or 'fullgrid'")
    if bf16_launch_mode not in ("auto", "persistent", "fullgrid"):
        raise ValueError("bf16_launch_mode must be 'auto', 'persistent', or 'fullgrid'")
    bf16_baseline_norm = str(bf16_baseline).lower()
    if bf16_baseline_norm in ("cute", "cute_dsl", "cute_dsl_fa4", "cute_dsl_fa4_bf16"):
        bf16_baseline_norm = "cute"
    elif bf16_baseline_norm in ("tk", "tk_extension", "regular_fa4_bf16", "regular_fa4"):
        bf16_baseline_norm = "tk"
    elif bf16_baseline_norm != "both":
        raise ValueError("bf16_baseline must be 'both', 'cute', or 'tk'")
    _check_choice("qk_quant_backend", qk_quant_backend, _LIVE_QK_QUANT_BACKENDS)
    mxfp4_fwd_config_env = mxfp4_fwd_config
    unstable_mxfp4_fwd_config = None
    if mxfp4_fwd_config_env == "08380fc_dualaccum":
        mxfp4_fwd_config_env = "dualaccum_legacy"
        unstable_mxfp4_fwd_config = "08380fc_dualaccum"
    effective_mxfp4_fwd_config, runtime_mxfp4_fwd_config = _resolve_mxfp4_fwd_config_for_run(
        seqlen,
        heads,
        mxfp4_fwd_config_env,
    )

    resolved_device = _benchmark_cuda_preflight(
        device,
        what="benchmark_forward_streaming_live_mxfp4_vs_bf16",
    )
    q_bf16, k_bf16, v_bf16 = _make_live_bf16_source_inputs(
        int(seqlen),
        seed=seed,
        batch=batch,
        heads=heads,
        device=resolved_device,
        zero_qk=zero_qk,
    )
    fp4_inputs = _fp4_qk_mxfp4_v_inputs_from_bf16_source(
        q_bf16,
        k_bf16,
        v_bf16,
        qk_quant_backend=qk_quant_backend,
        v_quant_mode=v_quant_mode,
    )
    fp4_inputs = _prepare_mxfp4_fwd_inputs_for_config(
        fp4_inputs,
        seqlen=seqlen,
        config=effective_mxfp4_fwd_config,
    )

    def collect_bf16_baseline(kind: str) -> tuple[dict[str, Any], list[float]]:
        def run_one() -> dict[str, Any]:
            if kind == "cute":
                return run_cute_dsl_fa4_bf16_baseline(
                    q_bf16,
                    k_bf16,
                    v_bf16,
                    timeout_ms=timeout_ms,
                )
            return run_bf16_causal_baseline(
                q_bf16,
                k_bf16,
                v_bf16,
                launch_mode=bf16_launch_mode,
                timeout_ms=timeout_ms,
            )

        for _ in range(warmup):
            run_one()
        record: dict[str, Any] | None = None
        samples: list[float] = []
        for _ in range(iters):
            record = run_one()
            samples.append(float(record["timing_ms"]))
        assert record is not None
        return record, samples

    cute_bf16_record: dict[str, Any] | None = None
    cute_bf16_samples: list[float] = []
    cute_bf16_error: str | None = None
    tk_bf16_record: dict[str, Any] | None = None
    tk_bf16_samples: list[float] = []
    tk_bf16_error: str | None = None

    if bf16_baseline_norm in ("both", "cute"):
        try:
            cute_bf16_record, cute_bf16_samples = collect_bf16_baseline("cute")
        except Exception as exc:
            cute_bf16_error = f"{type(exc).__name__}: {exc}"
            if bf16_baseline_norm == "cute":
                raise

    if bf16_baseline_norm in ("both", "tk"):
        try:
            tk_bf16_record, tk_bf16_samples = collect_bf16_baseline("tk")
        except Exception as exc:
            tk_bf16_error = f"{type(exc).__name__}: {exc}"
            if bf16_baseline_norm == "tk":
                raise

    bf16_record = cute_bf16_record if cute_bf16_record is not None else tk_bf16_record
    bf16_samples = cute_bf16_samples if cute_bf16_record is not None else tk_bf16_samples
    bf16_primary_baseline = (
        "cute_dsl_fa4_bf16"
        if cute_bf16_record is not None
        else "regular_fa4_bf16"
        if tk_bf16_record is not None
        else None
    )
    if bf16_record is None or bf16_primary_baseline is None:
        raise RuntimeError(
            "No BF16 baseline completed. "
            f"cute_dsl_fa4_bf16_error={cute_bf16_error!r}; "
            f"regular_fa4_bf16_error={tk_bf16_error!r}"
        )

    mxfp4_env = (
        _temporary_environ({"TK_FA4_FP4PV_FWD_CONFIG": runtime_mxfp4_fwd_config})
        if runtime_mxfp4_fwd_config is not None
        else nullcontext()
    )
    with mxfp4_env:
        for _ in range(warmup):
            _run_with_ms(
                _run_forward_streaming_live_mxfp4,
                *fp4_inputs,
                p_quant_mode=p_quant_mode,
                launch_mode=launch_mode,
                output_only=False,
                timeout_ms=timeout_ms,
            )
        mxfp4_record: tuple[torch.Tensor, torch.Tensor] | None = None
        mxfp4_samples: list[float] = []
        for _ in range(iters):
            mxfp4_record, ms = _run_with_ms(
                _run_forward_streaming_live_mxfp4,
                *fp4_inputs,
                p_quant_mode=p_quant_mode,
                launch_mode=launch_mode,
                output_only=False,
                timeout_ms=timeout_ms,
            )
            mxfp4_samples.append(float(ms))
        assert mxfp4_record is not None

        output_only_samples: list[float] = []
        if include_output_only:
            for _ in range(warmup):
                _run_with_ms(
                    _run_forward_streaming_live_mxfp4,
                    *fp4_inputs,
                    p_quant_mode=p_quant_mode,
                    launch_mode=launch_mode,
                    output_only=True,
                    timeout_ms=timeout_ms,
                )
            for _ in range(iters):
                _, ms = _run_with_ms(
                    _run_forward_streaming_live_mxfp4,
                    *fp4_inputs,
                    p_quant_mode=p_quant_mode,
                    launch_mode=launch_mode,
                    output_only=True,
                    timeout_ms=timeout_ms,
                )
                output_only_samples.append(float(ms))

    bf16_ms = _median(bf16_samples)
    cute_bf16_ms = _median(cute_bf16_samples) if cute_bf16_samples else float("nan")
    tk_bf16_ms = _median(tk_bf16_samples) if tk_bf16_samples else float("nan")
    mxfp4_ms = _median(mxfp4_samples)
    output_only_ms = _median(output_only_samples) if output_only_samples else float("nan")
    out, lse = mxfp4_record
    comparison = _compare_outputs(out, lse, bf16_record["out"], bf16_record["lse"])
    comparison["timing_ratio"] = float(mxfp4_ms / bf16_ms) if bf16_ms > 0 else float("nan")
    comparison_vs_cute_bf16 = None
    if cute_bf16_record is not None:
        comparison_vs_cute_bf16 = _compare_outputs(
            out,
            lse,
            cute_bf16_record["out"],
            cute_bf16_record["lse"],
        )
        comparison_vs_cute_bf16["timing_ratio"] = (
            float(mxfp4_ms / cute_bf16_ms) if cute_bf16_ms > 0 else float("nan")
        )
    comparison_vs_tk_bf16 = None
    if tk_bf16_record is not None:
        comparison_vs_tk_bf16 = _compare_outputs(
            out,
            lse,
            tk_bf16_record["out"],
            tk_bf16_record["lse"],
        )
        comparison_vs_tk_bf16["timing_ratio"] = (
            float(mxfp4_ms / tk_bf16_ms) if tk_bf16_ms > 0 else float("nan")
        )

    ratio_mxfp4_vs_cute_bf16 = (
        float(mxfp4_ms / cute_bf16_ms)
        if cute_bf16_ms > 0 and math.isfinite(cute_bf16_ms)
        else float("nan")
    )
    ratio_mxfp4_vs_tk_bf16 = (
        float(mxfp4_ms / tk_bf16_ms)
        if tk_bf16_ms > 0 and math.isfinite(tk_bf16_ms)
        else float("nan")
    )
    ratio_output_only_vs_cute_bf16 = (
        float(output_only_ms / cute_bf16_ms)
        if cute_bf16_ms > 0 and math.isfinite(cute_bf16_ms) and math.isfinite(output_only_ms)
        else float("nan")
    )
    ratio_output_only_vs_tk_bf16 = (
        float(output_only_ms / tk_bf16_ms)
        if tk_bf16_ms > 0 and math.isfinite(tk_bf16_ms) and math.isfinite(output_only_ms)
        else float("nan")
    )

    return {
        "seqlen": int(seqlen),
        "batch": int(batch),
        "heads": int(heads),
        "device": str(resolved_device),
        "input_mode": "zero_qk_random_v" if zero_qk else "random_live_fp4",
        "qk_quant_backend": str(qk_quant_backend),
        "v_quant_mode": _normalize_quant_mode_for_backend("mxfp4_v3", v_quant_mode),
        "p_quant_mode": _normalize_quant_mode_for_backend("mxfp4_v3", p_quant_mode),
        "mxfp4_fwd_config": str(effective_mxfp4_fwd_config),
        "mxfp4_fwd_config_requested": str(mxfp4_fwd_config) if mxfp4_fwd_config is not None else None,
        "mxfp4_fwd_config_remapped_from": unstable_mxfp4_fwd_config,
        "launch_mode": str(launch_mode),
        "bf16_launch_mode": str(bf16_record["launch_mode"]),
        "bf16_baseline_requested": str(bf16_baseline),
        "bf16_primary_baseline": str(bf16_primary_baseline),
        "assumes_prequantized_mxfp4_qkv": True,
        "quantization_excluded_from_timing": True,
        "bf16_ms": float(bf16_ms),
        "bf16_samples_ms": bf16_samples,
        "bf16_cute_dsl_fa4_ms": float(cute_bf16_ms),
        "bf16_cute_dsl_fa4_samples_ms": cute_bf16_samples,
        "bf16_cute_dsl_fa4_error": cute_bf16_error,
        "bf16_tk_fa4_ms": float(tk_bf16_ms),
        "bf16_tk_fa4_samples_ms": tk_bf16_samples,
        "bf16_tk_fa4_error": tk_bf16_error,
        "mxfp4_ms": float(mxfp4_ms),
        "mxfp4_samples_ms": mxfp4_samples,
        "mxfp4_output_only_ms": float(output_only_ms),
        "mxfp4_output_only_samples_ms": output_only_samples,
        "ratio_mxfp4_vs_bf16": float(mxfp4_ms / bf16_ms) if bf16_ms > 0 else float("nan"),
        "ratio_mxfp4_vs_bf16_cute_dsl_fa4": ratio_mxfp4_vs_cute_bf16,
        "ratio_mxfp4_vs_bf16_tk_fa4": ratio_mxfp4_vs_tk_bf16,
        "ratio_mxfp4_output_only_vs_bf16": (
            float(output_only_ms / bf16_ms)
            if bf16_ms > 0 and math.isfinite(output_only_ms)
            else float("nan")
        ),
        "ratio_mxfp4_output_only_vs_bf16_cute_dsl_fa4": ratio_output_only_vs_cute_bf16,
        "ratio_mxfp4_output_only_vs_bf16_tk_fa4": ratio_output_only_vs_tk_bf16,
        "speedup_mxfp4_over_bf16": float(bf16_ms / mxfp4_ms) if mxfp4_ms > 0 else float("nan"),
        "speedup_mxfp4_over_bf16_cute_dsl_fa4": (
            float(cute_bf16_ms / mxfp4_ms)
            if mxfp4_ms > 0 and math.isfinite(cute_bf16_ms)
            else float("nan")
        ),
        "speedup_mxfp4_over_bf16_tk_fa4": (
            float(tk_bf16_ms / mxfp4_ms)
            if mxfp4_ms > 0 and math.isfinite(tk_bf16_ms)
            else float("nan")
        ),
        "speedup_mxfp4_output_only_over_bf16": (
            float(bf16_ms / output_only_ms)
            if output_only_ms > 0 and math.isfinite(output_only_ms)
            else float("nan")
        ),
        "speedup_mxfp4_output_only_over_bf16_cute_dsl_fa4": (
            float(cute_bf16_ms / output_only_ms)
            if output_only_ms > 0 and math.isfinite(output_only_ms) and math.isfinite(cute_bf16_ms)
            else float("nan")
        ),
        "speedup_mxfp4_output_only_over_bf16_tk_fa4": (
            float(tk_bf16_ms / output_only_ms)
            if output_only_ms > 0 and math.isfinite(output_only_ms) and math.isfinite(tk_bf16_ms)
            else float("nan")
        ),
        "comparison_vs_bf16": comparison,
        "comparison_vs_bf16_cute_dsl_fa4": comparison_vs_cute_bf16,
        "comparison_vs_bf16_tk_fa4": comparison_vs_tk_bf16,
        "finite": bool(torch.isfinite(out).all().item() and torch.isfinite(lse).all().item()),
    }


def benchmark_forward_mxfp4_vs_localcta_fp4pv(
    *,
    seqlen: int = 4096,
    seed: int = 0,
    batch: int = 1,
    heads: int = 16,
    device: str | torch.device = "cuda",
    warmup: int = 2,
    iters: int = 5,
    zero_qk: bool = False,
    qk_quant_backend: str = "v5",
    local_v_quant_backend: str = "localcta",
    mxfp4_v_quant_mode: str | None = None,
    mxfp4_p_quant_mode: str | None = None,
    mxfp4_fwd_config: str | None = None,
    mxfp4_launch_mode: str = "auto",
    local_launch_mode: str = "persistent",
    include_bf16: bool = True,
    bf16_launch_mode: str = "auto",
    timeout_ms: float | None = _CUDA_EVENT_TIMEOUT_MS,
) -> dict[str, Any]:
    """Compare current MXFP4 forward against the restored localCTA/v5 FP4-PV path.

    This is the apples-to-apples forward comparison for the path used by the
    saved-LSE dV harness: same BF16 Q/K/V source, same Q/K FP4 backend, but
    localCTA-prepared V scales versus MXFP4 V/P scales. Quantization is outside
    the timed region for both candidates.
    """
    if warmup < 0:
        raise ValueError("warmup must be >= 0")
    if iters < 1:
        raise ValueError("iters must be >= 1")
    if mxfp4_launch_mode not in ("auto", "persistent", "fullgrid"):
        raise ValueError("mxfp4_launch_mode must be 'auto', 'persistent', or 'fullgrid'")
    if local_launch_mode not in ("persistent", "fullgrid"):
        raise ValueError("local_launch_mode must be 'persistent' or 'fullgrid'")
