_FORWARD_PRECISION_BF16_SUBPROCESS_CODE = r"""
import gc
import json
import sys
import torch

payload = json.loads(sys.argv[1])
sys.path.insert(0, payload["repo_root"])

from tk_fa4.fp4_pv_experiments import (
    _make_forward_matrix_bf16_inputs,
    _median,
    _median_breakdown,
    run_bf16_causal_baseline,
)

q_bf16, k_bf16, v_bf16 = _make_forward_matrix_bf16_inputs(
    payload["seqlen"],
    input_mode=payload["input_mode"],
    seed=payload["seed"],
    batch=payload["batch"],
    heads=payload["heads"],
    device=payload["device"],
    distribution=payload["distribution"],
    q_distribution=payload["q_distribution"],
    k_distribution=payload["k_distribution"],
    v_distribution=payload["v_distribution"],
)

samples = []
breakdowns = []
for _ in range(payload["warmup"]):
    run_bf16_causal_baseline(q_bf16, k_bf16, v_bf16, launch_mode="auto", timeout_ms=payload["timeout_ms"])
    gc.collect()
    torch.cuda.empty_cache()
    torch.cuda.synchronize(torch.device(payload["device"]))
for _ in range(payload["iters"]):
    rec = run_bf16_causal_baseline(q_bf16, k_bf16, v_bf16, launch_mode="auto", timeout_ms=payload["timeout_ms"])
    samples.append(float(rec["timing_ms"]))
    breakdowns.append({k: float(v) for k, v in rec["timing_breakdown"].items()})
    gc.collect()
    torch.cuda.empty_cache()
    torch.cuda.synchronize(torch.device(payload["device"]))
final = run_bf16_causal_baseline(q_bf16, k_bf16, v_bf16, launch_mode="auto", timeout_ms=payload["timeout_ms"])

result = {
    "launch_mode": final["launch_mode"],
    "bf16_baseline_ms": float(_median(samples)),
    "timing_ms": float(_median(samples)),
    "timing_breakdown": _median_breakdown(breakdowns),
}
print(json.dumps(result))
"""


_FORWARD_PRECISION_COMBO_SUBPROCESS_CODE = r"""
import gc
import json
import sys
import torch

payload = json.loads(sys.argv[1])
sys.path.insert(0, payload["repo_root"])

from tk_fa4.fp4_pv_experiments import (
    _compare_outputs,
    _is_forward_p_mode_experimental,
    _make_forward_matrix_bf16_inputs,
    _median,
    _median_breakdown,
    _run_forward_precision_combo_only,
    _run_with_host_ms,
    _run_with_ms,
    run_forward_precision_reference_baseline,
)

q_bf16, k_bf16, v_bf16 = _make_forward_matrix_bf16_inputs(
    payload["seqlen"],
    input_mode=payload["input_mode"],
    seed=payload["seed"],
    batch=payload["batch"],
    heads=payload["heads"],
    device=payload["device"],
    distribution=payload["distribution"],
    q_distribution=payload["q_distribution"],
    k_distribution=payload["k_distribution"],
    v_distribution=payload["v_distribution"],
)

bf16_samples = []
bf16_breakdowns = []
for _ in range(payload["warmup"]):
    run_forward_precision_reference_baseline(q_bf16, k_bf16, v_bf16, timeout_ms=payload["timeout_ms"])
    gc.collect()
    torch.cuda.empty_cache()
    torch.cuda.synchronize(torch.device(payload["device"]))
for _ in range(payload["iters"]):
    rec = run_forward_precision_reference_baseline(q_bf16, k_bf16, v_bf16, timeout_ms=payload["timeout_ms"])
    bf16_samples.append(float(rec["timing_ms"]))
    bf16_breakdowns.append({k: float(v) for k, v in rec["timing_breakdown"].items()})
    gc.collect()
    torch.cuda.empty_cache()
    torch.cuda.synchronize(torch.device(payload["device"]))
bf16_record = run_forward_precision_reference_baseline(q_bf16, k_bf16, v_bf16, timeout_ms=payload["timeout_ms"])
bf16_out = bf16_record["out"].cpu()
bf16_lse = bf16_record["lse"].cpu()
del bf16_record["out"], bf16_record["lse"]
gc.collect()
torch.cuda.empty_cache()
torch.cuda.synchronize(torch.device(payload["device"]))

timed_run = _run_with_host_ms

samples = []
breakdowns = []
for _ in range(payload["warmup"]):
    _run_forward_precision_combo_only(
        q_bf16,
        k_bf16,
        v_bf16,
        qk_backend=payload["qk_backend"],
        p_mode=payload["p_mode"],
        pv_backend=payload["pv_backend"],
    )
    gc.collect()
    torch.cuda.empty_cache()
    torch.cuda.synchronize(torch.device(payload["device"]))
for _ in range(payload["iters"]):
    (_, _), ms = timed_run(
        _run_forward_precision_combo_only,
        q_bf16,
        k_bf16,
        v_bf16,
        qk_backend=payload["qk_backend"],
        p_mode=payload["p_mode"],
        pv_backend=payload["pv_backend"],
        timeout_ms=payload["timeout_ms"],
    )
    samples.append(float(ms))
    breakdowns.append({"forward_precision_combo_ms": float(ms), "total_ms": float(ms)})
    gc.collect()
    torch.cuda.empty_cache()
    torch.cuda.synchronize(torch.device(payload["device"]))
final_out, final_lse = _run_forward_precision_combo_only(
    q_bf16,
    k_bf16,
    v_bf16,
    qk_backend=payload["qk_backend"],
    p_mode=payload["p_mode"],
    pv_backend=payload["pv_backend"],
)
compare = _compare_outputs(final_out.cpu(), final_lse.cpu(), bf16_out, bf16_lse)
bf16_ms = float(_median(bf16_samples))
combo_ms = float(_median(samples))

result = {
    "launch_mode": payload["launch_mode"],
    "bf16_baseline_ms": bf16_ms,
    "timing_ms": combo_ms,
    "timing_breakdown": _median_breakdown(breakdowns),
    "ratio_vs_bf16_baseline": float(combo_ms / bf16_ms) if bf16_ms > 0 else float("nan"),
    "mean_abs_diff_vs_bf16": compare["mean_abs_diff"],
    "max_abs_diff_vs_bf16": compare["max_abs_diff"],
    "mse_vs_bf16": compare["mse"],
    "rmse_vs_bf16": compare["rmse"],
    "max_rel_diff_vs_bf16": compare["max_rel_diff"],
    "lse_max_abs_diff_vs_bf16": compare["lse_max_abs_diff"],
    "reference_mode": bf16_record["reference_mode"],
    "bf16_kernel_output_finite": bf16_record["bf16_kernel_output_finite"],
    "bf16_kernel_lse_finite": bf16_record["bf16_kernel_lse_finite"],
    "safe_reference_ms": bf16_record["safe_reference_ms"],
    "output_has_nonfinite": compare["output_has_nonfinite"],
    "reference_has_nonfinite": compare["reference_has_nonfinite"],
    "lse_has_nonfinite": compare["lse_has_nonfinite"],
    "reference_lse_has_nonfinite": compare["reference_lse_has_nonfinite"],
    "uses_real_qk_backend": True,
    "uses_real_pv_backend": True,
    "finite_out": not compare["output_has_nonfinite"] and not compare["reference_has_nonfinite"],
    "finite_lse": not compare["lse_has_nonfinite"] and not compare["reference_lse_has_nonfinite"],
    "experimental": _is_forward_p_mode_experimental(payload["p_mode"]),
}
print(json.dumps(result))
"""


