def _run_pv_only_precision_inprocess(
    *,
    seqlen: int,
    input_mode: str,
    p_mode: str,
    pv_backend: str,
    pv_execution_mode: str,
    device: torch.device,
    seed: int,
    batch: int,
    heads: int,
    warmup: int,
    iters: int,
    timeout_ms: float,
    distribution: str = "gaussian",
    q_distribution: str | None = None,
    k_distribution: str | None = None,
    v_distribution: str | None = None,
) -> dict[str, Any]:
    p_mode = _normalize_forward_p_mode(p_mode)
    pv_backend = _normalize_forward_matrix_backend(pv_backend)
    pv_execution_mode = _normalize_pv_execution_mode(pv_execution_mode)
    q_bf16, k_bf16, v_bf16 = _make_forward_matrix_bf16_inputs(
        seqlen,
        input_mode=input_mode,
        seed=seed,
        batch=batch,
        heads=heads,
        device=device,
        distribution=distribution,
        q_distribution=q_distribution,
        k_distribution=k_distribution,
        v_distribution=v_distribution,
    )
    bf16_record = run_forward_precision_reference_baseline(q_bf16, k_bf16, v_bf16, timeout_ms=timeout_ms)
    bf16_out = bf16_record["out"].cpu()
    bf16_lse = bf16_record["lse"].cpu()
    del bf16_record["out"], bf16_record["lse"]
    gc.collect()
    torch.cuda.empty_cache()
    torch.cuda.synchronize(device)
    timed_run = _run_with_host_ms

    samples: list[float] = []
    for _ in range(int(max(warmup, 0))):
        _run_pv_only_precision_combo_only(
            q_bf16,
            k_bf16,
            v_bf16,
            p_mode=p_mode,
            pv_backend=pv_backend,
            pv_execution_mode=pv_execution_mode,
        )
        gc.collect()
        torch.cuda.empty_cache()
        torch.cuda.synchronize(device)
    for _ in range(int(max(iters, 1))):
        (_, _), ms = timed_run(
            _run_pv_only_precision_combo_only,
            q_bf16,
            k_bf16,
            v_bf16,
            p_mode=p_mode,
            pv_backend=pv_backend,
            pv_execution_mode=pv_execution_mode,
            timeout_ms=timeout_ms,
        )
        samples.append(float(ms))
        gc.collect()
        torch.cuda.empty_cache()
        torch.cuda.synchronize(device)
    out, lse = _run_pv_only_precision_combo_only(
        q_bf16,
        k_bf16,
        v_bf16,
        p_mode=p_mode,
        pv_backend=pv_backend,
        pv_execution_mode=pv_execution_mode,
    )
    compare = _compare_outputs(out.cpu(), lse.cpu(), bf16_out, bf16_lse)
    assessment = _assess_pv_precision_result(out.cpu(), bf16_out, pv_execution_mode=pv_execution_mode)
    bf16_ms = float(bf16_record["timing_ms"])
    combo_ms = float(_median(samples))
    return {
        "launch_mode": "orchestrated",
        "pv_execution_mode": pv_execution_mode,
        "kernel_contract_mode": _infer_pv_kernel_contract_mode(
            p_mode=p_mode,
            pv_backend=pv_backend,
            pv_execution_mode=pv_execution_mode,
        ),
        "bf16_baseline_ms": bf16_ms,
        "timing_ms": combo_ms,
        "ratio_vs_bf16_baseline": float(combo_ms / bf16_ms) if bf16_ms > 0 else float("nan"),
        "mean_abs_diff_vs_bf16": compare["mean_abs_diff"],
        "max_abs_diff_vs_bf16": compare["max_abs_diff"],
        "mse_vs_bf16": compare["mse"],
        "rmse_vs_bf16": compare["rmse"],
        "max_rel_diff_vs_bf16": compare["max_rel_diff"],
        "lse_max_abs_diff_vs_bf16": compare["lse_max_abs_diff"],
        "reference_mode": bf16_record["reference_mode"],
        "bf16_kernel_output_finite": bf16_record["bf16_kernel_output_finite"],
        "bf16_kernel_lse_finite": bf16_record["bf16_kernel_lse_finite"],
        "safe_reference_ms": bf16_record["safe_reference_ms"],
        "output_has_nonfinite": compare["output_has_nonfinite"],
        "reference_has_nonfinite": compare["reference_has_nonfinite"],
        "lse_has_nonfinite": compare["lse_has_nonfinite"],
        "reference_lse_has_nonfinite": compare["reference_lse_has_nonfinite"],
        "uses_real_qk_backend": False,
        "uses_real_pv_backend": True,
        "finite_out": not compare["output_has_nonfinite"] and not compare["reference_has_nonfinite"],
        "finite_lse": not compare["lse_has_nonfinite"] and not compare["reference_lse_has_nonfinite"],
        "experimental": _is_forward_p_mode_experimental(p_mode),
        **assessment,
    }


def _run_production_fp4pv_launch_modes_subprocess(
    *,
    seqlens: tuple[int, ...],
    input_modes: tuple[str, ...],
    device: torch.device,
    seed: int,
    batch: int,
    heads: int,
    warmup: int,
    iters: int,
    event_timeout_ms: float,
) -> list[dict[str, Any]]:
    payload = {
        "repo_root": str(_ROOT.parent),
        "seqlens": [int(s) for s in seqlens],
        "input_modes": [str(m) for m in input_modes],
        "device": "cuda:0",
        "seed": int(seed),
        "batch": int(batch),
        "heads": int(heads),
        "warmup": int(max(warmup, 0)),
        "iters": int(max(iters, 1)),
        "event_timeout_ms": float(event_timeout_ms),
    }
    timeout_s = max(
        30.0,
        len(payload["seqlens"]) * len(payload["input_modes"]) * (payload["warmup"] + payload["iters"]) * float(event_timeout_ms) / 1000.0 + 20.0,
    )
    result = _run_json_subprocess(
        code=_PRODUCTION_FP4PV_LAUNCH_MODES_SUBPROCESS_CODE,
        payload=payload,
        device=device,
        what=(
            "production fp4pv launch-modes benchmark "
            f"seqlens={tuple(payload['seqlens'])} input_modes={tuple(payload['input_modes'])}"
        ),
        timeout_s=timeout_s,
    )
    if not isinstance(result, list):
        raise RuntimeError("production fp4pv launch-modes subprocess returned non-list JSON")
    return result


def _run_streaming_speed_case_subprocess(
    *,
    seqlen: int,
    variant: str,
    launch_mode: str,
    input_mode: str,
    device: torch.device,
    seed: int,
    batch: int,
    heads: int,
    qk_quant_backend: str,
    v_quant_backend: str,
    event_timeout_ms: float,
) -> dict[str, Any]:
    visible_device_index = device.index if device.index is not None else torch.cuda.current_device()
    payload = {
        "repo_root": str(_ROOT.parent),
        "seqlen": int(seqlen),
        "variant": variant,
        "launch_mode": launch_mode,
        "input_mode": input_mode,
        "device": "cuda:0",
        "seed": int(seed),
        "batch": int(batch),
        "heads": int(heads),
        "qk_quant_backend": qk_quant_backend,
        "v_quant_backend": v_quant_backend,
        "event_timeout_ms": float(event_timeout_ms),
    }
    launch_plan = _streaming_variant_launch_plan(
        batch=batch,
        heads=heads,
        seqlen=seqlen,
        variant=variant,
        launch_mode=launch_mode,
    )
    timeout_s = max(
        15.0,
        max(1, int(launch_plan["head_chunks"])) * float(event_timeout_ms) / 1000.0 + 5.0,
    )
    env = dict(os.environ)
    env["CUDA_VISIBLE_DEVICES"] = str(visible_device_index)
    try:
        completed = subprocess.run(
            [sys.executable, "-c", _STREAMING_SPEED_CASE_SUBPROCESS_CODE, json.dumps(payload)],
            cwd=str(_ROOT.parent),
            capture_output=True,
            text=True,
            timeout=timeout_s,
            check=False,
            env=env,
        )
    except subprocess.TimeoutExpired as exc:
        raise TimeoutError(
            f"Timed out while running streaming speed subprocess for {variant}/{launch_mode} "
            f"at seqlen={seqlen} after {timeout_s:.0f} s"
        ) from exc
    stdout_lines = [line for line in completed.stdout.splitlines() if line.strip()]
    stderr_text = completed.stderr.strip()
    if completed.returncode != 0:
        detail = stderr_text or (stdout_lines[-1] if stdout_lines else f"return code {completed.returncode}")
        raise RuntimeError(
            f"streaming speed subprocess failed for {variant}/{launch_mode} at seqlen={seqlen}: {detail}"
        )
    if not stdout_lines:
        raise RuntimeError(
            f"streaming speed subprocess produced no JSON output for {variant}/{launch_mode} at seqlen={seqlen}"
        )
    try:
        return json.loads(stdout_lines[-1])
    except json.JSONDecodeError as exc:
        raise RuntimeError(
            f"streaming speed subprocess returned non-JSON output for {variant}/{launch_mode} at seqlen={seqlen}: "
            f"{stdout_lines[-1]}"
        ) from exc


