def _dump_live_quant_p_row_scales_and_bf16_ref_from_scores(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    *,
    return_debug: bool = False,
    allow_unsafe_live: bool = False,
):
    batch, heads, seqlen = _check_fp4_attention_inputs(q, q_sc, q_sg, k, k_sc, k_sg)
    if not return_debug:
        p_bf16_ref, lse = softmax_store_p(q, q_sc, q_sg, k, k_sc, k_sg)
        p_fp4, p_sc_prepared = quantize_p(p_bf16_ref)
        p_sc_rowmajor = _inverse_prepared_scale_swizzle(p_sc_prepared)
        return p_fp4, p_sc_prepared, p_sc_rowmajor, p_sc_rowmajor, p_bf16_ref, lse, None
    ext = _load_backward_experiments_ext()
    _validate_live_quant_dump_range(seqlen, allow_unsafe_live=allow_unsafe_live)
    with _cuda_device_ctx(q.device):
        out = ext.quantize_p_from_scores_with_live_row_scales_and_bf16_ref_debug(q, q_sc, q_sg, k, k_sc, k_sg)

    p_fp4, p_sc_prepared, p_sc_rowmajor_live_raw, p_sc_rowmajor_scan_raw, p_bf16_live, lse_bh1s, row_max, row_sum, tile_amax = out
    lse = lse_bh1s[:, :, 0, :].contiguous()
    _check_cuda_contiguous(p_fp4, "p_fp4")
    _check_cuda_contiguous(p_sc_prepared, "p_sc_prepared")
    _check_cuda_contiguous(p_sc_rowmajor_live_raw, "p_sc_rowmajor_live_raw")
    _check_cuda_contiguous(p_sc_rowmajor_scan_raw, "p_sc_rowmajor_scan_raw")
    _check_cuda_contiguous(p_bf16_live, "p_bf16_live")
    _check_cuda_contiguous(lse, "lse")
    if p_fp4.shape != (batch, heads, seqlen, seqlen // 2):
        raise ValueError("quantize_p_from_scores_with_live_row_scales_and_bf16_ref_debug returned unexpected P_fp4 shape")
    if p_sc_prepared.shape != (batch, heads, seqlen // 128, seqlen // 64, 512):
        raise ValueError("quantize_p_from_scores_with_live_row_scales_and_bf16_ref_debug returned unexpected P_sc_prepared shape")
    if p_sc_rowmajor_live_raw.shape != (batch, heads, seqlen, seqlen // 16):
        raise ValueError("quantize_p_from_scores_with_live_row_scales_and_bf16_ref_debug returned unexpected raw row-major scale shape")
    if p_sc_rowmajor_scan_raw.shape != (batch, heads, seqlen, seqlen // 16):
        raise ValueError("quantize_p_from_scores_with_live_row_scales_and_bf16_ref_debug returned unexpected raw scan row-major scale shape")
    if p_bf16_live.shape != (batch, heads, seqlen, seqlen):
        raise ValueError("quantize_p_from_scores_with_live_row_scales_and_bf16_ref_debug returned unexpected P_bf16_live shape")
    if lse.shape != (batch, heads, seqlen):
        raise ValueError("quantize_p_from_scores_with_live_row_scales_and_bf16_ref_debug returned unexpected LSE shape")
    p_bf16_ref = p_bf16_live.contiguous()
    debug = {
        "row_max": row_max,
        "row_sum": row_sum,
        "tile_amax": tile_amax,
        "p_bf16_live": p_bf16_live,
    }
    return p_fp4, p_sc_prepared, p_sc_rowmajor_live_raw, p_sc_rowmajor_scan_raw, p_bf16_ref, lse, debug


def _build_live_scale_oracle_from_scores(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    *,
    return_debug: bool = False,
    allow_unsafe_live: bool = False,
    include_stored_reference: bool = False,
) -> dict[str, Any]:
    if not return_debug:
        p_bf16_ref, lse = softmax_store_p(q, q_sc, q_sg, k, k_sc, k_sg)
        p_fp4_live, p_sc_prepared_live = quantize_p(p_bf16_ref)
        p_sc_rowmajor_live = _inverse_prepared_scale_swizzle(p_sc_prepared_live)
        record: dict[str, Any] = {
            "reference_mode": "stored_quantize_p_reference",
            "p_fp4_live": p_fp4_live,
            "p_sc_prepared_live": p_sc_prepared_live,
            "p_bf16_ref": p_bf16_ref,
            "p_fp4_ref": None,
            "p_sc_prepared_ref": p_sc_prepared_live,
            "p_sc_rowmajor_live_raw": p_sc_rowmajor_live,
            "p_sc_rowmajor_scan_raw": p_sc_rowmajor_live,
            "p_sc_rowmajor_live": p_sc_rowmajor_live,
            "p_sc_rowmajor_ref": p_sc_rowmajor_live,
            "p_sc_prepared_scan_ref": p_sc_prepared_live,
            "p_sc_rowmajor_scan_ref": p_sc_rowmajor_live,
            "lse": lse,
        }
    else:
        p_fp4_live, p_sc_prepared_live, p_sc_rowmajor_live_raw, p_sc_rowmajor_scan_raw, p_bf16_ref, lse, debug = _dump_live_quant_p_row_scales_and_bf16_ref_from_scores(
            q,
            q_sc,
            q_sg,
            k,
            k_sc,
            k_sg,
            return_debug=True,
            allow_unsafe_live=allow_unsafe_live,
        )
        tile_amax = debug["tile_amax"]
        p_sc_rowmajor_scan_ref = _apply_outer_tile_scale_to_rowmajor_scales(p_sc_rowmajor_scan_raw, tile_amax)
        p_sc_prepared_scan_ref = _forward_prepared_scale_swizzle(p_sc_rowmajor_scan_ref)
        record = {
            "reference_mode": "scan_rowmajor_plus_tile_amax",
            "p_fp4_live": p_fp4_live,
            "p_sc_prepared_live": p_sc_prepared_live,
            "p_bf16_ref": p_bf16_ref,
            "p_fp4_ref": None,
            "p_sc_prepared_ref": p_sc_prepared_scan_ref,
            "p_sc_rowmajor_live_raw": p_sc_rowmajor_live_raw,
            "p_sc_rowmajor_scan_raw": p_sc_rowmajor_scan_raw,
            "p_sc_rowmajor_live": _inverse_prepared_scale_swizzle(p_sc_prepared_live),
            "p_sc_rowmajor_ref": p_sc_rowmajor_scan_ref,
            "p_sc_prepared_scan_ref": p_sc_prepared_scan_ref,
            "p_sc_rowmajor_scan_ref": p_sc_rowmajor_scan_ref,
            "lse": lse,
        }
    if include_stored_reference:
        p_fp4_ref, p_sc_prepared_ref = quantize_p(record["p_bf16_ref"])
        record["p_fp4_ref"] = p_fp4_ref
        record["p_sc_prepared_stored_ref"] = p_sc_prepared_ref
        record["p_sc_rowmajor_stored_ref"] = _inverse_prepared_scale_swizzle(p_sc_prepared_ref)
    if return_debug:
        record["debug"] = debug
    return record


def _apply_outer_tile_scale_to_rowmajor_scales(
    sc_rowmajor_raw: torch.Tensor,
    tile_amax: torch.Tensor,
) -> torch.Tensor:
    _check_cuda_contiguous(sc_rowmajor_raw, "sc_rowmajor_raw")
    _check_cuda_contiguous(tile_amax, "tile_amax")
    if sc_rowmajor_raw.dtype != torch.float8_e4m3fn:
        raise ValueError("sc_rowmajor_raw must have dtype torch.float8_e4m3fn")
    if sc_rowmajor_raw.ndim != 4:
        raise ValueError("sc_rowmajor_raw must have shape (B,H,rows,cols/16)")
    if tile_amax.ndim != 4:
        raise ValueError("tile_amax must have shape (B,H,rows/128,cols/128)")

    batch, heads, rows, groups = sc_rowmajor_raw.shape
    if rows % 128 != 0:
        raise ValueError("row count must be divisible by 128")
    if groups % 8 != 0:
        raise ValueError("scale-group count must be divisible by 8")
    m_blocks = rows // 128
    k_tiles = groups // 8
    if tile_amax.shape != (batch, heads, m_blocks, k_tiles):
        raise ValueError(f"tile_amax must have shape {(batch, heads, m_blocks, k_tiles)}")

    scales = sc_rowmajor_raw.float().view(batch, heads, m_blocks, 128, k_tiles, 8)
    sg = (tile_amax.float() / _FP4PV_LOCALCTA_GLOBAL_SCALE_NUM).view(batch, heads, m_blocks, 1, k_tiles, 1)
    scales = scales * sg
    scales = torch.where(torch.isfinite(scales) & (scales >= 0.0), scales, torch.zeros_like(scales))
    return scales.view(batch, heads, rows, groups).to(torch.float8_e4m3fn).contiguous()


def measure_live_kernel_repeatability(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
    *,
    iters: int = 4,
    allow_unsafe_live: bool = False,
) -> dict[str, Any]:
    if iters < 2:
        raise ValueError("measure_live_kernel_repeatability expects iters >= 2")

    batch, heads, seqlen = _check_fp4_attention_inputs(q, q_sc, q_sg, k, k_sc, k_sg)
    _check_prequantized_v(v_fp4, v_sc_prepared, batch, heads, seqlen)
    _validate_live_kernel_range(seqlen, allow_unsafe_live=allow_unsafe_live)

    ref_out = ref_lse = None
    out_max_diffs: list[float] = []
    out_mean_diffs: list[float] = []
    lse_max_diffs: list[float] = []
    output_abs_mean_per_run: list[float] = []
    output_nan_runs: list[bool] = []
    lse_nan_runs: list[bool] = []

    for run_idx in range(iters):
        out, lse = _run_fp4pv_baseline(q, q_sc, q_sg, k, k_sc, k_sg, v_fp4, v_sc_prepared)
        out_f = out.float()
        lse_f = lse.float()
        output_abs_mean_per_run.append(float(out_f.abs().mean().item()))
        output_nan_runs.append(bool(torch.isnan(out_f).any().item()))
        lse_nan_runs.append(bool(torch.isnan(lse_f).any().item()))
        if run_idx == 0:
            ref_out = out_f.clone()
            ref_lse = lse_f.clone()
            continue
        out_delta = (ref_out - out_f).abs()
        lse_delta = (ref_lse - lse_f).abs()
        out_max_diffs.append(float(out_delta.max().item()))
        out_mean_diffs.append(float(out_delta.mean().item()))
        lse_max_diffs.append(float(lse_delta.max().item()))

    return {
        "iters": iters,
        "output_abs_mean_per_run": output_abs_mean_per_run,
        "output_nan_runs": output_nan_runs,
        "lse_nan_runs": lse_nan_runs,
        "max_abs_diff_vs_run0": max(out_max_diffs),
        "mean_abs_diff_vs_run0": max(out_mean_diffs),
        "lse_max_abs_diff_vs_run0": max(lse_max_diffs),
        "repeatable": (
            not any(output_nan_runs)
            and not any(lse_nan_runs)
            and max(out_max_diffs) == 0.0
            and max(lse_max_diffs) == 0.0
        ),
    }


def measure_live_quant_dump_repeatability(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    *,
    iters: int = 4,
    allow_unsafe_live: bool = False,
) -> dict[str, Any]:
    if iters < 2:
        raise ValueError("measure_live_quant_dump_repeatability expects iters >= 2")

    _check_fp4_attention_inputs(q, q_sc, q_sg, k, k_sc, k_sg)

    dump_runs: list[torch.Tensor] = []
    lse_runs: list[torch.Tensor] = []
    for _ in range(iters):
        _, p_sc_prepared, lse = dump_live_quant_p_from_scores(
            q,
            q_sc,
            q_sg,
            k,
            k_sc,
            k_sg,
            allow_unsafe_live=allow_unsafe_live,
        )
        _wait_for_current_stream(
            q.device,
            timeout_ms=_CUDA_EVENT_TIMEOUT_MS,
            what="live quant dump repeatability sample",
        )
        dump_runs.append(p_sc_prepared.float().clone())
        lse_runs.append(lse.float().clone())

    summary = _live_dump_repeatability_summary(dump_runs, lse_runs)
    summary["repeatable"] = (
        not any(summary["scale_has_nan_runs"])
        and summary["max_abs_diff_vs_run0"] == 0.0
        and summary["lse_max_abs_diff_vs_run0"] == 0.0
    )
    return summary


def diagnose_live_quant_dump_scales(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    *,
    repeatability_iters: int = 3,
    allow_unsafe_live: bool = False,
    include_stored_reference: bool = False,
) -> dict[str, Any]:
    oracle = _build_live_scale_oracle_from_scores(
        q,
        q_sc,
        q_sg,
        k,
        k_sc,
        k_sg,
        return_debug=False,
        allow_unsafe_live=allow_unsafe_live,
        include_stored_reference=include_stored_reference,
    )

    p_sc_live = oracle["p_sc_prepared_live"]
    p_sc_scan_ref = oracle["p_sc_prepared_ref"]
    scale_delta_scan = (p_sc_live.float() - p_sc_scan_ref.float()).abs()

    result: dict[str, Any] = {
        "reference_mode": oracle["reference_mode"],
        "scale_max_abs_diff_vs_scan_ref": float(scale_delta_scan.max().item()),
        "scale_mean_abs_diff_vs_scan_ref": float(scale_delta_scan.mean().item()),
        "scale_dump_has_nan": bool(torch.isnan(p_sc_live).any().item()),
        "scale_ref_has_nan": bool(torch.isnan(p_sc_scan_ref).any().item()),
        "head_scale_diff_vs_scan_ref": _head_scale_diff_summary(p_sc_live, p_sc_scan_ref),
        "rowmajor_raw_mean_abs_diff": float((oracle["p_sc_rowmajor_live_raw"].float() - oracle["p_sc_rowmajor_scan_raw"].float()).abs().mean().item()),
        "rowmajor_raw_max_abs_diff": float((oracle["p_sc_rowmajor_live_raw"].float() - oracle["p_sc_rowmajor_scan_raw"].float()).abs().max().item()),
        "repeatability": measure_live_quant_dump_repeatability(
            q,
            q_sc,
            q_sg,
            k,
            k_sc,
            k_sg,
            iters=repeatability_iters,
            allow_unsafe_live=allow_unsafe_live,
        ),
    }
    if include_stored_reference:
        p_bf16_ref, lse_ref = softmax_store_p(q, q_sc, q_sg, k, k_sc, k_sg)
        p_fp4_ref = oracle["p_fp4_ref"]
        p_sc_stored_ref = oracle["p_sc_prepared_stored_ref"]
        lse_dump = oracle["lse"]
        scale_delta_stored = (p_sc_live.float() - p_sc_stored_ref.float()).abs()
        lse_delta = (lse_dump.float() - lse_ref.float()).abs()
        result.update({
            "p_bf16_ref": p_bf16_ref,
            "p_fp4_ref": p_fp4_ref,
            "scale_max_abs_diff_vs_stored": float(scale_delta_stored.max().item()),
            "scale_mean_abs_diff_vs_stored": float(scale_delta_stored.mean().item()),
            "head_scale_diff_vs_stored": _head_scale_diff_summary(p_sc_live, p_sc_stored_ref),
            "lse_max_abs_diff_vs_stored": float(lse_delta.max().item()),
        })
    return result


def _measure_variant_repeatability(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
    *,
    variant: str,
    iters: int = 3,
    allow_unsafe_live: bool = False,
) -> dict[str, Any]:
    if variant == "live_kernel_fused":
        return measure_live_kernel_repeatability(
            q,
            q_sc,
            q_sg,
            k,
            k_sc,
            k_sg,
            v_fp4,
            v_sc_prepared,
            iters=iters,
            allow_unsafe_live=allow_unsafe_live,
        )

    ref_out = ref_lse = None
    out_max_diffs: list[float] = []
    out_mean_diffs: list[float] = []
    lse_max_diffs: list[float] = []
    output_abs_mean_per_run: list[float] = []
    output_nan_runs: list[bool] = []
    lse_nan_runs: list[bool] = []

    for run_idx in range(iters):
        record = run_variant(
            q,
            q_sc,
            q_sg,
            k,
            k_sc,
            k_sg,
            v_fp4,
            v_sc_prepared,
            variant=variant,
            return_debug=False,
            allow_unsafe_live=allow_unsafe_live,
        )
        out = record["out"].float()
        lse = record["lse"].float()
        output_abs_mean_per_run.append(float(out.abs().mean().item()))
        output_nan_runs.append(bool(torch.isnan(out).any().item()))
        lse_nan_runs.append(bool(torch.isnan(lse).any().item()))
        if run_idx == 0:
            ref_out = out.clone()
            ref_lse = lse.clone()
            continue
        out_delta = (ref_out - out).abs()
        lse_delta = (ref_lse - lse).abs()
        out_max_diffs.append(float(out_delta.max().item()))
        out_mean_diffs.append(float(out_delta.mean().item()))
        lse_max_diffs.append(float(lse_delta.max().item()))

    return {
        "iters": iters,
        "output_abs_mean_per_run": output_abs_mean_per_run,
        "output_nan_runs": output_nan_runs,
        "lse_nan_runs": lse_nan_runs,
        "max_abs_diff_vs_run0": max(out_max_diffs),
        "mean_abs_diff_vs_run0": max(out_mean_diffs),
        "lse_max_abs_diff_vs_run0": max(lse_max_diffs),
        "repeatable": (
            not any(output_nan_runs)
            and not any(lse_nan_runs)
            and max(out_max_diffs) == 0.0
            and max(lse_max_diffs) == 0.0
        ),
    }


def softmax_store_p(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Materialize BF16 P via exact QK-fp4 attention probes with identity BF16 V tiles."""
    ext = _load_backward_experiments_ext()
    batch, heads, seqlen = _check_fp4_attention_inputs(q, q_sc, q_sg, k, k_sc, k_sg)

    p_bf16 = torch.empty((batch, heads, seqlen, seqlen), dtype=torch.bfloat16, device=q.device)
    o_tile = torch.empty((batch, seqlen, heads, _D_VO), dtype=torch.bfloat16, device=q.device)
    lse_bh1s = torch.empty((batch, heads, 1, seqlen), dtype=torch.float32, device=q.device)
    probe_v, eye = _make_identity_value_probe(batch, seqlen, heads, q.device)

    prev_slice: slice | None = None
    for tile_start in range(0, seqlen, _TILE):
        tile_slice = slice(tile_start, tile_start + _TILE)
        if prev_slice is not None:
            probe_v[:, prev_slice, :, :].zero_()
        probe_v[:, tile_slice, :, :].copy_(eye.expand(batch, -1, heads, -1))
        with _cuda_device_ctx(q.device):
            ext.forward_persistent(q, q_sc, q_sg, k, k_sc, k_sg, probe_v, o_tile, lse_bh1s)
        p_bf16[:, :, :, tile_slice] = o_tile.permute(0, 2, 1, 3).contiguous()
        prev_slice = tile_slice

    if prev_slice is not None:
        probe_v[:, prev_slice, :, :].zero_()
    return p_bf16, lse_bh1s[:, :, 0, :].contiguous()


def _quantize_p_localcta(p_bf16: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
    local_q = _load_localcta_quant()
    batch, heads, seqlen = _check_stored_p(p_bf16)

    p_2d = p_bf16.contiguous().view(batch * heads * seqlen, seqlen)
    with _cuda_device_ctx(p_bf16.device):
        row_fp4, row_sc_prepared, _, _, _, _ = local_q.tk_localcta_quantize_for_gemm_prepared(
            p_2d, False, True
        )
    p_fp4 = row_fp4.view(batch, heads, seqlen, seqlen // 2)
    p_sc_prepared = row_sc_prepared.view(batch, heads, seqlen // 128, seqlen // 64, 512)
    return p_fp4, p_sc_prepared


def _quantize_p_v5(p_bf16: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
    batch, heads, seqlen = _check_stored_p(p_bf16)
    p_fp4 = _zeros_fp4((batch, heads, seqlen, seqlen // 2), p_bf16.device)
    p_sc_prepared = torch.empty((batch, heads, seqlen // 128, seqlen // 64, 512), device=p_bf16.device, dtype=torch.float8_e4m3fn)
    for b in range(batch):
        for h in range(heads):
            rec = _quantize_rows_2d_v5(p_bf16[b, h].contiguous())
            _copy_fp4_tensor_(p_fp4[b, h], rec["fp4"])
            p_sc_prepared[b, h].copy_(_apply_scalar_sg_to_prepared_scales(rec["scales"], rec["sg_scalar"]))
    return p_fp4.contiguous(), p_sc_prepared.contiguous()


def quantize_p(p_bf16: torch.Tensor, *, backend: str = "localcta") -> tuple[torch.Tensor, torch.Tensor]:
    """Quantize stored BF16 P into NVFP4 rowwise storage consumable by pv_from_p."""
    _require_finite_tensor(p_bf16, "p_bf16")
    _check_choice("backend", backend, _REAL_NVFP4_PV_BACKENDS)
    if backend == "localcta":
        return _quantize_p_localcta(p_bf16)
    if backend == "v5":
        return _quantize_p_v5(p_bf16)
    raise ValueError("unreachable P backend branch")


def _localcta_pv_into(
    p_fp4: torch.Tensor,
    p_sc_prepared: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
    out_bhsd: torch.Tensor | None = None,
) -> torch.Tensor:
    local_gemm = _load_localcta_gemm()
    _check_cuda_contiguous(p_fp4, "p_fp4")
    _check_cuda_contiguous(p_sc_prepared, "p_sc_prepared")
    _check_cuda_contiguous(v_fp4, "v_fp4")
    _check_cuda_contiguous(v_sc_prepared, "v_sc_prepared")
    if p_fp4.dtype != torch.float4_e2m1fn_x2:
        raise ValueError("p_fp4 must have dtype torch.float4_e2m1fn_x2")
    if p_sc_prepared.dtype != torch.float8_e4m3fn:
        raise ValueError("p_sc_prepared must have dtype torch.float8_e4m3fn")
    if v_fp4.dtype != torch.float4_e2m1fn_x2:
        raise ValueError("v_fp4 must have dtype torch.float4_e2m1fn_x2")
    if v_sc_prepared.dtype != torch.float8_e4m3fn:
        raise ValueError("v_sc_prepared must have dtype torch.float8_e4m3fn")
    if p_fp4.ndim != 4 or p_sc_prepared.ndim != 5:
        raise ValueError("p_fp4/p_sc_prepared must have shapes (B,H,M,K/2) and (B,H,M/128,K/64,512)")
    if v_fp4.ndim != 4 or v_sc_prepared.ndim != 5:
        raise ValueError("v_fp4/v_sc_prepared must have shapes (B,H,Dvo,K/2) and (B,H,Dvo/128,K/64,512)")

    batch, heads, rows, packed_k = p_fp4.shape
    k_cols = packed_k * 2
    dvo = v_fp4.shape[2]
    if rows % _TILE != 0 or k_cols % _TILE != 0:
        raise ValueError("localCTA PV expects M and K to be multiples of 128")
    if p_sc_prepared.shape != (batch, heads, rows // 128, k_cols // 64, 512):
        raise ValueError(f"p_sc_prepared must have shape {(batch, heads, rows // 128, k_cols // 64, 512)}")
    if dvo % _TILE != 0:
        raise ValueError("V head dim must be divisible by 128")
    if v_fp4.shape != (batch, heads, dvo, packed_k):
        raise ValueError(f"v_fp4 must have shape {(batch, heads, dvo, packed_k)}")
    if v_sc_prepared.shape != (batch, heads, dvo // 128, k_cols // 64, 512):
        raise ValueError(f"v_sc_prepared must have shape {(batch, heads, dvo // 128, k_cols // 64, 512)}")

    p_sg = _unit_sg_chunks(rows, k_cols, p_fp4.device)
    v_sg = _unit_sg_chunks(dvo, k_cols, p_fp4.device)
    if out_bhsd is None:
        out_bhsd = torch.zeros((batch, heads, rows, dvo), dtype=torch.bfloat16, device=p_fp4.device)
    else:
        _check_cuda_contiguous(out_bhsd, "out_bhsd")
        if out_bhsd.dtype != torch.bfloat16:
            raise ValueError("out_bhsd must be bfloat16")
        if out_bhsd.shape != (batch, heads, rows, dvo):
            raise ValueError(f"out_bhsd must have shape {(batch, heads, rows, dvo)}")
        out_bhsd.zero_()

    with _cuda_device_ctx(p_fp4.device):
        for b in range(batch):
            for h in range(heads):
                local_gemm.nvfp4_localcta_gemm(
                    p_fp4[b, h],
                    p_sc_prepared[b, h],
                    p_sg,
                    v_fp4[b, h],
                    v_sc_prepared[b, h],
                    v_sg,
                    out_bhsd[b, h],
                )
    return out_bhsd


def _native_pv_from_p(
    p_fp4: torch.Tensor,
    p_sc_prepared: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
) -> torch.Tensor:
    out_bhsd = _localcta_pv_into(p_fp4, p_sc_prepared, v_fp4, v_sc_prepared)
    return out_bhsd.permute(0, 2, 1, 3).contiguous()


def _inverse_prepared_scale_swizzle(sc_prepared: torch.Tensor) -> torch.Tensor:
    _check_cuda_contiguous(sc_prepared, "sc_prepared")
    if sc_prepared.dtype != torch.float8_e4m3fn:
        raise ValueError("sc_prepared must have dtype torch.float8_e4m3fn")
    if sc_prepared.ndim != 5 or sc_prepared.shape[-1] != 512:
        raise ValueError("sc_prepared must have shape (B,H,M/128,K/64,512)")

    batch, heads, m_blocks, n_blocks, _ = sc_prepared.shape
    unswizzled = sc_prepared.view(batch, heads, m_blocks, n_blocks, 32, 4, 4)
    unswizzled = unswizzled.transpose(-2, -3).contiguous()
    unswizzled = unswizzled.view(batch, heads, m_blocks, n_blocks, 128, 4)
    unswizzled = unswizzled.transpose(3, 4).contiguous()
    return unswizzled.view(batch, heads, m_blocks * 128, n_blocks * 4)


def _forward_prepared_scale_swizzle(sc_rowmajor: torch.Tensor) -> torch.Tensor:
    _check_cuda_contiguous(sc_rowmajor, "sc_rowmajor")
    if sc_rowmajor.dtype != torch.float8_e4m3fn:
        raise ValueError("sc_rowmajor must have dtype torch.float8_e4m3fn")
    if sc_rowmajor.ndim != 4:
        raise ValueError("sc_rowmajor must have shape (B,H,rows,cols/16)")

    batch, heads, rows, groups = sc_rowmajor.shape
    if rows % 128 != 0:
        raise ValueError("row count must be divisible by 128")
    if groups % 4 != 0:
        raise ValueError("scale-group count must be divisible by 4")

    m_blocks = rows // 128
    n_blocks = groups // 4
    prepared = sc_rowmajor.view(batch, heads, m_blocks, 128, n_blocks, 4)
    prepared = prepared.transpose(3, 4).contiguous()
    prepared = prepared.view(batch, heads, m_blocks, n_blocks, 4, 32, 4)
    prepared = prepared.transpose(-2, -3).contiguous()
    return prepared.view(batch, heads, m_blocks, n_blocks, 512)


def _raw_dump_scales_to_prepared(sc_raw_dump: torch.Tensor) -> torch.Tensor:
    _check_cuda_contiguous(sc_raw_dump, "sc_raw_dump")
    if sc_raw_dump.dtype != torch.float8_e4m3fn:
        raise ValueError("sc_raw_dump must have dtype torch.float8_e4m3fn")
    if sc_raw_dump.ndim != 5 or sc_raw_dump.shape[-1] != 512:
        raise ValueError("sc_raw_dump must have shape (B,H,M/128,K/64,512)")

    batch, heads, m_blocks, slab_blocks, _ = sc_raw_dump.shape
    if slab_blocks % 2 != 0:
        raise ValueError("raw dump scale slab count must be even")

    k_tiles = slab_blocks // 2
    rowmajor = sc_raw_dump.view(batch, heads, m_blocks, k_tiles, 2, 512)
    rowmajor = rowmajor.view(batch, heads, m_blocks, k_tiles, 128, 8)
    rowmajor = rowmajor.permute(0, 1, 2, 4, 3, 5).contiguous()
    rowmajor = rowmajor.view(batch, heads, m_blocks * 128, k_tiles * 8)
    return _forward_prepared_scale_swizzle(rowmajor)


def _sanitize_live_dump_prepared_scales(sc_prepared: torch.Tensor) -> torch.Tensor:
    sc = _inverse_prepared_scale_swizzle(sc_prepared).float()
    batch, heads, rows, groups = sc.shape
    valid_groups = ((torch.arange(rows, device=sc.device) + 16) // 16).view(1, 1, rows, 1)
    group_idx = torch.arange(groups, device=sc.device).view(1, 1, 1, groups)
    valid_mask = group_idx < valid_groups
    sc = torch.nan_to_num(sc, nan=0.0, posinf=_LIVE_DUMP_SCALE_MAX, neginf=0.0).clamp_(0.0, _LIVE_DUMP_SCALE_MAX)
    sc = torch.where(valid_mask, sc, torch.zeros_like(sc))
    return _forward_prepared_scale_swizzle(sc.to(torch.float8_e4m3fn).contiguous())


def _reconstruct_normalized_p_from_live_dump(
    p_fp4: torch.Tensor,
    p_sc_prepared: torch.Tensor,
    row_max_hist: torch.Tensor,
    row_sum_hist: torch.Tensor,
    q_sg: torch.Tensor,
    k_sg: torch.Tensor,
) -> torch.Tensor:
    p_live = _dequantize_prepared_fp4_rows_for_debug(p_fp4, p_sc_prepared).float()
    batch, heads, seqlen, _ = p_live.shape
    tile_count = seqlen // _TILE
    if row_max_hist.shape != (batch, heads, seqlen, tile_count):
        raise ValueError(f"row_max_hist must have shape {(batch, heads, seqlen, tile_count)}")
    if row_sum_hist.shape != (batch, heads, seqlen, tile_count):
        raise ValueError(f"row_sum_hist must have shape {(batch, heads, seqlen, tile_count)}")

    row_max = row_max_hist.float()
    row_sum = row_sum_hist.float()
    row_ids = torch.arange(seqlen, device=p_live.device)
    valid_tiles = (row_ids // _TILE) + 1
    tile_ids = torch.arange(tile_count, device=p_live.device)
    final_tile_idx = (valid_tiles - 1).view(1, 1, seqlen, 1).expand(batch, heads, seqlen, 1)
    final_max = torch.gather(row_max, -1, final_tile_idx)
    final_sum = torch.gather(row_sum, -1, final_tile_idx)

    scale_log2 = (
        _LIVE_DUMP_LOG2E_OVER_SQRT_D
        * q_sg.float()
        * k_sg.float()
    ).view(batch, heads, 1, 1)
    tile_factors = torch.exp2((row_max - final_max) * scale_log2) / final_sum.clamp_min(torch.finfo(torch.float32).tiny)
    valid_tile_mask = tile_ids.view(1, 1, 1, tile_count) < valid_tiles.view(1, 1, seqlen, 1)
    valid_row_mask = torch.isfinite(final_sum) & (final_sum > 0)
    tile_factors = torch.where(valid_tile_mask & valid_row_mask, tile_factors, torch.zeros_like(tile_factors))

    out = (p_live.view(batch, heads, seqlen, tile_count, _TILE) * tile_factors.unsqueeze(-1)).reshape(batch, heads, seqlen, seqlen)
    causal_mask = torch.arange(seqlen, device=p_live.device).view(1, 1, 1, seqlen) <= row_ids.view(1, 1, seqlen, 1)
    out = torch.where(causal_mask, out, torch.zeros_like(out))
    return out.to(torch.bfloat16)


def _reconstruct_normalized_p_from_live_bf16_dump(
    p_bf16_live: torch.Tensor,
    row_max_hist: torch.Tensor,
    row_sum_hist: torch.Tensor,
    q_sg: torch.Tensor,
    k_sg: torch.Tensor,
) -> torch.Tensor:
    _check_cuda_contiguous(p_bf16_live, "p_bf16_live")
    if p_bf16_live.dtype != torch.bfloat16:
        raise ValueError("p_bf16_live must have dtype torch.bfloat16")
    if p_bf16_live.ndim != 4:
        raise ValueError("p_bf16_live must have shape (B,H,S,S)")

    p_live = p_bf16_live.float()
    batch, heads, seqlen, cols = p_live.shape
    if cols != seqlen:
        raise ValueError("p_bf16_live must be square in its last two dimensions")
    tile_count = seqlen // _TILE
    if row_max_hist.shape != (batch, heads, seqlen, tile_count):
        raise ValueError(f"row_max_hist must have shape {(batch, heads, seqlen, tile_count)}")
    if row_sum_hist.shape != (batch, heads, seqlen, tile_count):
        raise ValueError(f"row_sum_hist must have shape {(batch, heads, seqlen, tile_count)}")

    row_max = row_max_hist.float()
    row_sum = row_sum_hist.float()
    row_ids = torch.arange(seqlen, device=p_live.device)
    valid_tiles = (row_ids // _TILE) + 1
    tile_ids = torch.arange(tile_count, device=p_live.device)
    final_tile_idx = (valid_tiles - 1).view(1, 1, seqlen, 1).expand(batch, heads, seqlen, 1)
    final_max = torch.gather(row_max, -1, final_tile_idx)
    final_sum = torch.gather(row_sum, -1, final_tile_idx)

    scale_log2 = (
        _LIVE_DUMP_LOG2E_OVER_SQRT_D
        * q_sg.float()
        * k_sg.float()
    ).view(batch, heads, 1, 1)
    tile_factors = torch.exp2((row_max - final_max) * scale_log2) / final_sum.clamp_min(torch.finfo(torch.float32).tiny)
    valid_tile_mask = tile_ids.view(1, 1, 1, tile_count) < valid_tiles.view(1, 1, seqlen, 1)
    valid_row_mask = torch.isfinite(final_sum) & (final_sum > 0)
    tile_factors = torch.where(valid_tile_mask & valid_row_mask, tile_factors, torch.zeros_like(tile_factors))

    out = (p_live.view(batch, heads, seqlen, tile_count, _TILE) * tile_factors.unsqueeze(-1)).reshape(batch, heads, seqlen, seqlen)
    causal_mask = torch.arange(seqlen, device=p_live.device).view(1, 1, 1, seqlen) <= row_ids.view(1, 1, seqlen, 1)
    out = torch.where(causal_mask, out, torch.zeros_like(out))
    return out.to(torch.bfloat16)


def _dequantize_prepared_fp4_rows_for_debug(
    p_fp4: torch.Tensor,
    p_sc_prepared: torch.Tensor,
) -> torch.Tensor:
    _check_cuda_contiguous(p_fp4, "p_fp4")
    _check_cuda_contiguous(p_sc_prepared, "p_sc_prepared")
    if p_fp4.dtype != torch.float4_e2m1fn_x2:
        raise ValueError("p_fp4 must have dtype torch.float4_e2m1fn_x2")
    if p_sc_prepared.dtype != torch.float8_e4m3fn:
        raise ValueError("p_sc_prepared must have dtype torch.float8_e4m3fn")
    if p_fp4.ndim != 4 or p_sc_prepared.ndim != 5:
        raise ValueError("expected (B,H,M,K/2) and (B,H,M/128,K/64,512) tensors")

    batch, heads, rows, packed_cols = p_fp4.shape
    cols = packed_cols * 2
    if p_sc_prepared.shape != (batch, heads, rows // 128, cols // 64, 512):
        raise ValueError(f"p_sc_prepared must have shape {(batch, heads, rows // 128, cols // 64, 512)}")

    fp4_rows_2d = p_fp4.view(batch * heads * rows, packed_cols)
    fp32_rows = _fp4x2_to_fp32_for_debug(fp4_rows_2d)
    scales = _inverse_prepared_scale_swizzle(p_sc_prepared).view(batch * heads * rows, cols // 16)
    return (fp32_rows * scales.to(torch.float32).repeat_interleave(16, dim=-1)).view(batch, heads, rows, cols)


def _dequantize_live_fp4_qk_for_debug(
    x_fp4: torch.Tensor,
    x_sc: torch.Tensor,
    x_sg: torch.Tensor,
) -> torch.Tensor:
    """Dequantize live-format FP4 Q/K tensors back to BF16 for debug/reference checks."""
    batch, heads, seqlen, packed_dim = x_fp4.shape
    if packed_dim != _Q_PACKED_DIM:
        raise ValueError(f"x_fp4 last dim must be {_Q_PACKED_DIM}")
    if x_sc.dtype != torch.float8_e4m3fn:
        raise ValueError("x_sc must have dtype torch.float8_e4m3fn")
    if x_sg.shape != (batch, heads):
        raise ValueError(f"x_sg must have shape {(batch, heads)}")

    expected_q_depth = seqlen // _TILE
    expected_k_depth = seqlen // 64
    qk_chunks = _D_QK // 64
    if x_sc.shape == (batch, expected_q_depth, heads * qk_chunks, 512):
        sc_qstyle = x_sc
    elif x_sc.shape == (batch, expected_k_depth, heads * qk_chunks, 512):
        # Live K scales are depth-expanded by repeat_interleave(2).
        even = x_sc[:, 0::2, :, :].contiguous()
        odd = x_sc[:, 1::2, :, :].contiguous()
        if even.shape != (batch, expected_q_depth, heads * qk_chunks, 512):
            raise ValueError("collapsed K scales have unexpected shape")
        if not torch.equal(even, odd):
            raise ValueError("expanded K scales are not pairwise identical")
        sc_qstyle = even
    else:
        raise ValueError(
            f"x_sc must have shape {(batch, expected_q_depth, heads * qk_chunks, 512)} "
            f"or {(batch, expected_k_depth, heads * qk_chunks, 512)}"
        )

    sc_per_head = sc_qstyle.view(batch, expected_q_depth, heads, qk_chunks, 512).permute(0, 2, 1, 3, 4).contiguous()
    x_bhsd = _dequantize_prepared_fp4_rows_for_debug(x_fp4.contiguous(), sc_per_head)
    x_bhsd = x_bhsd.mul_(x_sg.to(device=x_bhsd.device, dtype=torch.float32).view(batch, heads, 1, 1))
    return x_bhsd.permute(0, 2, 1, 3).to(torch.bfloat16).contiguous()


def _quantize_rows_2d_localcta_prepared(
    x_2d: torch.Tensor,
    *,
    encode_centric: bool = True,
    pad_cols_to_tile: bool = False,
) -> dict[str, Any]:
    x_2d = x_2d.to(torch.bfloat16).contiguous()
    _require_finite_tensor(x_2d, "x_2d")
    local_q = _load_localcta_quant()
    rows, cols = int(x_2d.shape[0]), int(x_2d.shape[1])
    padded_cols = _next_multiple(cols, _TILE) if pad_cols_to_tile else cols
    if rows % _TILE != 0 or padded_cols % _TILE != 0:
        raise ValueError("localCTA quantization requires M and K to be multiples of 128")
    if padded_cols != cols:
        x_work = torch.zeros((rows, padded_cols), dtype=x_2d.dtype, device=x_2d.device)
        x_work[:, :cols] = x_2d
    else:
        x_work = x_2d.contiguous()
    with _cuda_device_ctx(x_2d.device):
        row_fp4, row_sc_prepared, _, _, row_sg, _ = local_q.tk_localcta_quantize_for_gemm_prepared(
            x_work, False, encode_centric
        )
    return {
        "backend": "localcta",
        "format": "nvfp4_localcta_prepared",
        "fp4": row_fp4.contiguous(),
        "scales": row_sc_prepared.contiguous(),
        "sg_chunks": row_sg.contiguous(),
        "rows": rows,
        "cols": cols,
        "padded_cols": padded_cols,
    }


def _dequantize_v5_rows_2d(
    fp4: torch.Tensor,
    scales: torch.Tensor,
    sg_scalar: torch.Tensor | float,
    *,
    rows: int,
    cols: int,
) -> torch.Tensor:
    fp4_4d = fp4.view(1, 1, rows, fp4.shape[-1])
    sc_5d = scales.view(1, 1, rows // 128, cols // 64, 512)
    out = _dequantize_prepared_fp4_rows_for_debug(fp4_4d, sc_5d).view(rows, cols)
    if isinstance(sg_scalar, torch.Tensor):
        sg = sg_scalar.reshape(1).to(device=out.device, dtype=torch.float32)
    else:
        sg = torch.tensor([float(sg_scalar)], device=out.device, dtype=torch.float32)
    return out * sg[0]


def _inverse_mxfp4_scale_swizzle(scales: torch.Tensor) -> torch.Tensor:
    _check_cuda_contiguous(scales, "scales")
    if scales.dtype != torch.uint8:
        raise ValueError("MXFP4 scales must be uint8")
    if scales.ndim != 4 or scales.shape[-2:] != (32, 16):
        raise ValueError("MXFP4 scales must have shape (M/128, K/128, 32, 16)")
    return _inverse_mxfp4_scale_swizzle_layout(scales)


def _inverse_mxfp4_scale_swizzle_layout(scales: torch.Tensor) -> torch.Tensor:
    rowmajor = scales.view(scales.shape[0], scales.shape[1], 32, 4, 4)
    rowmajor = rowmajor.permute(0, 1, 3, 2, 4).contiguous()
    rowmajor = rowmajor.view(scales.shape[0], scales.shape[1], 128, 4)
    rowmajor = rowmajor.permute(0, 2, 1, 3).contiguous()
    return rowmajor.view(scales.shape[0] * 128, scales.shape[1] * 4)


def _e8m0_scales_to_float(e8m0: torch.Tensor) -> torch.Tensor:
    bits = torch.bitwise_left_shift(e8m0.to(torch.int32), 23).contiguous()
    scale = bits.view(torch.float32)
    zero = torch.zeros((), device=e8m0.device, dtype=torch.float32)
    finite = torch.where(e8m0 == 0, zero, scale)
    return torch.where(e8m0 >= 0xFE, zero, finite)


def _fp4x2_to_fp32_reference(fp4: torch.Tensor) -> torch.Tensor:
    values = torch.tensor(
        [0.0, 0.5, 1.0, 1.5, 2.0, 3.0, 4.0, 6.0, -0.0, -0.5, -1.0, -1.5, -2.0, -3.0, -4.0, -6.0],
        dtype=torch.float32,
        device=fp4.device,
    )
    packed = fp4.contiguous().view(torch.uint8).to(torch.int64)
    nibbles = torch.stack((packed & 0xF, (packed >> 4) & 0xF), dim=-1).flatten(start_dim=-2)
    return values[nibbles]


def _fp4x2_to_fp32_for_debug(fp4: torch.Tensor) -> torch.Tensor:
    try:
        utils = _load_nvfp4_utils()
        fn = getattr(utils, "fp4x2_to_fp32", None)
    except Exception:
        fn = None
    if fn is not None:
        return fn(fp4.contiguous())
    return _fp4x2_to_fp32_reference(fp4)


def _dequantize_mxfp4_rows_2d(
    fp4: torch.Tensor,
    scales: torch.Tensor,
    *,
    rows: int,
    cols: int,
) -> torch.Tensor:
    fp32_rows = _fp4x2_to_fp32_for_debug(fp4.contiguous())
    row_scales = _inverse_mxfp4_scale_swizzle(scales).to(torch.uint8)
    scale = _e8m0_scales_to_float(row_scales).repeat_interleave(_MXFP4_BLOCK, dim=-1) / 6.0
    return (fp32_rows[:, :cols] * scale[:, :cols]).view(rows, cols)


def _tensor_diff_metrics(candidate: torch.Tensor, reference: torch.Tensor) -> dict[str, float]:
    candidate_f = candidate.float()
    reference_f = reference.float()
    diff = candidate_f - reference_f
    ref_l2 = torch.linalg.vector_norm(reference_f)
    return {
        "max_abs": float(diff.abs().max().item()),
        "mean_abs": float(diff.abs().mean().item()),
        "rel_l2": float((torch.linalg.vector_norm(diff) / ref_l2.clamp_min(1.0e-12)).item()),
    }


def _byte_tensor_diff_metrics(candidate: torch.Tensor, reference: torch.Tensor) -> dict[str, int | float]:
    candidate_u8 = candidate.view(torch.uint8).contiguous()
    reference_u8 = reference.view(torch.uint8).contiguous()
    if candidate_u8.shape != reference_u8.shape:
        raise ValueError(
            f"byte tensor shapes differ: candidate={tuple(candidate_u8.shape)} "
            f"reference={tuple(reference_u8.shape)}"
        )
    diff = candidate_u8.to(torch.int16) - reference_u8.to(torch.int16)
    abs_diff = diff.abs()
    return {
        "mismatch_count": int(torch.count_nonzero(diff).item()),
        "max_abs": float(abs_diff.max().item()) if abs_diff.numel() else 0.0,
        "mean_abs": float(abs_diff.float().mean().item()) if abs_diff.numel() else 0.0,
    }


def _mxfp4_transposed_ds_abt_dk_contract_metrics(
    ds_col_fp4: torch.Tensor,
    ds_col_sc: torch.Tensor,
    q_col_fp4: torch.Tensor,
    q_col_sc: torch.Tensor,
    dk_pad: torch.Tensor,
) -> dict[str, Any]:
    """Debug-only check for the transposed-dS ABt dK probe.

    This compares the tensorcore result against the nearest internal contract,
    not against CuTe BF16: ``dequant(dS_col) @ dequant(Q_col).T``.
    """
    batch, heads, seqlen, packed_cols = (int(v) for v in ds_col_fp4.shape)
    if packed_cols != seqlen // 2:
        raise ValueError("dS_col payload must have shape (B,H,S,S/2)")
    if tuple(dk_pad.shape) != (batch, heads, seqlen, _D_QK_GEMM_PAD):
        raise ValueError(f"dK pad must have shape {(batch, heads, seqlen, _D_QK_GEMM_PAD)}")
    max_seqlen = int(os.environ.get("TK_FA4_MXFP4_BWD_TRANSPOSED_DS_ABT_DK_CONTRACT_MAX_SEQLEN", "512"))
    if seqlen > max_seqlen:
        return {
            "skipped": True,
            "reason": (
                f"seqlen {seqlen} exceeds "
                "TK_FA4_MXFP4_BWD_TRANSPOSED_DS_ABT_DK_CONTRACT_MAX_SEQLEN="
                f"{max_seqlen}"
            ),
        }

    probe = _mxfp4_transposed_ds_abt_dk_probe(
        ds_col_fp4,
        ds_col_sc,
        q_col_fp4,
        q_col_sc,
    )
    probe_vs_output = _tensor_diff_metrics(probe, dk_pad)

    full_diff_sq = torch.zeros((), device=dk_pad.device, dtype=torch.float64)
    full_ref_sq = torch.zeros((), device=dk_pad.device, dtype=torch.float64)
    full_max_abs = torch.zeros((), device=dk_pad.device, dtype=torch.float32)
    full_sum_abs = torch.zeros((), device=dk_pad.device, dtype=torch.float64)
    full_count = 0
    real_diff_sq = torch.zeros((), device=dk_pad.device, dtype=torch.float64)
    real_ref_sq = torch.zeros((), device=dk_pad.device, dtype=torch.float64)
    real_max_abs = torch.zeros((), device=dk_pad.device, dtype=torch.float32)
    real_sum_abs = torch.zeros((), device=dk_pad.device, dtype=torch.float64)
    real_count = 0
    pad_norm_sq = torch.zeros((), device=dk_pad.device, dtype=torch.float64)
    pad_max_abs = torch.zeros((), device=dk_pad.device, dtype=torch.float32)
    wrong_diff_sq = torch.zeros((), device=dk_pad.device, dtype=torch.float64)
    wrong_ref_sq = torch.zeros((), device=dk_pad.device, dtype=torch.float64)
    wrong_max_abs = torch.zeros((), device=dk_pad.device, dtype=torch.float32)
    wrong_sum_abs = torch.zeros((), device=dk_pad.device, dtype=torch.float64)
    wrong_count = 0

    for b in range(batch):
        for h in range(heads):
            ds_ref = _dequantize_mxfp4_rows_2d(
                ds_col_fp4[b, h].contiguous(),
                ds_col_sc[b, h].contiguous(),
                rows=seqlen,
                cols=seqlen,
            ).float()
            q_ref = _dequantize_mxfp4_rows_2d(
                q_col_fp4[b, h].contiguous(),
                q_col_sc[b, h].contiguous(),
                rows=_D_QK_GEMM_PAD,
                cols=seqlen,
            ).float()
            dequant_abt = ds_ref @ q_ref.T
            candidate = dk_pad[b, h].float()
            diff = candidate - dequant_abt
            full_diff_sq += (diff.double() * diff.double()).sum()
            full_ref_sq += (dequant_abt.double() * dequant_abt.double()).sum()
            full_max_abs = torch.maximum(full_max_abs, diff.abs().max())
            full_sum_abs += diff.abs().double().sum()
            full_count += int(diff.numel())

            real_diff = diff[:, :_D_QK]
            real_ref = dequant_abt[:, :_D_QK]
            real_diff_sq += (real_diff.double() * real_diff.double()).sum()
            real_ref_sq += (real_ref.double() * real_ref.double()).sum()
            real_max_abs = torch.maximum(real_max_abs, real_diff.abs().max())
            real_sum_abs += real_diff.abs().double().sum()
            real_count += int(real_diff.numel())

            pad = dequant_abt[:, _D_QK:]
            pad_norm_sq += (pad.double() * pad.double()).sum()
            pad_max_abs = torch.maximum(pad_max_abs, pad.abs().max())

            wrong_orientation = ds_ref.T @ q_ref.T
            wrong_diff = candidate - wrong_orientation
            wrong_diff_sq += (wrong_diff.double() * wrong_diff.double()).sum()
            wrong_ref_sq += (wrong_orientation.double() * wrong_orientation.double()).sum()
            wrong_max_abs = torch.maximum(wrong_max_abs, wrong_diff.abs().max())
            wrong_sum_abs += wrong_diff.abs().double().sum()
            wrong_count += int(wrong_diff.numel())

    full_metrics = {
        "max_abs": float(full_max_abs.item()),
        "mean_abs": float((full_sum_abs / max(full_count, 1)).item()),
        "rel_l2": float(torch.sqrt(full_diff_sq / full_ref_sq.clamp_min(1.0e-24)).item()),
    }
    real_metrics = {
        "max_abs": float(real_max_abs.item()),
        "mean_abs": float((real_sum_abs / max(real_count, 1)).item()),
        "rel_l2": float(torch.sqrt(real_diff_sq / real_ref_sq.clamp_min(1.0e-24)).item()),
    }
    wrong_orientation_metrics = {
        "max_abs": float(wrong_max_abs.item()),
        "mean_abs": float((wrong_sum_abs / max(wrong_count, 1)).item()),
        "rel_l2": float(torch.sqrt(wrong_diff_sq / wrong_ref_sq.clamp_min(1.0e-24)).item()),
    }
    return {
        "skipped": False,
        "probe_vs_output": probe_vs_output,
        "probe_vs_dequant_abt_full": full_metrics,
        "probe_vs_dequant_abt_real_0_192": real_metrics,
        "dequant_abt_pad_192_256_norm": float(torch.sqrt(pad_norm_sq).item()),
        "dequant_abt_pad_192_256_max_abs": float(pad_max_abs.item()),
        "probe_vs_wrong_orientation": wrong_orientation_metrics,
    }


def _mxfp4_materialized_p_a_artifact_empty_metrics(status: str) -> dict[str, Any]:
    return {
        "a_artifact_status": status,
        "a_artifact_contract": (
            "debug-only reconstruction of materialized dS_col MXFP4 payload/E8M0 scales "
            "against BF16 dS_col reference over the one-shot first-valid-k tiles"
        ),
        "a_artifact_identity_one_shot_max_abs_diff": None,
        "a_artifact_identity_one_shot_rel_diff": None,
        "a_artifact_identity_full_max_abs_diff": None,
        "a_artifact_identity_full_rel_diff": None,
        "a_artifact_best_candidate_name": None,
        "a_artifact_best_candidate_max_abs_diff": None,
        "a_artifact_best_candidate_rel_diff": None,
        "a_artifact_candidate_count": 0,
        "a_artifact_ref_max_abs": None,
        "a_artifact_recon_max_abs": None,
    }


def _mxfp4_materialized_p_live_dp_active_raw_a_metrics(
    a_stage_debug: torch.Tensor | None,
    dout_row_fp4: torch.Tensor | None,
    *,
    batch: int,
    heads: int,
    seqlen: int,
) -> dict[str, Any]:
    prefix = "live_dp_active_raw_a"

    def _empty(status: str) -> dict[str, Any]:
        return {
            f"{prefix}_status": status,
            f"{prefix}_shape": None,
            f"{prefix}_expected_shape": None,
            f"{prefix}_vs_dout_row_fp4_match": None,
            f"{prefix}_mismatch_count": None,
            f"{prefix}_total_count": None,
            f"{prefix}_first_mismatch": None,
            f"{prefix}_rank": None,
            f"{prefix}_selected_row_start": None,
            f"{prefix}_selected_row_end": None,
            f"{prefix}_row0_first16": None,
            f"{prefix}_expected_row0_first16": None,
            f"{prefix}_sentinel_status": None,
            f"{prefix}_sentinel_first16": None,
        }

    if not _use_mxfp4_bwd_materialized_p_ds_scan_abt_dk_real_kiter_accum_a_stage_readback_probe_default():
        return _empty("not_requested")
    if a_stage_debug is None:
        return _empty("schedule_raw_a_not_returned")
    if dout_row_fp4 is None:
        return _empty("missing_dout_row_fp4")

    expected_debug_shape = (batch, heads, _FP4PV_CLUSTER_SIZE + 1, _TILE, _TILE // 2)
    expected_dout_shape = (batch, heads, seqlen, _D_VO // 2)
    if tuple(a_stage_debug.shape) != expected_debug_shape:
        out = _empty("shape_mismatch")
        out[f"{prefix}_shape"] = tuple(int(v) for v in a_stage_debug.shape)
        out[f"{prefix}_expected_shape"] = expected_debug_shape
        return out
    if tuple(dout_row_fp4.shape) != expected_dout_shape:
        out = _empty("dout_row_fp4_shape_mismatch")
        out[f"{prefix}_shape"] = tuple(int(v) for v in a_stage_debug.shape)
        out[f"{prefix}_expected_shape"] = expected_dout_shape
        return out

    selected_row_env = os.environ.get("TK_FA4_MXFP4_LIVE_DP_SELECTED_ROW_TILE", "0")
    try:
        selected_row_tile = int(selected_row_env)
    except ValueError:
        selected_row_tile = 0
    selected_m_tile = _selected_row_tile_cluster_base(selected_row_tile)
    selected_row_start = selected_m_tile * _TILE
    selected_row_end = selected_row_start + _TILE
    if selected_row_start < 0 or selected_row_end > seqlen:
        out = _empty("selected_row_tile_out_of_range")
        out[f"{prefix}_shape"] = tuple(int(v) for v in a_stage_debug.shape)
        out[f"{prefix}_expected_shape"] = expected_debug_shape
        out[f"{prefix}_selected_row_start"] = int(selected_row_start)
        out[f"{prefix}_selected_row_end"] = int(min(max(selected_row_end, 0), seqlen))
        return out

    debug_cpu = a_stage_debug.detach().cpu()
    actual = debug_cpu[0, 0, 0]
    expected = (
        dout_row_fp4.detach()
        .contiguous()
        .view(torch.uint8)[0, 0, selected_row_start:selected_row_end, :]
        .cpu()
    )
    mismatch = actual != expected
    mismatch_count = int(mismatch.sum().item())

    def _first_mismatch() -> dict[str, int] | None:
        if mismatch_count == 0:
            return None
        row, col = (int(v) for v in mismatch.nonzero(as_tuple=False)[0].tolist())
        return {
            "row": row,
            "packed_col": col,
            "actual": int(actual[row, col].item()),
            "expected": int(expected[row, col].item()),
        }

    sentinel = [
        int(v)
        for v in debug_cpu[0, 0, _FP4PV_CLUSTER_SIZE, 0, :16].tolist()
    ]
    if sentinel[:4] == [0xA5, 0xD0, 0, 0x4C] and sentinel[4] == 0x5A:
        sentinel_status = "active_live_dp_readback_helper_observed"
    elif sentinel[:4] == [0xA5, 0xD0, 0, 0x41] and sentinel[4] == 0x5A:
        sentinel_status = "readback_helper_observed"
    elif sentinel[:4] == [0xA5, 0xD1, 0, 0x4C] and sentinel[8] == 0x5A:
        sentinel_status = "active_branch_pre_helper_only"
    elif all(v == 0 for v in sentinel):
        sentinel_status = "not_observed"
    else:
        sentinel_status = "unexpected_sentinel_bytes"

    return {
        f"{prefix}_status": (
            "active_branch_raw_a_matches_dout_row_fp4"
            if mismatch_count == 0
            else "active_branch_raw_a_mismatch"
        ),
        f"{prefix}_shape": tuple(int(v) for v in debug_cpu.shape),
        f"{prefix}_expected_shape": expected_debug_shape,
        f"{prefix}_vs_dout_row_fp4_match": mismatch_count == 0,
        f"{prefix}_mismatch_count": mismatch_count,
        f"{prefix}_total_count": int(actual.numel()),
        f"{prefix}_first_mismatch": _first_mismatch(),
        f"{prefix}_rank": 0,
        f"{prefix}_selected_row_start": int(selected_row_start),
        f"{prefix}_selected_row_end": int(selected_row_end),
        f"{prefix}_row0_first16": [int(v) for v in actual[0, :16].tolist()],
        f"{prefix}_expected_row0_first16": [int(v) for v in expected[0, :16].tolist()],
        f"{prefix}_sentinel_status": sentinel_status,
        f"{prefix}_sentinel_first16": sentinel,
    }


def _mxfp4_materialized_p_a_artifact_metrics(
    ds_col_fp4: torch.Tensor | None,
    ds_col_sc: torch.Tensor | None,
    p_cache_row_fp4: torch.Tensor | None,
    p_cache_row_sc: torch.Tensor | None,
    v_row_fp4: torch.Tensor | None,
    v_row_sc: torch.Tensor | None,
    out_bshd: torch.Tensor | None,
    dout_bshd: torch.Tensor | None,
    *,
    softmax_scale: float,
    max_k_iters: int,
) -> dict[str, Any]:
    if ds_col_fp4 is None or ds_col_sc is None:
        return _mxfp4_materialized_p_a_artifact_empty_metrics("missing_ds_col_artifact")
    if p_cache_row_fp4 is None or p_cache_row_sc is None:
        return _mxfp4_materialized_p_a_artifact_empty_metrics("missing_materialized_p_cache_artifact")
    if v_row_fp4 is None or v_row_sc is None:
        return _mxfp4_materialized_p_a_artifact_empty_metrics("missing_v_row_artifact")
    if out_bshd is None or dout_bshd is None:
        return _mxfp4_materialized_p_a_artifact_empty_metrics("missing_out_or_dout_artifact")

    batch, heads, seqlen, packed_cols = (int(v) for v in ds_col_fp4.shape)
    if packed_cols != seqlen // 2:
        raise ValueError("dS_col A artifact payload must have shape (B,H,S,S/2)")
    if seqlen % _TILE != 0:
        raise ValueError("dS_col A artifact diagnostic requires S divisible by 128")
    tiles = seqlen // _TILE
    expected_ds_sc_shape = (batch, heads, tiles, tiles, 32, 16)
    expected_p_shape = (batch, heads, seqlen, seqlen // 2)
    expected_p_sc_shape = (batch, heads, tiles, tiles, 32, 16)
    expected_v_shape = (batch, heads, seqlen, _D_VO // 2)
    expected_v_sc_shape = (batch, heads, tiles, _D_VO // _TILE, 32, 16)
    if tuple(ds_col_sc.shape) != expected_ds_sc_shape:
        raise ValueError(f"dS_col A artifact scales must have shape {expected_ds_sc_shape}")
    if tuple(p_cache_row_fp4.shape) != expected_p_shape:
        raise ValueError(f"materialized P cache payload must have shape {expected_p_shape}")
    if tuple(p_cache_row_sc.shape) != expected_p_sc_shape:
        raise ValueError(f"materialized P cache scales must have shape {expected_p_sc_shape}")
    if tuple(v_row_fp4.shape) != expected_v_shape:
        raise ValueError(f"V row payload must have shape {expected_v_shape}")
    if tuple(v_row_sc.shape) != expected_v_sc_shape:
        raise ValueError(f"V row scales must have shape {expected_v_sc_shape}")
    if tuple(out_bshd.shape) != (batch, seqlen, heads, _D_VO):
        raise ValueError(f"out must have shape {(batch, seqlen, heads, _D_VO)}")
    if tuple(dout_bshd.shape) != (batch, seqlen, heads, _D_VO):
        raise ValueError(f"dout must have shape {(batch, seqlen, heads, _D_VO)}")

    def _dequant_with_scale_transform(
        fp4_2d: torch.Tensor,
        scales_4d: torch.Tensor,
        transform,
    ) -> torch.Tensor:
        fp32_rows = _fp4x2_to_fp32_for_debug(fp4_2d.contiguous())
        row_scales = _inverse_mxfp4_scale_swizzle(scales_4d).to(torch.uint8)
        scale_view = row_scales.view(tiles, _TILE, tiles, 4)
        scale_view = transform(scale_view).contiguous()
        scale_rows = scale_view.view(seqlen, tiles * 4)
        scale = _e8m0_scales_to_float(scale_rows).repeat_interleave(_MXFP4_BLOCK, dim=-1) / 6.0
        return (fp32_rows[:, :seqlen] * scale[:, :seqlen]).view(seqlen, seqlen)

    def _identity_scale(scale_view: torch.Tensor) -> torch.Tensor:
        return scale_view

    def _roll_scale_rows(offset: int):
        def _transform(scale_view: torch.Tensor) -> torch.Tensor:
            return torch.roll(scale_view, shifts=-int(offset), dims=1)

        return _transform

    def _roll_scale_groups(offset: int):
        def _transform(scale_view: torch.Tensor) -> torch.Tensor:
            return torch.roll(scale_view, shifts=-int(offset), dims=3)

        return _transform

    def _one_shot_mask(device: torch.device) -> torch.Tensor:
        mask = torch.zeros((seqlen, seqlen), device=device, dtype=torch.bool)
        compute_k_iter_base = 0
        for m_tile in range(tiles):
            cluster_start = (m_tile // _FP4PV_CLUSTER_SIZE) * _FP4PV_CLUSTER_SIZE
            full_iters_per_task = min(cluster_start + _FP4PV_CLUSTER_SIZE, tiles)
            if max_k_iters < 0:
                executed_k_iters = full_iters_per_task
            else:
                remaining_iters = full_iters_per_task - compute_k_iter_base
                executed_k_iters = 0 if remaining_iters <= 0 else min(remaining_iters, max_k_iters)
            remaining_valid = m_tile + 1 - compute_k_iter_base
            valid_k_iters = 0 if remaining_valid <= 0 else min(executed_k_iters, remaining_valid)
            full_cluster_valid = cluster_start + _FP4PV_CLUSTER_SIZE - 1 < tiles
            if not full_cluster_valid or valid_k_iters <= 0:
                continue
            key_start = compute_k_iter_base * _TILE
            query_start = m_tile * _TILE
            mask[key_start:key_start + _TILE, query_start:query_start + _TILE] = True
        return mask

    one_shot_mask = _one_shot_mask(ds_col_fp4.device)
    if not bool(one_shot_mask.any().item()):
        return _mxfp4_materialized_p_a_artifact_empty_metrics("no_valid_one_shot_tile")

    candidate_parts: dict[str, list[torch.Tensor]] = {}
    references: list[torch.Tensor] = []
    identity_full_max_abs_diff: float | None = None
    identity_full_rel_diff: float | None = None
    identity_one_shot_max_abs_diff: float | None = None
    identity_one_shot_rel_diff: float | None = None
    ref_max_abs = 0.0
    recon_max_abs = 0.0

    for b in range(batch):
        for h in range(heads):
            p_ref = _dequantize_mxfp4_rows_2d(
                p_cache_row_fp4[b, h],
                p_cache_row_sc[b, h],
                rows=seqlen,
                cols=seqlen,
            ).float()
            v_ref = _dequantize_mxfp4_rows_2d(
                v_row_fp4[b, h],
                v_row_sc[b, h],
                rows=seqlen,
                cols=_D_VO,
            ).float()
            dout_ref = dout_bshd[b, :, h, :].float()
            out_ref = out_bshd[b, :, h, :].float()
            dP_ref = dout_ref @ v_ref.T
            delta_ref = (dout_ref * out_ref).sum(dim=-1)
            ds_row_ref = p_ref * (dP_ref - delta_ref[:, None]) * float(softmax_scale)
            references.append(ds_row_ref.T.contiguous())

            identity = _dequant_with_scale_transform(
                ds_col_fp4[b, h],
                ds_col_sc[b, h],
                _identity_scale,
            ).float()
            candidate_views = [("a_identity", identity)]
            for offset in (32, 64, 96):
                candidate_views.append(
                    (
                        f"a_scale_row_offset{offset}",
                        _dequant_with_scale_transform(
                            ds_col_fp4[b, h],
                            ds_col_sc[b, h],
                            _roll_scale_rows(offset),
                        ).float(),
                    )
                )
            for offset in (1, 2, 3):
                candidate_views.append(
                    (
                        f"a_scale_group_offset{offset}",
                        _dequant_with_scale_transform(
                            ds_col_fp4[b, h],
                            ds_col_sc[b, h],
                            _roll_scale_groups(offset),
                        ).float(),
                    )
                )
            row_chunks32 = identity.reshape(tiles, 4, 32, seqlen)
            candidate_views.extend(
                (
                    (
                        "a_row_swap32_pairs",
                        row_chunks32[:, [1, 0, 3, 2], :, :].reshape_as(identity),
                    ),
                    (
                        "a_row_reverse32_chunks",
                        row_chunks32[:, [3, 2, 1, 0], :, :].reshape_as(identity),
                    ),
                )
            )
            row_chunks16 = identity.reshape(tiles, 8, 16, seqlen)
            candidate_views.append(
                (
                    "a_row_swap16_pairs",
                    row_chunks16[:, [1, 0, 3, 2, 5, 4, 7, 6], :, :].reshape_as(identity),
                )
            )
            for name, view in candidate_views:
                candidate_parts.setdefault(name, []).append(view)

    ref_full = torch.stack(references, dim=0).view(batch, heads, seqlen, seqlen)
    mask = one_shot_mask.view(1, 1, seqlen, seqlen)
    best_name: str | None = None
    best_max_abs: float | None = None
    best_rel: float | None = None

    def _diff_metrics(candidate: torch.Tensor, reference: torch.Tensor, active_mask: torch.Tensor | None) -> tuple[float, float]:
        if active_mask is not None:
            candidate = candidate[active_mask.expand_as(candidate)]
            reference = reference[active_mask.expand_as(reference)]
        diff = candidate.float() - reference.float()
        ref_norm = torch.linalg.vector_norm(reference.float())
        max_abs = float(diff.abs().max().item()) if diff.numel() else 0.0
        rel = float((torch.linalg.vector_norm(diff) / ref_norm.clamp_min(1.0e-12)).item())
        return max_abs, rel

    candidate_count = 0
    for name, candidate_views in candidate_parts.items():
        candidate = torch.stack(candidate_views, dim=0).view(batch, heads, seqlen, seqlen)
        candidate_count += 1
        full_max, full_rel = _diff_metrics(candidate, ref_full, None)
        shot_max, shot_rel = _diff_metrics(candidate, ref_full, mask)
        if name == "a_identity":
            identity_full_max_abs_diff = full_max
            identity_full_rel_diff = full_rel
            identity_one_shot_max_abs_diff = shot_max
            identity_one_shot_rel_diff = shot_rel
            recon_max_abs = float(candidate.abs().max().item()) if candidate.numel() else 0.0
            ref_max_abs = float(ref_full.abs().max().item()) if ref_full.numel() else 0.0
        if best_rel is None or shot_rel < best_rel:
            best_name = name
            best_max_abs = shot_max
            best_rel = shot_rel

    if best_name == "a_identity" and best_rel is not None and best_rel < 0.25:
        status = "a_artifact_reconstruction_faithful_identity_simple_a_layout_falsified"
    elif best_name == "a_identity":
        status = "a_artifact_reconstruction_mismatched_best_identity"
    elif best_name is not None:
        status = f"a_artifact_reconstruction_best_candidate_{best_name}"
    else:
        status = "a_artifact_reconstruction_no_candidate"

    return {
        "a_artifact_status": status,
        "a_artifact_contract": (
            "A=dS_col MXFP4 artifact is dequantized from the materialized-P cached-P path; "
            "reference is dS_col=(P_cache*(dO@V_row.T-delta)*softmax_scale).T over the "
            "same first-valid-k one-shot tiles; candidates vary only A-side scale/index layout"
        ),
        "a_artifact_identity_one_shot_max_abs_diff": identity_one_shot_max_abs_diff,
        "a_artifact_identity_one_shot_rel_diff": identity_one_shot_rel_diff,
        "a_artifact_identity_full_max_abs_diff": identity_full_max_abs_diff,
        "a_artifact_identity_full_rel_diff": identity_full_rel_diff,
        "a_artifact_best_candidate_name": best_name,
        "a_artifact_best_candidate_max_abs_diff": best_max_abs,
        "a_artifact_best_candidate_rel_diff": best_rel,
        "a_artifact_candidate_count": int(candidate_count),
        "a_artifact_ref_max_abs": ref_max_abs,
        "a_artifact_recon_max_abs": recon_max_abs,
    }


def _repair_materialized_p_ds_scan_abt_dk_partial_debug_from_artifacts(
    ds_col_fp4: torch.Tensor,
    ds_col_sc: torch.Tensor,
    q_col_fp4: torch.Tensor,
    q_col_sc: torch.Tensor,
    *,
    max_k_iters: int,
    source_k_iter_offset: int = 0,
) -> torch.Tensor:
    _check_cuda_contiguous(ds_col_fp4, "partial_debug_repair_ds_col_fp4")
    _check_cuda_contiguous(ds_col_sc, "partial_debug_repair_ds_col_sc")
    _check_cuda_contiguous(q_col_fp4, "partial_debug_repair_q_col_fp4")
    _check_cuda_contiguous(q_col_sc, "partial_debug_repair_q_col_sc")
    batch, heads, seqlen, packed_cols = (int(v) for v in ds_col_fp4.shape)
    if packed_cols != seqlen // 2 or seqlen % _TILE != 0:
        raise ValueError("partial debug repair expects dS_col shape (B,H,S,S/2), S divisible by 128")
    tiles = seqlen // _TILE
    expected_ds_sc_shape = (batch, heads, tiles, tiles, 32, 16)
    expected_q_shape = (batch, heads, _D_QK_GEMM_PAD, seqlen // 2)
    expected_q_sc_shape = (batch, heads, _D_QK_GEMM_PAD // _D_VO, tiles, 32, 16)
    if tuple(ds_col_sc.shape) != expected_ds_sc_shape:
        raise ValueError(f"partial debug repair dS scales must have shape {expected_ds_sc_shape}")
    if tuple(q_col_fp4.shape) != expected_q_shape:
        raise ValueError(f"partial debug repair Q-col payload must have shape {expected_q_shape}")
    if tuple(q_col_sc.shape) != expected_q_sc_shape:
        raise ValueError(f"partial debug repair Q-col scales must have shape {expected_q_sc_shape}")

    q_col_chunk_pattern = _mxfp4_bwd_materialized_p_q_col_chunk_pattern_default()
    q_col_chunk_idx = {"chunk0": 0, "chunk1": 1, "chunk2": 2}[q_col_chunk_pattern]
    q_row_base = q_col_chunk_idx * (_D_VO // 2)
    if q_row_base + (_D_VO // 2) > _D_QK_GEMM_PAD:
        raise ValueError("partial debug repair Q-col chunk is out of padded Q range")

    local_k_start = max(0, int(source_k_iter_offset))
    local_k_count = max(0, int(max_k_iters))
    out = torch.zeros(
        (batch, heads, seqlen, _D_VO // 2),
        device=ds_col_fp4.device,
        dtype=torch.float32,
    )
    for b in range(batch):
        for h in range(heads):
            ds_full = _dequantize_mxfp4_rows_2d(
                ds_col_fp4[b, h],
                ds_col_sc[b, h],
                rows=seqlen,
                cols=seqlen,
            )
            q_full = _dequantize_mxfp4_rows_2d(
                q_col_fp4[b, h],
                q_col_sc[b, h],
                rows=_D_QK_GEMM_PAD,
                cols=seqlen,
            )
            for cluster_m_tile in range(0, tiles, _FP4PV_CLUSTER_SIZE):
                if cluster_m_tile + _FP4PV_CLUSTER_SIZE > tiles:
                    continue
                output_query_start = cluster_m_tile * _TILE
                for rank in range(_FP4PV_CLUSTER_SIZE):
                    m_tile = cluster_m_tile + rank
                    bounded_k_end = min(m_tile + 1, tiles)
                    if local_k_count > 0:
                        bounded_k_end = min(bounded_k_end, local_k_start + local_k_count)
                    if local_k_start >= bounded_k_end:
                        continue
                    query_start = m_tile * _TILE
                    q_rank_row_start = q_row_base + rank * 32
                    q_rank = q_full[
                        q_rank_row_start:q_rank_row_start + 32,
                        query_start:query_start + _TILE,
                    ]
                    accum = torch.zeros((_TILE, 32), device=out.device, dtype=torch.float32)
                    for local_k in range(local_k_start, bounded_k_end):
                        k_iter = local_k
                        if k_iter > m_tile or k_iter >= tiles:
                            continue
                        key_start = k_iter * _TILE
                        ds_tile = ds_full[
                            key_start:key_start + _TILE,
                            query_start:query_start + _TILE,
                        ]
                        accum += (ds_tile.to(torch.bfloat16) @ q_rank.to(torch.bfloat16).T).float()
                    col_start = rank * 32
                    out[
                        b,
                        h,
                        output_query_start:output_query_start + _TILE,
                        col_start:col_start + 32,
                    ].copy_(accum)
    return out.to(torch.bfloat16)


def _mxfp4_materialized_p_real_kiter_accum_label(max_count: int, start: int = 0) -> str:
    max_count = max(0, int(max_count))
    start = max(0, int(start))
    if max_count <= 0:
        return "all_valid_kiter"
    if max_count <= 8:
        return "+".join(f"k{start + i}" for i in range(max_count))
    return f"k{start}_to_k{start + max_count - 1}"


def _mxfp4_materialized_p_partial_dk_debug_reference_metrics(
    partial_debug: torch.Tensor | None,
    ds_col_fp4: torch.Tensor | None,
    ds_col_sc: torch.Tensor | None,
    q_col_fp4: torch.Tensor,
    q_col_sc: torch.Tensor,
    a_stage_debug: torch.Tensor | None = None,
    *,
    zero_only_store_probe: bool = False,
    synthetic_calibration_probe: bool = False,
    synthetic_calibration_pattern: str = "all_ones",
    synthetic_d_read_pattern: str = "normal",
    synthetic_issue_pattern: str = "normal",
    synthetic_d_prefill_pattern: str = "zero",
    synthetic_d_target_pattern: str = "tail64_current",
    synthetic_b_scale_tmem_pattern: str = "normal",
    real_kiter_accum_probe: bool = False,
    real_kiter_accum_max_k_iters: int = 0,
    real_kiter_accum_start_k_iter_offset: int = 0,
    real_kiter_accum_source_k_iter_offset: int | None = None,
    real_kiter_accum_slot_mode: str = "both",
    real_kiter_accum_clear_each_issue_probe: bool = False,
    real_kiter_accum_pingpong_ds_probe: bool = False,
    real_kiter_accum_pingpong_issue_cta_wait_probe: bool = False,
    real_kiter_accum_zero_a_at_issue_probe: bool = False,
    real_kiter_accum_zero_b_at_issue_probe: bool = False,
    real_kiter_accum_scale_kill_at_issue_probe: bool = False,
    real_kiter_accum_no_issue_probe: bool = False,
    p_cache_row_fp4: torch.Tensor | None = None,
    p_cache_row_sc: torch.Tensor | None = None,
    v_row_fp4: torch.Tensor | None = None,
    v_row_sc: torch.Tensor | None = None,
    out_bshd: torch.Tensor | None = None,
    dout_bshd: torch.Tensor | None = None,
    softmax_scale: float | None = None,
) -> dict[str, Any]:
    """Compare the one-shot debug dK scratch against its current ABt contract.

    The debug scratch is intentionally not production dK. The current kernel stores
    the first-valid-k_iter ABt accumulator into the current post-store row-tile
    location, so later row tiles contain the first-k tile contribution at the debug
    store coordinate rather than at its eventual production dK row coordinate.
    """
    a_artifact_metrics = _mxfp4_materialized_p_a_artifact_empty_metrics("not_requested")
    if partial_debug is None:
        return {
            "partial_ref_status": "not_requested",
            "partial_ref_contract": "not_requested",
            "partial_ref_max_abs_diff": None,
            "partial_ref_rel_diff": None,
            "partial_ref_best_candidate_name": None,
            "partial_ref_best_candidate_max_abs_diff": None,
            "partial_ref_best_candidate_rel_diff": None,
            "partial_ref_best_candidate_scale_ratio": None,
            "partial_ref_best_scale_convention_name": None,
            "partial_ref_best_scale_convention_max_abs_diff": None,
            "partial_ref_best_scale_convention_rel_diff": None,
            "partial_ref_best_readback_mapping_name": None,
            "partial_ref_best_readback_mapping_max_abs_diff": None,
            "partial_ref_best_readback_mapping_rel_diff": None,
            "partial_ref_readback_mapping_status": "not_requested",
            "synthetic_calibration_status": "not_requested",
            "synthetic_calibration_best_candidate_name": None,
            "synthetic_calibration_best_candidate_max_abs_diff": None,
            "synthetic_calibration_best_candidate_rel_diff": None,
            "synthetic_calibration_candidate_count": 0,
            **a_artifact_metrics,
        }
    batch, heads, seqlen, tail_cols = (int(v) for v in partial_debug.shape)
    if tail_cols != _D_VO // 2:
        raise ValueError("partial dK debug scratch must have tail64 shape (B,H,S,64)")

    def _debug_scratch_summary_metrics(candidate: torch.Tensor) -> dict[str, Any]:
        candidate = candidate.float()
        numel = int(candidate.numel())
        finite_mask = torch.isfinite(candidate)
        finite_count = int(finite_mask.sum().item()) if numel else 0
        first_head = (
            candidate[0, 0]
            if candidate.ndim == 4 and batch > 0 and heads > 0
            else candidate.reshape(0, 0)
        )
        block_rows = seqlen // 32
        block_cols = tail_cols // 16
        if first_head.numel() and block_rows > 0 and block_cols > 0:
            block_view = first_head.reshape(block_rows, 32, block_cols, 16).permute(0, 2, 1, 3)
            block_mean = block_view.mean(dim=(-1, -2))
            block_min = block_view.amin(dim=(-1, -2))
            block_max = block_view.amax(dim=(-1, -2))
            block_nonzero = (block_view != 0).sum(dim=(-1, -2))
            first_row_first16 = [
                float(v) for v in first_head[0, : min(16, tail_cols)].detach().cpu().tolist()
            ]
            first_col_first16 = [
                float(v) for v in first_head[: min(16, seqlen), 0].detach().cpu().tolist()
            ]
            first_four_row_means = [
                float(v)
                for v in first_head[: min(4, seqlen), :].mean(dim=1).detach().cpu().tolist()
            ]
            first_four_col_means = [
                float(v)
                for v in first_head[:, : min(4, tail_cols)].mean(dim=0).detach().cpu().tolist()
            ]
        else:
            block_mean = block_min = block_max = block_nonzero = torch.empty(0, device=candidate.device)
            first_row_first16 = []
            first_col_first16 = []
            first_four_row_means = []
            first_four_col_means = []
        return {
            "synthetic_calibration_debug_total_count": numel,
            "synthetic_calibration_debug_finite_count": finite_count,
            "synthetic_calibration_debug_nonzero": int(torch.count_nonzero(candidate).item()),
            "synthetic_calibration_debug_zero_count": int((candidate == 0).sum().item()),
            "synthetic_calibration_debug_positive_count": int((candidate > 0).sum().item()),
            "synthetic_calibration_debug_negative_count": int((candidate < 0).sum().item()),
            "synthetic_calibration_debug_min": float(candidate.min().item()) if numel else 0.0,
            "synthetic_calibration_debug_max": float(candidate.max().item()) if numel else 0.0,
            "synthetic_calibration_debug_mean": (
                float(candidate.mean().item()) if candidate.numel() else 0.0
            ),
            "synthetic_calibration_debug_std": (
                float(candidate.std(unbiased=False).item()) if numel else 0.0
            ),
            "synthetic_calibration_debug_max_abs": (
                float(candidate.abs().max().item()) if candidate.numel() else 0.0
            ),
            "synthetic_calibration_debug_first_head_block32x16_mean": (
                block_mean.detach().cpu().tolist()
            ),
            "synthetic_calibration_debug_first_head_block32x16_min": (
                block_min.detach().cpu().tolist()
            ),
            "synthetic_calibration_debug_first_head_block32x16_max": (
                block_max.detach().cpu().tolist()
            ),
            "synthetic_calibration_debug_first_head_block32x16_nonzero": (
                block_nonzero.detach().cpu().tolist()
            ),
            "synthetic_calibration_debug_first_row_first16": first_row_first16,
            "synthetic_calibration_debug_first_col_first16": first_col_first16,
            "synthetic_calibration_debug_first_four_row_means": first_four_row_means,
            "synthetic_calibration_debug_first_four_col_means": first_four_col_means,
        }

    if zero_only_store_probe:
        return {
            "partial_ref_status": "zero_only_store_probe_no_mma_reference_skipped",
            "partial_ref_contract": (
                "zero-only debug probe stores the post-prefill tail64 accumulator "
                "without issuing TCGEN05; correctness check is zero_only_nonzero/max_abs "
                "and, for sentinel_halves, the synthetic block summaries"
            ),
            "partial_ref_max_abs_diff": None,
            "partial_ref_rel_diff": None,
            "partial_ref_best_candidate_name": None,
            "partial_ref_best_candidate_max_abs_diff": None,
            "partial_ref_best_candidate_rel_diff": None,
            "partial_ref_best_candidate_scale_ratio": None,
            "partial_ref_best_scale_convention_name": None,
            "partial_ref_best_scale_convention_max_abs_diff": None,
            "partial_ref_best_scale_convention_rel_diff": None,
            "partial_ref_best_readback_mapping_name": None,
            "partial_ref_best_readback_mapping_max_abs_diff": None,
            "partial_ref_best_readback_mapping_rel_diff": None,
            "partial_ref_readback_mapping_status": "zero_only_not_applicable",
            "synthetic_calibration_status": (
                "zero_only_sentinel_prefill_debug_scratch"
                if synthetic_d_prefill_pattern == "sentinel_halves"
                else "zero_only_not_applicable"
            ),
            "synthetic_calibration_pattern": synthetic_calibration_pattern,
            "synthetic_d_read_pattern": synthetic_d_read_pattern,
            "synthetic_issue_pattern": synthetic_issue_pattern,
            "synthetic_d_prefill_pattern": synthetic_d_prefill_pattern,
            "synthetic_d_prefill_pattern_env": (
                "TK_FA4_MXFP4_BWD_MATERIALIZED_P_DS_SCAN_ABT_DK_SYNTHETIC_D_PREFILL_PATTERN"
            ),
            "synthetic_d_prefill_pattern_contract": (
                "debug-only pre-issue D accumulator fill: zero clears raw tail64; "
                "sentinel_halves fills raw cols0:32 with +11 and raw cols32:64 with -13"
            ),
            "synthetic_d_target_pattern": synthetic_d_target_pattern,
            "synthetic_d_target_pattern_env": (
                "TK_FA4_MXFP4_BWD_MATERIALIZED_P_DS_SCAN_ABT_DK_SYNTHETIC_D_TARGET_PATTERN"
            ),
            "synthetic_d_target_pattern_contract": (
                "debug-only D target/descriptor selector: tail64_current uses rows0:32 B view "
                "with tail64 D; tail64_b_rows32_64 uses rows32:64 B view with the same tail64 D; "
                "full128 modes are selected-row-only because the alt Q-scale slot is safe but "
                "full D overlaps live-dP scale slots in multi-tile launches"
            ),
            "synthetic_b_scale_tmem_pattern": synthetic_b_scale_tmem_pattern,
            "synthetic_b_scale_tmem_pattern_env": (
                "TK_FA4_MXFP4_BWD_MATERIALIZED_P_DS_SCAN_ABT_DK_SYNTHETIC_B_SCALE_TMEM_PATTERN"
            ),
            "synthetic_b_scale_tmem_pattern_contract": (
                "debug-only B scale TMEM lane diagnostic: normal passes the existing single "
                "full_tt_fp8e8m0<16> Q scale tile; duplicate_lane0_to_lane1 aliases the same "
                "TMEM base as full_tt_fp8e8m0<32> and loads the scale-one shared tile into "
                "both 16-column lanes before the N32 ABt issue"
            ),
            "synthetic_calibration_best_candidate_name": None,
            "synthetic_calibration_best_candidate_max_abs_diff": None,
            "synthetic_calibration_best_candidate_rel_diff": None,
            "synthetic_calibration_candidate_count": 0,
            **_debug_scratch_summary_metrics(partial_debug),
            **_mxfp4_materialized_p_a_artifact_empty_metrics("zero_only_not_applicable"),
        }
    if ds_col_fp4 is None or ds_col_sc is None:
        return {
            "partial_ref_status": "missing_ds_col_artifact",
            "partial_ref_contract": (
                "requires materialized dS_col fp4/sc artifacts from the cached-P dS scan path"
            ),
            "partial_ref_max_abs_diff": None,
            "partial_ref_rel_diff": None,
            "partial_ref_best_candidate_name": None,
            "partial_ref_best_candidate_max_abs_diff": None,
            "partial_ref_best_candidate_rel_diff": None,
            "partial_ref_best_candidate_scale_ratio": None,
            "partial_ref_best_scale_convention_name": None,
            "partial_ref_best_scale_convention_max_abs_diff": None,
            "partial_ref_best_scale_convention_rel_diff": None,
            "partial_ref_best_readback_mapping_name": None,
            "partial_ref_best_readback_mapping_max_abs_diff": None,
            "partial_ref_best_readback_mapping_rel_diff": None,
            "partial_ref_readback_mapping_status": "missing_ds_col_artifact",
            "synthetic_calibration_status": "missing_ds_col_artifact",
            "synthetic_calibration_best_candidate_name": None,
            "synthetic_calibration_best_candidate_max_abs_diff": None,
            "synthetic_calibration_best_candidate_rel_diff": None,
            "synthetic_calibration_candidate_count": 0,
            **_mxfp4_materialized_p_a_artifact_empty_metrics("missing_ds_col_artifact"),
        }
    tiles = seqlen // _TILE
    expected_ds_shape = (batch, heads, seqlen, seqlen // 2)
    expected_ds_sc_shape = (batch, heads, tiles, tiles, 32, 16)
    expected_q_shape = (batch, heads, _D_QK_GEMM_PAD, seqlen // 2)
    expected_q_sc_shape = (batch, heads, _D_QK_GEMM_PAD // _TILE, tiles, 32, 16)
    if tuple(ds_col_fp4.shape) != expected_ds_shape:
        raise ValueError(f"dS_col fp4 artifact must have shape {expected_ds_shape}")
    if tuple(ds_col_sc.shape) != expected_ds_sc_shape:
        raise ValueError(f"dS_col scale artifact must have shape {expected_ds_sc_shape}")
    if tuple(q_col_fp4.shape) != expected_q_shape:
        raise ValueError(f"Q_col fp4 artifact must have shape {expected_q_shape}")
    if tuple(q_col_sc.shape) != expected_q_sc_shape:
        raise ValueError(f"Q_col scale artifact must have shape {expected_q_sc_shape}")

    def _synthetic_calibration_metrics() -> dict[str, Any]:
        candidate = partial_debug.float()
        pattern = synthetic_calibration_pattern
        d_read_pattern = synthetic_d_read_pattern
        issue_pattern = synthetic_issue_pattern
        d_prefill_pattern = synthetic_d_prefill_pattern
        d_target_pattern = synthetic_d_target_pattern
        b_scale_tmem_pattern = synthetic_b_scale_tmem_pattern
        numel = int(candidate.numel())
        finite_mask = torch.isfinite(candidate)
        finite_count = int(finite_mask.sum().item()) if numel else 0
        first_head = candidate[0, 0] if candidate.ndim == 4 and batch > 0 and heads > 0 else candidate.reshape(0, 0)
        block_rows = seqlen // 32
        block_cols = tail_cols // 16
        if first_head.numel() and block_rows > 0 and block_cols > 0:
            block_view = first_head.reshape(block_rows, 32, block_cols, 16).permute(0, 2, 1, 3)
            block_mean = block_view.mean(dim=(-1, -2))
            block_min = block_view.amin(dim=(-1, -2))
            block_max = block_view.amax(dim=(-1, -2))
            block_nonzero = (block_view != 0).sum(dim=(-1, -2))
            first_row_first16 = [float(v) for v in first_head[0, : min(16, tail_cols)].detach().cpu().tolist()]
            first_col_first16 = [float(v) for v in first_head[: min(16, seqlen), 0].detach().cpu().tolist()]
            first_four_row_means = [
                float(v) for v in first_head[: min(4, seqlen), :].mean(dim=1).detach().cpu().tolist()
            ]
            first_four_col_means = [
                float(v) for v in first_head[:, : min(4, tail_cols)].mean(dim=0).detach().cpu().tolist()
            ]
        else:
            block_mean = block_min = block_max = block_nonzero = torch.empty(0, device=candidate.device)
            first_row_first16 = []
            first_col_first16 = []
            first_four_row_means = []
            first_four_col_means = []
        def _constant_ref(value: float) -> torch.Tensor:
            return torch.full_like(candidate, float(value), dtype=torch.float32)

        def _tail_half_ref(first_value: float, second_value: float) -> torch.Tensor:
            ref = torch.empty_like(candidate, dtype=torch.float32)
            split = tail_cols // 2
            ref[..., :split] = float(first_value)
            ref[..., split:] = float(second_value)
            return ref

        def _tail_n16_ref(
            col0_value: float,
            col16_value: float,
            col32_value: float,
            col48_value: float,
        ) -> torch.Tensor:
            ref = torch.empty_like(candidate, dtype=torch.float32)
            lane = tail_cols // 4
            ref[..., :lane] = float(col0_value)
            ref[..., lane : 2 * lane] = float(col16_value)
            ref[..., 2 * lane : 3 * lane] = float(col32_value)
            ref[..., 3 * lane :] = float(col48_value)
            return ref

        def _selected_row_rank_ref(rank0_value: float, rank1_value: float) -> torch.Tensor:
            ref = torch.zeros_like(candidate, dtype=torch.float32)
            row_tile = _TILE
            if seqlen >= row_tile:
                ref[..., :row_tile, :] = float(rank0_value)
            if seqlen >= 2 * row_tile:
                ref[..., row_tile : 2 * row_tile, :] = float(rank1_value)
            return ref

        def _apply_d_read_pattern(ref: torch.Tensor) -> torch.Tensor:
            split = tail_cols // 2
            if d_read_pattern == "duplicate_first_half_to_second_half":
                out = torch.empty_like(ref)
                out[..., :split] = ref[..., :split]
                out[..., split:] = ref[..., :split]
                return out
            if d_read_pattern == "second_half_to_first_half_only":
                out = torch.zeros_like(ref)
                out[..., :split] = ref[..., split:]
                return out
            if d_read_pattern == "first_half_to_second_half_only":
                out = torch.zeros_like(ref)
                out[..., split:] = ref[..., :split]
                return out
            return ref

        def _apply_issue_pattern(ref: torch.Tensor) -> torch.Tensor:
            if issue_pattern == "n_half0_chunk0_only":
                return _tail_half_ref(64.0, 0.0)
            if issue_pattern == "n_half1_chunk0_only":
                return _tail_half_ref(0.0, 64.0)
            if issue_pattern == "n_halves_chunk0_pair":
                return _tail_half_ref(64.0, 64.0)
            if issue_pattern == "n32_local_ncta1_half0_chunk0_only":
                return _tail_half_ref(64.0, 0.0)
            if issue_pattern == "n32_local_ncta1_half1_chunk0_only":
                return _tail_half_ref(0.0, 64.0)
            if issue_pattern == "n16_col0_chunk0_only":
                return _tail_n16_ref(64.0, 0.0, 0.0, 0.0)
            if issue_pattern == "n16_col16_chunk0_only":
                return _tail_n16_ref(0.0, 64.0, 0.0, 0.0)
            if issue_pattern == "n16_col32_chunk0_only":
                return _tail_n16_ref(0.0, 0.0, 64.0, 0.0)
            if issue_pattern == "n16_col48_chunk0_only":
                return _tail_n16_ref(0.0, 0.0, 0.0, 64.0)
            if issue_pattern in {
                "first_chunk_only",
                "second_chunk_only",
                "first_acc1_only",
                "second_acc1_only",
            }:
                return ref * 0.5
            return ref

        if pattern == "b_first_half_ones_second_half_zero":
            expected_candidates = (
                (
                    "synthetic_raw_b_first_half_direct_dcols0_32_128_dcols32_64_0",
                    _tail_half_ref(128.0, 0.0),
                ),
                (
                    "synthetic_raw_b_first_half_swapped_dcols0_32_0_dcols32_64_128",
                    _tail_half_ref(0.0, 128.0),
                ),
                ("synthetic_raw_b_first_half_all_ones_control_expected128", _constant_ref(128.0)),
                ("synthetic_raw_b_first_half_all_zero_control", _constant_ref(0.0)),
            )
        elif pattern == "b_first_half_zero_second_half_ones":
            expected_candidates = (
                (
                    "synthetic_raw_b_second_half_direct_dcols0_32_0_dcols32_64_128",
                    _tail_half_ref(0.0, 128.0),
                ),
                (
                    "synthetic_raw_b_second_half_swapped_dcols0_32_128_dcols32_64_0",
                    _tail_half_ref(128.0, 0.0),
                ),
                ("synthetic_raw_b_second_half_all_ones_control_expected128", _constant_ref(128.0)),
                ("synthetic_raw_b_second_half_all_zero_control", _constant_ref(0.0)),
            )
        elif pattern == "rank0_one_rank1_zero":
            expected_candidates = (
                (
                    "synthetic_rank0_one_rank1_zero_rows0_128_128_rows128_256_0",
                    _selected_row_rank_ref(128.0, 0.0),
                ),
                (
                    "synthetic_rank0_one_rank1_zero_swapped_rows0_128_0_rows128_256_128",
                    _selected_row_rank_ref(0.0, 128.0),
                ),
                (
                    "synthetic_rank0_one_rank1_zero_all_ones_control_expected128",
                    _constant_ref(128.0),
                ),
                ("synthetic_rank0_one_rank1_zero_all_zero_control", _constant_ref(0.0)),
            )
        else:
            expected_candidates = (
                (
                    "synthetic_all_ones_direct_dcols0_32_128_dcols32_64_128",
                    _tail_half_ref(128.0, 128.0),
                ),
                (
                    "synthetic_all_ones_swapped_dcols0_32_128_dcols32_64_128",
                    _tail_half_ref(128.0, 128.0),
                ),
                ("synthetic_all_ones_scale1_k128_expected128", _constant_ref(128.0)),
                ("synthetic_all_ones_scale1_single_k64_expected64", _constant_ref(64.0)),
                (
                    "synthetic_all_ones_scale1_mxfp4_dequant_div6xdiv6_expected128_over36",
                    _constant_ref(128.0 / 36.0),
                ),
                (
                    "synthetic_all_ones_scale1_single_k64_div6xdiv6_expected64_over36",
                    _constant_ref(64.0 / 36.0),
                ),
            )
        best_name: str | None = None
        best_max_abs: float | None = None
        best_rel: float | None = None
        transformed_expected_candidates = tuple(
            (
                f"{name}__issue_{issue_pattern}__d_read_{d_read_pattern}",
                _apply_d_read_pattern(_apply_issue_pattern(ref)),
            )
            for name, ref in expected_candidates
        )
        for name, ref in transformed_expected_candidates:
            diff = candidate - ref
            rel = float(
                (torch.linalg.vector_norm(diff) / torch.linalg.vector_norm(ref).clamp_min(1.0e-12)).item()
            )
            max_abs = float(diff.abs().max().item()) if diff.numel() else 0.0
            if best_rel is None or rel < best_rel:
                best_name = name
                best_max_abs = max_abs
                best_rel = rel
        best_base_name = best_name.split("__issue_", 1)[0] if best_name is not None else None
        all_ones_expected128_bases = {
            "synthetic_all_ones_direct_dcols0_32_128_dcols32_64_128",
            "synthetic_all_ones_swapped_dcols0_32_128_dcols32_64_128",
            "synthetic_all_ones_scale1_k128_expected128",
        }
        pattern_interpretation = "not_available"
        if pattern == "all_ones":
            pattern_interpretation = (
                f"all_ones_d_read_{d_read_pattern}_expected_match"
                if best_base_name in all_ones_expected128_bases
                and best_rel is not None
                and best_rel < 1.0e-3
                else f"all_ones_d_read_{d_read_pattern}_mismatch"
            )
        elif best_name is None:
            pattern_interpretation = "no_half_pattern_candidate"
        elif pattern == "rank0_one_rank1_zero" and "swapped" in best_name:
            pattern_interpretation = "rank_tagged_output_maps_to_opposite_cta_rank_rows"
        elif pattern == "rank0_one_rank1_zero":
            pattern_interpretation = "rank_tagged_output_maps_to_cta_rank_rows"
        elif "_direct_" in best_name:
            pattern_interpretation = "raw_b_stage_half_maps_direct_to_d_tail_half"
        elif "_swapped_" in best_name:
            pattern_interpretation = "raw_b_stage_half_maps_swapped_to_d_tail_half"
        elif "all_ones_control" in best_name:
            pattern_interpretation = "raw_b_stage_half_selection_did_not_zero_a_tail_half"
        elif "all_zero_control" in best_name:
            pattern_interpretation = "raw_b_stage_half_selection_suppressed_most_output"
        matches_expected128 = (
            d_read_pattern in {"normal", "duplicate_first_half_to_second_half"}
            and best_base_name in all_ones_expected128_bases
            and best_rel is not None
            and best_rel < 1.0e-3
        )
        status = (
            "synthetic_calibration_matches_expected128"
            if matches_expected128
            else f"synthetic_calibration_mismatched_best_{best_name}"
            if best_name is not None
            else "synthetic_calibration_no_candidate"
        )
        return {
            "synthetic_calibration_status": status,
            "synthetic_calibration_pattern": pattern,
            "synthetic_calibration_pattern_env": (
                "TK_FA4_MXFP4_BWD_MATERIALIZED_P_DS_SCAN_ABT_DK_SYNTHETIC_CALIBRATION_PATTERN"
            ),
            "synthetic_calibration_pattern_interpretation": pattern_interpretation,
            "synthetic_d_read_pattern": d_read_pattern,
            "synthetic_d_read_pattern_env": (
                "TK_FA4_MXFP4_BWD_MATERIALIZED_P_DS_SCAN_ABT_DK_SYNTHETIC_D_READ_PATTERN"
            ),
            "synthetic_d_read_pattern_contract": (
                "debug-only raw TMEM/D-readback half transform: normal=[raw0,raw1], "
                "duplicate_first_half_to_second_half=[raw0,raw0], "
                "second_half_to_first_half_only=[raw1,0], "
                "first_half_to_second_half_only=[0,raw0]"
            ),
            "synthetic_issue_pattern": issue_pattern,
            "synthetic_issue_pattern_env": (
                "TK_FA4_MXFP4_BWD_MATERIALIZED_P_DS_SCAN_ABT_DK_SYNTHETIC_ISSUE_PATTERN"
            ),
            "synthetic_issue_pattern_contract": (
                "debug-only TCGEN05 ABt k64 issue selector: normal issues chunk0 clear/no-commit "
                "then chunk1 accumulate/commit; first_chunk_only issues chunk0 clear/commit; "
                "second_chunk_only issues chunk1 clear/commit; second_then_first reverses the "
                "two-call order; first_twice issues chunk0 twice; second_twice issues chunk1 twice; "
                "first_then_second_acc0 uses ACC0 for both calls; first_acc1_only and "
                "second_acc1_only issue one chunk with ACC1; n_half0_chunk0_only and "
                "n_half1_chunk0_only issue one K64 chunk into explicit N32/D-half views; "
                "n_halves_chunk0_pair issues both N32/D-half views before one commit; "
                "n32_local_ncta1_half*_chunk0_only are parsed as fail-closed diagnostics "
                "because ptxas rejects mixing TCGEN05 .cta_group::1 and .cta_group::2 "
                "instructions inside the existing materialized-P debug kernel; "
                "n16_col*_chunk0_only are parsed as fail-closed host diagnostics because "
                "CLUSTER_SIZE=2 would require an 8-row FP4 B shared view, below the local "
                "st<fp4e2m1_2> 16-row subtile granularity"
            ),
            "synthetic_d_prefill_pattern": d_prefill_pattern,
            "synthetic_d_prefill_pattern_env": (
                "TK_FA4_MXFP4_BWD_MATERIALIZED_P_DS_SCAN_ABT_DK_SYNTHETIC_D_PREFILL_PATTERN"
            ),
            "synthetic_d_prefill_pattern_contract": (
                "debug-only pre-issue D accumulator fill: zero clears raw tail64; "
                "sentinel_halves fills raw cols0:32 with +11 and raw cols32:64 with -13"
            ),
            "synthetic_d_target_pattern": d_target_pattern,
            "synthetic_d_target_pattern_env": (
                "TK_FA4_MXFP4_BWD_MATERIALIZED_P_DS_SCAN_ABT_DK_SYNTHETIC_D_TARGET_PATTERN"
            ),
            "synthetic_d_target_pattern_contract": (
                "debug-only D target/descriptor selector: tail64_current uses rows0:32 B view "
                "with tail64 D; tail64_b_rows32_64 uses rows32:64 B view with the same tail64 D; "
                "full128 modes are selected-row-only because the alt Q-scale slot is safe but "
                "full D overlaps live-dP scale slots in multi-tile launches"
            ),
            "synthetic_b_scale_tmem_pattern": b_scale_tmem_pattern,
            "synthetic_b_scale_tmem_pattern_env": (
                "TK_FA4_MXFP4_BWD_MATERIALIZED_P_DS_SCAN_ABT_DK_SYNTHETIC_B_SCALE_TMEM_PATTERN"
            ),
            "synthetic_b_scale_tmem_pattern_contract": (
                "debug-only B scale TMEM lane diagnostic: normal passes the existing single "
                "full_tt_fp8e8m0<16> Q scale tile; duplicate_lane0_to_lane1 aliases the same "
                "TMEM base as full_tt_fp8e8m0<32> and loads the scale-one shared tile into "
                "both 16-column lanes before the N32 ABt issue"
            ),
            "synthetic_calibration_contract": (
                "C++ debug path overwrites staged A with packed FP4 ones 0x22, overwrites staged B "
                "according to the raw q_col_stage byte-half pattern, keeps both "
                "E8M0 scale-one 0x7f, issues the same deferred two-k64 ABt tail64 MMA, "
                "and stores the tail64 accumulator debug scratch; primary expected value is 128"
            ),
            "synthetic_calibration_debug_total_count": numel,
            "synthetic_calibration_debug_finite_count": finite_count,
            "synthetic_calibration_debug_nonzero": int(torch.count_nonzero(partial_debug).item()),
            "synthetic_calibration_debug_zero_count": int((candidate == 0).sum().item()),
            "synthetic_calibration_debug_positive_count": int((candidate > 0).sum().item()),
            "synthetic_calibration_debug_negative_count": int((candidate < 0).sum().item()),
            "synthetic_calibration_debug_min": float(candidate.min().item()) if numel else 0.0,
            "synthetic_calibration_debug_max": float(candidate.max().item()) if numel else 0.0,
            "synthetic_calibration_debug_mean": float(candidate.mean().item()) if candidate.numel() else 0.0,
            "synthetic_calibration_debug_std": float(candidate.std(unbiased=False).item()) if numel else 0.0,
            "synthetic_calibration_debug_max_abs": float(candidate.abs().max().item()) if candidate.numel() else 0.0,
            "synthetic_calibration_debug_first_head_block32x16_mean": block_mean.detach().cpu().tolist(),
            "synthetic_calibration_debug_first_head_block32x16_min": block_min.detach().cpu().tolist(),
            "synthetic_calibration_debug_first_head_block32x16_max": block_max.detach().cpu().tolist(),
            "synthetic_calibration_debug_first_head_block32x16_nonzero": block_nonzero.detach().cpu().tolist(),
            "synthetic_calibration_debug_first_row_first16": first_row_first16,
            "synthetic_calibration_debug_first_col_first16": first_col_first16,
            "synthetic_calibration_debug_first_four_row_means": first_four_row_means,
            "synthetic_calibration_debug_first_four_col_means": first_four_col_means,
            "synthetic_calibration_best_candidate_name": best_name,
            "synthetic_calibration_best_candidate_max_abs_diff": best_max_abs,
            "synthetic_calibration_best_candidate_rel_diff": best_rel,
            "synthetic_calibration_matches_expected128": bool(matches_expected128),
            "synthetic_calibration_expected128_max_abs_diff": float((candidate - 128.0).abs().max().item()) if candidate.numel() else 0.0,
            "synthetic_calibration_expected128_rel_diff": float(
                (
                    torch.linalg.vector_norm(candidate - 128.0)
                    / torch.linalg.vector_norm(torch.full_like(candidate, 128.0, dtype=torch.float32)).clamp_min(1.0e-12)
                ).item()
            ),
            "synthetic_calibration_candidate_count": len(transformed_expected_candidates),
            "synthetic_calibration_expected_reference_names": list(
                _mxfp4_bwd_materialized_p_synthetic_d_read_expected_reference_names(
                    pattern,
                    d_read_pattern,
                    issue_pattern,
                )
            ),
        }

    if synthetic_calibration_probe:
        return {
            "partial_ref_status": "synthetic_calibration_probe_live_reference_skipped",
            "partial_ref_contract": (
                "synthetic calibration overrides A/B operands, so live dS_col/Q_col partial reference "
                "is intentionally skipped; use synthetic_calibration_* fields"
            ),
            "partial_ref_max_abs_diff": None,
            "partial_ref_rel_diff": None,
            "partial_ref_best_candidate_name": None,
            "partial_ref_best_candidate_max_abs_diff": None,
            "partial_ref_best_candidate_rel_diff": None,
            "partial_ref_best_candidate_scale_ratio": None,
            "partial_ref_best_scale_convention_name": None,
            "partial_ref_best_scale_convention_max_abs_diff": None,
            "partial_ref_best_scale_convention_rel_diff": None,
            "partial_ref_best_readback_mapping_name": None,
            "partial_ref_best_readback_mapping_max_abs_diff": None,
            "partial_ref_best_readback_mapping_rel_diff": None,
            "partial_ref_readback_mapping_status": "synthetic_calibration_not_applicable",
            **_synthetic_calibration_metrics(),
            **a_artifact_metrics,
        }

    max_k_iters_env = os.environ.get("TK_FA4_MXFP4_LIVE_DP_MAX_K_ITERS")
    try:
        max_k_iters = -1 if max_k_iters_env is None else int(max_k_iters_env)
    except ValueError:
        max_k_iters = -1
    a_artifact_metrics = _mxfp4_materialized_p_a_artifact_metrics(
        ds_col_fp4,
        ds_col_sc,
        p_cache_row_fp4,
        p_cache_row_sc,
        v_row_fp4,
        v_row_sc,
        out_bshd,
        dout_bshd,
        softmax_scale=(
            float(softmax_scale)
            if softmax_scale is not None
            else 1.0 / math.sqrt(float(_D_QK))
        ),
        max_k_iters=max_k_iters,
    )
    compute_k_iter_base = 0
    first_k_iter = compute_k_iter_base
    real_kiter_accum_max_k_iters = max(0, int(real_kiter_accum_max_k_iters))
    real_kiter_accum_start_k_iter_offset = max(
        0,
        int(real_kiter_accum_start_k_iter_offset),
    )
    if real_kiter_accum_source_k_iter_offset is None or int(real_kiter_accum_source_k_iter_offset) < 0:
        real_kiter_accum_source_k_iter_offset = real_kiter_accum_start_k_iter_offset
    else:
        real_kiter_accum_source_k_iter_offset = max(
            0,
            int(real_kiter_accum_source_k_iter_offset),
        )
    real_kiter_accum_slot_mode = str(real_kiter_accum_slot_mode).strip().lower().replace(
        "-",
        "_",
    )
    if real_kiter_accum_slot_mode in ("0", ""):
        real_kiter_accum_slot_mode = "both"
    elif real_kiter_accum_slot_mode in ("1", "slot0"):
        real_kiter_accum_slot_mode = "slot0_only"
    elif real_kiter_accum_slot_mode in ("2", "slot1"):
        real_kiter_accum_slot_mode = "slot1_only"
    elif real_kiter_accum_slot_mode in ("3", "slot1_as_slot0"):
        real_kiter_accum_slot_mode = "slot1_via_slot0"
    real_kiter_accum_ref_local_k_start = real_kiter_accum_source_k_iter_offset
    real_kiter_accum_ref_local_k_count: int | None = (
        real_kiter_accum_max_k_iters if real_kiter_accum_max_k_iters > 0 else None
    )
    if real_kiter_accum_slot_mode == "slot0_only":
        real_kiter_accum_ref_local_k_count = 1
    elif real_kiter_accum_slot_mode in ("slot1_only", "slot1_via_slot0"):
        real_kiter_accum_ref_local_k_start = real_kiter_accum_source_k_iter_offset + 1
        real_kiter_accum_ref_local_k_count = 1
    q_col_chunk_pattern = _mxfp4_bwd_materialized_p_q_col_chunk_pattern_default()
    q_col_chunk_idx = {"chunk0": 0, "chunk1": 1, "chunk2": 2}[q_col_chunk_pattern]
    synthetic_issue_pattern_for_ref = _mxfp4_bwd_materialized_p_synthetic_issue_pattern_default()
    synthetic_mixed_operand_pattern_for_ref = (
        _mxfp4_bwd_materialized_p_synthetic_mixed_operand_pattern_default()
    )
    candidate = partial_debug.float()
    ds_full_by_bh: dict[tuple[int, int], torch.Tensor] = {}
    q_full_by_bh: dict[tuple[int, int], torch.Tensor] = {}
    q_payload_scale_one_by_bh: dict[tuple[int, int], torch.Tensor] = {}
    q_payload_scale_one_high_first_by_bh: dict[tuple[int, int], torch.Tensor] = {}

    def _fp4x2_to_fp32_high_first_for_ref(fp4: torch.Tensor) -> torch.Tensor:
        values = torch.tensor(
            [
                0.0, 0.5, 1.0, 1.5,
                2.0, 3.0, 4.0, 6.0,
                -0.0, -0.5, -1.0, -1.5,
                -2.0, -3.0, -4.0, -6.0,
            ],
            dtype=torch.float32,
            device=fp4.device,
        )
        packed = fp4.contiguous().view(torch.uint8).to(torch.int64)
        nibbles = torch.stack(((packed >> 4) & 0xF, packed & 0xF), dim=-1).flatten(
            start_dim=-2
        )
        return values[nibbles]

    for b in range(batch):
        for h in range(heads):
            ds_full_by_bh[(b, h)] = _dequantize_mxfp4_rows_2d(
                ds_col_fp4[b, h],
                ds_col_sc[b, h],
                rows=seqlen,
                cols=seqlen,
            )
            q_full_by_bh[(b, h)] = _dequantize_mxfp4_rows_2d(
                q_col_fp4[b, h],
                q_col_sc[b, h],
                rows=_D_QK_GEMM_PAD,
                cols=seqlen,
            )
            q_payload_scale_one_by_bh[(b, h)] = _fp4x2_to_fp32_for_debug(
                q_col_fp4[b, h].contiguous()
            )[:, :seqlen].contiguous()
            q_payload_scale_one_high_first_by_bh[(b, h)] = _fp4x2_to_fp32_high_first_for_ref(
                q_col_fp4[b, h].contiguous()
            )[:, :seqlen].contiguous()

    def _executed_and_valid(m_tile: int) -> tuple[int, int, bool]:
        cluster_start = (m_tile // _FP4PV_CLUSTER_SIZE) * _FP4PV_CLUSTER_SIZE
        full_iters_per_task = min(cluster_start + _FP4PV_CLUSTER_SIZE, tiles)
        if max_k_iters < 0:
            executed_k_iters = full_iters_per_task
        else:
            remaining_iters = full_iters_per_task - compute_k_iter_base
            executed_k_iters = 0 if remaining_iters <= 0 else min(remaining_iters, max_k_iters)
        remaining_valid = m_tile + 1 - compute_k_iter_base
        valid_k_iters = 0 if remaining_valid <= 0 else min(executed_k_iters, remaining_valid)
        full_cluster_valid = cluster_start + _FP4PV_CLUSTER_SIZE - 1 < tiles
        return executed_k_iters, valid_k_iters, full_cluster_valid

    def _candidate_k_iter(strategy: str, m_tile: int) -> int:
        if strategy == "k0":
            return compute_k_iter_base
        if strategy == "k1":
            return min(compute_k_iter_base + 1, tiles - 1)
        if strategy == "cluster_start":
            return (m_tile // _FP4PV_CLUSTER_SIZE) * _FP4PV_CLUSTER_SIZE
        if strategy == "row_m_tile":
            return m_tile
        raise ValueError(f"unknown partial dK candidate k strategy {strategy}")

    def _build_ref(
        *,
        q_row_start: int,
        k_strategy: str,
        orientation: str,
    ) -> torch.Tensor:
        out = torch.zeros(partial_debug.shape, device=partial_debug.device, dtype=torch.float32)
        if q_row_start < 0 or q_row_start + tail_cols > _D_QK_GEMM_PAD:
            return out
        for b in range(batch):
            for h in range(heads):
                ds_full = ds_full_by_bh[(b, h)]
                q_full = q_full_by_bh[(b, h)]
                for m_tile in range(tiles):
                    _, valid_k_iters, full_cluster_valid = _executed_and_valid(m_tile)
                    if not full_cluster_valid or valid_k_iters <= 0:
                        continue
                    k_iter = _candidate_k_iter(k_strategy, m_tile)
                    if not (0 <= k_iter < tiles) or k_iter > m_tile:
                        continue
                    key_start = k_iter * _TILE
                    query_start = m_tile * _TILE
                    ds_tile = ds_full[key_start:key_start + _TILE, query_start:query_start + _TILE]
                    q_tile = q_full[q_row_start:q_row_start + tail_cols, query_start:query_start + _TILE]
                    if orientation == "ds_qt":
                        ref_tile = (ds_tile.to(torch.bfloat16) @ q_tile.to(torch.bfloat16).T).float()
                    elif orientation == "dst_qt":
                        ref_tile = (ds_tile.T.to(torch.bfloat16) @ q_tile.to(torch.bfloat16).T).float()
                    else:
                        raise ValueError(f"unknown partial dK candidate orientation {orientation}")
                    out[b, h, query_start:query_start + _TILE, :].copy_(ref_tile)
        return out

    def _build_cluster_mtile_per_rank_ref(
        *,
        q_chunk_idx: int,
        k_strategy: str,
        orientation: str,
    ) -> torch.Tensor:
        out = torch.zeros(partial_debug.shape, device=partial_debug.device, dtype=torch.float32)
        q_row_base = q_chunk_idx * tail_cols
        if _FP4PV_CLUSTER_SIZE != 2 or tail_cols != 64:
            return out
        if q_row_base < 0 or q_row_base + tail_cols > _D_QK_GEMM_PAD:
            return out
        for b in range(batch):
            for h in range(heads):
                ds_full = ds_full_by_bh[(b, h)]
                q_full = q_full_by_bh[(b, h)]
                for cluster_m_tile in range(0, tiles, _FP4PV_CLUSTER_SIZE):
                    if cluster_m_tile + _FP4PV_CLUSTER_SIZE > tiles:
                        continue
                    for rank in range(_FP4PV_CLUSTER_SIZE):
                        m_tile = cluster_m_tile + rank
                        _, valid_k_iters, full_cluster_valid = _executed_and_valid(m_tile)
                        if not full_cluster_valid or valid_k_iters <= 0:
                            continue
                        k_iter = _candidate_k_iter(k_strategy, m_tile)
                        if not (0 <= k_iter < tiles) or k_iter > m_tile:
                            continue
                        key_start = k_iter * _TILE
                        query_start = m_tile * _TILE
                        q_rank_row_start = q_row_base + rank * 32
                        q_rank = q_full[
                            q_rank_row_start:q_rank_row_start + 32,
                            query_start:query_start + _TILE,
                        ]
                        ds_tile = ds_full[
                            key_start:key_start + _TILE,
                            query_start:query_start + _TILE,
                        ]
                        if orientation == "ds_qt":
                            ref_half = (
                                ds_tile.to(torch.bfloat16) @ q_rank.to(torch.bfloat16).T
                            ).float()
                        elif orientation == "dst_qt":
                            ref_half = (
                                ds_tile.T.to(torch.bfloat16) @ q_rank.to(torch.bfloat16).T
                            ).float()
                        else:
                            raise ValueError(
                                f"unknown partial dK candidate orientation {orientation}"
                            )
                        col_start = rank * 32
                        out[
                            b,
                            h,
                            query_start:query_start + _TILE,
                            col_start:col_start + 32,
                        ].copy_(ref_half)
        return out

    def _build_cluster_mtile_per_rank_all_valid_kiter_accum_ref(
        *,
        q_chunk_idx: int,
        orientation: str,
        shared_output: bool = False,
        local_k_start: int = 0,
        local_k_count: int | None = None,
        ds_source_by_bh: dict[tuple[int, int], torch.Tensor] | None = None,
    ) -> torch.Tensor:
        """Reference for the slow real-kiter debug contract.

        This is deliberately a debug scratch contract, not production dK layout:
        the C++ probe serially reuses one tail64 accumulator at the current
        post-store row tile and accumulates every valid causal dS_col k_iter into
        that scratch before storing it.  Production dK still needs key-owned
        output placement/reduction.
        """
        out = torch.zeros(partial_debug.shape, device=partial_debug.device, dtype=torch.float32)
        q_row_base = q_chunk_idx * tail_cols
        if _FP4PV_CLUSTER_SIZE != 2 or tail_cols != 64:
            return out
        if q_row_base < 0 or q_row_base + tail_cols > _D_QK_GEMM_PAD:
            return out
        ds_sources = ds_full_by_bh if ds_source_by_bh is None else ds_source_by_bh
        for b in range(batch):
            for h in range(heads):
                ds_full = ds_sources[(b, h)]
                q_full = q_full_by_bh[(b, h)]
                for cluster_m_tile in range(0, tiles, _FP4PV_CLUSTER_SIZE):
                    if cluster_m_tile + _FP4PV_CLUSTER_SIZE > tiles:
                        continue
                    for rank in range(_FP4PV_CLUSTER_SIZE):
                        m_tile = cluster_m_tile + rank
                        _, valid_k_iters, full_cluster_valid = _executed_and_valid(m_tile)
                        if not full_cluster_valid or valid_k_iters <= 0:
                            continue
                        bounded_local_k_start = max(0, int(local_k_start))
                        bounded_local_k_end = valid_k_iters
                        if local_k_count is not None:
                            bounded_local_k_end = min(
                                bounded_local_k_end,
                                bounded_local_k_start + max(0, int(local_k_count)),
                            )
                        elif real_kiter_accum_max_k_iters > 0:
                            bounded_local_k_end = min(
                                bounded_local_k_end,
                                real_kiter_accum_max_k_iters,
                            )
                        if bounded_local_k_start >= bounded_local_k_end:
                            continue
                        query_start = m_tile * _TILE
                        q_rank_row_start = q_row_base + rank * 32
                        q_rank = q_full[
                            q_rank_row_start:q_rank_row_start + 32,
                            query_start:query_start + _TILE,
                        ]
                        output_query_start = (
                            cluster_m_tile * _TILE if shared_output else query_start
                        )
                        accum = torch.zeros((_TILE, 32), device=partial_debug.device, dtype=torch.float32)
                        for local_k in range(bounded_local_k_start, bounded_local_k_end):
                            k_iter = compute_k_iter_base + local_k
                            if not (0 <= k_iter < tiles) or k_iter > m_tile:
                                continue
                            key_start = k_iter * _TILE
                            ds_tile = ds_full[
                                key_start:key_start + _TILE,
                                query_start:query_start + _TILE,
                            ]
                            if orientation == "ds_qt":
                                ref_half = (
                                    ds_tile.to(torch.bfloat16) @ q_rank.to(torch.bfloat16).T
                                ).float()
                            elif orientation == "dst_qt":
                                ref_half = (
                                    ds_tile.T.to(torch.bfloat16) @ q_rank.to(torch.bfloat16).T
                                ).float()
                            else:
                                raise ValueError(
                                    f"unknown real-kiter dK candidate orientation {orientation}"
                                )
                            accum += ref_half
                        col_start = rank * 32
                        out[
                            b,
                            h,
                            output_query_start:output_query_start + _TILE,
                            col_start:col_start + 32,
                        ].copy_(accum)
        return out

    def _build_cluster_synthetic_ds_q_payload_scale_one_ref(
        *,
        q_chunk_idx: int,
        issue_pattern: str,
        high_first_nibbles: bool = False,
    ) -> torch.Tensor:
        out = torch.zeros(partial_debug.shape, device=partial_debug.device, dtype=torch.float32)
        q_row_base = q_chunk_idx * tail_cols
        if _FP4PV_CLUSTER_SIZE != 2 or tail_cols != 64:
            return out
        if q_row_base < 0 or q_row_base + tail_cols > _D_QK_GEMM_PAD:
            return out
        if issue_pattern == "first_chunk_only":
            issue_k_offset = 0
        elif issue_pattern == "second_chunk_only":
            issue_k_offset = _TILE // 2
        else:
            return out
        for b in range(batch):
            for h in range(heads):
                q_full = (
                    q_payload_scale_one_high_first_by_bh[(b, h)]
                    if high_first_nibbles
                    else q_payload_scale_one_by_bh[(b, h)]
                )
                for cluster_m_tile in range(0, tiles, _FP4PV_CLUSTER_SIZE):
                    if cluster_m_tile + _FP4PV_CLUSTER_SIZE > tiles:
                        continue
                    for rank in range(_FP4PV_CLUSTER_SIZE):
                        m_tile = cluster_m_tile + rank
                        _, valid_k_iters, full_cluster_valid = _executed_and_valid(m_tile)
                        if not full_cluster_valid or valid_k_iters <= 0:
                            continue
                        query_start = m_tile * _TILE
                        q_rank_row_start = q_row_base + rank * 32
                        q_rank = q_full[
                            q_rank_row_start:q_rank_row_start + 32,
                            query_start + issue_k_offset:
                            query_start + issue_k_offset + (_TILE // 2),
                        ]
                        ref_half = q_rank.float().sum(dim=1).view(1, 32).expand(_TILE, 32)
                        col_start = rank * 32
                        out[
                            b,
                            h,
                            query_start:query_start + _TILE,
                            col_start:col_start + 32,
                        ].copy_(ref_half)
        return out

    def _build_cluster_synthetic_ds_q_payload_scale_one_shared_output_ref(
        *,
        q_chunk_idx: int,
        issue_pattern: str,
        high_first_nibbles: bool = False,
    ) -> torch.Tensor:
        out = torch.zeros(partial_debug.shape, device=partial_debug.device, dtype=torch.float32)
        q_row_base = q_chunk_idx * tail_cols
        if _FP4PV_CLUSTER_SIZE != 2 or tail_cols != 64:
            return out
        if q_row_base < 0 or q_row_base + tail_cols > _D_QK_GEMM_PAD:
            return out
        if issue_pattern == "first_chunk_only":
            issue_k_offset = 0
        elif issue_pattern == "second_chunk_only":
            issue_k_offset = _TILE // 2
        else:
            return out
        for b in range(batch):
            for h in range(heads):
                q_full = (
                    q_payload_scale_one_high_first_by_bh[(b, h)]
                    if high_first_nibbles
                    else q_payload_scale_one_by_bh[(b, h)]
                )
                for cluster_m_tile in range(0, tiles, _FP4PV_CLUSTER_SIZE):
                    if cluster_m_tile + _FP4PV_CLUSTER_SIZE > tiles:
                        continue
                    output_query_start = cluster_m_tile * _TILE
                    for rank in range(_FP4PV_CLUSTER_SIZE):
                        rank_m_tile = cluster_m_tile + rank
                        _, valid_k_iters, full_cluster_valid = _executed_and_valid(rank_m_tile)
                        if not full_cluster_valid or valid_k_iters <= 0:
                            continue
                        q_query_start = rank_m_tile * _TILE
                        q_rank_row_start = q_row_base + rank * 32
                        q_rank = q_full[
                            q_rank_row_start:q_rank_row_start + 32,
                            q_query_start + issue_k_offset:
                            q_query_start + issue_k_offset + (_TILE // 2),
                        ]
                        ref_half = q_rank.float().sum(dim=1).view(1, 32).expand(_TILE, 32)
                        col_start = rank * 32
                        out[
                            b,
                            h,
                            output_query_start:output_query_start + _TILE,
                            col_start:col_start + 32,
                        ].copy_(ref_half)
        return out

    real_kiter_accum_effective_label = _mxfp4_materialized_p_real_kiter_accum_label(
        (
            real_kiter_accum_ref_local_k_count
            if real_kiter_accum_ref_local_k_count is not None
            else real_kiter_accum_max_k_iters
        ),
        start=real_kiter_accum_ref_local_k_start,
    )
    if real_kiter_accum_probe:
        ref = _build_cluster_mtile_per_rank_all_valid_kiter_accum_ref(
            q_chunk_idx=q_col_chunk_idx,
            orientation="ds_qt",
            shared_output=bool(real_kiter_accum_pingpong_issue_cta_wait_probe),
            local_k_start=real_kiter_accum_ref_local_k_start,
            local_k_count=real_kiter_accum_ref_local_k_count,
        )
    else:
        ref = _build_ref(q_row_start=0, k_strategy="k0", orientation="ds_qt")
    diff = candidate - ref
    ref_norm = torch.linalg.vector_norm(ref)
    candidate_norm_sq = torch.sum(candidate * candidate)
    best_candidate_name: str | None = None
    best_candidate_max_abs_diff: float | None = None
    best_candidate_rel_diff: float | None = None
    best_candidate_scale_ratio: float | None = None
    best_scale_convention_name: str | None = None
    best_scale_convention_max_abs_diff: float | None = None
    best_scale_convention_rel_diff: float | None = None
    best_readback_mapping_name: str | None = None
    best_readback_mapping_max_abs_diff: float | None = None
    best_readback_mapping_rel_diff: float | None = None
    cluster_mtile_per_rank_candidate_count = 0
    cluster_mtile_per_rank_best_candidate_name: str | None = None
    cluster_mtile_per_rank_best_candidate_max_abs_diff: float | None = None
    cluster_mtile_per_rank_best_candidate_rel_diff: float | None = None
    cluster_mtile_per_rank_best_candidate_scale_ratio: float | None = None
    candidate_count = 0
    real_kiter_pair_debug_metrics: dict[str, Any] = {
        "partial_ref_real_kiter_pair0_label": None,
        "partial_ref_real_kiter_pair0_shared_output_raw_rel_diff": None,
        "partial_ref_real_kiter_pair0_shared_output_raw_max_abs_diff": None,
        "partial_ref_real_kiter_pair0_shared_output_scaled_rel_diff": None,
        "partial_ref_real_kiter_pair0_shared_output_scaled_max_abs_diff": None,
        "partial_ref_real_kiter_pair0_shared_output_scale_ratio": None,
        "partial_ref_real_kiter_pair1_label": None,
        "partial_ref_real_kiter_pair1_shared_output_raw_rel_diff": None,
        "partial_ref_real_kiter_pair1_shared_output_raw_max_abs_diff": None,
        "partial_ref_real_kiter_pair1_shared_output_scaled_rel_diff": None,
        "partial_ref_real_kiter_pair1_shared_output_scaled_max_abs_diff": None,
        "partial_ref_real_kiter_pair1_shared_output_scale_ratio": None,
        "partial_ref_real_kiter_accum_shared_output_raw_rel_diff": None,
        "partial_ref_real_kiter_accum_shared_output_raw_max_abs_diff": None,
        "partial_ref_real_kiter_accum_shared_output_scaled_rel_diff": None,
        "partial_ref_real_kiter_accum_shared_output_scaled_max_abs_diff": None,
        "partial_ref_real_kiter_accum_shared_output_scale_ratio": None,
    }
    real_kiter_artifact_replay_metrics: dict[str, Any] = {
        "partial_ref_real_kiter_artifact_replay_status": "not_requested",
        "partial_ref_real_kiter_artifact_replay_label": None,
        "partial_ref_real_kiter_artifact_replay_control_start_k_iter_offset": None,
        "partial_ref_real_kiter_artifact_replay_source_k_iter_offset": None,
        "partial_ref_real_kiter_artifact_replay_slot_mode": None,
        "partial_ref_real_kiter_artifact_replay_vs_bf16_rel_diff": None,
        "partial_ref_real_kiter_artifact_replay_vs_bf16_max_abs_diff": None,
        "partial_ref_real_kiter_artifact_replay_vs_existing_partial_ref_rel_diff": None,
        "partial_ref_real_kiter_artifact_replay_vs_existing_partial_ref_max_abs_diff": None,
        "partial_ref_real_kiter_artifact_replay_vs_kernel_rel_diff": None,
        "partial_ref_real_kiter_artifact_replay_vs_kernel_max_abs_diff": None,
        "partial_ref_real_kiter_artifact_replay_vs_kernel_scale_ratio": None,
        "partial_ref_real_kiter_artifact_replay_nonzero": None,
        "partial_ref_real_kiter_artifact_replay_max_abs": None,
        "partial_ref_real_kiter_bf16_replay_nonzero": None,
        "partial_ref_real_kiter_bf16_replay_max_abs": None,
    }
    consumer_b_expectation_metrics: dict[str, Any] = {
        key: None for key in _MATERIALIZED_P_DK_CONSUMER_B_EXPECTATION_KEYS
    }
    consumer_b_expectation_metrics["partial_ref_consumer_b_expectation_status"] = (
        "not_requested"
    )

    def _debug_vs_ref_raw_scaled_metrics(ref_candidate: torch.Tensor) -> dict[str, float | None]:
        ref_norm_sq = torch.sum(ref_candidate * ref_candidate)
        ref_norm_sq_value = float(ref_norm_sq.item())
        if not math.isfinite(ref_norm_sq_value) or ref_norm_sq_value <= 1.0e-24:
            return {
                "raw_rel_diff": None,
                "raw_max_abs_diff": None,
                "scaled_rel_diff": None,
                "scaled_max_abs_diff": None,
                "scale_ratio": None,
            }
        raw_diff = candidate - ref_candidate
        raw_rel = float(
            (torch.linalg.vector_norm(raw_diff) / torch.sqrt(ref_norm_sq).clamp_min(1.0e-12)).item()
        )
        raw_max = float(raw_diff.abs().max().item()) if raw_diff.numel() else 0.0
        scale = float((torch.sum(candidate * ref_candidate) / ref_norm_sq.clamp_min(1.0e-24)).item())
        scaled_ref = ref_candidate * scale
        scaled_diff = candidate - scaled_ref
        scaled_den = torch.sqrt((ref_norm_sq * (scale * scale)).clamp_min(1.0e-24))
        scaled_rel = float(
            (torch.linalg.vector_norm(scaled_diff) / scaled_den.clamp_min(1.0e-12)).item()
        )
        scaled_max = float(scaled_diff.abs().max().item()) if scaled_diff.numel() else 0.0
        return {
            "raw_rel_diff": raw_rel,
            "raw_max_abs_diff": raw_max,
            "scaled_rel_diff": scaled_rel,
            "scaled_max_abs_diff": scaled_max,
            "scale_ratio": scale,
        }

    def _consumer_b_slice_metrics(
        *,
        name: str,
        debug_slice: torch.Tensor,
        ref_slice: torch.Tensor,
    ) -> dict[str, Any]:
        ref_norm_sq = torch.sum(ref_slice * ref_slice)
        ref_norm_sq_value = float(ref_norm_sq.item())
        debug_norm_sq = torch.sum(debug_slice * debug_slice)
        debug_norm_sq_value = float(debug_norm_sq.item())
        if (
            not math.isfinite(ref_norm_sq_value)
            or ref_norm_sq_value <= 1.0e-24
            or not math.isfinite(debug_norm_sq_value)
        ):
            return {
                f"{name}_raw_rel_diff": None,
                f"{name}_raw_max_abs_diff": None,
                f"{name}_scaled_rel_diff": None,
                f"{name}_scaled_max_abs_diff": None,
                f"{name}_scale_ratio": None,
                f"{name}_cosine": None,
                f"{name}_correlation": None,
                f"{name}_debug_nonzero": int(torch.count_nonzero(debug_slice).item()),
                f"{name}_ref_nonzero": int(torch.count_nonzero(ref_slice).item()),
                f"{name}_support_intersection": None,
                f"{name}_debug_only": None,
                f"{name}_ref_only": None,
                f"{name}_kernel_first8": [
                    float(v) for v in debug_slice.flatten()[:8].detach().cpu().tolist()
                ],
                f"{name}_ref_first8": [
                    float(v) for v in ref_slice.flatten()[:8].detach().cpu().tolist()
                ],
            }
        diff = debug_slice - ref_slice
        raw_rel = float(
            (
                torch.linalg.vector_norm(diff)
                / torch.sqrt(ref_norm_sq).clamp_min(1.0e-12)
            ).item()
        )
        raw_max = float(diff.abs().max().item()) if diff.numel() else 0.0
        scale = float(
            (
                torch.sum(debug_slice * ref_slice)
                / ref_norm_sq.clamp_min(1.0e-24)
            ).item()
        )
        scaled_ref = ref_slice * scale
        scaled_diff = debug_slice - scaled_ref
        scaled_den = torch.sqrt((ref_norm_sq * (scale * scale)).clamp_min(1.0e-24))
        scaled_rel = float(
            (
                torch.linalg.vector_norm(scaled_diff)
                / scaled_den.clamp_min(1.0e-12)
            ).item()
        )
        scaled_max = float(scaled_diff.abs().max().item()) if scaled_diff.numel() else 0.0
        cosine = float(
            (
                torch.sum(debug_slice * ref_slice)
                / (
                    torch.sqrt(debug_norm_sq).clamp_min(1.0e-12)
                    * torch.sqrt(ref_norm_sq).clamp_min(1.0e-12)
                )
            ).item()
        )
        debug_flat = debug_slice.flatten()
        ref_flat = ref_slice.flatten()
        debug_centered = debug_flat - debug_flat.mean()
        ref_centered = ref_flat - ref_flat.mean()
        corr_den = (
            torch.linalg.vector_norm(debug_centered)
            * torch.linalg.vector_norm(ref_centered)
        )
        correlation = (
            float((torch.sum(debug_centered * ref_centered) / corr_den).item())
            if float(corr_den.item()) > 1.0e-12
            else None
        )
        debug_support = debug_slice != 0
        ref_support = ref_slice != 0
        support_intersection = int((debug_support & ref_support).sum().item())
        debug_only = int((debug_support & ~ref_support).sum().item())
        ref_only = int((~debug_support & ref_support).sum().item())
        return {
            f"{name}_raw_rel_diff": raw_rel,
            f"{name}_raw_max_abs_diff": raw_max,
            f"{name}_scaled_rel_diff": scaled_rel,
            f"{name}_scaled_max_abs_diff": scaled_max,
            f"{name}_scale_ratio": scale,
            f"{name}_cosine": cosine,
            f"{name}_correlation": correlation,
            f"{name}_debug_nonzero": int(torch.count_nonzero(debug_slice).item()),
            f"{name}_ref_nonzero": int(torch.count_nonzero(ref_slice).item()),
            f"{name}_support_intersection": support_intersection,
            f"{name}_debug_only": debug_only,
            f"{name}_ref_only": ref_only,
            f"{name}_kernel_first8": [
                float(v) for v in debug_slice.flatten()[:8].detach().cpu().tolist()
            ],
            f"{name}_ref_first8": [
                float(v) for v in ref_slice.flatten()[:8].detach().cpu().tolist()
            ],
        }

    def _build_selected_consumer_b_bad_half_ref(
        q_row_start: int,
        *,
        b_chunk_order: str = "default_kmajor",
    ) -> torch.Tensor:
        out = torch.zeros(
            partial_debug.shape,
            device=partial_debug.device,
            dtype=torch.float32,
        )
        if q_row_start < 0 or q_row_start + 32 > _D_QK_GEMM_PAD:
            return out
        selected_row_env = os.environ.get("TK_FA4_MXFP4_LIVE_DP_SELECTED_ROW_TILE", "0")
        try:
            selected_row_tile = int(selected_row_env)
        except ValueError:
            selected_row_tile = 0
        selected_m_tile = _selected_row_tile_cluster_base(selected_row_tile)
        if selected_m_tile < 0 or selected_m_tile >= tiles:
            return out
        _, valid_k_iters, full_cluster_valid = _executed_and_valid(selected_m_tile)
        if not full_cluster_valid or valid_k_iters <= 0:
            return out
        bounded_local_k_start = max(0, int(real_kiter_accum_ref_local_k_start))
        bounded_local_k_end = valid_k_iters
        if real_kiter_accum_ref_local_k_count is not None:
            bounded_local_k_end = min(
                bounded_local_k_end,
                bounded_local_k_start + max(0, int(real_kiter_accum_ref_local_k_count)),
            )
        elif real_kiter_accum_max_k_iters > 0:
            bounded_local_k_end = min(
                bounded_local_k_end,
                real_kiter_accum_max_k_iters,
            )
        if bounded_local_k_start >= bounded_local_k_end:
            return out
        query_start = selected_m_tile * _TILE
        output_query_start = (
            selected_m_tile * _TILE
            if real_kiter_accum_pingpong_issue_cta_wait_probe
            else query_start
        )
        for b in range(batch):
            for h in range(heads):
                ds_full = ds_full_by_bh[(b, h)]
                q_full = q_full_by_bh[(b, h)]
                q_candidate = q_full[
                    q_row_start:q_row_start + 32,
                    query_start:query_start + _TILE,
                ]
                accum = torch.zeros((_TILE, 32), device=partial_debug.device, dtype=torch.float32)
                for local_k in range(bounded_local_k_start, bounded_local_k_end):
                    k_iter = compute_k_iter_base + local_k
                    if not (0 <= k_iter < tiles) or k_iter > selected_m_tile:
                        continue
                    key_start = k_iter * _TILE
                    ds_tile = ds_full[
                        key_start:key_start + _TILE,
                        query_start:query_start + _TILE,
                    ]
                    if b_chunk_order == "swap_kmajor_chunks":
                        accum += (
                            ds_tile[:, : _TILE // 2].to(torch.bfloat16)
                            @ q_candidate[:, _TILE // 2 : _TILE].to(torch.bfloat16).T
                        ).float()
                        accum += (
                            ds_tile[:, _TILE // 2 : _TILE].to(torch.bfloat16)
                            @ q_candidate[:, : _TILE // 2].to(torch.bfloat16).T
                        ).float()
                    else:
                        accum += (
                            ds_tile.to(torch.bfloat16) @ q_candidate.to(torch.bfloat16).T
                        ).float()
                out[
                    b,
                    h,
                    output_query_start:output_query_start + _TILE,
                    32:64,
                ].copy_(accum)
        return out

