def _quantize_dequantize_rows_2d(
    x_2d: torch.Tensor,
    *,
    backend: str,
) -> torch.Tensor:
    backend = _normalize_sandbox_quant_backend(backend)
    if backend == "none":
        return x_2d.to(torch.bfloat16)
    if backend == "v5":
        rec = _quantize_rows_2d_v5(x_2d)
        return _dequantize_v5_rows_2d(rec["fp4"], rec["scales"], rec["sg_scalar"], rows=rec["rows"], cols=rec["cols"]).to(torch.bfloat16)
    if backend == "localcta":
        rec = _quantize_rows_2d_localcta_prepared(x_2d, pad_cols_to_tile=True)
        fp4_4d = rec["fp4"].view(1, 1, rec["rows"], rec["padded_cols"] // 2)
        sc_5d = rec["scales"].view(1, 1, rec["rows"] // 128, rec["padded_cols"] // 64, 512)
        out = _dequantize_prepared_fp4_rows_for_debug(fp4_4d, sc_5d).view(rec["rows"], rec["padded_cols"])
        return out[:, :rec["cols"]].to(torch.bfloat16).contiguous()
    if backend == "mxfp4":
        rec = _quantize_rows_2d_mxfp4(x_2d, backend=backend, pad_cols_to_tile=True)
        return _dequantize_mxfp4_rows_2d(rec["fp4"], rec["scales"], rows=rec["rows"], cols=rec["cols"]).to(torch.bfloat16)
    raise ValueError("backend must be one of 'none', 'v5', 'localcta', 'mxfp4'")


def pv_from_p(
    p_fp4: torch.Tensor,
    p_sc_prepared: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
) -> torch.Tensor:
    """Run FP4 PV from prequantized P and prequantized V."""
    _check_cuda_contiguous(p_fp4, "p_fp4")
    _check_cuda_contiguous(p_sc_prepared, "p_sc_prepared")
    if p_fp4.dtype != torch.float4_e2m1fn_x2:
        raise ValueError("p_fp4 must have dtype torch.float4_e2m1fn_x2")
    if p_sc_prepared.dtype != torch.float8_e4m3fn:
        raise ValueError("p_sc_prepared must have dtype torch.float8_e4m3fn")
    if p_fp4.ndim != 4 or p_sc_prepared.ndim != 5:
        raise ValueError("p_fp4/p_sc_prepared must have shapes (B,H,S,S/2) and (B,H,S/128,S/64,512)")

    batch, heads, seqlen, packed_cols = p_fp4.shape
    if packed_cols * 2 != seqlen:
        raise ValueError("p_fp4 last dimension must equal seqlen/2")
    if p_sc_prepared.shape != (batch, heads, seqlen // 128, seqlen // 64, 512):
        raise ValueError(f"p_sc_prepared must have shape {(batch, heads, seqlen // 128, seqlen // 64, 512)}")
    _check_prequantized_v(v_fp4, v_sc_prepared, batch, heads, seqlen)

    out_bhsd = _localcta_pv_into(p_fp4, p_sc_prepared, v_fp4, v_sc_prepared)
    return out_bhsd.permute(0, 2, 1, 3).contiguous()


def _slice_prepared_scale_k_window(sc_prepared: torch.Tensor, tile_idx: int, tile_count: int = 1) -> torch.Tensor:
    _check_cuda_contiguous(sc_prepared, "sc_prepared")
    if sc_prepared.dtype != torch.float8_e4m3fn:
        raise ValueError("sc_prepared must have dtype torch.float8_e4m3fn")
    if sc_prepared.ndim != 5:
        raise ValueError("sc_prepared must have rank 5")
    blocks_per_tile = _TILE // 64
    start = tile_idx * blocks_per_tile
    stop = start + tile_count * blocks_per_tile
    return sc_prepared[:, :, :, start:stop, :].contiguous()


def _native_two_tile_pv_tmem_debug(
    p_fp4: torch.Tensor,
    p_sc_prepared: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
    *,
    second_tile_mm2: bool,
) -> tuple[torch.Tensor, torch.Tensor]:
    ext = _load_forward_experiments_ext()
    batch, heads, rows, packed_cols = p_fp4.shape
    seqlen = packed_cols * 2
    if rows != seqlen:
        raise ValueError("p_fp4 must be square in its sequence dimensions for two-tile PV debug")
    _check_prequantized_v(v_fp4, v_sc_prepared, batch, heads, seqlen)
    out0 = torch.empty((batch, seqlen, heads, _D_VO), dtype=torch.bfloat16, device=p_fp4.device)
    out1 = torch.empty_like(out0)
    with _cuda_device_ctx(p_fp4.device):
        ext.two_tile_pv_tmem_debug(
            p_fp4,
            p_sc_prepared,
            v_fp4,
            v_sc_prepared,
            out0,
            out1,
            bool(second_tile_mm2),
        )
    return out0.float(), out1.float()


def _native_two_tile_pv_mainpath_debug(
    p_fp4: torch.Tensor,
    p_sc_prepared: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
    *,
    tile_begin: int = 0,
    tiles_to_run: int = 2,
    second_tile_mm2: bool = False,
    pv_wait_count: int | None = None,
    early_tile_arrived: bool = False,
) -> torch.Tensor:
    ext = _load_forward_experiments_ext()
    batch, heads, rows, packed_cols = p_fp4.shape
    seqlen = packed_cols * 2
    if rows != seqlen:
        raise ValueError("p_fp4 must be square in its sequence dimensions for two-tile PV mainpath debug")
    if seqlen % (2 * _TILE) != 0:
        raise ValueError("two_tile_pv_mainpath_debug currently requires sequence length divisible by 256")
    if tile_begin < 0:
        raise ValueError("tile_begin must be non-negative")
    if tiles_to_run not in (1, 2):
        raise ValueError("tiles_to_run must be 1 or 2")
    if tile_begin + tiles_to_run > seqlen // _TILE:
        raise ValueError("tile range must fit within sequence tiles")
    if pv_wait_count is None:
        pv_wait_count = tiles_to_run
    if pv_wait_count < 1 or pv_wait_count > tiles_to_run:
        raise ValueError("pv_wait_count must be in [1, tiles_to_run]")
    _check_prequantized_v(v_fp4, v_sc_prepared, batch, heads, seqlen)
    out = torch.empty((batch, seqlen, heads, _D_VO), dtype=torch.bfloat16, device=p_fp4.device)
    with _cuda_device_ctx(p_fp4.device):
        ext.two_tile_pv_mainpath_debug(
            p_fp4,
            p_sc_prepared,
            v_fp4,
            v_sc_prepared,
            out,
            int(tile_begin),
            int(tiles_to_run),
            bool(second_tile_mm2),
            int(pv_wait_count),
            bool(early_tile_arrived),
        )
    return out.float()


def _native_two_tile_correction_replay_debug(
    o_pre_correction: torch.Tensor,
    correction: torch.Tensor,
    row_sum: torch.Tensor,
) -> torch.Tensor:
    ext = _load_forward_experiments_ext()
    _check_cuda_contiguous(o_pre_correction, "o_pre_correction")
    _check_cuda_contiguous(correction, "correction")
    _check_cuda_contiguous(row_sum, "row_sum")
    if o_pre_correction.dtype != torch.float32:
        raise ValueError("o_pre_correction must have dtype torch.float32")
    if correction.dtype != torch.float32:
        raise ValueError("correction must have dtype torch.float32")
    if row_sum.dtype != torch.float32:
        raise ValueError("row_sum must have dtype torch.float32")
    if o_pre_correction.ndim != 4:
        raise ValueError("o_pre_correction must have shape (B,S,H,D)")
    batch, seqlen, heads, dvo = o_pre_correction.shape
    if dvo != _D_VO:
        raise ValueError(f"o_pre_correction last dim must be {_D_VO}")
    if correction.shape != (batch, heads, seqlen):
        raise ValueError(f"correction must have shape {(batch, heads, seqlen)}")
    if row_sum.shape != correction.shape:
        raise ValueError("row_sum must match correction shape")
    out = torch.empty((batch, seqlen, heads, dvo), dtype=torch.bfloat16, device=o_pre_correction.device)
    with _cuda_device_ctx(o_pre_correction.device):
        ext.two_tile_correction_replay_debug(o_pre_correction, correction, row_sum, out)
    return out


def _two_tile_online_correction_from_debug(debug: dict[str, Any]) -> tuple[torch.Tensor, torch.Tensor]:
    row_max_hist = debug.get("row_max")
    row_sum_hist = debug.get("row_sum")
    if row_max_hist is None or row_sum_hist is None:
        raise ValueError("online tiled debug must include row_max and row_sum histories")
    if row_max_hist.shape[0] < 2 or row_sum_hist.shape[0] < 2:
        raise ValueError("two-tile correction debug requires at least two K tiles")
    row_max0 = row_max_hist[0].float()
    row_max1 = row_max_hist[1].float()
    row_sum0 = row_sum_hist[0].float()
    row_sum1 = row_sum_hist[1].float()
    prev_contrib = row_sum0 * torch.exp(row_max0 - row_max1)
    correction = torch.where(
        (prev_contrib > 0.0) & (row_sum1 > 0.0) & torch.isfinite(prev_contrib) & torch.isfinite(row_sum1),
        prev_contrib / row_sum1,
        torch.zeros_like(row_sum1),
    )
    correction = torch.where(torch.isfinite(correction) & (correction >= 0.0), correction, torch.zeros_like(correction))
    return correction.contiguous(), row_sum1.contiguous()


def _two_tile_absdiff_summary(out: torch.Tensor, ref: torch.Tensor) -> dict[str, float]:
    delta = (out.float() - ref.float()).abs()
    result = {
        "max_abs_diff": float(delta.max().item()),
        "mean_abs_diff": float(delta.mean().item()),
    }
    if delta.shape[1] >= 256:
        result["rows0_127_mean_abs_diff"] = float(delta[:, :128].mean().item())
        result["rows128_191_mean_abs_diff"] = float(delta[:, 128:192].mean().item())
        result["rows192_255_mean_abs_diff"] = float(delta[:, 192:256].mean().item())
    return result


def _debug_two_tile_pv_issue_from_stored_p(
    p_bf16: torch.Tensor,
    lse: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
) -> dict[str, Any]:
    batch, heads, seqlen = _check_stored_p(p_bf16)
    if seqlen < 2 * _TILE:
        raise ValueError("two-tile PV issue debug requires sequence length >= 256")
    _check_prequantized_v(v_fp4, v_sc_prepared, batch, heads, seqlen)

    p_fp4_full, p_sc_prepared_full = quantize_p(p_bf16)
    tile0_snap, tile1_snap = _native_two_tile_pv_tmem_debug(
        p_fp4_full, p_sc_prepared_full, v_fp4, v_sc_prepared, second_tile_mm2=False
    )
    tile0_snap_mm2, tile1_snap_mm2 = _native_two_tile_pv_tmem_debug(
        p_fp4_full, p_sc_prepared_full, v_fp4, v_sc_prepared, second_tile_mm2=True
    )

    p_fp4_tile0 = _contiguous_fp4_lastdim_slice(p_fp4_full, 0, _TILE // 2)
    p_fp4_tile1 = _contiguous_fp4_lastdim_slice(p_fp4_full, _TILE // 2, _TILE // 2)
    p_sc_tile0 = _slice_prepared_scale_k_window(p_sc_prepared_full, 0)
    p_sc_tile1 = _slice_prepared_scale_k_window(p_sc_prepared_full, 1)
    v_fp4_tile0 = _contiguous_fp4_lastdim_slice(v_fp4, 0, _TILE // 2)
    v_fp4_tile1 = _contiguous_fp4_lastdim_slice(v_fp4, _TILE // 2, _TILE // 2)
    v_sc_tile0 = _slice_prepared_scale_k_window(v_sc_prepared, 0)
    v_sc_tile1 = _slice_prepared_scale_k_window(v_sc_prepared, 1)

    tile0_ref = _localcta_pv_into(p_fp4_tile0, p_sc_tile0, v_fp4_tile0, v_sc_tile0).permute(0, 2, 1, 3).contiguous().float()
    tile1_ref = _localcta_pv_into(p_fp4_tile1, p_sc_tile1, v_fp4_tile1, v_sc_tile1).permute(0, 2, 1, 3).contiguous().float()
    pre_correction_ref = tile0_ref + tile1_ref

    online_out, _, online_debug = _forward_stored_p_tiled_localcta(
        p_bf16,
        lse,
        v_fp4,
        v_sc_prepared,
        online=True,
        return_debug=True,
    )
    correction, row_sum = _two_tile_online_correction_from_debug(online_debug)
    replay_out = _native_two_tile_correction_replay_debug(tile1_snap, correction, row_sum)

    return {
        "tile0_snapshot": tile0_snap,
        "tile1_pre_correction_snapshot": tile1_snap,
        "tile0_snapshot_mm2": tile0_snap_mm2,
        "tile1_pre_correction_snapshot_mm2": tile1_snap_mm2,
        "tile0_reference": tile0_ref,
        "tile1_reference": tile1_ref,
        "two_tile_pre_correction_reference": pre_correction_ref,
        "correction_replay_out": replay_out,
        "online_reference_out": online_out,
        "correction": correction,
        "row_sum": row_sum,
        "tile0_snapshot_vs_reference": _two_tile_absdiff_summary(tile0_snap, tile0_ref),
        "tile1_pre_correction_vs_reference": _two_tile_absdiff_summary(tile1_snap, pre_correction_ref),
        "tile1_pre_correction_mm2_vs_reference": _two_tile_absdiff_summary(tile1_snap_mm2, pre_correction_ref),
        "correction_replay_vs_online_reference": _two_tile_absdiff_summary(replay_out.float(), online_out.float()),
    }


def _debug_two_tile_pv_issue_oracle(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
) -> dict[str, Any]:
    p_bf16, lse = softmax_store_p(q, q_sc, q_sg, k, k_sc, k_sg)
    return _debug_two_tile_pv_issue_from_stored_p(p_bf16, lse, v_fp4, v_sc_prepared)


def _debug_stored_p_mainpath_tile_window_from_stored_p(
    p_bf16: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
    *,
    tile_begin: int,
    tiles_to_run: int = 1,
    second_tile_mm2: bool = False,
    pv_wait_count: int | None = None,
    early_tile_arrived: bool = False,
    repeatability_iters: int = 2,
) -> dict[str, Any]:
    batch, heads, seqlen = _check_stored_p(p_bf16)
    _check_prequantized_v(v_fp4, v_sc_prepared, batch, heads, seqlen)
    if repeatability_iters < 1:
        raise ValueError("repeatability_iters must be >= 1")

    p_fp4_full, p_sc_prepared_full = quantize_p(p_bf16)
    runs = [
        _native_two_tile_pv_mainpath_debug(
            p_fp4_full,
            p_sc_prepared_full,
            v_fp4,
            v_sc_prepared,
            tile_begin=tile_begin,
            tiles_to_run=tiles_to_run,
            second_tile_mm2=second_tile_mm2,
            pv_wait_count=pv_wait_count,
            early_tile_arrived=early_tile_arrived,
        ).float()
        for _ in range(repeatability_iters)
    ]

    ref = torch.zeros_like(runs[0])
    packed_tile = _TILE // 2
    for idx in range(tiles_to_run):
        k_tile = tile_begin + idx
        packed_begin = k_tile * packed_tile
        p_fp4_tile = _contiguous_fp4_lastdim_slice(p_fp4_full, packed_begin, packed_tile)
        p_sc_tile = _slice_prepared_scale_k_window(p_sc_prepared_full, k_tile, 1)
        v_fp4_tile = _contiguous_fp4_lastdim_slice(v_fp4, packed_begin, packed_tile)
        v_sc_tile = _slice_prepared_scale_k_window(v_sc_prepared, k_tile, 1)
        ref.add_(
            _localcta_pv_into(
                p_fp4_tile,
                p_sc_tile,
                v_fp4_tile,
                v_sc_tile,
            ).permute(0, 2, 1, 3).contiguous().float()
        )

    result: dict[str, Any] = {
        "run0": runs[0],
        "reference": ref,
        "run0_vs_reference": _two_tile_absdiff_summary(runs[0], ref),
        "tile_begin": int(tile_begin),
        "tiles_to_run": int(tiles_to_run),
        "second_tile_mm2": bool(second_tile_mm2),
        "pv_wait_count": int(tiles_to_run if pv_wait_count is None else pv_wait_count),
        "early_tile_arrived": bool(early_tile_arrived),
    }
    if len(runs) >= 2:
        result["run1"] = runs[1]
        result["run01"] = _two_tile_absdiff_summary(runs[0], runs[1])
    return result


def _debug_stored_p_mainpath_tile_window(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
    *,
    tile_begin: int,
    tiles_to_run: int = 1,
    second_tile_mm2: bool = False,
    pv_wait_count: int | None = None,
    early_tile_arrived: bool = False,
    repeatability_iters: int = 2,
) -> dict[str, Any]:
    p_bf16, _ = softmax_store_p(q, q_sc, q_sg, k, k_sc, k_sg)
    return _debug_stored_p_mainpath_tile_window_from_stored_p(
        p_bf16,
        v_fp4,
        v_sc_prepared,
        tile_begin=tile_begin,
        tiles_to_run=tiles_to_run,
        second_tile_mm2=second_tile_mm2,
        pv_wait_count=pv_wait_count,
        early_tile_arrived=early_tile_arrived,
        repeatability_iters=repeatability_iters,
    )


def _pad_bf16_sandbox_qkv(
    q_bf16: torch.Tensor,
    k_bf16: torch.Tensor,
    v_bf16: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, dict[str, int]]:
    batch, seqlen, heads, d_qk, d_vo = _check_bf16_sandbox_qkv(q_bf16, k_bf16, v_bf16)
    padded_seqlen = _next_multiple(seqlen, _TILE)
    padded_d_vo = _next_multiple(d_vo, _TILE)
    meta = {
        "batch": batch,
        "heads": heads,
        "d_qk": d_qk,
        "orig_seqlen": seqlen,
        "padded_seqlen": padded_seqlen,
        "orig_d_vo": d_vo,
        "padded_d_vo": padded_d_vo,
    }
    if padded_seqlen == seqlen and padded_d_vo == d_vo:
        return q_bf16.contiguous(), k_bf16.contiguous(), v_bf16.contiguous(), meta

    q_pad = torch.zeros((batch, padded_seqlen, heads, d_qk), dtype=q_bf16.dtype, device=q_bf16.device)
    k_pad = torch.zeros((batch, padded_seqlen, heads, d_qk), dtype=k_bf16.dtype, device=k_bf16.device)
    v_pad = torch.zeros((batch, padded_seqlen, heads, padded_d_vo), dtype=v_bf16.dtype, device=v_bf16.device)
    q_pad[:, :seqlen] = q_bf16
    k_pad[:, :seqlen] = k_bf16
    v_pad[:, :seqlen, :, :d_vo] = v_bf16
    return q_pad.contiguous(), k_pad.contiguous(), v_pad.contiguous(), meta


def _bf16_causal_softmax_store_p(
    q_bf16: torch.Tensor,
    k_bf16: torch.Tensor,
    *,
    softmax_scale: float | None = None,
) -> tuple[torch.Tensor, torch.Tensor]:
    batch, seqlen, heads, d_qk, _ = _check_bf16_sandbox_qkv(q_bf16, k_bf16, q_bf16.new_empty((*q_bf16.shape[:3], 1)))
    scale = float(softmax_scale) if softmax_scale is not None else 1.0 / math.sqrt(float(d_qk))
    q_bhsd = q_bf16.permute(0, 2, 1, 3).float()
    k_bhsd = k_bf16.permute(0, 2, 1, 3).float()
    scores = torch.matmul(q_bhsd, k_bhsd.transpose(-1, -2)) * scale
    causal_mask = torch.triu(torch.ones((seqlen, seqlen), device=scores.device, dtype=torch.bool), diagonal=1)
    scores = scores.masked_fill(causal_mask.view(1, 1, seqlen, seqlen), float("-inf"))
    lse = torch.logsumexp(scores, dim=-1)
    p_bf16 = torch.softmax(scores, dim=-1).to(torch.bfloat16)
    return p_bf16, lse.contiguous()


def _bf16_reference_pv_from_p(
    p_bf16: torch.Tensor,
    v_bf16: torch.Tensor,
) -> torch.Tensor:
    batch, heads, seqlen = _check_stored_p(p_bf16)
    if v_bf16.shape[:3] != (batch, seqlen, heads):
        raise ValueError(f"v_bf16 must have shape {(batch, seqlen, heads, 'd_vo')}")
    return torch.einsum("bhmk,bkhd->bmhd", p_bf16.float(), v_bf16.float()).to(torch.bfloat16).contiguous()


def _quantize_dequantize_qk_bf16(
    x_bf16: torch.Tensor,
    *,
    backend: str,
) -> torch.Tensor:
    if backend == "none":
        return x_bf16.contiguous()
    batch, seqlen, heads, d = x_bf16.shape
    x_bhsd = x_bf16.permute(0, 2, 1, 3).contiguous()
    out = torch.empty_like(x_bhsd, dtype=torch.bfloat16)
    for b in range(batch):
        for h in range(heads):
            out[b, h].copy_(_quantize_dequantize_rows_2d(x_bhsd[b, h].float(), backend=backend))
    return out.permute(0, 2, 1, 3).contiguous()


def _quantize_dequantize_p_bf16(
    p_bf16: torch.Tensor,
    *,
    backend: str,
) -> torch.Tensor:
    backend = _normalize_sandbox_quant_backend(backend)
    if backend == "none":
        return p_bf16.contiguous()
    if backend in ("localcta", "v5"):
        p_fp4, p_sc = quantize_p(p_bf16, backend=backend)
        return _dequantize_prepared_fp4_rows_for_debug(p_fp4, p_sc).to(torch.bfloat16).contiguous()

    batch, heads, seqlen = _check_stored_p(p_bf16)
    out = torch.empty_like(p_bf16)
    for b in range(batch):
        for h in range(heads):
            rec = _quantize_rows_2d_mxfp4(p_bf16[b, h].float(), backend=backend)
            out[b, h].copy_(_dequantize_mxfp4_rows_2d(rec["fp4"], rec["scales"], rows=seqlen, cols=seqlen).to(torch.bfloat16))
    return out.contiguous()


def _quantize_dequantize_v_bf16(
    v_bf16: torch.Tensor,
    *,
    backend: str,
) -> torch.Tensor:
    backend = _normalize_sandbox_quant_backend(backend)
    if backend == "none":
        return v_bf16.contiguous()
    if backend in ("localcta", "v5"):
        v_fp4, v_sc = _quantize_v_prepared(v_bf16, backend=backend)
        v_bhds = _dequantize_prepared_fp4_rows_for_debug(v_fp4, v_sc).to(torch.bfloat16)
        return v_bhds.permute(0, 3, 1, 2).contiguous()

    batch, seqlen, heads, dvo = v_bf16.shape
    out = torch.empty_like(v_bf16)
    for b in range(batch):
        for h in range(heads):
            rec = _quantize_rows_2d_mxfp4(v_bf16[b, :, h, :].permute(1, 0).contiguous().float(), backend=backend)
            deq = _dequantize_mxfp4_rows_2d(rec["fp4"], rec["scales"], rows=dvo, cols=seqlen).to(torch.bfloat16)
            out[b, :, h, :].copy_(deq.permute(1, 0))
    return out.contiguous()


def forward_bf16_sandbox_pv(
    q_bf16: torch.Tensor,
    k_bf16: torch.Tensor,
    v_bf16: torch.Tensor,
    *,
    pv_variant: str = "full_p_quant_pv",
    qk_quant_backend: str = "none",
    p_quant_backend: str = "localcta",
    v_quant_backend: str = "localcta",
    softmax_scale: float | None = None,
    pad_to_tile: bool = True,
    return_intermediates: bool = False,
) -> dict[str, Any]:
    _check_bf16_sandbox_qkv(q_bf16, k_bf16, v_bf16)
    qk_quant_backend = _normalize_sandbox_quant_backend(qk_quant_backend)
    p_quant_backend = _normalize_sandbox_quant_backend(p_quant_backend)
    v_quant_backend = _normalize_sandbox_quant_backend(v_quant_backend)
    _check_choice("qk_quant_backend", qk_quant_backend, _SANDBOX_QUANT_BACKENDS)
    _check_choice("p_quant_backend", p_quant_backend, _SANDBOX_QUANT_BACKENDS)
    _check_choice("v_quant_backend", v_quant_backend, _SANDBOX_QUANT_BACKENDS)
    if pv_variant not in _SANDBOX_PV_VARIANTS:
        raise ValueError(f"pv_variant must be one of {list_bf16_sandbox_pv_variants()}")
    if pad_to_tile:
        q_work, k_work, v_work, meta = _pad_bf16_sandbox_qkv(q_bf16, k_bf16, v_bf16)
    else:
        q_work = q_bf16.contiguous()
        k_work = k_bf16.contiguous()
        v_work = v_bf16.contiguous()
        _, seqlen, heads, d_qk, d_vo = _check_bf16_sandbox_qkv(q_work, k_work, v_work)
        if seqlen % _TILE != 0:
            raise ValueError("pad_to_tile=False requires seqlen divisible by 128")
        if d_vo % _TILE != 0:
            raise ValueError("pad_to_tile=False requires V head dim divisible by 128")
        meta = {
            "batch": q_work.shape[0],
            "heads": heads,
            "d_qk": d_qk,
            "orig_seqlen": seqlen,
            "padded_seqlen": seqlen,
            "orig_d_vo": d_vo,
            "padded_d_vo": d_vo,
        }

    qk_quant_ms = 0.0
    if qk_quant_backend == "none":
        q_softmax = q_work
        k_softmax = k_work
    else:
        q_softmax, q_ms = _run_with_ms(_quantize_dequantize_qk_bf16, q_work, backend=qk_quant_backend)
        k_softmax, k_ms = _run_with_ms(_quantize_dequantize_qk_bf16, k_work, backend=qk_quant_backend)
        qk_quant_ms = q_ms + k_ms

    (p_bf16_full, lse_full), softmax_ms = _run_with_ms(
        _bf16_causal_softmax_store_p,
        q_softmax,
        k_softmax,
        softmax_scale=softmax_scale,
    )
    quant_v_ms = 0.0
    quant_p_ms = 0.0
    p_qdq = None
    v_qdq = None
    pv_execution_mode = "bf16_reference"
    uses_real_fp4_pv = False
    if pv_variant == "bf16_reference":
        if p_quant_backend != "none":
            p_qdq, quant_p_ms = _run_with_ms(_quantize_dequantize_p_bf16, p_bf16_full, backend=p_quant_backend)
        if v_quant_backend != "none":
            v_qdq, quant_v_ms = _run_with_ms(_quantize_dequantize_v_bf16, v_work.to(torch.bfloat16), backend=v_quant_backend)
        out_full, pv_ms = _run_with_ms(
            _bf16_reference_pv_from_p,
            p_bf16_full if p_qdq is None else p_qdq,
            v_work.to(torch.bfloat16) if v_qdq is None else v_qdq,
        )
        pv_label = "bf16_reference_pv_ms"
        p_fp4 = None
        p_sc_prepared = None
        v_fp4 = None
        v_sc_prepared = None
    else:
        if v_quant_backend in ("localcta", "v5"):
            (v_fp4, v_sc_prepared), quant_v_ms = _run_with_ms(_quantize_v_prepared, v_work.to(torch.bfloat16), backend=v_quant_backend)
        else:
            v_fp4 = None
            v_sc_prepared = None
        p_fp4 = None
        p_sc_prepared = None
        pv_label = ""

        if pv_variant == "full_p_quant_pv":
            if p_quant_backend == "mxfp4" and v_quant_backend == "mxfp4":
                (p_fp4, p_sc_mx), quant_p_ms = _run_with_ms(_mxfp4_quantize_p_for_gemm, p_bf16_full)
                (v_fp4_mx, v_sc_mx), quant_v_ms = _run_with_ms(_mxfp4_quantize_v_for_gemm, v_work.to(torch.bfloat16))
                out_full, pv_ms = _run_with_ms(_mxfp4_pv_from_p, p_fp4, p_sc_mx, v_fp4_mx, v_sc_mx)
                pv_label = "mxfp4_gemm_ms"
                pv_execution_mode = "mxfp4_gemm"
                uses_real_fp4_pv = True
            elif p_quant_backend in ("localcta", "v5") and v_quant_backend in ("localcta", "v5"):
                (p_fp4, p_sc_prepared), quant_p_ms = _run_with_ms(quantize_p, p_bf16_full, backend=p_quant_backend)
                out_full, pv_ms = _run_with_ms(pv_from_p, p_fp4, p_sc_prepared, v_fp4, v_sc_prepared)
                pv_label = "pv_from_p_ms"
                pv_execution_mode = "nvfp4_pv_from_p"
                uses_real_fp4_pv = True
            else:
                if (p_quant_backend == "mxfp4") != (v_quant_backend == "mxfp4"):
                    raise ValueError("MXFP4 sandbox PV currently requires p_quant_backend='mxfp4' and v_quant_backend='mxfp4' together")
                if p_quant_backend != "none":
                    p_qdq, quant_p_ms = _run_with_ms(_quantize_dequantize_p_bf16, p_bf16_full, backend=p_quant_backend)
                if v_quant_backend != "none":
                    v_qdq, quant_v_ms = _run_with_ms(_quantize_dequantize_v_bf16, v_work.to(torch.bfloat16), backend=v_quant_backend)
                out_full, pv_ms = _run_with_ms(
                    _bf16_reference_pv_from_p,
                    p_bf16_full if p_qdq is None else p_qdq,
                    v_work.to(torch.bfloat16) if v_qdq is None else v_qdq,
                )
                pv_label = "bf16_quantized_reference_pv_ms"
                pv_execution_mode = "bf16_quantized_reference_pv"
        elif pv_variant == "tiled_direct_localcta":
            if p_quant_backend not in ("localcta",) or v_quant_backend not in ("localcta", "v5"):
                raise ValueError("tiled_direct_localcta currently supports p_quant_backend='localcta' and v_quant_backend in ('localcta', 'v5')")
            (out_full, _, tiled_debug), pv_ms = _run_with_ms(
                _forward_stored_p_tiled_localcta,
                p_bf16_full,
                lse_full,
                v_fp4,
                v_sc_prepared,
                online=False,
                p_quant_backend=p_quant_backend,
                return_debug=return_intermediates,
            )
            pv_label = "stored_p_tiled_direct_localcta_ms"
            pv_execution_mode = "stored_p_tiled_direct_localcta"
            uses_real_fp4_pv = True
        else:
            if p_quant_backend not in ("localcta",) or v_quant_backend not in ("localcta", "v5"):
                raise ValueError("tiled_online_localcta currently supports p_quant_backend='localcta' and v_quant_backend in ('localcta', 'v5')")
            (out_full, _, tiled_debug), pv_ms = _run_with_ms(
                _forward_stored_p_tiled_localcta,
                p_bf16_full,
                lse_full,
                v_fp4,
                v_sc_prepared,
                online=True,
                p_quant_backend=p_quant_backend,
                return_debug=return_intermediates,
            )
            pv_label = "stored_p_tiled_online_localcta_ms"
            pv_execution_mode = "stored_p_tiled_online_localcta"
            uses_real_fp4_pv = True

    orig_seqlen = meta["orig_seqlen"]
    orig_d_vo = meta["orig_d_vo"]
    out = out_full[:, :orig_seqlen, :, :orig_d_vo].contiguous()
    lse = lse_full[:, :, :orig_seqlen].contiguous()
    timing_breakdown = {
        "qk_quantize_dequantize_ms": qk_quant_ms,
        "bf16_softmax_store_p_ms": softmax_ms,
        "quantize_v_ms": quant_v_ms,
        pv_label: pv_ms,
        "total_ms": softmax_ms + quant_v_ms + pv_ms + quant_p_ms + qk_quant_ms,
    }
    if quant_p_ms:
        timing_breakdown["quantize_p_ms"] = quant_p_ms
    result: dict[str, Any] = {
        "out": out,
        "lse": lse,
        "timing_ms": timing_breakdown["total_ms"],
        "timing_breakdown": timing_breakdown,
        "padding": meta,
        "pv_variant": pv_variant,
        "qk_quant_backend": qk_quant_backend,
        "p_quant_backend": p_quant_backend,
        "v_quant_backend": v_quant_backend,
        "pv_execution_mode": pv_execution_mode,
        "uses_real_fp4_pv": uses_real_fp4_pv,
        "softmax_scale": float(softmax_scale) if softmax_scale is not None else 1.0 / math.sqrt(float(meta["d_qk"])),
    }
    if return_intermediates:
        result["p_bf16"] = p_bf16_full[:, :, :orig_seqlen, :orig_seqlen].contiguous()
        result["v_fp4"] = v_fp4
        result["v_sc_prepared"] = v_sc_prepared
        if p_fp4 is not None:
            result["p_fp4"] = p_fp4
            result["p_sc_prepared"] = p_sc_prepared
        if pv_variant in ("tiled_direct_localcta", "tiled_online_localcta"):
            result["tiled_debug"] = tiled_debug
    return result


def benchmark_bf16_sandbox_pv_variants(
    q_bf16: torch.Tensor,
    k_bf16: torch.Tensor,
    v_bf16: torch.Tensor,
    *,
    variants: list[str] | tuple[str, ...] | None = None,
    qk_quant_backend: str = "none",
    p_quant_backend: str = "localcta",
    v_quant_backend: str = "localcta",
    softmax_scale: float | None = None,
    pad_to_tile: bool = True,
    warmup: int = 1,
    iters: int = 3,
) -> list[dict[str, Any]]:
    if iters < 1:
        raise ValueError("iters must be >= 1")
    qk_quant_backend = _normalize_sandbox_quant_backend(qk_quant_backend)
    p_quant_backend = _normalize_sandbox_quant_backend(p_quant_backend)
    v_quant_backend = _normalize_sandbox_quant_backend(v_quant_backend)
    variants = list(_SANDBOX_PV_VARIANTS if variants is None else variants)
    for variant in variants:
        if variant not in _SANDBOX_PV_VARIANTS:
            raise ValueError(f"unknown sandbox pv_variant {variant!r}; expected one of {list_bf16_sandbox_pv_variants()}")

    ref = forward_bf16_sandbox_pv(
        q_bf16,
        k_bf16,
        v_bf16,
        pv_variant="bf16_reference",
        qk_quant_backend=qk_quant_backend,
        p_quant_backend=p_quant_backend,
        v_quant_backend=v_quant_backend,
        softmax_scale=softmax_scale,
        pad_to_tile=pad_to_tile,
    )

    rows: list[dict[str, Any]] = []
    for variant in variants:
        for _ in range(warmup):
            forward_bf16_sandbox_pv(
                q_bf16,
                k_bf16,
                v_bf16,
                pv_variant=variant,
                qk_quant_backend=qk_quant_backend,
                p_quant_backend=p_quant_backend,
                v_quant_backend=v_quant_backend,
                softmax_scale=softmax_scale,
                pad_to_tile=pad_to_tile,
            )

        samples: list[float] = []
        breakdowns: list[dict[str, float]] = []
        final = None
        for _ in range(iters):
            final = forward_bf16_sandbox_pv(
                q_bf16,
                k_bf16,
                v_bf16,
                pv_variant=variant,
                qk_quant_backend=qk_quant_backend,
                p_quant_backend=p_quant_backend,
                v_quant_backend=v_quant_backend,
                softmax_scale=softmax_scale,
                pad_to_tile=pad_to_tile,
            )
            samples.append(float(final["timing_ms"]))
            breakdowns.append({k: float(v) for k, v in final["timing_breakdown"].items()})

        assert final is not None
        rows.append(
            {
                "pv_variant": variant,
                "timing_ms_median": _median(samples),
                "timing_breakdown_median": _median_breakdown(breakdowns),
                "diagnostics_vs_bf16_reference": _compare_outputs(final["out"], final["lse"], ref["out"], ref["lse"]),
                "padding": final["padding"],
                "softmax_scale": final["softmax_scale"],
                "qk_quant_backend": qk_quant_backend,
                "p_quant_backend": p_quant_backend,
                "v_quant_backend": v_quant_backend,
                "pv_execution_mode": final["pv_execution_mode"],
                "uses_real_fp4_pv": final["uses_real_fp4_pv"],
            }
        )
    return rows


def _forward_alt1_impl(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
):
    (p_bf16, lse), softmax_ms = _run_with_ms(softmax_store_p, q, q_sc, q_sg, k, k_sc, k_sg)
    (p_fp4, p_sc_prepared), quant_ms = _run_with_ms(quantize_p, p_bf16)
    out, pv_ms = _run_with_ms(pv_from_p, p_fp4, p_sc_prepared, v_fp4, v_sc_prepared)
    breakdown = {
        "softmax_store_p_ms": softmax_ms,
        "quantize_p_ms": quant_ms,
        "pv_from_p_ms": pv_ms,
        "total_ms": softmax_ms + quant_ms + pv_ms,
    }
    return out, lse, breakdown, None


def _forward_stored_p_tiled_localcta(
    p_bf16: torch.Tensor,
    lse: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
    *,
    online: bool,
    p_quant_backend: str = "localcta",
    return_debug: bool = False,
):
    if p_quant_backend != "localcta":
        raise ValueError("_forward_stored_p_tiled_localcta currently only supports p_quant_backend='localcta'")
    local_q = _load_localcta_quant()
    batch, heads, seqlen = _check_stored_p(p_bf16)
    if lse.shape != (batch, heads, seqlen):
        raise ValueError(f"lse must have shape {(batch, heads, seqlen)}")
    _check_prequantized_v(v_fp4, v_sc_prepared, batch, heads, seqlen)
    dvo = v_fp4.shape[2]

    out_accum = torch.zeros((batch, heads, seqlen, dvo), dtype=torch.float32, device=p_bf16.device)
    tile_out = torch.empty((batch, heads, seqlen, dvo), dtype=torch.bfloat16, device=p_bf16.device)
    with _cuda_device_ctx(p_bf16.device):
        quant_workspace = local_q.tk_localcta_quantize_for_gemm_prepared_alloc(
            batch * heads * seqlen, _TILE, False, p_bf16.device
        )

    row_sum = None
    row_max = None
    if online:
        row_sum = torch.zeros((batch, heads, seqlen), dtype=torch.float32, device=p_bf16.device)
        row_max = torch.full((batch, heads, seqlen), float("-inf"), dtype=torch.float32, device=p_bf16.device)

    debug_row_max = []
    debug_row_sum = []
    debug_absmax = []

    for tile_start in range(0, seqlen, _TILE):
        tile_slice = slice(tile_start, tile_start + _TILE)
        p_tile_final = p_bf16[:, :, :, tile_slice].float()

        if online:
            tile_pmax = p_tile_final.amax(dim=-1)
            neg_inf = torch.full_like(tile_pmax, float("-inf"))
            tile_row_max = torch.where(tile_pmax > 0, lse + torch.log(tile_pmax), neg_inf)
            new_row_max = torch.maximum(row_max, tile_row_max)
            alpha = torch.where(
                torch.isfinite(row_max),
                torch.exp(row_max - new_row_max),
                torch.zeros_like(new_row_max),
            )
            scale = torch.where(
                torch.isfinite(new_row_max),
                torch.exp(lse - new_row_max),
                torch.zeros_like(new_row_max),
            )
            p_tile_work = p_tile_final * scale.unsqueeze(-1)
            next_row_sum = row_sum * alpha + p_tile_work.sum(dim=-1)
            if return_debug:
                debug_row_max.append(new_row_max.detach().clone())
                debug_row_sum.append(next_row_sum.detach().clone())
                debug_absmax.append(p_tile_work.abs().amax(dim=-1).detach().clone())
        else:
            p_tile_work = p_tile_final
            if return_debug:
                debug_absmax.append(p_tile_work.abs().amax(dim=-1).detach().clone())

        p_tile_2d = p_tile_work.to(torch.bfloat16).contiguous().view(batch * heads * seqlen, _TILE)
        row_fp4, row_sc_prepared, col_fp4, col_sc_prepared, row_sg, col_sg = quant_workspace
        with _cuda_device_ctx(p_bf16.device):
            local_q.tk_localcta_quantize_for_gemm_prepared_launch(
                p_tile_2d, False, True,
                row_fp4, row_sc_prepared, col_fp4, col_sc_prepared, row_sg, col_sg,
            )

        p_fp4_tile = row_fp4.view(batch, heads, seqlen, _TILE // 2)
        p_sc_tile = row_sc_prepared.view(batch, heads, seqlen // 128, _TILE // 64, 512)
        v_tile_fp4 = _contiguous_fp4_lastdim_slice(v_fp4, tile_start // 2, _TILE // 2)
        v_tile_sc = v_sc_prepared[:, :, :, tile_start // 64:(tile_start + _TILE) // 64, :].contiguous()
        tile_out.zero_()
        _localcta_pv_into(p_fp4_tile, p_sc_tile, v_tile_fp4, v_tile_sc, tile_out)

        if online:
            out_accum.mul_(alpha.unsqueeze(-1))
            out_accum.add_(tile_out.float())
            row_sum = next_row_sum
            row_max = new_row_max
        else:
            out_accum.add_(tile_out.float())

    if online:
        row_sum_bsh = row_sum.permute(0, 2, 1).contiguous()
        out = torch.where(
            row_sum_bsh.unsqueeze(-1) > 0,
            out_accum.permute(0, 2, 1, 3).contiguous() / row_sum_bsh.unsqueeze(-1),
            torch.zeros((batch, seqlen, heads, dvo), dtype=torch.float32, device=p_bf16.device),
        ).to(torch.bfloat16)
    else:
        out = out_accum.permute(0, 2, 1, 3).contiguous().to(torch.bfloat16)

    if not return_debug:
        return out, lse, None

    debug: dict[str, Any] = {
        "row_max": torch.stack(debug_row_max, dim=0) if debug_row_max else None,
        "row_sum": torch.stack(debug_row_sum, dim=0) if debug_row_sum else None,
        "absmax_p": torch.stack(debug_absmax, dim=0) if debug_absmax else None,
    }
    return out, lse, debug


def _quantize_stored_p_tile_window_localcta_prepared(
    p_bf16: torch.Tensor,
    *,
    tile_begin: int,
    tiles_to_run: int = 1,
    quant_workspace: tuple[torch.Tensor, ...] | None = None,
) -> tuple[torch.Tensor, torch.Tensor]:
    local_q = _load_localcta_quant()
    batch, heads, seqlen = _check_stored_p(p_bf16)
    if tile_begin < 0:
        raise ValueError("tile_begin must be non-negative")
    if tiles_to_run <= 0:
        raise ValueError("tiles_to_run must be positive")
    if tile_begin + tiles_to_run > seqlen // _TILE:
        raise ValueError("tile window must fit within the sequence tile range")

    cols = tiles_to_run * _TILE
    tile_slice = slice(tile_begin * _TILE, (tile_begin + tiles_to_run) * _TILE)
    p_tile_2d = p_bf16[:, :, :, tile_slice].to(torch.bfloat16).contiguous().view(batch * heads * seqlen, cols)

    if quant_workspace is None:
        with _cuda_device_ctx(p_bf16.device):
            quant_workspace = local_q.tk_localcta_quantize_for_gemm_prepared_alloc(
                batch * heads * seqlen, cols, False, p_bf16.device
            )
    row_fp4, row_sc_prepared, col_fp4, col_sc_prepared, row_sg, col_sg = quant_workspace
    del col_fp4, col_sc_prepared, row_sg, col_sg
    with _cuda_device_ctx(p_bf16.device):
        local_q.tk_localcta_quantize_for_gemm_prepared_launch(
            p_tile_2d,
            False,
            True,
            row_fp4,
            row_sc_prepared,
            quant_workspace[2],
            quant_workspace[3],
            quant_workspace[4],
            quant_workspace[5],
        )
    return (
        row_fp4.view(batch, heads, seqlen, cols // 2).contiguous(),
        row_sc_prepared.view(batch, heads, seqlen // 128, cols // 64, 512).contiguous(),
    )


def _run_variant_alt1(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
    *,
    return_debug: bool = False,
    allow_unsafe_live: bool = False,
):
    del return_debug, allow_unsafe_live
    return _forward_alt1_impl(q, q_sc, q_sg, k, k_sc, k_sg, v_fp4, v_sc_prepared)


def _run_variant_stored_direct(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
    *,
    return_debug: bool = False,
    allow_unsafe_live: bool = False,
):
    del allow_unsafe_live
    (p_bf16, lse), softmax_ms = _run_with_ms(softmax_store_p, q, q_sc, q_sg, k, k_sc, k_sg)
    (out, _, debug), direct_ms = _run_with_ms(
        _forward_stored_p_tiled_localcta,
        p_bf16,
        lse,
        v_fp4,
        v_sc_prepared,
        online=False,
        return_debug=return_debug,
    )
    breakdown = {
        "softmax_store_p_ms": softmax_ms,
        "stored_p_tiled_direct_localcta_ms": direct_ms,
        "total_ms": softmax_ms + direct_ms,
    }
    return out, lse, breakdown, debug


