def _make_forward_matrix_bf16_inputs(
    seqlen: int,
    *,
    input_mode: str,
    seed: int = 0,
    batch: int = 1,
    heads: int = 16,
    device: str | torch.device = "cuda",
    distribution: str = "gaussian",
    q_distribution: str | None = None,
    k_distribution: str | None = None,
    v_distribution: str | None = None,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    _check_choice("input_mode", input_mode, _FORWARD_MATRIX_INPUT_MODES)
    return _make_live_bf16_source_inputs(
        seqlen,
        seed=seed,
        batch=batch,
        heads=heads,
        device=device,
        zero_qk=(input_mode == "zero_qk_random_v"),
        distribution=distribution,
        q_distribution=q_distribution,
        k_distribution=k_distribution,
        v_distribution=v_distribution,
    )


def _pad_rows_cols_bf16_2d(
    x_2d: torch.Tensor,
    *,
    min_rows: int = 0,
    min_cols: int = 0,
) -> tuple[torch.Tensor, dict[str, int]]:
    _check_cuda_contiguous(x_2d, "x_2d")
    if x_2d.ndim != 2:
        raise ValueError("x_2d must be rank-2")
    rows, cols = int(x_2d.shape[0]), int(x_2d.shape[1])
    padded_rows = max(_next_multiple(rows, _TILE), int(min_rows))
    padded_cols = max(_next_multiple(cols, _TILE), int(min_cols))
    if padded_rows == rows and padded_cols == cols:
        return x_2d.to(torch.bfloat16).contiguous(), {
            "rows": rows,
            "cols": cols,
            "padded_rows": padded_rows,
            "padded_cols": padded_cols,
        }
    out = torch.zeros((padded_rows, padded_cols), dtype=torch.bfloat16, device=x_2d.device)
    out[:rows, :cols].copy_(x_2d.to(torch.bfloat16))
    return out.contiguous(), {
        "rows": rows,
        "cols": cols,
        "padded_rows": padded_rows,
        "padded_cols": padded_cols,
    }


def _quantize_rows_2d_v5_direct(
    x_2d: torch.Tensor,
    *,
    encode_centric: bool = True,
) -> dict[str, Any]:
    x_2d = x_2d.to(torch.bfloat16).contiguous()
    _require_finite_tensor(x_2d, "x_2d")
    tk = _load_v5_quant()
    with _cuda_device_ctx(x_2d.device):
        row_fp4, row_sc, _, _, row_sg, _ = tk.tk_quantize_for_gemm(x_2d, False, encode_centric)
    return {
        "backend": "v5",
        "format": "nvfp4_v5_direct",
        "fp4": row_fp4.contiguous(),
        "scales": row_sc.contiguous(),
        "sg_chunks": row_sg.contiguous(),
        "rows": int(x_2d.shape[0]),
        "cols": int(x_2d.shape[1]),
        "padded_rows": int(x_2d.shape[0]),
        "padded_cols": int(x_2d.shape[1]),
    }


def _quantize_rows_2d_localcta_direct(
    x_2d: torch.Tensor,
    *,
    encode_centric: bool = True,
) -> dict[str, Any]:
    x_2d = x_2d.to(torch.bfloat16).contiguous()
    _require_finite_tensor(x_2d, "x_2d")
    local_q = _load_localcta_quant()
    with _cuda_device_ctx(x_2d.device):
        row_fp4, row_sc, _, _, row_sg, _ = local_q.tk_localcta_quantize_for_gemm(x_2d, False, encode_centric)
    return {
        "backend": "localcta",
        "format": "nvfp4_localcta_direct",
        "fp4": row_fp4.contiguous(),
        "scales": row_sc.contiguous(),
        "sg_chunks": row_sg.contiguous(),
        "rows": int(x_2d.shape[0]),
        "cols": int(x_2d.shape[1]),
        "padded_rows": int(x_2d.shape[0]),
        "padded_cols": int(x_2d.shape[1]),
    }


def _quantize_rows_2d_forward_backend(
    x_2d: torch.Tensor,
    *,
    backend: str,
    min_rows: int = 0,
    min_cols: int = 0,
    quant_mode: str | None = None,
) -> dict[str, Any]:
    backend = _normalize_forward_matrix_backend(backend)
    _check_choice("backend", backend, _FORWARD_MATRIX_QK_BACKENDS)
    x_work, meta = _pad_rows_cols_bf16_2d(x_2d, min_rows=min_rows, min_cols=min_cols)
    if backend == "v5":
        rec = _quantize_rows_2d_v5_direct(
            x_work,
            encode_centric=_nvfp4_quant_mode_to_encode_centric(quant_mode, backend=backend),
        )
    elif backend == "localcta":
        rec = _quantize_rows_2d_localcta_direct(
            x_work,
            encode_centric=_nvfp4_quant_mode_to_encode_centric(quant_mode, backend=backend),
        )
    elif backend == "mxfp4_v3":
        rec = _quantize_rows_2d_mxfp4(x_work, backend="mxfp4", quant_mode=quant_mode)
        rec = {
            "backend": "mxfp4_v3",
            "format": "mxfp4_v3",
            "fp4": rec["fp4"].contiguous(),
            "scales": rec["scales"].contiguous(),
            "quant_mode": rec["quant_mode"],
            "rows": rec["rows"],
            "cols": rec["cols"],
            "padded_rows": rec["rows"],
            "padded_cols": rec["padded_cols"],
        }
    else:  # pragma: no cover - guarded above
        raise ValueError(f"unsupported backend {backend!r}")
    rec.update(meta)
    rec["quant_mode"] = _normalize_quant_mode_for_backend(backend, quant_mode)
    return rec


def _backend_gemm_quantized(
    a_quant: dict[str, Any],
    b_quant: dict[str, Any],
    *,
    backend: str,
) -> torch.Tensor:
    backend = _normalize_forward_matrix_backend(backend)
    if a_quant["padded_cols"] != b_quant["padded_cols"]:
        raise ValueError("backend GEMM expects A and B to have the same padded K dimension")
    out = torch.empty(
        (a_quant["padded_rows"], b_quant["padded_rows"]),
        dtype=torch.bfloat16,
        device=a_quant["fp4"].device,
    )
    with _cuda_device_ctx(out.device):
        if backend == "v5":
            legacy = _load_nvfp4_legacy_gemm()
            legacy.nvfp4_gemm(
                a_quant["fp4"],
                a_quant["scales"],
                a_quant["sg_chunks"],
                b_quant["fp4"],
                b_quant["scales"],
                b_quant["sg_chunks"],
                out,
            )
        elif backend == "localcta":
            local_gemm = _load_localcta_gemm()
            local_gemm.nvfp4_localcta_gemm(
                a_quant["fp4"],
                a_quant["scales"],
                a_quant["sg_chunks"],
                b_quant["fp4"],
                b_quant["scales"],
                b_quant["sg_chunks"],
                out,
            )
        elif backend == "mxfp4_v3":
            tk_gemm = _load_tk_mxfp4_gemm()
            tk_gemm.mxfp4_gemm(
                a_quant["fp4"],
                a_quant["scales"],
                b_quant["fp4"],
                b_quant["scales"],
                out,
            )
        else:  # pragma: no cover - guarded above
            raise ValueError(f"unsupported backend {backend!r}")
    return out[: a_quant["rows"], : b_quant["rows"]].contiguous()


def _slice_quantized_rows_2d_forward_backend(
    rec: dict[str, Any],
    row_start: int,
    row_end: int,
) -> dict[str, Any]:
    backend = _normalize_forward_matrix_backend(str(rec["backend"]))
    if row_start < 0 or row_end < row_start or row_end > int(rec["rows"]):
        raise ValueError("invalid quantized row slice")
    if row_start % _TILE != 0 or row_end % _TILE != 0:
        raise ValueError("quantized row slices must be 128-aligned")
    row_blocks_start = row_start // _TILE
    row_blocks_end = row_end // _TILE
    out = dict(rec)
    out["rows"] = row_end - row_start
    out["padded_rows"] = row_end - row_start
    out["fp4"] = _contiguous_fp4_row_slice(rec["fp4"], row_start, row_end - row_start)
    if backend in ("localcta", "v5"):
        out["scales"] = rec["scales"][row_blocks_start:row_blocks_end].contiguous()
        sg_chunks = rec.get("sg_chunks")
        if isinstance(sg_chunks, torch.Tensor):
            if sg_chunks.ndim > 0 and int(sg_chunks.shape[0]) == int(rec["padded_rows"]) // _TILE:
                out["sg_chunks"] = sg_chunks[row_blocks_start:row_blocks_end].contiguous()
            else:
                out["sg_chunks"] = sg_chunks.contiguous()
    elif backend == "mxfp4_v3":
        out["scales"] = rec["scales"][row_blocks_start:row_blocks_end].contiguous()
    else:  # pragma: no cover - guarded by normalization above
        raise ValueError(f"unsupported backend {backend!r}")
    return out


def _backend_gemm_from_bf16(
    a_bf16: torch.Tensor,
    b_bf16: torch.Tensor,
    *,
    backend: str,
    a_min_rows: int = 0,
    a_min_cols: int = 0,
    b_min_rows: int = 0,
    b_min_cols: int = 0,
    a_quant_mode: str | None = None,
    b_quant_mode: str | None = None,
) -> torch.Tensor:
    backend = _normalize_forward_matrix_backend(backend)
    _require_finite_tensor(a_bf16, "a_bf16")
    _require_finite_tensor(b_bf16, "b_bf16")
    a_quant = _quantize_rows_2d_forward_backend(
        a_bf16,
        backend=backend,
        min_rows=a_min_rows,
        min_cols=a_min_cols,
        quant_mode=a_quant_mode,
    )
    b_quant = _quantize_rows_2d_forward_backend(
        b_bf16,
        backend=backend,
        min_rows=b_min_rows,
        min_cols=b_min_cols,
        quant_mode=b_quant_mode,
    )
    return _backend_gemm_quantized(a_quant, b_quant, backend=backend)


def _localcta_fast_gemm_from_prepared(
    a_fp4: torch.Tensor,
    a_sc_prepared: torch.Tensor,
    b_fp4: torch.Tensor,
    b_sc_prepared: torch.Tensor,
) -> torch.Tensor:
    local_gemm = _load_localcta_gemm()
    _check_cuda_contiguous(a_fp4, "a_fp4")
    _check_cuda_contiguous(a_sc_prepared, "a_sc_prepared")
    _check_cuda_contiguous(b_fp4, "b_fp4")
    _check_cuda_contiguous(b_sc_prepared, "b_sc_prepared")
    if a_fp4.dtype != torch.float4_e2m1fn_x2 or b_fp4.dtype != torch.float4_e2m1fn_x2:
        raise ValueError("localCTA fast GEMM expects float4_e2m1fn_x2 payloads")
    if a_sc_prepared.dtype != torch.float8_e4m3fn or b_sc_prepared.dtype != torch.float8_e4m3fn:
        raise ValueError("localCTA fast GEMM expects float8_e4m3fn prepared scales")
    if a_fp4.ndim != 4 or a_sc_prepared.ndim != 5:
        raise ValueError("A must use (B,H,M,K/2) payloads and (B,H,M/128,K/64,512) prepared scales")
    if b_fp4.ndim != 4 or b_sc_prepared.ndim != 5:
        raise ValueError("B must use (B,H,N,K/2) payloads and (B,H,N/128,K/64,512) prepared scales")

    batch, heads, rows, packed_k = a_fp4.shape
    cols = packed_k * 2
    n_rows = int(b_fp4.shape[2])
    if a_sc_prepared.shape != (batch, heads, rows // 128, cols // 64, 512):
        raise ValueError(f"a_sc_prepared must have shape {(batch, heads, rows // 128, cols // 64, 512)}")
    if b_fp4.shape != (batch, heads, n_rows, packed_k):
        raise ValueError(f"b_fp4 must have shape {(batch, heads, n_rows, packed_k)}")
    if b_sc_prepared.shape != (batch, heads, n_rows // 128, cols // 64, 512):
        raise ValueError(f"b_sc_prepared must have shape {(batch, heads, n_rows // 128, cols // 64, 512)}")

    out = torch.zeros((batch, heads, rows, n_rows), dtype=torch.bfloat16, device=a_fp4.device)
    with _cuda_device_ctx(a_fp4.device):
        for b in range(batch):
            for h in range(heads):
                local_gemm.nvfp4_localcta_fast_gemm(
                    a_fp4[b, h],
                    a_sc_prepared[b, h],
                    b_fp4[b, h],
                    b_sc_prepared[b, h],
                    out[b, h],
                )
    return out


def _dequantize_rows_2d_forward_backend_for_debug(rec: dict[str, Any]) -> torch.Tensor:
    backend = _normalize_forward_matrix_backend(str(rec["backend"]))
    rows = int(rec["rows"])
    cols = int(rec["cols"])
    padded_rows = int(rec.get("padded_rows", rows))
    padded_cols = int(rec.get("padded_cols", cols))
    if backend == "v5":
        return _dequantize_v5_rows_2d(
            rec["fp4"],
            rec["scales"],
            rec["sg_chunks"],
            rows=rows,
            cols=cols,
        ).to(torch.bfloat16).contiguous()
    if backend == "localcta":
        local_q = _load_localcta_quant()
        return local_q.tk_localcta_reconstruct_row(
            rec["fp4"],
            rec["scales"],
            rec["sg_chunks"],
        )[:rows, :cols].to(torch.bfloat16).contiguous()
    if backend == "mxfp4_v3":
        deq = _dequantize_mxfp4_rows_2d(
            rec["fp4"],
            rec["scales"],
            rows=padded_rows,
            cols=cols,
        ).to(torch.bfloat16)
        return deq[:rows, :cols].contiguous()
    raise ValueError(f"unsupported backend {backend!r}")


def _quantize_dequantize_rows_2d_forward_backend(
    x_2d: torch.Tensor,
    *,
    backend: str,
    min_rows: int = 0,
    min_cols: int = 0,
    quant_mode: str | None = None,
) -> torch.Tensor:
    rec = _quantize_rows_2d_forward_backend(
        x_2d.to(torch.bfloat16).contiguous(),
        backend=backend,
        min_rows=min_rows,
        min_cols=min_cols,
        quant_mode=quant_mode,
    )
    return _dequantize_rows_2d_forward_backend_for_debug(rec)


def _dequantize_prequantized_p_rows_for_qdq_proxy(p_quant: dict[str, Any]) -> torch.Tensor:
    fmt = str(p_quant.get("format"))
    if fmt == "nvfp4_prepared":
        return _dequantize_prepared_fp4_rows_for_debug(
            p_quant["fp4"],
            p_quant["scales"],
        )[0, 0].to(torch.bfloat16).contiguous()
    if fmt in ("nvfp4_v5_direct", "nvfp4_localcta_direct"):
        return _dequantize_rows_2d_forward_backend_for_debug(p_quant).to(torch.bfloat16).contiguous()
    if fmt == "mxfp4_v3":
        rows = int(p_quant.get("rows", p_quant["fp4"].shape[0]))
        cols = int(p_quant.get("cols", int(p_quant["fp4"].shape[1]) * 2))
        padded_rows = int(p_quant.get("padded_rows", rows))
        return _dequantize_mxfp4_rows_2d(
            p_quant["fp4"],
            p_quant["scales"],
            rows=padded_rows,
            cols=cols,
        )[:rows, :cols].to(torch.bfloat16).contiguous()
    raise ValueError(f"unsupported prequantized P format {fmt!r}")


def _pv_backend_gemm_qdq_proxy_from_bf16(
    p_2d: torch.Tensor,
    v_rows_2d: torch.Tensor,
    *,
    backend: str,
    p_quant_mode: str | None = None,
    v_quant_mode: str | None = None,
) -> torch.Tensor:
    backend = _normalize_forward_matrix_backend(backend)
    p_qdq = _quantize_dequantize_rows_2d_forward_backend(
        p_2d,
        backend=backend,
        quant_mode=p_quant_mode,
    )
    v_qdq = _quantize_dequantize_rows_2d_forward_backend(
        v_rows_2d,
        backend=backend,
        min_rows=256 if backend == "mxfp4_v3" else 0,
        quant_mode=v_quant_mode,
    )
    return torch.matmul(p_qdq.float(), v_qdq.float().transpose(0, 1)).to(torch.bfloat16).contiguous()


def _pv_backend_gemm_from_prequantized_p_qdq_proxy(
    p_quant: dict[str, Any],
    v_rows_2d: torch.Tensor,
    *,
    backend: str,
    v_quant_mode: str | None = None,
) -> torch.Tensor:
    backend = _normalize_forward_matrix_backend(backend)
    p_qdq = _dequantize_prequantized_p_rows_for_qdq_proxy(p_quant)
    v_qdq = _quantize_dequantize_rows_2d_forward_backend(
        v_rows_2d.to(torch.bfloat16).contiguous(),
        backend=backend,
        min_rows=256 if backend == "mxfp4_v3" else 0,
        quant_mode=v_quant_mode,
    )
    out = torch.matmul(p_qdq.float(), v_qdq.float().transpose(0, 1)).to(torch.bfloat16).contiguous()
    return _apply_post_row_scale_to_pv_out(
        out,
        post_row_scale=p_quant.get("post_row_scale"),
        rows=int(p_qdq.shape[0]),
    )


def _materialize_prequantized_p_rows_for_native_requant(p_quant: dict[str, Any]) -> torch.Tensor:
    p_rows = _dequantize_prequantized_p_rows_for_qdq_proxy(p_quant)
    return _apply_post_row_scale_to_pv_out(
        p_rows,
        post_row_scale=p_quant.get("post_row_scale"),
        rows=int(p_rows.shape[0]),
    )


def _pv_backend_gemm_from_prequantized_strategy_p(
    p_quant: dict[str, Any],
    v_rows_2d: torch.Tensor,
    *,
    backend: str,
    pv_execution_mode: str = "real_kernel",
    p_quant_mode: str | None = None,
    v_quant_mode: str | None = None,
) -> torch.Tensor:
    backend = _normalize_forward_matrix_backend(backend)
    pv_execution_mode = _normalize_pv_execution_mode(pv_execution_mode)
    _check_choice("pv_execution_mode", pv_execution_mode, _PV_EXECUTION_MODES)
    _require_finite_tensor(v_rows_2d, "v_rows_2d")
    if pv_execution_mode == "qdq_proxy":
        return _pv_backend_gemm_from_prequantized_p_qdq_proxy(
            p_quant,
            v_rows_2d,
            backend=backend,
            v_quant_mode=v_quant_mode,
        )
    p_rows_native = _materialize_prequantized_p_rows_for_native_requant(p_quant)
    if backend == "mxfp4_v3":
        return _backend_gemm_from_bf16(
            p_rows_native,
            v_rows_2d.to(torch.bfloat16).contiguous(),
            backend=backend,
            a_min_cols=256,
            b_min_rows=256,
            b_min_cols=256,
            a_quant_mode=p_quant_mode,
            b_quant_mode=v_quant_mode,
        )
    return _backend_gemm_from_bf16(
        p_rows_native,
        v_rows_2d.to(torch.bfloat16).contiguous(),
        backend=backend,
        a_quant_mode=p_quant_mode,
        b_quant_mode=v_quant_mode,
    )


def _pv_backend_gemm_from_bf16(
    p_2d: torch.Tensor,
    v_rows_2d: torch.Tensor,
    *,
    backend: str,
    pv_execution_mode: str = "real_kernel",
    p_quant_mode: str | None = None,
    v_quant_mode: str | None = None,
) -> torch.Tensor:
    backend = _normalize_forward_matrix_backend(backend)
    pv_execution_mode = _normalize_pv_execution_mode(pv_execution_mode)
    _check_choice("pv_execution_mode", pv_execution_mode, _PV_EXECUTION_MODES)
    _require_finite_tensor(p_2d, "p_2d")
    _require_finite_tensor(v_rows_2d, "v_rows_2d")
    if pv_execution_mode == "qdq_proxy":
        return _pv_backend_gemm_qdq_proxy_from_bf16(
            p_2d,
            v_rows_2d,
            backend=backend,
            p_quant_mode=p_quant_mode,
            v_quant_mode=v_quant_mode,
        )
    if backend == "mxfp4_v3":
        return _backend_gemm_from_bf16(
            p_2d,
            v_rows_2d,
            backend=backend,
            a_min_cols=256,
            b_min_rows=256,
            b_min_cols=256,
            a_quant_mode=p_quant_mode,
            b_quant_mode=v_quant_mode,
        )
    return _backend_gemm_from_bf16(
        p_2d,
        v_rows_2d,
        backend=backend,
        a_quant_mode=p_quant_mode,
        b_quant_mode=v_quant_mode,
    )


def _quantize_rows_2d_sageattn3_p(x_2d: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, float]:
    x_2d = x_2d.to(torch.bfloat16).contiguous()
    _require_finite_tensor(x_2d, "x_2d")
    rows, cols = int(x_2d.shape[0]), int(x_2d.shape[1])
    if rows % _TILE != 0 or cols != _TILE:
        raise ValueError("SageAttention3 live P quantization currently expects shape (M, 128) with M divisible by 128")

    utils = _load_nvfp4_utils()
    x_groups = x_2d.float().view(rows, cols // 16, 16)
    group_amax = x_groups.abs().amax(dim=-1)
    valid_groups = torch.isfinite(group_amax) & (group_amax > 0)
    payload_scale = torch.where(valid_groups, 6.0 / group_amax, torch.zeros_like(group_amax))
    payload_input = (x_groups * payload_scale.unsqueeze(-1)).reshape(rows, cols).contiguous()
    row_scales = torch.where(
        valid_groups,
        (group_amax * (_SAGEATTN3_FP4_RECON_SCALE / 6.0)).to(torch.float8_e4m3fn),
        torch.zeros_like(group_amax, dtype=torch.float32).to(torch.float8_e4m3fn),
    ).contiguous()
    with _cuda_device_ctx(x_2d.device):
        p_fp4_rows = utils.fp32_to_fp4x2(payload_input)
    p_sc_prepared = _forward_prepared_scale_swizzle(row_scales.view(1, 1, rows, cols // 16))
    return p_fp4_rows.view(1, 1, rows, cols // 2).contiguous(), p_sc_prepared.contiguous(), float(_SAGEATTN3_FP4_RECON_SCALE)


def _quantize_rows_2d_localcta_cta_amax_p(x_2d: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    x_2d = x_2d.to(torch.bfloat16).contiguous()
    _require_finite_tensor(x_2d, "x_2d")
    rows, cols = int(x_2d.shape[0]), int(x_2d.shape[1])
    if rows % _TILE != 0 or cols != _TILE:
        raise ValueError("localCTA CTA-amax P quantization expects shape (M, 128) with M divisible by 128")

    utils = _load_nvfp4_utils()
    x_blocks = x_2d.float().view(rows // _TILE, _TILE, cols)
    x_groups = x_blocks.view(rows // _TILE, _TILE, cols // 16, 16)
    tile_amax = x_blocks.abs().amax(dim=(1, 2))
    tile_valid = torch.isfinite(tile_amax) & (tile_amax > 0)
    s_global_enc = torch.where(
        tile_valid,
        torch.full_like(tile_amax, _FP4PV_LOCALCTA_GLOBAL_SCALE_NUM) / tile_amax,
        torch.ones_like(tile_amax),
    )
    s_global_dec = torch.where(tile_valid, tile_amax / _FP4PV_LOCALCTA_GLOBAL_SCALE_NUM, torch.ones_like(tile_amax))

    local_amax = x_groups.abs().amax(dim=-1)
    local_scale_raw = (local_amax / 6.0) * s_global_enc.view(-1, 1, 1)
    local_scale_fp8 = local_scale_raw.to(torch.float8_e4m3fn)
    local_scale = local_scale_fp8.float()
    raw_valid = torch.isfinite(local_scale) & (local_scale > 0)
    payload_scale = torch.where(
        raw_valid,
        s_global_enc.view(-1, 1, 1) / local_scale,
        torch.zeros_like(local_scale),
    )

    scaled = (x_groups * payload_scale.unsqueeze(-1)).reshape(rows, cols).contiguous()
    with _cuda_device_ctx(x_2d.device):
        p_fp4_rows = utils.fp32_to_fp4x2(scaled)

    row_scales_raw = local_scale_fp8.reshape(rows, cols // 16).contiguous()
    post_row_scale = s_global_dec.repeat_interleave(_TILE).to(torch.float32).contiguous()
    p_sc_prepared = _forward_prepared_scale_swizzle(row_scales_raw.view(1, 1, rows, cols // 16))
    return p_fp4_rows.view(1, 1, rows, cols // 2).contiguous(), p_sc_prepared.contiguous(), post_row_scale


def _apply_post_row_scale_to_pv_out(
    out: torch.Tensor,
    *,
    post_row_scale: torch.Tensor | float | None,
    rows: int,
) -> torch.Tensor:
    if post_row_scale is None:
        return out
    if isinstance(post_row_scale, torch.Tensor):
        scale_rows = post_row_scale.to(device=out.device, dtype=torch.float32)
    else:
        scale_rows = torch.full((rows,), float(post_row_scale), device=out.device, dtype=torch.float32)
    if scale_rows.ndim == 0:
        scale_rows = scale_rows.expand(rows)
    if scale_rows.ndim != 1 or int(scale_rows.numel()) != rows:
        raise ValueError("post_row_scale must be a scalar or a length-M row scale vector")
    return (out.float() * scale_rows.view(rows, 1)).to(torch.bfloat16).contiguous()


def _pv_backend_gemm_from_prequantized_nvfp4_p(
    p_fp4: torch.Tensor,
    p_sc_prepared: torch.Tensor,
    v_rows_2d: torch.Tensor,
    *,
    backend: str,
    pv_execution_mode: str = "real_kernel",
    post_row_scale: torch.Tensor | float | None = None,
) -> torch.Tensor:
    backend = _normalize_forward_matrix_backend(backend)
    pv_execution_mode = _normalize_pv_execution_mode(pv_execution_mode)
    _check_choice("pv_execution_mode", pv_execution_mode, _PV_EXECUTION_MODES)
    if backend not in _REAL_NVFP4_PV_BACKENDS:
        raise ValueError(f"prequantized NVFP4 P only supports NVFP4 PV backends, got {backend!r}")
    _check_cuda_contiguous(p_fp4, "p_fp4")
    _check_cuda_contiguous(p_sc_prepared, "p_sc_prepared")
    _require_finite_tensor(v_rows_2d, "v_rows_2d")

    rows = int(p_fp4.shape[2])
    cols = int(v_rows_2d.shape[1])
    dvo = int(v_rows_2d.shape[0])
    if p_fp4.shape != (1, 1, rows, cols // 2):
        raise ValueError("prequantized P payload shape must be (1,1,M,K/2)")
    if p_sc_prepared.shape != (1, 1, rows // 128, cols // 64, 512):
        raise ValueError("prequantized P scales shape must be (1,1,M/128,K/64,512)")
    if rows % _TILE != 0 or cols % _TILE != 0 or dvo % _TILE != 0:
        raise ValueError("NVFP4 PV backend GEMM expects M/N/K to be multiples of 128")

    if pv_execution_mode == "qdq_proxy":
        return _pv_backend_gemm_from_prequantized_p_qdq_proxy(
            {
                "format": "nvfp4_prepared",
                "fp4": p_fp4,
                "scales": p_sc_prepared,
                "post_row_scale": post_row_scale,
            },
            v_rows_2d,
            backend=backend,
        )
    p_rows_native = _materialize_prequantized_p_rows_for_native_requant(
        {
            "format": "nvfp4_prepared",
            "fp4": p_fp4,
            "scales": p_sc_prepared,
            "post_row_scale": post_row_scale,
        }
    )
    return _backend_gemm_from_bf16(
        p_rows_native,
        v_rows_2d.to(torch.bfloat16).contiguous(),
        backend=backend,
    )


def _pv_backend_gemm_from_prequantized_mxfp4_p(
    p_fp4: torch.Tensor,
    p_sc: torch.Tensor,
    v_rows_2d: torch.Tensor,
    *,
    pv_execution_mode: str = "real_kernel",
    post_row_scale: torch.Tensor | float | None = None,
) -> torch.Tensor:
    pv_execution_mode = _normalize_pv_execution_mode(pv_execution_mode)
    _check_choice("pv_execution_mode", pv_execution_mode, _PV_EXECUTION_MODES)
    _check_cuda_contiguous(p_fp4, "p_fp4")
    _check_cuda_contiguous(p_sc, "p_sc")
    _require_finite_tensor(v_rows_2d, "v_rows_2d")
    if p_fp4.dtype != torch.float4_e2m1fn_x2:
        raise ValueError("p_fp4 must have dtype torch.float4_e2m1fn_x2")
    if p_sc.dtype != torch.uint8:
        raise ValueError("p_sc must have dtype torch.uint8")
    if p_fp4.ndim != 2:
        raise ValueError("p_fp4 must have shape (M, K/2)")
    rows, packed_cols = int(p_fp4.shape[0]), int(p_fp4.shape[1])
    cols = packed_cols * 2
    if p_sc.shape != (rows // 128, cols // 128, 32, 16):
        raise ValueError(f"p_sc must have shape {(rows // 128, cols // 128, 32, 16)}")
    if v_rows_2d.shape[1] != cols:
        raise ValueError("PV backend GEMM expects V rows to share P's K dimension")
    if rows % _TILE != 0 or cols % _TILE != 0:
        raise ValueError("MXFP4 PV backend GEMM expects M and K to be multiples of 128")

    if pv_execution_mode == "qdq_proxy":
        return _pv_backend_gemm_from_prequantized_p_qdq_proxy(
            {
                "format": "mxfp4_v3",
                "fp4": p_fp4,
                "scales": p_sc,
                "rows": rows,
                "cols": cols,
                "post_row_scale": post_row_scale,
            },
            v_rows_2d,
            backend="mxfp4_v3",
        )
    p_rows_native = _materialize_prequantized_p_rows_for_native_requant(
        {
            "format": "mxfp4_v3",
            "fp4": p_fp4,
            "scales": p_sc,
            "rows": rows,
            "cols": cols,
            "post_row_scale": post_row_scale,
        }
    )
    return _backend_gemm_from_bf16(
        p_rows_native,
        v_rows_2d.to(torch.bfloat16).contiguous(),
        backend="mxfp4_v3",
        a_min_cols=256,
        b_min_rows=256,
        b_min_cols=256,
    )


def _pv_backend_gemm_from_prequantized_p(
    p_quant: dict[str, Any],
    v_rows_2d: torch.Tensor,
    *,
    backend: str,
    pv_execution_mode: str = "real_kernel",
) -> torch.Tensor:
    backend = _normalize_forward_matrix_backend(backend)
    if backend in _REAL_NVFP4_PV_BACKENDS:
        if p_quant.get("format") != "nvfp4_prepared":
            raise ValueError(f"backend {backend!r} expects an nvfp4_prepared P artifact")
        return _pv_backend_gemm_from_prequantized_nvfp4_p(
            p_quant["fp4"],
            p_quant["scales"],
            v_rows_2d,
            backend=backend,
            pv_execution_mode=pv_execution_mode,
            post_row_scale=p_quant.get("post_row_scale"),
        )
    if backend == "mxfp4_v3":
        if p_quant.get("format") != "mxfp4_v3":
            raise ValueError("backend 'mxfp4_v3' expects an mxfp4_v3 P artifact")
        return _pv_backend_gemm_from_prequantized_mxfp4_p(
            p_quant["fp4"],
            p_quant["scales"],
            v_rows_2d,
            pv_execution_mode=pv_execution_mode,
            post_row_scale=p_quant.get("post_row_scale"),
        )
    raise ValueError(f"unsupported prequantized PV backend {backend!r}")


def _quantize_live_sa3_p_for_pv_backend(
    exp_tile: torch.Tensor,
    *,
    backend: str,
) -> dict[str, Any]:
    backend = _normalize_forward_matrix_backend(backend)
    if backend in _REAL_NVFP4_PV_BACKENDS:
        p_fp4, p_sc_prepared, row_sum_scale = _quantize_rows_2d_sageattn3_p(exp_tile)
        return {
            "format": "nvfp4_prepared",
            "fp4": p_fp4,
            "scales": p_sc_prepared,
            "row_sum_scale": float(row_sum_scale),
        }
    if backend == "mxfp4_v3":
        scaled_tile = (exp_tile.float() * _SAGEATTN3_FP4_RECON_SCALE).to(torch.bfloat16).contiguous()
        rec = _quantize_rows_2d_mxfp4(scaled_tile, backend="mxfp4")
        return {
            "format": "mxfp4_v3",
            "fp4": rec["fp4"].contiguous(),
            "scales": rec["scales"].contiguous(),
            "rows": rec["rows"],
            "cols": rec["cols"],
            "row_sum_scale": float(_SAGEATTN3_FP4_RECON_SCALE),
        }
    raise ValueError(f"unsupported PV backend {backend!r}")


def _quantize_live_mxfp4_p_for_pv_backend(
    exp_tile: torch.Tensor,
    *,
    padded_cols: int,
) -> dict[str, Any]:
    rows, cols = int(exp_tile.shape[0]), int(exp_tile.shape[1])
    padded_cols = max(_next_multiple(cols, _TILE), int(padded_cols))
    scaled_src = (exp_tile.float() * _SAGEATTN3_FP4_RECON_SCALE).to(torch.bfloat16)
    if cols == padded_cols:
        scaled_tile = scaled_src.contiguous()
    else:
        scaled_tile = torch.zeros((rows, padded_cols), device=exp_tile.device, dtype=torch.bfloat16)
        scaled_tile[:, :cols].copy_(scaled_src)
    rec = _quantize_rows_2d_mxfp4(scaled_tile, backend="mxfp4")
    return {
        "format": "mxfp4_v3",
        "fp4": rec["fp4"].contiguous(),
        "scales": rec["scales"].contiguous(),
        "rows": rec["rows"],
        "cols": rec["cols"],
        "row_sum_scale": float(_SAGEATTN3_FP4_RECON_SCALE),
    }


def _quantize_live_mxfp4_p_from_masked_logits_for_pv_backend(
    logits_tile: torch.Tensor,
    row_max: torch.Tensor,
    *,
    padded_cols: int,
    quant_mode: str | None = None,
) -> tuple[dict[str, Any], torch.Tensor] | None:
    if os.getenv("TK_FA4_DISABLE_FUSED_MXFP4_SOFTMAX_QUANT", "0") not in ("", "0"):
        return None
    mod = _load_mxfp4_v3_quant()
    if not hasattr(mod, "mxfp4_softmax_tile_quantize"):
        return None
    rows, cols = int(logits_tile.shape[0]), int(logits_tile.shape[1])
    padded_cols = max(_next_multiple(cols, _TILE), int(padded_cols))
    with _cuda_device_ctx(logits_tile.device):
        p_fp4, p_sc, row_sum = mod.mxfp4_softmax_tile_quantize(
            logits_tile.float().contiguous(),
            row_max.float().contiguous(),
            padded_cols,
            float(_SAGEATTN3_FP4_RECON_SCALE),
            _mxfp4_quant_mode_to_int(quant_mode),
        )
    return (
        {
            "format": "mxfp4_v3",
            "fp4": p_fp4.contiguous(),
            "scales": p_sc.contiguous(),
            "rows": rows,
            "cols": padded_cols,
            "row_sum_scale": float(_SAGEATTN3_FP4_RECON_SCALE),
            "quant_mode": _normalize_quant_mode_for_backend("mxfp4_v3", quant_mode),
            "strategy_family": "live_mxfp4_softmax_fused_pv",
        },
        row_sum.contiguous(),
    )


def _prepare_live_mxfp4_v_tile_cache(
    v_fp4: torch.Tensor,
    v_sc: torch.Tensor,
    *,
    seqlen: int,
    padded_tile_cols: int = 256,
) -> list[tuple[torch.Tensor, torch.Tensor]]:
    if padded_tile_cols % _TILE != 0:
        raise ValueError("padded_tile_cols must be divisible by 128")
    packed_tile_cols = padded_tile_cols // 2
    tile_block_cols = padded_tile_cols // _TILE
    cache: list[tuple[torch.Tensor, torch.Tensor]] = []
    d_blocks = int(v_sc.shape[2])
    step_cols = padded_tile_cols
    for tile_start in range(0, seqlen, step_cols):
        tile_end = min(tile_start + step_cols, seqlen)
        packed_start = tile_start // 2
        packed_end = tile_end // 2
        block_start = tile_start // _TILE
        block_end = tile_end // _TILE
        v_fp4_tile = _zeros_fp4(
            (int(v_fp4.shape[0]), int(v_fp4.shape[1]), int(v_fp4.shape[2]), packed_tile_cols),
            v_fp4.device,
        )
        src_u8 = v_fp4[:, :, :, packed_start:packed_end].view(torch.uint8)
        v_fp4_tile.view(torch.uint8)[..., : int(src_u8.shape[-1])].copy_(src_u8)
        v_sc_tile = torch.zeros(
            (int(v_sc.shape[0]), int(v_sc.shape[1]), d_blocks, tile_block_cols, 32, 16),
            device=v_sc.device,
            dtype=torch.uint8,
        )
        v_sc_tile[:, :, :, : block_end - block_start, :, :].copy_(v_sc[:, :, :, block_start:block_end, :, :])
        cache.append((v_fp4_tile.contiguous(), v_sc_tile.contiguous()))
    return cache


def _quantize_live_localcta_cta_amax_p_for_pv_backend(
    p_tile: torch.Tensor,
    *,
    backend: str,
) -> dict[str, Any]:
    backend = _normalize_forward_matrix_backend(backend)
    if backend in _REAL_NVFP4_PV_BACKENDS:
        p_fp4, p_sc_prepared, post_row_scale = _quantize_rows_2d_localcta_cta_amax_p(p_tile)
        return {
            "format": "nvfp4_prepared",
            "fp4": p_fp4,
            "scales": p_sc_prepared,
            "post_row_scale": post_row_scale,
        }
    if backend == "mxfp4_v3":
        rows, cols = int(p_tile.shape[0]), int(p_tile.shape[1])
        x_blocks = p_tile.float().view(rows // _TILE, _TILE, cols)
        tile_amax = x_blocks.abs().amax(dim=(1, 2))
        tile_valid = torch.isfinite(tile_amax) & (tile_amax > 0)
        s_global_enc = torch.where(
            tile_valid,
            torch.full_like(tile_amax, _FP4PV_LOCALCTA_GLOBAL_SCALE_NUM) / tile_amax,
            torch.ones_like(tile_amax),
        )
        s_global_dec = torch.where(tile_valid, tile_amax / _FP4PV_LOCALCTA_GLOBAL_SCALE_NUM, torch.ones_like(tile_amax))
        row_encode_scale = s_global_enc.repeat_interleave(_TILE).to(torch.float32).contiguous()
        post_row_scale = s_global_dec.repeat_interleave(_TILE).to(torch.float32).contiguous()
        scaled_tile = (p_tile.float() * row_encode_scale.view(rows, 1)).to(torch.bfloat16).contiguous()
        rec = _quantize_rows_2d_mxfp4(scaled_tile, backend="mxfp4")
        return {
            "format": "mxfp4_v3",
            "fp4": rec["fp4"].contiguous(),
            "scales": rec["scales"].contiguous(),
            "rows": rec["rows"],
            "cols": rec["cols"],
            "post_row_scale": post_row_scale,
        }
    raise ValueError(f"unsupported PV backend {backend!r}")


def _quantize_live_sa3_p_for_probability_study(
    exp_tile: torch.Tensor,
    *,
    backend: str,
    p_quant_mode: str | None = None,
    sa3_payload_target_max: float = 6.0,
    sa3_recon_scale_base: float = 448.0,
) -> dict[str, Any]:
    backend = _normalize_forward_matrix_backend(backend)
    row_sum_scale = float(sa3_payload_target_max) * float(sa3_recon_scale_base)
    scaled_tile = (exp_tile.float() * row_sum_scale).to(torch.bfloat16).contiguous()
    rec = _quantize_rows_2d_forward_backend(
        scaled_tile,
        backend=backend,
        quant_mode=p_quant_mode,
    )
    rec["row_sum_scale"] = row_sum_scale
    rec["strategy_family"] = "live_sa3_baseline"
    return rec


def _quantize_live_localcta_cta_amax_p_for_probability_study(
    p_tile: torch.Tensor,
    *,
    backend: str,
    p_quant_mode: str | None = None,
    localcta_global_scale_num: float = _FP4PV_LOCALCTA_GLOBAL_SCALE_NUM,
) -> dict[str, Any]:
    backend = _normalize_forward_matrix_backend(backend)
    rows, cols = int(p_tile.shape[0]), int(p_tile.shape[1])
    if rows % _TILE != 0 or cols != _TILE:
        raise ValueError("localCTA probability-study quantization expects shape (M, 128) with M divisible by 128")
    x_blocks = p_tile.float().view(rows // _TILE, _TILE, cols)
    tile_amax = x_blocks.abs().amax(dim=(1, 2))
    tile_valid = torch.isfinite(tile_amax) & (tile_amax > 0)
    row_encode_scale = torch.where(
        tile_valid,
        torch.full_like(tile_amax, float(localcta_global_scale_num)) / tile_amax,
        torch.ones_like(tile_amax),
    ).repeat_interleave(_TILE).to(torch.float32).contiguous()
    post_row_scale = torch.where(
        tile_valid,
        tile_amax / float(localcta_global_scale_num),
        torch.ones_like(tile_amax),
    ).repeat_interleave(_TILE).to(torch.float32).contiguous()
    scaled_tile = (p_tile.float() * row_encode_scale.view(rows, 1)).to(torch.bfloat16).contiguous()
    rec = _quantize_rows_2d_forward_backend(
        scaled_tile,
        backend=backend,
        quant_mode=p_quant_mode,
    )
    rec["post_row_scale"] = post_row_scale
    rec["strategy_family"] = "live_localcta_cta_amax_experimental"
    return rec


def _quantize_live_nvfp4_fixed_scale_p_for_probability_study(
    p_tile: torch.Tensor,
    *,
    backend: str,
    p_quant_mode: str | None = None,
    fixed_nvfp4_scale_num: float = _FP4PV_LOCALCTA_GLOBAL_SCALE_NUM,
) -> dict[str, Any]:
    backend = _normalize_forward_matrix_backend(backend)
    if backend not in _REAL_NVFP4_PV_BACKENDS:
        raise ValueError(f"fixed-scale NVFP4 P quantization requires an NVFP4 backend, got {backend!r}")
    if float(fixed_nvfp4_scale_num) <= 0:
        raise ValueError("fixed_nvfp4_scale_num must be positive")
    scaled_tile = (p_tile.float() * float(fixed_nvfp4_scale_num)).to(torch.bfloat16).contiguous()
    rec = _quantize_rows_2d_forward_backend(
        scaled_tile,
        backend=backend,
        quant_mode=p_quant_mode,
    )
    rec["post_row_scale"] = float(1.0 / float(fixed_nvfp4_scale_num))
    rec["strategy_family"] = "live_nvfp4_fixed_scale_pv"
    rec["fixed_nvfp4_scale_num"] = float(fixed_nvfp4_scale_num)
    return rec


def _run_online_probability_strategy_from_logits_2d(
    logits_2d: torch.Tensor,
    v_2d: torch.Tensor,
    *,
    p_mode: str,
    pv_backend: str,
    pv_execution_mode: str = "qdq_proxy",
    p_quant_mode: str | None = None,
    v_quant_mode: str | None = None,
    sa3_payload_target_max: float = 6.0,
    sa3_recon_scale_base: float = 448.0,
    localcta_global_scale_num: float = _FP4PV_LOCALCTA_GLOBAL_SCALE_NUM,
    fixed_nvfp4_scale_num: float = _FP4PV_LOCALCTA_GLOBAL_SCALE_NUM,
) -> tuple[torch.Tensor, torch.Tensor]:
    p_mode = _normalize_forward_p_mode(p_mode)
    pv_backend = _normalize_forward_matrix_backend(pv_backend)
    pv_execution_mode = _normalize_pv_execution_mode(pv_execution_mode)
    logits = logits_2d.float()
    seqlen, dvo = logits.shape[0], int(v_2d.shape[1])
    row_max = torch.full((seqlen,), float("-inf"), dtype=torch.float32, device=logits.device)
    row_sum = torch.zeros((seqlen,), dtype=torch.float32, device=logits.device)
    out_accum = torch.zeros((seqlen, dvo), dtype=torch.float32, device=logits.device)
    tiny = torch.finfo(torch.float32).tiny
    row_sum_scale = 1.0

    for tile_start in range(0, seqlen, _TILE):
        tile_end = min(tile_start + _TILE, seqlen)
        logits_tile = _causal_mask_logits_tile_2d(logits[:, tile_start:tile_end], tile_start=tile_start)
        tile_max = logits_tile.max(dim=-1).values
        new_row_max = torch.maximum(row_max, tile_max)
        alpha = torch.where(torch.isfinite(row_max), torch.exp(row_max - new_row_max), torch.zeros_like(new_row_max))
        exp_tile = torch.exp(logits_tile - new_row_max.unsqueeze(-1))
        exp_tile = torch.where(torch.isfinite(logits_tile), exp_tile, torch.zeros_like(exp_tile))
        _require_finite_tensor(exp_tile, "exp_tile")
        v_rows = v_2d[tile_start:tile_end].transpose(0, 1).contiguous()

        if p_mode == "live_direct":
            pv_tile = _pv_backend_gemm_from_bf16(
                exp_tile.to(torch.bfloat16).contiguous(),
                v_rows,
                backend=pv_backend,
                pv_execution_mode=pv_execution_mode,
                p_quant_mode=p_quant_mode,
                v_quant_mode=v_quant_mode,
            )
            out_accum.mul_(alpha.unsqueeze(-1))
            out_accum.add_(pv_tile.float())
            row_sum = row_sum * alpha + exp_tile.sum(dim=-1)
        elif p_mode == "live_sa3_baseline":
            p_quant = _quantize_live_sa3_p_for_probability_study(
                exp_tile,
                backend=pv_backend,
                p_quant_mode=p_quant_mode,
                sa3_payload_target_max=sa3_payload_target_max,
                sa3_recon_scale_base=sa3_recon_scale_base,
            )
            row_sum_scale = float(p_quant["row_sum_scale"])
            pv_tile = _pv_backend_gemm_from_prequantized_strategy_p(
                p_quant,
                v_rows,
                backend=pv_backend,
                pv_execution_mode=pv_execution_mode,
                p_quant_mode=p_quant_mode,
                v_quant_mode=v_quant_mode,
            )
            out_accum.mul_(alpha.unsqueeze(-1))
            out_accum.add_(pv_tile.float())
            row_sum = row_sum * alpha + exp_tile.sum(dim=-1)
        elif p_mode == "live_mxfp4_pv":
            if pv_backend != "mxfp4_v3":
                raise ValueError(f"live_mxfp4_pv requires pv_backend='mxfp4_v3', got {pv_backend!r}")
            p_quant = _quantize_live_sa3_p_for_probability_study(
                exp_tile,
                backend=pv_backend,
                p_quant_mode=p_quant_mode,
                sa3_payload_target_max=sa3_payload_target_max,
                sa3_recon_scale_base=sa3_recon_scale_base,
            )
            row_sum_scale = float(p_quant["row_sum_scale"])
            pv_tile = _pv_backend_gemm_from_prequantized_strategy_p(
                p_quant,
                v_rows,
                backend=pv_backend,
                pv_execution_mode=pv_execution_mode,
                p_quant_mode=p_quant_mode,
                v_quant_mode=v_quant_mode,
            )
            out_accum.mul_(alpha.unsqueeze(-1))
            out_accum.add_(pv_tile.float())
            row_sum = row_sum * alpha + exp_tile.sum(dim=-1)
        elif p_mode == "live_localcta_cta_amax_experimental":
            next_row_sum = row_sum * alpha + exp_tile.sum(dim=-1)
            correction = torch.where(
                next_row_sum > 0,
                (row_sum * alpha) / next_row_sum.clamp_min(tiny),
                torch.zeros_like(next_row_sum),
            )
            p_tile = torch.where(
                next_row_sum.unsqueeze(-1) > 0,
                exp_tile / next_row_sum.clamp_min(tiny).unsqueeze(-1),
                torch.zeros_like(exp_tile),
            )
            _require_finite_tensor(p_tile, "p_tile")
            p_quant = _quantize_live_localcta_cta_amax_p_for_probability_study(
                p_tile,
                backend=pv_backend,
                p_quant_mode=p_quant_mode,
                localcta_global_scale_num=localcta_global_scale_num,
            )
            pv_tile = _pv_backend_gemm_from_prequantized_strategy_p(
                p_quant,
                v_rows,
                backend=pv_backend,
                pv_execution_mode=pv_execution_mode,
                p_quant_mode=p_quant_mode,
                v_quant_mode=v_quant_mode,
            )
            out_accum.mul_(correction.unsqueeze(-1))
            out_accum.add_(pv_tile.float())
            row_sum = next_row_sum
        elif p_mode == "live_nvfp4_fixed_scale_pv":
            next_row_sum = row_sum * alpha + exp_tile.sum(dim=-1)
            correction = torch.where(
                next_row_sum > 0,
                (row_sum * alpha) / next_row_sum.clamp_min(tiny),
                torch.zeros_like(next_row_sum),
            )
            p_tile = torch.where(
                next_row_sum.unsqueeze(-1) > 0,
                exp_tile / next_row_sum.clamp_min(tiny).unsqueeze(-1),
                torch.zeros_like(exp_tile),
            )
            _require_finite_tensor(p_tile, "p_tile")
            p_quant = _quantize_live_nvfp4_fixed_scale_p_for_probability_study(
                p_tile,
                backend=pv_backend,
                p_quant_mode=p_quant_mode,
                fixed_nvfp4_scale_num=fixed_nvfp4_scale_num,
            )
            pv_tile = _pv_backend_gemm_from_prequantized_strategy_p(
                p_quant,
                v_rows,
                backend=pv_backend,
                pv_execution_mode=pv_execution_mode,
                p_quant_mode=p_quant_mode,
                v_quant_mode=v_quant_mode,
            )
            out_accum.mul_(correction.unsqueeze(-1))
            out_accum.add_(pv_tile.float())
            row_sum = next_row_sum
        else:
            raise ValueError(f"unsupported probability-study p_mode {p_mode!r}")
        row_max = new_row_max

    if p_mode in {"live_sa3_baseline", "live_mxfp4_pv"}:
        out = torch.where(
            row_sum.unsqueeze(-1) > 0,
            out_accum / (row_sum.clamp_min(tiny).unsqueeze(-1) * float(row_sum_scale)),
            torch.zeros_like(out_accum),
        ).to(torch.bfloat16)
    elif p_mode == "live_direct":
        out = torch.where(
            row_sum.unsqueeze(-1) > 0,
            out_accum / row_sum.clamp_min(tiny).unsqueeze(-1),
            torch.zeros_like(out_accum),
        ).to(torch.bfloat16)
    else:
        out = out_accum.to(torch.bfloat16)
    lse = torch.where(row_sum > 0, row_max + torch.log(row_sum.clamp_min(tiny)), torch.full_like(row_sum, float("-inf")))
    return out.contiguous(), lse.contiguous()


def _live_sa3_exact_forward_from_logits_2d(
    logits_2d: torch.Tensor,
    v_2d: torch.Tensor,
    *,
    pv_backend: str,
    pv_execution_mode: str = "real_kernel",
) -> tuple[torch.Tensor, torch.Tensor]:
    logits = logits_2d.float()
    seqlen, dvo = logits.shape[0], int(v_2d.shape[1])
    row_max = torch.full((seqlen,), float("-inf"), dtype=torch.float32, device=logits.device)
    row_sum = torch.zeros((seqlen,), dtype=torch.float32, device=logits.device)
    out_accum = torch.zeros((seqlen, dvo), dtype=torch.float32, device=logits.device)
    tiny = torch.finfo(torch.float32).tiny
    row_sum_scale = float(_SAGEATTN3_FP4_RECON_SCALE)

    for tile_start in range(0, seqlen, _TILE):
        tile_end = min(tile_start + _TILE, seqlen)
        logits_tile = _causal_mask_logits_tile_2d(logits[:, tile_start:tile_end], tile_start=tile_start)
        tile_max = logits_tile.max(dim=-1).values
        new_row_max = torch.maximum(row_max, tile_max)
        alpha = torch.where(torch.isfinite(row_max), torch.exp(row_max - new_row_max), torch.zeros_like(new_row_max))
        exp_tile = torch.exp(logits_tile - new_row_max.unsqueeze(-1))
        exp_tile = torch.where(torch.isfinite(logits_tile), exp_tile, torch.zeros_like(exp_tile))
        _require_finite_tensor(exp_tile, "exp_tile")
        p_quant = _quantize_live_sa3_p_for_pv_backend(exp_tile, backend=pv_backend)
        row_sum_scale = float(p_quant.get("row_sum_scale", row_sum_scale))
        pv_tile = _pv_backend_gemm_from_prequantized_p(
            p_quant,
            v_2d[tile_start:tile_end].transpose(0, 1).contiguous(),
            backend=pv_backend,
            pv_execution_mode=pv_execution_mode,
        )
        out_accum.mul_(alpha.unsqueeze(-1))
        out_accum.add_(pv_tile.float())
        row_sum = row_sum * alpha + exp_tile.sum(dim=-1)
        row_max = new_row_max

    out = torch.where(
        row_sum.unsqueeze(-1) > 0,
        out_accum / (row_sum.clamp_min(tiny).unsqueeze(-1) * float(row_sum_scale)),
        torch.zeros_like(out_accum),
    ).to(torch.bfloat16)
    lse = torch.where(row_sum > 0, row_max + torch.log(row_sum.clamp_min(tiny)), torch.full_like(row_sum, float("-inf")))
    return out.contiguous(), lse.contiguous()


def _mxfp4_live_pv_tile_from_prequantized_v(
    p_quant: dict[str, Any],
    v_fp4_tile: torch.Tensor,
    v_sc_tile: torch.Tensor,
    *,
    dvo: int,
) -> torch.Tensor:
    if str(p_quant.get("format")) != "mxfp4_v3":
        raise ValueError("MXFP4 live PV expects an mxfp4_v3 P artifact")
    p_fp4 = p_quant["fp4"].unsqueeze(0).unsqueeze(0).contiguous()
    p_sc = p_quant["scales"].unsqueeze(0).unsqueeze(0).contiguous()
    out = _mxfp4_pv_from_p(
        p_fp4,
        p_sc,
        v_fp4_tile.contiguous(),
        v_sc_tile.contiguous(),
        output_layout="bhrd",
    )
    return out[0, 0, :, :dvo].contiguous()


def _quantize_mxfp4_pt_from_logits_tile_for_dv(
    logits_tile: torch.Tensor,
    lse_1d: torch.Tensor | None = None,
    *,
    tile_start: int,
    padded_cols: int,
    payload_scale: float = _SAGEATTN3_FP4_RECON_SCALE,
    quant_mode: str | None = None,
    row_max_1d: torch.Tensor | None = None,
    row_sum_1d: torch.Tensor | None = None,
) -> dict[str, Any]:
    rows, cols = int(logits_tile.shape[0]), int(logits_tile.shape[1])
    padded_cols = max(_next_multiple(cols, _TILE), int(padded_cols))
    if rows % _TILE != 0 or padded_cols % _TILE != 0:
        raise ValueError("MXFP4 dV P^T quantization requires row and padded column multiples of 128")
    have_stats = row_max_1d is not None or row_sum_1d is not None
    if have_stats:
        if row_max_1d is None or row_sum_1d is None:
            raise ValueError("row_max_1d and row_sum_1d must be provided together")
        if int(row_max_1d.numel()) != rows or int(row_sum_1d.numel()) != rows:
            raise ValueError("row_max_1d and row_sum_1d must have one value per logits row")
    elif lse_1d is None:
        raise ValueError("either lse_1d or row_max_1d/row_sum_1d must be provided")
    elif int(lse_1d.numel()) != rows:
        raise ValueError("lse_1d must have one value per logits row")
    mod = _load_mxfp4_v3_quant()
    if (
        have_stats
        and os.getenv("TK_FA4_DISABLE_FUSED_MXFP4_DV_SOFTMAX_TRANSPOSE_STATS_QUANT", "0") in ("", "0")
        and hasattr(mod, "mxfp4_softmax_tile_quantize_transpose_from_stats")
    ):
        with _cuda_device_ctx(logits_tile.device):
            pt_fp4, pt_sc = mod.mxfp4_softmax_tile_quantize_transpose_from_stats(
                logits_tile.float().contiguous(),
                row_max_1d.float().contiguous(),
                row_sum_1d.float().contiguous(),
                int(tile_start),
                int(padded_cols),
                float(payload_scale),
                _mxfp4_quant_mode_to_int(quant_mode),
            )
        strategy_family = "live_mxfp4_softmax_transpose_stats_fused_dv"
    elif (
        lse_1d is not None
        and os.getenv("TK_FA4_DISABLE_FUSED_MXFP4_DV_SOFTMAX_TRANSPOSE_QUANT", "0") in ("", "0")
        and hasattr(mod, "mxfp4_softmax_tile_quantize_transpose")
    ):
        with _cuda_device_ctx(logits_tile.device):
            pt_fp4, pt_sc = mod.mxfp4_softmax_tile_quantize_transpose(
                logits_tile.float().contiguous(),
                lse_1d.float().contiguous(),
                int(tile_start),
                int(padded_cols),
                float(payload_scale),
                _mxfp4_quant_mode_to_int(quant_mode),
            )
        strategy_family = "live_mxfp4_softmax_transpose_fused_dv"
    else:
        logits = logits_tile.float()
        row_ids = torch.arange(rows, device=logits.device).view(rows, 1)
        col_ids = torch.arange(int(tile_start), int(tile_start) + cols, device=logits.device).view(1, cols)
        valid = col_ids <= row_ids
        if have_stats:
            denom = row_sum_1d.float().view(rows, 1)
            p_tile = torch.exp(logits - row_max_1d.float().view(rows, 1)) / denom.clamp_min(torch.finfo(torch.float32).tiny)
            p_tile = torch.where(valid & torch.isfinite(logits) & (denom > 0), p_tile, torch.zeros_like(p_tile))
            strategy_family = "materialized_mxfp4_softmax_transpose_stats_dv"
        else:
            p_tile = torch.exp(logits - lse_1d.float().view(rows, 1))
            p_tile = torch.where(valid & torch.isfinite(logits), p_tile, torch.zeros_like(p_tile))
            strategy_family = "materialized_mxfp4_softmax_transpose_dv"
        scaled_tile = (p_tile * float(payload_scale)).to(torch.bfloat16)
        if cols != padded_cols:
            scaled_work = torch.zeros((rows, padded_cols), dtype=torch.bfloat16, device=logits.device)
            scaled_work[:, :cols].copy_(scaled_tile)
        else:
            scaled_work = scaled_tile.contiguous()
        with _cuda_device_ctx(logits_tile.device):
            _, _, pt_fp4, pt_sc = mod.mxfp4_quantize_row_and_col(
                scaled_work.contiguous(),
                _mxfp4_quant_mode_to_int(quant_mode),
            )
    return {
        "format": "mxfp4_v3",
        "fp4": pt_fp4.contiguous(),
        "scales": pt_sc.contiguous(),
        "rows": padded_cols,
        "cols": rows,
        "payload_scale": float(payload_scale),
        "tile_start": int(tile_start),
        "tile_cols": cols,
        "quant_mode": _normalize_quant_mode_for_backend("mxfp4_v3", quant_mode),
        "strategy_family": strategy_family,
    }


def _quantize_mxfp4_pt_batched_from_logits_tile_for_dv(
    logits_tile: torch.Tensor,
    lse_2d: torch.Tensor,
    *,
    tile_start: int,
    padded_cols: int,
    row_start: int = 0,
    logits_scale: float | None = None,
    payload_scale: float = _SAGEATTN3_FP4_RECON_SCALE,
    quant_mode: str | None = None,
) -> dict[str, Any] | None:
    groups, rows, cols = (int(logits_tile.shape[0]), int(logits_tile.shape[1]), int(logits_tile.shape[2]))
    padded_cols = max(_next_multiple(cols, _TILE), int(padded_cols))
    if rows % _TILE != 0 or padded_cols % _TILE != 0:
        raise ValueError("batched MXFP4 dV P^T quantization requires row and padded column multiples of 128")
    row_start = int(row_start)
    if row_start < 0 or row_start % _TILE != 0:
        raise ValueError("row_start must be a non-negative multiple of 128")
    if tuple(lse_2d.shape) != (groups, rows):
        raise ValueError(f"lse_2d must have shape {(groups, rows)}")
    mod = _load_mxfp4_v3_quant()
    if (
        os.getenv("TK_FA4_DISABLE_FUSED_MXFP4_DV_BATCHED_SOFTMAX_TRANSPOSE_QUANT", "0") not in ("", "0")
        or not (
            hasattr(mod, "mxfp4_softmax_tile_quantize_transpose_batched")
            or hasattr(mod, "mxfp4_softmax_tile_quantize_transpose_batched_bf16_scaled")
        )
    ):
        return None
    with _cuda_device_ctx(logits_tile.device):
        if (
            logits_scale is not None
            and logits_tile.dtype == torch.bfloat16
            and hasattr(mod, "mxfp4_softmax_tile_quantize_transpose_batched_bf16_scaled")
            and os.getenv("TK_FA4_DISABLE_FUSED_MXFP4_DV_BF16_SCALED_P_QUANT", "0") in ("", "0")
        ):
            if row_start and hasattr(mod, "mxfp4_softmax_tile_quantize_transpose_batched_bf16_scaled_offset"):
                pt_fp4, pt_sc = mod.mxfp4_softmax_tile_quantize_transpose_batched_bf16_scaled_offset(
                    logits_tile.contiguous(),
                    lse_2d.float().contiguous(),
                    int(row_start),
                    int(tile_start),
                    int(padded_cols),
                    float(logits_scale),
                    float(payload_scale),
                    _mxfp4_quant_mode_to_int(quant_mode),
                )
            elif row_start:
                return None
            else:
                pt_fp4, pt_sc = mod.mxfp4_softmax_tile_quantize_transpose_batched_bf16_scaled(
                    logits_tile.contiguous(),
                    lse_2d.float().contiguous(),
                    int(tile_start),
                    int(padded_cols),
                    float(logits_scale),
                    float(payload_scale),
                    _mxfp4_quant_mode_to_int(quant_mode),
                )
            strategy_family = "live_mxfp4_batched_bf16_scaled_softmax_transpose_fused_dv"
        else:
            if row_start:
                return None
            work = logits_tile.float()
            if logits_scale is not None:
                work = work.mul(float(logits_scale))
            pt_fp4, pt_sc = mod.mxfp4_softmax_tile_quantize_transpose_batched(
                work.contiguous(),
                lse_2d.float().contiguous(),
                int(tile_start),
                int(padded_cols),
                float(payload_scale),
                _mxfp4_quant_mode_to_int(quant_mode),
            )
            strategy_family = "live_mxfp4_batched_softmax_transpose_fused_dv"
    return {
        "format": "mxfp4_v3",
        "fp4": pt_fp4.contiguous(),
        "scales": pt_sc.contiguous(),
        "groups": groups,
        "rows": padded_cols,
        "cols": rows,
        "payload_scale": float(payload_scale),
        "row_start": int(row_start),
        "tile_start": int(tile_start),
        "tile_cols": cols,
        "quant_mode": _normalize_quant_mode_for_backend("mxfp4_v3", quant_mode),
        "strategy_family": strategy_family,
    }


def _mxfp4_dv_tile_from_prequantized_dout(
    pt_quant: dict[str, Any],
    dout_fp4: torch.Tensor,
    dout_sc: torch.Tensor,
    *,
    dvo: int,
) -> torch.Tensor:
    if str(pt_quant.get("format")) != "mxfp4_v3":
        raise ValueError("MXFP4 dV expects an mxfp4_v3 P^T artifact")
    pt_fp4 = pt_quant["fp4"].unsqueeze(0).unsqueeze(0).contiguous()
    pt_sc = pt_quant["scales"].unsqueeze(0).unsqueeze(0).contiguous()
    dv_scaled = _mxfp4_pv_from_p(
        pt_fp4,
        pt_sc,
        dout_fp4.contiguous(),
        dout_sc.contiguous(),
        output_layout="bhrd",
    )
    scale = float(pt_quant.get("payload_scale", 1.0))
    return (dv_scaled[0, 0, :, :dvo].float() / scale).to(torch.bfloat16).contiguous()


def _bf16_backward_dv_from_logits_2d(
    logits_2d: torch.Tensor,
    dout_2d: torch.Tensor,
    *,
    lse_1d: torch.Tensor | None = None,
) -> torch.Tensor:
    logits = logits_2d.float().contiguous()
    dout = dout_2d.to(torch.bfloat16).contiguous()
    if logits.ndim != 2 or dout.ndim != 2:
        raise ValueError("logits_2d and dout_2d must be rank-2")
    seqlen = int(logits.shape[0])
    if logits.shape[1] != seqlen or int(dout.shape[0]) != seqlen:
        raise ValueError("dV probe expects square logits and matching dO sequence length")
    lse = _require_saved_lse_1d(lse_1d, seqlen=seqlen, name="BF16 dV logits reference")
    row_ids = torch.arange(seqlen, device=logits.device).view(seqlen, 1)
    col_ids = torch.arange(seqlen, device=logits.device).view(1, seqlen)
    p = torch.exp(logits - lse.view(seqlen, 1))
    p = torch.where(col_ids <= row_ids, p, torch.zeros_like(p))
    return torch.matmul(p.transpose(0, 1), dout.float()).to(torch.bfloat16).contiguous()


def _mxfp4_full_backward_reference_from_prequantized_saved_lse(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
    dout: torch.Tensor,
    lse_bhs: torch.Tensor,
    *,
    softmax_scale: float | None = None,
    max_reference_seqlen: int = 2048,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """Slow full MXFP4 backward contract from prequantized forward artifacts.

    This is a correctness/profiling reference, not the fast kernel.  It uses the
    same prequantized Q/K/V tensors and forward-saved LSE expected by the MXFP4
    backward design, then dequantizes and computes full FA backward in PyTorch.
    """
    batch, heads, seqlen = _check_fp4_attention_inputs(q, q_sc, q_sg, k, k_sc, k_sg)
    _check_prequantized_v(v_fp4, v_sc_prepared, batch, heads, seqlen)
    if dout.dtype != torch.bfloat16 or tuple(dout.shape) != (batch, seqlen, heads, _D_VO):
        raise ValueError(f"dout must be BF16 with shape {(batch, seqlen, heads, _D_VO)}")
    if int(seqlen) > int(max_reference_seqlen):
        raise NotImplementedError(
            "slow full-MXFP4 reference is intentionally capped; the fast full MXFP4 dq/dk/dv kernel is not implemented"
        )
    lse = _normalize_mxfp4_dv_lse_bhs(lse_bhs, batch=batch, heads=heads, seqlen=seqlen)
    scale = float(softmax_scale) if softmax_scale is not None else 1.0 / math.sqrt(float(_D_QK))

    q_bf16 = _dequantize_live_fp4_qk_for_debug(q, q_sc, q_sg)
    k_bf16 = _dequantize_live_fp4_qk_for_debug(k, k_sc, k_sg)
    v_bhds = _dequantize_prepared_fp4_rows_for_debug(v_fp4, v_sc_prepared).to(torch.bfloat16)
    v_bf16 = v_bhds.permute(0, 3, 1, 2).contiguous()

    dq = torch.empty((batch, seqlen, heads, _D_QK), dtype=torch.float32, device=q.device)
    dk = torch.empty_like(dq)
    dv = torch.empty((batch, seqlen, heads, _D_VO), dtype=torch.float32, device=q.device)
    row_ids = torch.arange(seqlen, device=q.device).view(seqlen, 1)
    col_ids = torch.arange(seqlen, device=q.device).view(1, seqlen)
    causal_mask = col_ids <= row_ids

    for b in range(batch):
        for h in range(heads):
            q_2d = q_bf16[b, :, h, :].float()
            k_2d = k_bf16[b, :, h, :].float()
            v_2d = v_bf16[b, :, h, :].float()
            do_2d = dout[b, :, h, :].float()
            logits = torch.matmul(q_2d, k_2d.transpose(0, 1)).mul_(scale)
            p = torch.exp(logits - lse[b, h].view(seqlen, 1))
            p = torch.where(causal_mask, p, torch.zeros_like(p))
            dp = torch.matmul(do_2d, v_2d.transpose(0, 1))
            delta = (p * dp).sum(dim=-1, keepdim=True)
            ds = p * (dp - delta)
            dq[b, :, h, :].copy_(torch.matmul(ds, k_2d).mul_(scale))
            dk[b, :, h, :].copy_(torch.matmul(ds.transpose(0, 1), q_2d).mul_(scale))
            dv[b, :, h, :].copy_(torch.matmul(p.transpose(0, 1), do_2d))
    return dq.contiguous(), dk.contiguous(), dv.contiguous()


def _mxfp4_backward_dv_from_logits_2d(
    logits_2d: torch.Tensor,
    dout_2d: torch.Tensor,
    *,
    lse_1d: torch.Tensor | None = None,
    chunk_cols: int | None = None,
    p_payload_scale: float = _SAGEATTN3_FP4_RECON_SCALE,
    p_quant_mode: str | None = None,
    dout_quant_mode: str | None = None,
) -> torch.Tensor:
    logits = logits_2d.float().contiguous()
    dout = dout_2d.to(torch.bfloat16).contiguous()
    if logits.ndim != 2 or dout.ndim != 2:
        raise ValueError("logits_2d and dout_2d must be rank-2")
    seqlen, cols = int(logits.shape[0]), int(logits.shape[1])
    dvo = int(dout.shape[1])
    if cols != seqlen or int(dout.shape[0]) != seqlen:
        raise ValueError("dV probe expects square logits and matching dO sequence length")
    if seqlen % _TILE != 0 or dvo % _TILE != 0:
        raise ValueError("MXFP4 dV probe requires seqlen and dO dim divisible by 128")
    if dvo != _D_VO:
        raise ValueError(f"MXFP4 dV probe is currently wired for dO dim {_D_VO}")
    if chunk_cols is None:
        chunk_cols = min(seqlen, 8192)
    chunk_cols = int(chunk_cols)
    if chunk_cols <= 0 or chunk_cols % _TILE != 0:
        raise ValueError("chunk_cols must be a positive multiple of 128")
    lse = _require_saved_lse_1d(lse_1d, seqlen=seqlen, name="MXFP4 dV logits probe")

    dout_fp4, dout_sc = _mxfp4_quantize_v_for_gemm(
        dout.unsqueeze(0).unsqueeze(2),
        quant_mode=dout_quant_mode,
        pad_dvo_to_256=False,
        pad_scale_rows_for_grouped=True,
    )
    dv = torch.empty((seqlen, dvo), dtype=torch.bfloat16, device=logits.device)
    for tile_start in range(0, seqlen, chunk_cols):
        tile_end = min(tile_start + chunk_cols, seqlen)
        tile_cols = tile_end - tile_start
        padded_tile_cols = _next_multiple(tile_cols, _TILE)
        pt_quant = _quantize_mxfp4_pt_from_logits_tile_for_dv(
            logits[:, tile_start:tile_end],
            lse,
            tile_start=tile_start,
            padded_cols=padded_tile_cols,
            payload_scale=p_payload_scale,
            quant_mode=p_quant_mode,
        )
        dv_tile = _mxfp4_dv_tile_from_prequantized_dout(
            pt_quant,
            dout_fp4,
            dout_sc,
            dvo=dvo,
        )
        dv[tile_start:tile_end].copy_(dv_tile[:tile_cols])
    return dv.contiguous()


def _softmax_tile_stats_from_logits_tile(
    logits_tile: torch.Tensor,
    *,
    tile_start: int,
) -> tuple[torch.Tensor, torch.Tensor]:
    mod = _load_mxfp4_v3_quant()
    if (
        os.getenv("TK_FA4_DISABLE_FUSED_MXFP4_DV_SOFTMAX_STATS", "0") in ("", "0")
        and hasattr(mod, "mxfp4_softmax_tile_stats")
    ):
        with _cuda_device_ctx(logits_tile.device):
            tile_max, tile_sum = mod.mxfp4_softmax_tile_stats(logits_tile.float().contiguous(), int(tile_start))
        return tile_max.contiguous(), tile_sum.contiguous()
    masked = _causal_mask_logits_tile_2d(logits_tile.float(), tile_start=tile_start)
    tile_max = masked.max(dim=-1).values
    exp_tile = torch.exp(masked - tile_max.view(-1, 1))
    exp_tile = torch.where(torch.isfinite(masked), exp_tile, torch.zeros_like(exp_tile))
    return tile_max.contiguous(), exp_tile.sum(dim=-1).contiguous()


def _combine_online_softmax_stats(
    row_max: torch.Tensor,
    row_sum: torch.Tensor,
    tile_max: torch.Tensor,
    tile_sum: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor]:
    new_row_max = torch.maximum(row_max, tile_max)
    old_scale = torch.where(
        torch.isfinite(row_max),
        torch.exp(row_max - new_row_max),
        torch.zeros_like(row_max),
    )
    tile_scale = torch.where(
        torch.isfinite(tile_max),
        torch.exp(tile_max - new_row_max),
        torch.zeros_like(tile_max),
    )
    return new_row_max.contiguous(), (row_sum * old_scale + tile_sum * tile_scale).contiguous()


def _causal_softmax_stats_from_qk_2d(
    q_2d: torch.Tensor,
    k_2d: torch.Tensor,
    *,
    softmax_scale: float | None = None,
    chunk_cols: int | None = None,
) -> tuple[torch.Tensor, torch.Tensor]:
    q = q_2d.to(torch.bfloat16).contiguous()
    k = k_2d.to(torch.bfloat16).contiguous()
    if q.ndim != 2 or k.ndim != 2:
        raise ValueError("q_2d and k_2d must be rank-2")
    if q.shape != k.shape:
        raise ValueError("q_2d and k_2d must have the same shape")
    seqlen, dim = int(q.shape[0]), int(q.shape[1])
    if dim != _D_QK:
        raise ValueError(f"Q/K head dim must be {_D_QK}")
    if seqlen % _TILE != 0:
        raise ValueError("streaming softmax stats require seqlen divisible by 128")
    if chunk_cols is None:
        chunk_cols = min(seqlen, 8192)
    chunk_cols = int(chunk_cols)
    if chunk_cols <= 0 or chunk_cols % _TILE != 0:
        raise ValueError("chunk_cols must be a positive multiple of 128")
    scale = float(softmax_scale) if softmax_scale is not None else 1.0 / math.sqrt(float(_D_QK))
    row_max = torch.full((seqlen,), float("-inf"), dtype=torch.float32, device=q.device)
    row_sum = torch.zeros((seqlen,), dtype=torch.float32, device=q.device)
    for tile_start in range(0, seqlen, chunk_cols):
        tile_end = min(tile_start + chunk_cols, seqlen)
        logits_tile = torch.matmul(q, k[tile_start:tile_end].transpose(0, 1)).float().mul_(scale).contiguous()
        tile_max, tile_sum = _softmax_tile_stats_from_logits_tile(logits_tile, tile_start=tile_start)
        row_max, row_sum = _combine_online_softmax_stats(row_max, row_sum, tile_max, tile_sum)
    return row_max.contiguous(), row_sum.contiguous()


def _causal_lse_from_qk_2d(
    q_2d: torch.Tensor,
    k_2d: torch.Tensor,
    *,
    softmax_scale: float | None = None,
    chunk_cols: int | None = None,
) -> torch.Tensor:
    row_max, row_sum = _causal_softmax_stats_from_qk_2d(
        q_2d,
        k_2d,
        softmax_scale=softmax_scale,
        chunk_cols=chunk_cols,
    )
    tiny = torch.finfo(torch.float32).tiny
    return torch.where(row_sum > 0, row_max + torch.log(row_sum.clamp_min(tiny)), torch.full_like(row_sum, float("-inf"))).contiguous()


def _mxfp4_backward_dv_from_qk_2d(
    q_2d: torch.Tensor,
    k_2d: torch.Tensor,
    dout_2d: torch.Tensor,
    *,
    softmax_scale: float | None = None,
    lse_1d: torch.Tensor | None = None,
    chunk_cols: int | None = None,
    p_payload_scale: float = _SAGEATTN3_FP4_RECON_SCALE,
    p_quant_mode: str | None = None,
    dout_quant_mode: str | None = None,
) -> torch.Tensor:
    q = q_2d.to(torch.bfloat16).contiguous()
    k = k_2d.to(torch.bfloat16).contiguous()
    dout = dout_2d.to(torch.bfloat16).contiguous()
    if q.ndim != 2 or k.ndim != 2 or dout.ndim != 2:
        raise ValueError("q_2d, k_2d and dout_2d must be rank-2")
    if q.shape != k.shape:
        raise ValueError("q_2d and k_2d must have the same shape")
    seqlen, dim = int(q.shape[0]), int(q.shape[1])
    dvo = int(dout.shape[1])
    if dim != _D_QK:
        raise ValueError(f"Q/K head dim must be {_D_QK}")
    if int(dout.shape[0]) != seqlen or dvo != _D_VO:
        raise ValueError(f"dout_2d must have shape (seqlen, {_D_VO})")
    if seqlen % _TILE != 0:
        raise ValueError("MXFP4 streaming dV requires seqlen divisible by 128")
    if chunk_cols is None:
        chunk_cols = min(seqlen, 8192)
    chunk_cols = int(chunk_cols)
    if chunk_cols <= 0 or chunk_cols % _TILE != 0:
        raise ValueError("chunk_cols must be a positive multiple of 128")
    scale = float(softmax_scale) if softmax_scale is not None else 1.0 / math.sqrt(float(_D_QK))
    lse = _require_saved_lse_1d(lse_1d, seqlen=seqlen, name="MXFP4 dV QK probe")

    dout_fp4, dout_sc = _mxfp4_quantize_v_for_gemm(
        dout.unsqueeze(0).unsqueeze(2),
        quant_mode=dout_quant_mode,
        pad_dvo_to_256=False,
        pad_scale_rows_for_grouped=True,
    )
    dv = torch.empty((seqlen, dvo), dtype=torch.bfloat16, device=q.device)
    for tile_start in range(0, seqlen, chunk_cols):
        tile_end = min(tile_start + chunk_cols, seqlen)
        logits_tile = torch.matmul(q, k[tile_start:tile_end].transpose(0, 1)).float().mul_(scale).contiguous()
        pt_quant = _quantize_mxfp4_pt_from_logits_tile_for_dv(
            logits_tile,
            lse,
            tile_start=tile_start,
            padded_cols=tile_end - tile_start,
            payload_scale=p_payload_scale,
            quant_mode=p_quant_mode,
        )
        dv_tile = _mxfp4_dv_tile_from_prequantized_dout(
            pt_quant,
            dout_fp4,
            dout_sc,
            dvo=dvo,
        )
        dv[tile_start:tile_end].copy_(dv_tile[: tile_end - tile_start])
    return dv.contiguous()


def _mxfp4_backward_dv_from_qk_grouped(
    q_bf16: torch.Tensor,
    k_bf16: torch.Tensor,
    dout_bf16: torch.Tensor,
    *,
    softmax_scale: float | None = None,
    lse_bhs: torch.Tensor | None = None,
    chunk_cols: int | None = None,
    p_payload_scale: float = _SAGEATTN3_FP4_RECON_SCALE,
    p_quant_mode: str | None = None,
    dout_quant_mode: str | None = None,
) -> torch.Tensor:
    batch, seqlen, heads = _check_bf16_exact_qkv_inputs(q_bf16, k_bf16, dout_bf16)
    num_gemms = batch * heads
    if chunk_cols is None:
        chunk_cols = _mxfp4_grouped_dv_default_chunk_cols(seqlen, num_gemms)
    chunk_cols = int(chunk_cols)
    if chunk_cols <= 0 or chunk_cols % _TILE != 0:
        raise ValueError("chunk_cols must be a positive multiple of 128")
    scale = float(softmax_scale) if softmax_scale is not None else 1.0 / math.sqrt(float(_D_QK))
    device = q_bf16.device

    lse = _require_saved_mxfp4_dv_lse_bhs(
        lse_bhs,
        batch=batch,
        heads=heads,
        seqlen=seqlen,
        name="MXFP4 grouped dV probe",
    )

    dout_fp4, dout_sc = _mxfp4_quantize_dout_for_dv_gemm_grouped(
        dout_bf16.to(torch.bfloat16).contiguous(),
        quant_mode=dout_quant_mode,
        pad_scale_rows_for_grouped=True,
    )
    dv_bhrd = torch.empty((batch, heads, seqlen, _D_VO), dtype=torch.bfloat16, device=device)
    grouped_q = None
    grouped_k = None
    grouped_lse = None
    if lse is not None:
        grouped_q = q_bf16.to(torch.bfloat16).permute(0, 2, 1, 3).contiguous().view(batch * heads, seqlen, _D_QK)
        grouped_k = k_bf16.to(torch.bfloat16).permute(0, 2, 1, 3).contiguous().view(batch * heads, seqlen, _D_QK)
        grouped_lse = lse.contiguous().view(batch * heads, seqlen)
    use_causal_suffix = (
        grouped_lse is not None
        and grouped_q is not None
        and grouped_k is not None
        and num_gemms > 1
        and os.getenv("TK_FA4_DISABLE_FUSED_MXFP4_DV_CAUSAL_SUFFIX", "0") in ("", "0")
        and _tk_mxfp4_grouped_gemm_supports_k_offset()
    )
    for tile_start in range(0, seqlen, chunk_cols):
        tile_end = min(tile_start + chunk_cols, seqlen)
        tile_cols = tile_end - tile_start
        row_start = 0
        p_fp4: torch.Tensor
        p_sc: torch.Tensor
        dout_k_offset = 0
        batched_pt_quant = None
        if grouped_lse is not None and grouped_q is not None and grouped_k is not None:
            if use_causal_suffix and tile_start > 0:
                row_start = tile_start
                dout_k_offset = row_start
            logits_tile_batched = torch.bmm(
                grouped_q[:, row_start:, :],
                grouped_k[:, tile_start:tile_end, :].transpose(1, 2),
            ).contiguous()
            batched_pt_quant = _quantize_mxfp4_pt_batched_from_logits_tile_for_dv(
                logits_tile_batched,
                grouped_lse[:, row_start:].contiguous(),
                tile_start=tile_start,
                padded_cols=tile_cols,
                row_start=row_start,
                logits_scale=scale,
                payload_scale=p_payload_scale,
                quant_mode=p_quant_mode,
            )
        if batched_pt_quant is not None:
            tile_k_cols = seqlen - row_start
            p_fp4 = batched_pt_quant["fp4"].contiguous().view(batch, heads, tile_cols, tile_k_cols // 2)
            p_sc = batched_pt_quant["scales"].contiguous().view(batch, heads, tile_cols // _TILE, tile_k_cols // _TILE, 32, 16)
        else:
            row_start = 0
            dout_k_offset = 0
            p_fp4 = torch.empty(
                (batch, heads, tile_cols, seqlen // 2),
                dtype=torch.float4_e2m1fn_x2,
                device=device,
            )
            p_sc = torch.empty(
                (batch, heads, tile_cols // _TILE, seqlen // _TILE, 32, 16),
                dtype=torch.uint8,
                device=device,
            )
            for b in range(batch):
                for h in range(heads):
                    logits_tile = torch.matmul(
                        q_bf16[b, :, h, :].to(torch.bfloat16),
                        k_bf16[b, tile_start:tile_end, h, :].to(torch.bfloat16).transpose(0, 1),
                    ).float().mul_(scale).contiguous()
                    pt_quant = _quantize_mxfp4_pt_from_logits_tile_for_dv(
                        logits_tile,
                        None if lse is None else lse[b, h],
                        tile_start=tile_start,
                        padded_cols=tile_cols,
                        payload_scale=p_payload_scale,
                        quant_mode=p_quant_mode,
                    )
                    _copy_fp4_tensor_(p_fp4[b, h], pt_quant["fp4"])
                    p_sc[b, h].copy_(pt_quant["scales"])
        dv_tile = _mxfp4_pv_from_p(
            p_fp4.contiguous(),
            p_sc.contiguous(),
            dout_fp4,
            dout_sc,
            output_layout="bhrd",
            v_k_offset=dout_k_offset,
        )
        dv_bhrd[:, :, tile_start:tile_end, :].copy_((dv_tile[:, :, :tile_cols, :_D_VO].float() / float(p_payload_scale)).to(torch.bfloat16))
    return dv_bhrd.permute(0, 2, 1, 3).contiguous()


def run_fp4_backward_dv_streaming_live_probe(
    q_bf16: torch.Tensor,
    k_bf16: torch.Tensor,
    dout_bf16: torch.Tensor,
    *,
    softmax_scale: float | None = None,
    lse_bhs: torch.Tensor | None = None,
    qk_quant_backend: str = "v5",
    dout_quant_backend: str = "mxfp4",
    launch_mode: str = "auto",
    compare_reference: bool = True,
    max_reference_seqlen: int = 4096,
    timeout_ms: float | None = _CUDA_EVENT_TIMEOUT_MS,
) -> dict[str, Any]:
    _require_streaming_live_localcta_enabled()
    _check_choice("qk_quant_backend", qk_quant_backend, _LIVE_QK_QUANT_BACKENDS)
    _check_choice("dout_quant_backend", dout_quant_backend, _LIVE_V_QUANT_BACKENDS)
    batch, seqlen, heads = _check_bf16_exact_qkv_inputs(q_bf16, k_bf16, dout_bf16)
    effective_launch_mode = _resolve_streaming_live_dv_launch_mode(launch_mode, batch, heads, seqlen)
    if softmax_scale is not None and not math.isclose(float(softmax_scale), 1.0 / math.sqrt(float(_D_QK)), rel_tol=0.0, abs_tol=1e-12):
        raise ValueError("the fused TK dV path currently uses the kernel's built-in 1/sqrt(Dqk) scale")
    lse = _require_saved_mxfp4_dv_lse_bhs(
        lse_bhs,
        batch=batch,
        heads=heads,
        seqlen=seqlen,
        name="FP4 streaming-live dV probe",
    )
    lse_ms = 0.0

    q, q_sc, q_sg, k, k_sc, k_sg, dout_fp4, dout_sc = _fp4_inputs_from_bf16_source(
        q_bf16,
        k_bf16,
        dout_bf16,
        qk_quant_backend=qk_quant_backend,
        v_quant_backend=dout_quant_backend,
    )

    fp4, fp4_ms = _run_with_ms(
        _run_backward_dv_streaming_live_localcta,
        q,
        q_sc,
        q_sg,
        k,
        k_sc,
        k_sg,
        dout_fp4,
        dout_sc,
        lse,
        launch_mode=effective_launch_mode,
        timeout_ms=timeout_ms,
    )
    out: dict[str, Any] = {
        "batch": int(batch),
        "heads": int(heads),
        "seqlen": int(seqlen),
        "dvo": int(_D_VO),
        "fp4_streaming_live_dv_ms": float(fp4_ms),
        "diagnostic_recomputed_lse_ms": float(lse_ms),
        "lse_ms": float(lse_ms),
        "launch_mode": str(effective_launch_mode),
        "requested_launch_mode": str(launch_mode),
        "qk_quant_backend": str(qk_quant_backend),
        "dout_quant_backend": str(dout_quant_backend),
        "uses_external_lse": True,
        "saved_lse_required": True,
        "lse_source": "external_saved_forward",
        "finite": bool(torch.isfinite(fp4).all().item()),
    }
    if compare_reference and seqlen <= int(max_reference_seqlen):
        ref = torch.empty_like(fp4)
        scale = 1.0 / math.sqrt(float(_D_QK))
        for b in range(batch):
            for h in range(heads):
                logits = torch.matmul(
                    q_bf16[b, :, h, :].float(),
                    k_bf16[b, :, h, :].float().transpose(0, 1),
                ).mul_(scale).contiguous()
                ref[b, :, h, :].copy_(
                    _bf16_backward_dv_from_logits_2d(
                        logits,
                        dout_bf16[b, :, h, :],
                        lse_1d=lse[b, h].contiguous(),
                    )
                )
        diff = (fp4.float() - ref.float()).abs()
        out["max_abs_diff"] = float(diff.max().item())
        out["mean_abs_diff"] = float(diff.mean().item())
        out["reference_lse_source"] = "external_saved_forward"
    return out


def run_fp4_backward_dv_streaming_live_mxfp4_probe(
    q_bf16: torch.Tensor,
    k_bf16: torch.Tensor,
    dout_bf16: torch.Tensor,
    *,
    softmax_scale: float | None = None,
    lse_bhs: torch.Tensor | None = None,
    qk_quant_backend: str = "v5",
    p_payload_scale: float = _SAGEATTN3_FP4_RECON_SCALE,
    p_quant_mode: str | None = None,
    dout_quant_mode: str | None = None,
    pv_issue_mode: int | str | None = "auto",
    launch_mode: str = "auto",
    compare_reference: bool = True,
    max_reference_seqlen: int = 4096,
    timeout_ms: float | None = _CUDA_EVENT_TIMEOUT_MS,
) -> dict[str, Any]:
    _require_streaming_live_localcta_enabled()
    _check_choice("qk_quant_backend", qk_quant_backend, _LIVE_QK_QUANT_BACKENDS)
    batch, seqlen, heads = _check_bf16_exact_qkv_inputs(q_bf16, k_bf16, dout_bf16)
    head_chunk_size = heads
    requested_pv_issue_mode = pv_issue_mode
    use_rewrite_entrypoint = _use_mxfp4_dv_rewrite_entrypoint(pv_issue_mode)
    pv_issue_mode = _resolve_mxfp4_dv_pv_issue_mode(pv_issue_mode, seqlen)
    launch_pv_issue_mode = "rewrite" if use_rewrite_entrypoint else pv_issue_mode
    effective_launch_mode = _resolve_streaming_live_dv_launch_mode(launch_mode, batch, heads, seqlen)
    if effective_launch_mode == "fullgrid":
        head_chunk_size = _mxfp4_dv_fullgrid_head_chunk_size(batch, heads, seqlen)
    head_chunks = (heads + head_chunk_size - 1) // head_chunk_size
    if softmax_scale is not None and not math.isclose(float(softmax_scale), 1.0 / math.sqrt(float(_D_QK)), rel_tol=0.0, abs_tol=1e-12):
        raise ValueError("the fused TK dV path currently uses the kernel's built-in 1/sqrt(Dqk) scale")
    lse = _require_saved_mxfp4_dv_lse_bhs(
        lse_bhs,
        batch=batch,
        heads=heads,
        seqlen=seqlen,
        name="MXFP4 streaming-live dV probe",
    )
    lse_ms = 0.0

    q, q_sc, q_sg, k, k_sc, k_sg = _fp4_qk_inputs_from_bf16_source(
        q_bf16,
        k_bf16,
        qk_quant_backend=qk_quant_backend,
    )
    dout_fp4, dout_sc = _mxfp4_quantize_dout_for_dv_gemm_grouped(
        dout_bf16.to(torch.bfloat16).contiguous(),
        quant_mode=dout_quant_mode,
        pad_scale_rows_for_grouped=True,
    )
    if head_chunks == 1:
        k_as_q_sc, q_as_k_sc = _prepare_mxfp4_dv_qk_scales(
            q_sc,
            k_sc,
            batch=batch,
            heads=heads,
            seqlen=seqlen,
        )

    if head_chunks > 1:
        fp4, fp4_ms = _run_backward_dv_streaming_live_mxfp4_chunked_by_head_timed(
            q,
            q_sc,
            q_sg,
            k,
            k_sc,
            k_sg,
            dout_fp4,
            dout_sc,
            lse,
            launch_mode=effective_launch_mode,
            p_payload_scale=p_payload_scale,
            p_quant_mode=p_quant_mode,
            pv_issue_mode=launch_pv_issue_mode,
            head_chunk_size=head_chunk_size,
            timeout_ms=timeout_ms,
        )
    else:
        fp4, fp4_ms = _run_with_ms(
            _run_backward_dv_streaming_live_mxfp4_prepared_scales,
            q,
            q_sg,
            k,
            k_sg,
            k_as_q_sc,
            q_as_k_sc,
            dout_fp4,
            dout_sc,
            lse,
            launch_mode=effective_launch_mode,
            p_payload_scale=p_payload_scale,
            p_quant_mode=p_quant_mode,
            pv_issue_mode=launch_pv_issue_mode,
            timeout_ms=timeout_ms,
        )
    out: dict[str, Any] = {
        "batch": int(batch),
        "heads": int(heads),
        "seqlen": int(seqlen),
        "dvo": int(_D_VO),
        "fp4_streaming_live_mxfp4_dv_ms": float(fp4_ms),
        "diagnostic_recomputed_lse_ms": float(lse_ms),
        "lse_ms": float(lse_ms),
        "launch_mode": str(effective_launch_mode),
        "requested_launch_mode": str(launch_mode),
        "head_chunk_size": int(head_chunk_size),
        "head_chunks": int(head_chunks),
        "bids_per_launch": int(_streaming_total_bids(batch, head_chunk_size, seqlen)),
        "qk_quant_backend": str(qk_quant_backend),
        "p_payload_scale": float(p_payload_scale),
        "p_quant_mode": _normalize_quant_mode_for_backend("mxfp4_v3", p_quant_mode),
        "dout_quant_mode": _normalize_quant_mode_for_backend("mxfp4_v3", dout_quant_mode),
        "requested_pv_issue_mode": requested_pv_issue_mode,
        "pv_issue_mode": int(pv_issue_mode),
        "rewrite_entrypoint": bool(use_rewrite_entrypoint),
        "uses_external_lse": True,
        "saved_lse_required": True,
        "lse_source": "external_saved_forward",
        "assumes_prepared_dv_qk_scales": True,
        "finite": bool(torch.isfinite(fp4).all().item()),
    }
    if compare_reference and seqlen <= int(max_reference_seqlen):
        ref = torch.empty_like(fp4)
        scale = 1.0 / math.sqrt(float(_D_QK))
        for b in range(batch):
            for h in range(heads):
                logits = torch.matmul(
                    q_bf16[b, :, h, :].float(),
                    k_bf16[b, :, h, :].float().transpose(0, 1),
                ).mul_(scale).contiguous()
                ref[b, :, h, :].copy_(
                    _bf16_backward_dv_from_logits_2d(
                        logits,
                        dout_bf16[b, :, h, :],
                        lse_1d=lse[b, h].contiguous(),
                    )
                )
        diff = (fp4.float() - ref.float()).abs()
        out["max_abs_diff"] = float(diff.max().item())
        out["mean_abs_diff"] = float(diff.mean().item())
        out["reference_lse_source"] = "external_saved_forward"
    return out


def benchmark_mxfp4_backward_dv_vs_bf16(
    *,
    seqlens: tuple[int, ...] = (2048, 4096, 8192, 16384),
    seed: int = 0,
    warmup: int = 2,
    iters: int = 5,
    batch: int = 1,
    heads: int = 16,
    device: str | torch.device = "cuda",
    qk_quant_backend: str = "v5",
    p_payload_scale: float = _SAGEATTN3_FP4_RECON_SCALE,
    p_quant_mode: str | None = None,
    dout_quant_mode: str | None = None,
    pv_issue_mode: int | str | None = "auto",
    launch_mode: str = "auto",
    bf16_launch_mode: str = "auto",
    compare_reference: bool = True,
    max_reference_seqlen: int = 4096,
    timeout_ms: float | None = _CUDA_EVENT_TIMEOUT_MS,
) -> list[dict[str, Any]]:
    if warmup < 0:
        raise ValueError("warmup must be >= 0")
    if iters < 1:
        raise ValueError("iters must be >= 1")
    _check_choice("qk_quant_backend", qk_quant_backend, _LIVE_QK_QUANT_BACKENDS)
    if bf16_launch_mode not in ("auto", "persistent", "fullgrid"):
        raise ValueError("bf16_launch_mode must be 'auto', 'persistent', or 'fullgrid'")
    if launch_mode not in ("auto", "persistent", "fullgrid"):
        raise ValueError("launch_mode must be 'auto', 'persistent', or 'fullgrid'")
    requested_pv_issue_mode = pv_issue_mode

    resolved_device = _benchmark_cuda_preflight(device, what="benchmark_mxfp4_backward_dv_vs_bf16")
    rows: list[dict[str, Any]] = []
    for seqlen in seqlens:
        inputs = make_paired_bf16_fp4_attention_inputs(
            int(seqlen),
            batch=batch,
            heads=heads,
            seed=seed + int(seqlen),
            device=resolved_device,
            qk_quant_backend=qk_quant_backend,
            v_quant_backend="localcta",
        )
        q_bf16, k_bf16, dout_bf16 = inputs["bf16"]
        batch_i, seqlen_i, heads_i = _check_bf16_exact_qkv_inputs(q_bf16, k_bf16, dout_bf16)
        use_rewrite_entrypoint = _use_mxfp4_dv_rewrite_entrypoint(requested_pv_issue_mode)
        resolved_pv_issue_mode = _resolve_mxfp4_dv_pv_issue_mode(requested_pv_issue_mode, seqlen_i)
        launch_pv_issue_mode = "rewrite" if use_rewrite_entrypoint else resolved_pv_issue_mode
        effective_launch_mode = _resolve_streaming_live_dv_launch_mode(launch_mode, batch_i, heads_i, seqlen_i)
        head_chunk_size = heads_i
        if effective_launch_mode == "fullgrid":
            head_chunk_size = _mxfp4_dv_fullgrid_head_chunk_size(batch_i, heads_i, seqlen_i)
        head_chunks = (heads_i + head_chunk_size - 1) // head_chunk_size
        bids_per_launch = _streaming_total_bids(batch_i, head_chunk_size, seqlen_i)

        q, q_sc, q_sg, k, k_sc, k_sg, forward_v_fp4, forward_v_sc_prepared = inputs["fp4"]
        dout_fp4, dout_sc = _mxfp4_quantize_dout_for_dv_gemm_grouped(
            dout_bf16.to(torch.bfloat16).contiguous(),
            quant_mode=dout_quant_mode,
            pad_scale_rows_for_grouped=True,
        )
        if head_chunks == 1:
            k_as_q_sc, q_as_k_sc = _prepare_mxfp4_dv_qk_scales(
                q_sc,
                k_sc,
                batch=batch_i,
                heads=heads_i,
                seqlen=seqlen_i,
            )
        (_, lse), forward_saved_lse_ms = _run_with_ms(
            _run_fp4pv_baseline,
            q,
            q_sc,
            q_sg,
            k,
            k_sc,
            k_sg,
            forward_v_fp4,
            forward_v_sc_prepared,
            timeout_ms=timeout_ms,
        )
        lse = _normalize_mxfp4_dv_lse_bhs(lse, batch=batch_i, heads=heads_i, seqlen=seqlen_i)

        bf16_samples: list[float] = []
        for _ in range(int(warmup)):
            run_bf16_causal_baseline(
                q_bf16,
                k_bf16,
                dout_bf16,
                launch_mode=bf16_launch_mode,
                timeout_ms=timeout_ms,
            )
        bf16_record: dict[str, Any] | None = None
        for _ in range(int(iters)):
            bf16_record = run_bf16_causal_baseline(
                q_bf16,
                k_bf16,
                dout_bf16,
                launch_mode=bf16_launch_mode,
                timeout_ms=timeout_ms,
            )
            bf16_samples.append(float(bf16_record["timing_ms"]))
        assert bf16_record is not None

        dv_samples: list[float] = []
        fp4_out: torch.Tensor | None = None
        dv_warmup = int(warmup)
        dv_iters = int(iters)
        for _ in range(dv_warmup):
            if head_chunks > 1:
                _run_backward_dv_streaming_live_mxfp4_chunked_by_head_timed(
                    q,
                    q_sc,
                    q_sg,
                    k,
                    k_sc,
                    k_sg,
                    dout_fp4,
                    dout_sc,
                    lse,
                    launch_mode=effective_launch_mode,
                    p_payload_scale=p_payload_scale,
                    p_quant_mode=p_quant_mode,
                    pv_issue_mode=launch_pv_issue_mode,
                    head_chunk_size=head_chunk_size,
                    timeout_ms=timeout_ms,
                )
            else:
                _run_with_ms(
                    _run_backward_dv_streaming_live_mxfp4_prepared_scales,
                    q,
                    q_sg,
                    k,
                    k_sg,
                    k_as_q_sc,
                    q_as_k_sc,
                    dout_fp4,
                    dout_sc,
                    lse,
                    launch_mode=effective_launch_mode,
                    p_payload_scale=p_payload_scale,
                    p_quant_mode=p_quant_mode,
                    pv_issue_mode=launch_pv_issue_mode,
                    timeout_ms=timeout_ms,
                )
        for _ in range(dv_iters):
            if head_chunks > 1:
                fp4_out, dv_ms = _run_backward_dv_streaming_live_mxfp4_chunked_by_head_timed(
                    q,
                    q_sc,
                    q_sg,
                    k,
                    k_sc,
                    k_sg,
                    dout_fp4,
                    dout_sc,
                    lse,
                    launch_mode=effective_launch_mode,
                    p_payload_scale=p_payload_scale,
                    p_quant_mode=p_quant_mode,
                    pv_issue_mode=launch_pv_issue_mode,
                    head_chunk_size=head_chunk_size,
                    timeout_ms=timeout_ms,
                )
            else:
                fp4_out, dv_ms = _run_with_ms(
                    _run_backward_dv_streaming_live_mxfp4_prepared_scales,
                    q,
                    q_sg,
                    k,
                    k_sg,
                    k_as_q_sc,
                    q_as_k_sc,
                    dout_fp4,
                    dout_sc,
                    lse,
                    launch_mode=effective_launch_mode,
                    p_payload_scale=p_payload_scale,
                    p_quant_mode=p_quant_mode,
                    pv_issue_mode=launch_pv_issue_mode,
                    timeout_ms=timeout_ms,
                )
            dv_samples.append(float(dv_ms))

        bf16_ms = _median(bf16_samples)
        lse_ms = 0.0
        dv_ms = _median(dv_samples)
        total_ms = dv_ms
        row: dict[str, Any] = {
            "seqlen": int(seqlen_i),
            "batch": int(batch_i),
            "heads": int(heads_i),
            "qk_quant_backend": str(qk_quant_backend),
            "p_payload_scale": float(p_payload_scale),
            "p_quant_mode": _normalize_quant_mode_for_backend("mxfp4_v3", p_quant_mode),
            "dout_quant_mode": _normalize_quant_mode_for_backend("mxfp4_v3", dout_quant_mode),
            "requested_pv_issue_mode": requested_pv_issue_mode,
            "pv_issue_mode": int(resolved_pv_issue_mode),
            "rewrite_entrypoint": bool(use_rewrite_entrypoint),
            "launch_mode": str(effective_launch_mode),
            "requested_launch_mode": str(launch_mode),
            "head_chunk_size": int(head_chunk_size),
            "head_chunks": int(head_chunks),
            "bids_per_launch": int(bids_per_launch),
            "bf16_launch_mode": str(bf16_record["launch_mode"]),
            "bf16_fa4_ms": float(bf16_ms),
            "bf16_fa4_timing_role": "forward_proxy_not_backward",
            "comparison_note": (
                "bf16_fa4_ms is the historical FA4 forward proxy, not true BF16 backward; "
                "use benchmark_mxfp4_dv_vs_true_fused_bf16_backward for the real backward comparison."
            ),
            "assumes_prequantized_inputs": True,
            "assumes_prepared_dv_qk_scales": True,
            "assumes_saved_lse": True,
            "saved_lse_required": True,
            "lse_source": "fp4_forward_saved_lse",
            "mxfp4_total_definition": "saved_forward_lse_dv_only",
            "diagnostic_recomputed_lse_ms": float(lse_ms),
            "mxfp4_lse_setup_ms": float(lse_ms),
            "mxfp4_qk_lse_ms": float(lse_ms),
            "fp4_forward_saved_lse_ms": float(forward_saved_lse_ms),
            "mxfp4_dv_ms": float(dv_ms),
            "mxfp4_total_ms": float(total_ms),
            "diagnostic_mxfp4_with_recomputed_lse_ms": float("nan"),
            "mxfp4_with_lse_sidecar_ms": float("nan"),
            "ratio_mxfp4_total_vs_bf16_fa4": float(total_ms / bf16_ms) if bf16_ms > 0 else float("nan"),
            "ratio_mxfp4_dv_vs_bf16_fa4": float(dv_ms / bf16_ms) if bf16_ms > 0 else float("nan"),
            "ratio_mxfp4_with_lse_sidecar_vs_bf16_fa4": float("nan"),
            "bf16_samples_ms": bf16_samples,
            "mxfp4_qk_lse_samples_ms": [],
            "fp4_forward_saved_lse_samples_ms": [float(forward_saved_lse_ms)],
            "mxfp4_dv_samples_ms": dv_samples,
            "mxfp4_dv_warmup": int(dv_warmup),
            "mxfp4_dv_iters": int(dv_iters),
            "finite": bool(fp4_out is not None and torch.isfinite(fp4_out).all().item()),
        }

        if compare_reference and seqlen_i <= int(max_reference_seqlen) and fp4_out is not None:
            ref = torch.empty_like(fp4_out)
            scale = 1.0 / math.sqrt(float(_D_QK))
            for b in range(batch_i):
                for h in range(heads_i):
                    logits = torch.matmul(
                        q_bf16[b, :, h, :].float(),
                        k_bf16[b, :, h, :].float().transpose(0, 1),
                    ).mul_(scale).contiguous()
                    ref[b, :, h, :].copy_(
                        _bf16_backward_dv_from_logits_2d(
                            logits,
                            dout_bf16[b, :, h, :],
                            lse_1d=lse[b, h].contiguous(),
                        )
                    )
            diff = (fp4_out.float() - ref.float()).abs()
            row["max_abs_diff_vs_bf16_dv_reference"] = float(diff.max().item())
            row["mean_abs_diff_vs_bf16_dv_reference"] = float(diff.mean().item())
            row["reference_lse_source"] = "fp4_forward_saved_lse"
        rows.append(row)
    return rows


def _run_bf16_true_fused_backward_once(
    q: torch.Tensor,
    k: torch.Tensor,
    v: torch.Tensor,
    out: torch.Tensor,
    lse: torch.Tensor,
    dout: torch.Tensor,
    *,
    implementation: str = "hot",
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    try:
        from .interface import b300_mha_bwd_experimental
    except ImportError:
        from tk_fa4.interface import b300_mha_bwd_experimental

    return b300_mha_bwd_experimental(
        q,
        k,
        v,
        out,
        lse,
        dout,
        causal=True,
        deterministic=False,
        implementation=implementation,
    )


def _load_local_cute_interface() -> Any:
    flash_root = _ROOT.parent / "flash-attention"
    if flash_root.exists():
        flash_root_s = str(flash_root)
        if flash_root_s not in sys.path:
            sys.path.insert(0, flash_root_s)
    return importlib.import_module("flash_attn.cute.interface")


def _run_cute_dsl_fa4_bf16_forward_once(
    q: torch.Tensor,
    k: torch.Tensor,
    v: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor]:
    cute_interface = _load_local_cute_interface()
    return cute_interface.flash_attn_func(q, k, v, causal=True, return_lse=True)


def _run_cute_dsl_fa4_bf16_backward_once(
    q: torch.Tensor,
    k: torch.Tensor,
    v: torch.Tensor,
    out: torch.Tensor,
    lse_raw: torch.Tensor,
    dout: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    cute_interface = _load_local_cute_interface()
    return cute_interface._flash_attn_bwd(
        q,
        k,
        v,
        out,
        dout,
        lse_raw,
        causal=True,
        deterministic=False,
    )


def _run_mxfp4_full_backward_direct_once(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
    out: torch.Tensor,
    lse_bhs: torch.Tensor,
    dout: torch.Tensor,
    *,
    softmax_scale: float | None = None,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """Removed scalar-dequantizing full-backward path.

    This entrypoint used prequantized MXFP4 tensors only as compressed storage,
    unpacked Q/K/V with scalar scale multiplies, and then ran a BF16/float
    backward. It is intentionally disabled so benchmarks cannot report it as a
    true MXFP4 tensorcore FlashAttention backward.
    """
    raise NotImplementedError(
        "backward_full_mxfp4_direct is disabled because it scalar-dequantized "
        "prequantized MXFP4 Q/K/V; build a true MXFP4 tensorcore backward path instead."
    )


def _run_mxfp4_full_backward_tile_staged_once(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
    out: torch.Tensor,
    lse_bhs: torch.Tensor,
    dout: torch.Tensor,
    *,
    softmax_scale: float | None = None,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """Removed scalar-dequantizing full-backward path.

    This entrypoint staged Q/K/V as BF16 tiles before the backward math. It is
    intentionally disabled so benchmarks cannot report it as a true MXFP4
    tensorcore FlashAttention backward.
    """
    raise NotImplementedError(
        "backward_full_mxfp4_tile_staged is disabled because it scalar-dequantized "
        "prequantized MXFP4 Q/K/V into BF16 shared tiles; build a true MXFP4 "
        "tensorcore backward path instead."
    )


def _fp4_scale_dtypes() -> tuple[torch.dtype, ...]:
    dtypes = [torch.float8_e4m3fn]
    e8m0 = getattr(torch, "float8_e8m0fnu", None)
    if e8m0 is not None:
        dtypes.append(e8m0)
    return tuple(dtypes)


def _check_mxfp4_column_artifact(
    packed: torch.Tensor,
    scale: torch.Tensor,
    *,
    name: str,
    batch: int,
    heads: int,
    seqlen: int,
) -> None:
    _check_cuda_contiguous(packed, f"{name}_packed")
    _check_cuda_contiguous(scale, f"{name}_scale")
    if packed.dtype != torch.float4_e2m1fn_x2:
        raise ValueError(f"{name}_packed must be saved prequantized torch.float4_e2m1fn_x2")
    if scale.dtype not in _fp4_scale_dtypes():
        raise ValueError(f"{name}_scale must be saved FP8 block scales, got {scale.dtype}")
    if packed.ndim != 4:
        raise ValueError(f"{name}_packed must be rank-4")
    allowed_packed_shapes = {
        (batch, _D_QK, heads, seqlen // 2),
        (batch, heads, _D_QK, seqlen // 2),
    }
    if tuple(packed.shape) not in allowed_packed_shapes:
        raise ValueError(
            f"{name}_packed must use a saved column layout shaped like "
            f"(B,D,H,S/2) or (B,H,D,S/2); got {tuple(packed.shape)}"
        )
    if scale.ndim != 4:
        raise ValueError(f"{name}_scale must be rank-4")
    if int(scale.shape[0]) != batch:
        raise ValueError(f"{name}_scale batch dimension must be {batch}")
    if heads not in (int(scale.shape[1]), int(scale.shape[2])):
        raise ValueError(f"{name}_scale must include heads={heads} in dimension 1 or 2")
    if _D_QK not in (int(scale.shape[1]), int(scale.shape[2])):
        raise ValueError(f"{name}_scale must include Dqk={_D_QK} in dimension 1 or 2")
    if int(scale.shape[3]) not in (seqlen // 16, seqlen // 32):
        raise ValueError(f"{name}_scale last dimension must be S/16 or S/32")


def _check_mxfp4_gemm_artifact(
    packed: torch.Tensor,
    scale: torch.Tensor,
    *,
    name: str,
    batch: int,
    heads: int,
    rows: int,
    cols: int,
) -> None:
    _check_cuda_contiguous(packed, f"{name}_packed")
    _check_cuda_contiguous(scale, f"{name}_scale")
    if packed.dtype != torch.float4_e2m1fn_x2:
        raise ValueError(f"{name}_packed must have dtype torch.float4_e2m1fn_x2")
    if scale.dtype != torch.uint8:
        raise ValueError(f"{name}_scale must have dtype torch.uint8 E8M0 scales")
    if rows % _TILE != 0 or cols % _TILE != 0:
        raise ValueError(f"{name} MXFP4 GEMM artifact rows/cols must be multiples of 128")
    if tuple(packed.shape) != (batch, heads, rows, cols // 2):
        raise ValueError(f"{name}_packed must have shape {(batch, heads, rows, cols // 2)}")
    expected_scale_rows = rows // _TILE
    if scale.ndim != 6 or scale.shape[:2] != (batch, heads) or scale.shape[3:] != (cols // _TILE, 32, 16):
        raise ValueError(
            f"{name}_scale must have shape (B,H,rows/128,cols/128,32,16) for rows={rows}, cols={cols}"
        )
    scale_rows = int(scale.shape[2])
    if scale_rows != expected_scale_rows and not (expected_scale_rows == 1 and scale_rows == 2):
        raise ValueError(f"{name}_scale row tiles must be {expected_scale_rows} or padded 2 for single-row-tile operands")


def _quantize_v_row_col_mxfp4_for_backward(
    v_bf16: torch.Tensor,
    *,
    quant_mode: str | None = None,
) -> dict[str, torch.Tensor]:
    _require_finite_tensor(v_bf16, "v_bf16")
    if v_bf16.dtype != torch.bfloat16:
        v_bf16 = v_bf16.to(torch.bfloat16)
    if v_bf16.ndim != 4:
        raise ValueError("v_bf16 must have shape (B,S,H,Dvo)")
    batch, seqlen, heads, dvo = (int(v) for v in v_bf16.shape)
    if dvo != _D_VO:
        raise ValueError(f"V head dim must be {_D_VO}")
    if seqlen % _TILE != 0:
        raise ValueError("sequence length must be divisible by 128")
    effective_quant_mode = quant_mode
    if effective_quant_mode is None and _env_flag("TK_FA4_MXFP4_BWD_V_ROW_COL_ENCODE_DEFAULT", default=True):
        effective_quant_mode = "encode"
    v_row_fp4 = torch.empty((batch, heads, seqlen, dvo // 2), device=v_bf16.device, dtype=torch.float4_e2m1fn_x2)
    v_row_sc = torch.empty((batch, heads, seqlen // _TILE, dvo // _TILE, 32, 16), device=v_bf16.device, dtype=torch.uint8)
    v_col_fp4 = torch.empty((batch, heads, dvo, seqlen // 2), device=v_bf16.device, dtype=torch.float4_e2m1fn_x2)
    v_col_sc = torch.empty((batch, heads, dvo // _TILE, seqlen // _TILE, 32, 16), device=v_bf16.device, dtype=torch.uint8)
    for b in range(batch):
        for h in range(heads):
            v_rows = v_bf16[b, :, h, :].contiguous()
            row_rec = _quantize_rows_2d_mxfp4(v_rows, backend="mxfp4", quant_mode=effective_quant_mode)
            _copy_fp4_tensor_(v_row_fp4[b, h], row_rec["fp4"])
            v_row_sc[b, h].copy_(row_rec["scales"])

            v_cols = v_rows.transpose(0, 1).contiguous()
            col_rec = _quantize_rows_2d_mxfp4(v_cols, backend="mxfp4", quant_mode=effective_quant_mode)
            _copy_fp4_tensor_(v_col_fp4[b, h], col_rec["fp4"])
            v_col_sc[b, h].copy_(col_rec["scales"])
    return {
        "v_row_fp4": v_row_fp4.contiguous(),
        "v_row_sc": v_row_sc.contiguous(),
        "v_col_fp4": v_col_fp4.contiguous(),
        "v_col_sc": v_col_sc.contiguous(),
    }


def _quantize_qk_col_mxfp4_for_backward(
    x_bf16: torch.Tensor,
    *,
    name: str,
    quant_mode: str | None = None,
) -> tuple[torch.Tensor, torch.Tensor]:
    _require_finite_tensor(x_bf16, name)
    if x_bf16.dtype != torch.bfloat16:
        x_bf16 = x_bf16.to(torch.bfloat16)
    if x_bf16.ndim != 4:
        raise ValueError(f"{name} must have shape (B,S,H,Dqk)")
    batch, seqlen, heads, d_qk = (int(v) for v in x_bf16.shape)
    if d_qk != _D_QK:
        raise ValueError(f"{name} head dim must be {_D_QK}")
    if seqlen % _TILE != 0:
        raise ValueError("sequence length must be divisible by 128")
    col_fp4 = torch.empty((batch, heads, _D_QK_GEMM_PAD, seqlen // 2), device=x_bf16.device, dtype=torch.float4_e2m1fn_x2)
    col_sc = torch.empty((batch, heads, _D_QK_GEMM_PAD // _TILE, seqlen // _TILE, 32, 16), device=x_bf16.device, dtype=torch.uint8)
    for b in range(batch):
        for h in range(heads):
            rows = torch.zeros((_D_QK_GEMM_PAD, seqlen), device=x_bf16.device, dtype=torch.bfloat16)
            rows[:_D_QK].copy_(x_bf16[b, :, h, :].transpose(0, 1).contiguous())
            rec = _quantize_rows_2d_mxfp4(rows, backend="mxfp4", quant_mode=quant_mode)
            _copy_fp4_tensor_(col_fp4[b, h], rec["fp4"])
            col_sc[b, h].copy_(rec["scales"])
    return col_fp4.contiguous(), col_sc.contiguous()


def _quantize_bshd_rows_mxfp4_for_gemm(
    x_bshd: torch.Tensor,
    *,
    name: str,
    quant_mode: str | None = None,
) -> tuple[torch.Tensor, torch.Tensor]:
    _require_finite_tensor(x_bshd, name)
    if x_bshd.dtype != torch.bfloat16:
        x_bshd = x_bshd.to(torch.bfloat16)
    if x_bshd.ndim != 4:
        raise ValueError(f"{name} must have shape (B,S,H,D)")
    batch, seqlen, heads, dim = (int(v) for v in x_bshd.shape)
    if seqlen % _TILE != 0 or dim % _TILE != 0:
        raise ValueError(f"{name} sequence and dim must be multiples of 128")
    fp4 = torch.empty((batch, heads, seqlen, dim // 2), device=x_bshd.device, dtype=torch.float4_e2m1fn_x2)
    sc = torch.empty((batch, heads, seqlen // _TILE, dim // _TILE, 32, 16), device=x_bshd.device, dtype=torch.uint8)
    for b in range(batch):
        for h in range(heads):
            rec = _quantize_rows_2d_mxfp4(
                x_bshd[b, :, h, :].contiguous(),
                backend="mxfp4",
                quant_mode=quant_mode,
            )
            _copy_fp4_tensor_(fp4[b, h], rec["fp4"])
            sc[b, h].copy_(rec["scales"])
    return fp4.contiguous(), sc.contiguous()


def _quantize_dout_row_col_mxfp4_for_backward(
    dout_bshd: torch.Tensor,
    *,
    out_bshd: torch.Tensor | None = None,
    quant_mode: str | None = None,
    validate_finite: bool = True,
    row_fp4_out: torch.Tensor | None = None,
    row_sc_out: torch.Tensor | None = None,
    col_fp4_out: torch.Tensor | None = None,
    col_sc_out: torch.Tensor | None = None,
    delta_out: torch.Tensor | None = None,
) -> dict[str, torch.Tensor]:
    if validate_finite:
        _require_finite_tensor(dout_bshd, "dout")
    if dout_bshd.dtype != torch.bfloat16:
        dout_bshd = dout_bshd.to(torch.bfloat16)
    if dout_bshd.ndim != 4:
        raise ValueError("dout must have shape (B,S,H,Dvo)")
    batch, seqlen, heads, dvo = (int(v) for v in dout_bshd.shape)
    if dvo != _D_VO:
        raise ValueError(f"dout head dim must be {_D_VO}")
    if seqlen % _TILE != 0:
        raise ValueError("sequence length must be divisible by 128")
    if out_bshd is not None:
        _check_cuda_contiguous(out_bshd, "out_bshd")
        if out_bshd.dtype != torch.bfloat16 or tuple(out_bshd.shape) != (batch, seqlen, heads, dvo):
            raise ValueError(f"out_bshd must be BF16 with shape {(batch, seqlen, heads, dvo)}")
    prealloc_args = (row_fp4_out, row_sc_out, col_fp4_out, col_sc_out, delta_out)
    use_prealloc = any(t is not None for t in prealloc_args)
    if use_prealloc:
        if out_bshd is None:
            raise ValueError("preallocated dOut row+col quantization requires out_bshd for delta")
        if any(t is None for t in prealloc_args):
            raise ValueError("row_fp4_out, row_sc_out, col_fp4_out, col_sc_out, and delta_out must be provided together")
        assert row_fp4_out is not None
        assert row_sc_out is not None
        assert col_fp4_out is not None
        assert col_sc_out is not None
        assert delta_out is not None
        _check_cuda_contiguous(row_fp4_out, "dout_row_fp4_out")
        _check_cuda_contiguous(row_sc_out, "dout_row_sc_out")
        _check_cuda_contiguous(col_fp4_out, "dout_col_fp4_out")
        _check_cuda_contiguous(col_sc_out, "dout_col_sc_out")
        _check_cuda_contiguous(delta_out, "delta_out")
        if row_fp4_out.dtype != torch.float4_e2m1fn_x2 or tuple(row_fp4_out.shape) != (batch, heads, seqlen, dvo // 2):
            raise ValueError(f"dout_row_fp4_out must be float4_e2m1fn_x2 with shape {(batch, heads, seqlen, dvo // 2)}")
        if row_sc_out.dtype != torch.uint8 or tuple(row_sc_out.shape) != (batch, heads, seqlen // _TILE, dvo // _TILE, 32, 16):
            raise ValueError(f"dout_row_sc_out must be uint8 with shape {(batch, heads, seqlen // _TILE, dvo // _TILE, 32, 16)}")
        if col_fp4_out.dtype != torch.float4_e2m1fn_x2 or tuple(col_fp4_out.shape) != (batch, heads, dvo, seqlen // 2):
            raise ValueError(f"dout_col_fp4_out must be float4_e2m1fn_x2 with shape {(batch, heads, dvo, seqlen // 2)}")
        if col_sc_out.dtype != torch.uint8 or tuple(col_sc_out.shape) != (batch, heads, dvo // _TILE, seqlen // _TILE, 32, 16):
            raise ValueError(f"dout_col_sc_out must be uint8 with shape {(batch, heads, dvo // _TILE, seqlen // _TILE, 32, 16)}")
        if delta_out.dtype != torch.float32 or tuple(delta_out.shape) != (batch, heads, seqlen):
            raise ValueError(f"delta_out must be float32 with shape {(batch, heads, seqlen)}")

    ext = _load_mxfp4_v3_quant()
    effective_quant_mode = quant_mode
    if effective_quant_mode is None and _env_flag("TK_FA4_MXFP4_BWD_DOUT_ROW_COL_ENCODE_DEFAULT", default=True):
        effective_quant_mode = "encode"
    quant_arg = 0 if effective_quant_mode in (None, "mxfp4") else _mxfp4_quant_mode_to_int(effective_quant_mode)

    def _compute_delta_bhs() -> torch.Tensor:
        if out_bshd is None:
            raise ValueError("delta computation requires out_bshd")
        delta = _bf16_delta_bhs_from_out_dout(out_bshd.contiguous(), dout_bshd.contiguous())
        if delta_out is not None:
            delta_out.copy_(delta)
            return delta_out
        return delta

    if use_prealloc and hasattr(ext, "mxfp4_quantize_bshd128_row_and_col_with_delta_out"):
        assert out_bshd is not None
        assert row_fp4_out is not None
        assert row_sc_out is not None
        assert col_fp4_out is not None
        assert col_sc_out is not None
        assert delta_out is not None
        with _cuda_device_ctx(dout_bshd.device):
            row_fp4, row_sc, col_fp4, col_sc, delta = ext.mxfp4_quantize_bshd128_row_and_col_with_delta_out(
                dout_bshd.contiguous(),
                out_bshd.contiguous(),
                row_fp4_out,
                row_sc_out,
                col_fp4_out,
                col_sc_out,
                delta_out,
                quant_arg,
            )
            delta = _compute_delta_bhs()
        return {
            "dout_row_fp4": row_fp4,
            "dout_row_sc": row_sc,
            "dout_col_fp4": col_fp4,
            "dout_col_sc": col_sc,
            "delta_bhs": delta,
        }
    if out_bshd is not None and hasattr(ext, "mxfp4_quantize_bshd128_row_and_col_with_delta"):
        with _cuda_device_ctx(dout_bshd.device):
            row_fp4, row_sc, col_fp4, col_sc, delta = ext.mxfp4_quantize_bshd128_row_and_col_with_delta(
                dout_bshd.contiguous(),
                out_bshd.contiguous(),
                quant_arg,
            )
            delta = _compute_delta_bhs()
        return {
            "dout_row_fp4": row_fp4.contiguous(),
            "dout_row_sc": row_sc.contiguous(),
            "dout_col_fp4": col_fp4.contiguous(),
            "dout_col_sc": col_sc.contiguous(),
            "delta_bhs": delta.contiguous(),
        }
    if hasattr(ext, "mxfp4_quantize_bshd128_row_and_col"):
        with _cuda_device_ctx(dout_bshd.device):
            row_fp4, row_sc, col_fp4, col_sc = ext.mxfp4_quantize_bshd128_row_and_col(
                dout_bshd.contiguous(),
                quant_arg,
            )
        return {
            "dout_row_fp4": row_fp4.contiguous(),
            "dout_row_sc": row_sc.contiguous(),
            "dout_col_fp4": col_fp4.contiguous(),
            "dout_col_sc": col_sc.contiguous(),
        }

    row_fp4 = torch.empty(
        (batch, heads, seqlen, dvo // 2),
        device=dout_bshd.device,
        dtype=torch.float4_e2m1fn_x2,
    )
    row_sc = torch.empty(
        (batch, heads, seqlen // _TILE, dvo // _TILE, 32, 16),
        device=dout_bshd.device,
        dtype=torch.uint8,
    )
    col_fp4 = torch.empty(
        (batch, heads, dvo, seqlen // 2),
        device=dout_bshd.device,
        dtype=torch.float4_e2m1fn_x2,
    )
    col_sc = torch.empty(
        (batch, heads, dvo // _TILE, seqlen // _TILE, 32, 16),
        device=dout_bshd.device,
        dtype=torch.uint8,
    )
    for b in range(batch):
        for h in range(heads):
            r_fp4, r_sc, c_fp4, c_sc = ext.mxfp4_quantize_row_and_col(
                dout_bshd[b, :, h, :].contiguous(),
                quant_arg,
            )
            _copy_fp4_tensor_(row_fp4[b, h], r_fp4)
            row_sc[b, h].copy_(r_sc)
            _copy_fp4_tensor_(col_fp4[b, h], c_fp4)
            col_sc[b, h].copy_(c_sc)
    return {
        "dout_row_fp4": row_fp4.contiguous(),
        "dout_row_sc": row_sc.contiguous(),
        "dout_col_fp4": col_fp4.contiguous(),
        "dout_col_sc": col_sc.contiguous(),
    }


def _materialize_p_bf16_from_prequantized_saved_lse(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    lse_bhs: torch.Tensor,
) -> torch.Tensor:
    ext = _load_backward_experiments_ext()
    batch, heads, seqlen = _check_fp4_attention_inputs(q, q_sc, q_sg, k, k_sc, k_sg)
    lse_bh1s = _normalize_mxfp4_dv_lse_bh1s(lse_bhs, batch=batch, heads=heads, seqlen=seqlen)
    if not hasattr(ext, "forward_streaming_live_qk_only_saved_lse"):
        raise RuntimeError(
            "experiments extension is missing forward_streaming_live_qk_only_saved_lse; "
            "rebuild tk_fa4/b300_causal_fp4_experiments"
        )
    with _cuda_device_ctx(q.device):
        p_bf16 = ext.forward_streaming_live_qk_only_saved_lse(q, q_sc, q_sg, k, k_sc, k_sg, lse_bh1s)
    _check_cuda_contiguous(p_bf16, "p_bf16_saved_lse")
    if p_bf16.dtype != torch.bfloat16 or tuple(p_bf16.shape) != (batch, heads, seqlen, seqlen):
        raise ValueError("forward_streaming_live_qk_only_saved_lse returned an unexpected P tensor")
    return p_bf16.contiguous()


def _fused_ds_bf16_from_prequantized_saved_lse(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    lse_bhs: torch.Tensor,
    dP_bhss: torch.Tensor,
    delta_bhs: torch.Tensor,
    *,
    softmax_scale: float,
) -> torch.Tensor:
    ext = _load_backward_experiments_ext()
    batch, heads, seqlen = _check_fp4_attention_inputs(q, q_sc, q_sg, k, k_sc, k_sg)
    _check_cuda_contiguous(dP_bhss, "dP_bhss")
    _check_cuda_contiguous(delta_bhs, "delta_bhs")
    if dP_bhss.dtype != torch.bfloat16 or tuple(dP_bhss.shape) != (batch, heads, seqlen, seqlen):
        raise ValueError(f"dP_bhss must be BF16 with shape {(batch, heads, seqlen, seqlen)}")
    if delta_bhs.dtype != torch.float32 or tuple(delta_bhs.shape) != (batch, heads, seqlen):
        raise ValueError(f"delta_bhs must be float32 with shape {(batch, heads, seqlen)}")
    if not hasattr(ext, "backward_ds_streaming_live_qk_saved_lse"):
        raise RuntimeError(
            "experiments extension is missing backward_ds_streaming_live_qk_saved_lse; "
            "rebuild tk_fa4/b300_causal_fp4_experiments"
        )
    lse_bh1s = _normalize_mxfp4_dv_lse_bh1s(lse_bhs, batch=batch, heads=heads, seqlen=seqlen)
    with _cuda_device_ctx(q.device):
        if hasattr(ext, "backward_ds_streaming_live_qk_saved_lse_clustered_full"):
            dS = ext.backward_ds_streaming_live_qk_saved_lse_clustered_full(
                q,
                q_sc,
                q_sg,
                k,
                k_sc,
                k_sg,
                lse_bh1s,
                dP_bhss.contiguous(),
                delta_bhs.contiguous(),
                float(softmax_scale),
            )
        else:
            if not (hasattr(ext, "backward_ds_streaming_live_qk_saved_lse_row_cluster") or hasattr(ext, "backward_ds_streaming_live_qk_saved_lse_row_tile")):
                raise RuntimeError(
                    "experiments extension is missing saved-LSE dS clustered-full/row-cluster/row-tile entry points; "
                    "rebuild tk_fa4/b300_causal_fp4_experiments"
                )
            dS = torch.zeros((batch, heads, seqlen, seqlen), device=q.device, dtype=torch.bfloat16)
            row_tiles = seqlen // _TILE
            if hasattr(ext, "backward_ds_streaming_live_qk_saved_lse_row_cluster"):
                row_cluster_tiles = 2
                for row_cluster_base in range(0, row_tiles, row_cluster_tiles):
                    dS_cluster = ext.backward_ds_streaming_live_qk_saved_lse_row_cluster(
                        q,
                        q_sc,
                        q_sg,
                        k,
                        k_sc,
                        k_sg,
                        lse_bh1s,
                        dP_bhss.contiguous(),
                        delta_bhs.contiguous(),
                        row_cluster_base,
                        float(softmax_scale),
                    )
                    row_begin = row_cluster_base * _TILE
                    rows = dS_cluster.shape[-2]
                    cols = dS_cluster.shape[-1]
                    dS[:, :, row_begin : row_begin + rows, :cols].copy_(dS_cluster)
            else:
                for row_tile in range(row_tiles):
                    dS_tile = ext.backward_ds_streaming_live_qk_saved_lse_row_tile(
                        q,
                        q_sc,
                        q_sg,
                        k,
                        k_sc,
                        k_sg,
                        lse_bh1s,
                        dP_bhss.contiguous(),
                        delta_bhs.contiguous(),
                        row_tile,
                        float(softmax_scale),
                    )
                    row_begin = row_tile * _TILE
                    cols = dS_tile.shape[-1]
                    dS[:, :, row_begin : row_begin + _TILE, :cols].copy_(dS_tile)
    _check_cuda_contiguous(dS, "dS_bf16_fused")
    if dS.dtype != torch.bfloat16 or tuple(dS.shape) != (batch, heads, seqlen, seqlen):
        raise ValueError("backward_ds_streaming_live_qk_saved_lse returned an unexpected dS tensor")
    return dS.contiguous()


def _fused_ds_row_mxfp4_from_prequantized_saved_lse(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    lse_bhs: torch.Tensor,
    dP_bhss: torch.Tensor,
    delta_bhs: torch.Tensor,
    *,
    softmax_scale: float,
    quant_mode: str | None = None,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor | None, torch.Tensor | None, torch.Tensor | None]:
    ext = _load_backward_experiments_ext()
    batch, heads, seqlen = _check_fp4_attention_inputs(q, q_sc, q_sg, k, k_sc, k_sg)
    _check_cuda_contiguous(dP_bhss, "dP_bhss")
    _check_cuda_contiguous(delta_bhs, "delta_bhs")
    if dP_bhss.dtype != torch.bfloat16 or tuple(dP_bhss.shape) != (batch, heads, seqlen, seqlen):
        raise ValueError(f"dP_bhss must be BF16 with shape {(batch, heads, seqlen, seqlen)}")
    if delta_bhs.dtype != torch.float32 or tuple(delta_bhs.shape) != (batch, heads, seqlen):
        raise ValueError(f"delta_bhs must be float32 with shape {(batch, heads, seqlen)}")
    if not (
        hasattr(ext, "backward_ds_streaming_live_qk_saved_lse_fullgrid_row_col_mxfp4_no_bf16")
        or hasattr(ext, "backward_ds_streaming_live_qk_saved_lse_fullgrid_row_mxfp4")
        or hasattr(ext, "backward_ds_streaming_live_qk_saved_lse_clustered_full_row_mxfp4")
    ):
        raise RuntimeError(
            "experiments extension is missing a direct row-MXFP4 saved-LSE dS entrypoint; "
            "rebuild tk_fa4/b300_causal_fp4_experiments"
        )
    lse_bh1s = _normalize_mxfp4_dv_lse_bh1s(lse_bhs, batch=batch, heads=heads, seqlen=seqlen)
    mode = _mxfp4_quant_mode_to_int(quant_mode)
    with _cuda_device_ctx(q.device):
        row_tiles = seqlen // _TILE
        safe_k_tile_window = _resolve_mxfp4_backward_ds_window(row_tiles)
        if (
            safe_k_tile_window != 3
            and hasattr(ext, "backward_ds_streaming_live_qk_saved_lse_fullgrid_row_col_mxfp4_window_no_bf16")
        ):
            out = ext.backward_ds_streaming_live_qk_saved_lse_fullgrid_row_col_mxfp4_window_no_bf16(
                q,
                q_sc,
                q_sg,
                k,
                k_sc,
                k_sg,
                lse_bh1s,
                dP_bhss.contiguous(),
                delta_bhs.contiguous(),
                int(mode),
                float(softmax_scale),
                int(safe_k_tile_window),
            )
        elif hasattr(ext, "backward_ds_streaming_live_qk_saved_lse_fullgrid_row_col_mxfp4_no_bf16"):
            out = ext.backward_ds_streaming_live_qk_saved_lse_fullgrid_row_col_mxfp4_no_bf16(
                q,
                q_sc,
                q_sg,
                k,
                k_sc,
                k_sg,
                lse_bh1s,
                dP_bhss.contiguous(),
                delta_bhs.contiguous(),
                int(mode),
                float(softmax_scale),
            )
        elif hasattr(ext, "backward_ds_streaming_live_qk_saved_lse_fullgrid_row_mxfp4_no_bf16"):
            out = ext.backward_ds_streaming_live_qk_saved_lse_fullgrid_row_mxfp4_no_bf16(
                q,
                q_sc,
                q_sg,
                k,
                k_sc,
                k_sg,
                lse_bh1s,
                dP_bhss.contiguous(),
                delta_bhs.contiguous(),
                int(mode),
                float(softmax_scale),
            )
        elif hasattr(ext, "backward_ds_streaming_live_qk_saved_lse_clustered_full_row_mxfp4_no_bf16"):
            out = ext.backward_ds_streaming_live_qk_saved_lse_clustered_full_row_mxfp4_no_bf16(
                q,
                q_sc,
                q_sg,
                k,
                k_sc,
                k_sg,
                lse_bh1s,
                dP_bhss.contiguous(),
                delta_bhs.contiguous(),
                int(mode),
                float(softmax_scale),
            )
        elif hasattr(ext, "backward_ds_streaming_live_qk_saved_lse_clustered_full_row_mxfp4"):
            out = ext.backward_ds_streaming_live_qk_saved_lse_clustered_full_row_mxfp4(
                q,
                q_sc,
                q_sg,
                k,
                k_sc,
                k_sg,
                lse_bh1s,
                dP_bhss.contiguous(),
                delta_bhs.contiguous(),
                int(mode),
                float(softmax_scale),
            )
        else:
            out = ext.backward_ds_streaming_live_qk_saved_lse_fullgrid_row_mxfp4(
                q,
                q_sc,
                q_sg,
                k,
                k_sc,
                k_sg,
                lse_bh1s,
                dP_bhss.contiguous(),
                delta_bhs.contiguous(),
                int(mode),
                float(softmax_scale),
            )
    if len(out) not in (2, 3, 4, 5):
        raise ValueError("direct row-MXFP4 dS entrypoint returned an unexpected result count")
    dS_fp4 = out[0].contiguous()
    dS_sc = out[1].contiguous()
    _check_mxfp4_gemm_artifact(dS_fp4, dS_sc, name="dS_row_direct", batch=batch, heads=heads, rows=seqlen, cols=seqlen)
    dS_col_fp4 = None
    dS_col_sc = None
    if len(out) in (4, 5):
        dS_col_fp4 = out[2].contiguous()
        dS_col_sc = out[3].contiguous()
        _check_mxfp4_gemm_artifact(
            dS_col_fp4,
            dS_col_sc,
            name="dS_col_direct",
            batch=batch,
            heads=heads,
            rows=seqlen,
            cols=seqlen,
        )
    if len(out) in (2, 4):
        dS_bf16 = None
    else:
        dS_bf16 = out[-1].contiguous()
        _check_cuda_contiguous(dS_bf16, "dS_bf16_direct_validation")
        if dS_bf16.dtype != torch.bfloat16 or tuple(dS_bf16.shape) != (batch, heads, seqlen, seqlen):
            raise ValueError("direct row-MXFP4 dS entrypoint returned an unexpected BF16 tensor")
    return dS_fp4, dS_sc, dS_col_fp4, dS_col_sc, dS_bf16


def _fused_ds_col_mxfp4_from_prequantized_saved_lse(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    lse_bhs: torch.Tensor,
    dP_bhss: torch.Tensor,
    delta_bhs: torch.Tensor,
    *,
    softmax_scale: float,
    quant_mode: str | None = None,
) -> tuple[torch.Tensor, torch.Tensor]:
    ext = _load_backward_experiments_ext()
    batch, heads, seqlen = _check_fp4_attention_inputs(q, q_sc, q_sg, k, k_sc, k_sg)
    _check_cuda_contiguous(dP_bhss, "dP_bhss")
    _check_cuda_contiguous(delta_bhs, "delta_bhs")
    if dP_bhss.dtype != torch.bfloat16 or tuple(dP_bhss.shape) != (batch, heads, seqlen, seqlen):
        raise ValueError(f"dP_bhss must be BF16 with shape {(batch, heads, seqlen, seqlen)}")
    if delta_bhs.dtype != torch.float32 or tuple(delta_bhs.shape) != (batch, heads, seqlen):
        raise ValueError(f"delta_bhs must be float32 with shape {(batch, heads, seqlen)}")

    if not hasattr(ext, "backward_ds_streaming_live_qk_saved_lse_fullgrid_col_mxfp4_window_no_bf16"):
        dS_fp4, dS_sc, dS_col_fp4, dS_col_sc, dS = _fused_ds_row_mxfp4_from_prequantized_saved_lse(
            q,
            q_sc,
            q_sg,
            k,
            k_sc,
            k_sg,
            lse_bhs,
            dP_bhss,
            delta_bhs,
            softmax_scale=softmax_scale,
            quant_mode=quant_mode,
        )
        if dS_col_fp4 is not None and dS_col_sc is not None:
            return dS_col_fp4.contiguous(), dS_col_sc.contiguous()
        if dS is not None:
            return _mxfp4_quantize_p_col_for_gemm(dS, quant_mode=quant_mode)
        return _mxfp4_transpose_row_artifact_for_gemm(
            dS_fp4,
            dS_sc,
            quant_mode=quant_mode,
        )

    lse_bh1s = _normalize_mxfp4_dv_lse_bh1s(lse_bhs, batch=batch, heads=heads, seqlen=seqlen)
    row_tiles = seqlen // _TILE
    safe_k_tile_window = _resolve_mxfp4_backward_ds_window(row_tiles)
    mode = _mxfp4_quant_mode_to_int(quant_mode)
    with _cuda_device_ctx(q.device):
        out = ext.backward_ds_streaming_live_qk_saved_lse_fullgrid_col_mxfp4_window_no_bf16(
            q,
            q_sc,
            q_sg,
            k,
            k_sc,
            k_sg,
            lse_bh1s,
            dP_bhss.contiguous(),
            delta_bhs.contiguous(),
            int(mode),
            float(softmax_scale),
            int(safe_k_tile_window),
        )
    if len(out) != 2:
        raise ValueError("direct col-MXFP4 dS entrypoint returned an unexpected result count")
    dS_col_fp4, dS_col_sc = (t.contiguous() for t in out)
    _check_mxfp4_gemm_artifact(
        dS_col_fp4,
        dS_col_sc,
        name="dS_col_direct",
        batch=batch,
        heads=heads,
        rows=seqlen,
        cols=seqlen,
    )
    return dS_col_fp4, dS_col_sc


def _mxfp4_p_cache_from_prequantized_saved_lse(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    lse_bhs: torch.Tensor,
    *,
    quant_mode: str | None = None,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    ext = _load_backward_experiments_ext()
    batch, heads, seqlen = _check_fp4_attention_inputs(q, q_sc, q_sg, k, k_sc, k_sg)
    if not hasattr(ext, "mxfp4_p_from_scores_saved_lse_row_col"):
        raise RuntimeError(
            "experiments extension is missing the saved-LSE MXFP4 P cache producer; "
            "rebuild tk_fa4/fp4_fa4_bwd"
        )
    lse_bh1s = _normalize_mxfp4_dv_lse_bh1s(lse_bhs, batch=batch, heads=heads, seqlen=seqlen)
    row_tiles = seqlen // _TILE
    safe_k_tile_window = _resolve_mxfp4_backward_ds_window(row_tiles)
    mode = _mxfp4_quant_mode_to_int(quant_mode)
    with _cuda_device_ctx(q.device):
        out = ext.mxfp4_p_from_scores_saved_lse_row_col(
            q,
            q_sc,
            q_sg,
            k,
            k_sc,
            k_sg,
            lse_bh1s,
            int(mode),
            int(safe_k_tile_window),
        )
    if len(out) != 4:
        raise ValueError("saved-LSE MXFP4 P cache producer returned an unexpected result count")
    p_row_fp4, p_row_sc, p_col_fp4, p_col_sc = (t.contiguous() for t in out)
    _check_mxfp4_gemm_artifact(
        p_row_fp4,
        p_row_sc,
        name="P_cache_row",
        batch=batch,
        heads=heads,
        rows=seqlen,
        cols=seqlen,
    )
    _check_mxfp4_gemm_artifact(
        p_col_fp4,
        p_col_sc,
        name="P_cache_col",
        batch=batch,
        heads=heads,
        rows=seqlen,
        cols=seqlen,
    )
    return p_row_fp4, p_row_sc, p_col_fp4, p_col_sc


