def _fused_dq_dk_pad_mxfp4_live_dp_pair_from_prequantized_saved_lse_out(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    k_col_packed: torch.Tensor,
    k_col_scale: torch.Tensor,
    q_col_packed: torch.Tensor,
    q_col_scale: torch.Tensor,
    lse_bhs: torch.Tensor,
    dout_row_fp4: torch.Tensor,
    dout_row_sc: torch.Tensor,
    v_row_fp4: torch.Tensor,
    v_row_sc: torch.Tensor,
    delta_bhs: torch.Tensor,
    dq_pad_out: torch.Tensor,
    dk_pad_out: torch.Tensor,
    *,
    softmax_scale: float,
    quant_mode: str | None = None,
    debug_stage_cut: int = 15,
) -> (
    tuple[torch.Tensor, torch.Tensor]
    | tuple[torch.Tensor, torch.Tensor, torch.Tensor]
    | tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]
):
    ext = _load_backward_experiments_ext()
    pair_ds_col_hbm_bridge = _env_flag("TK_FA4_MXFP4_BWD_PAIR_DS_COL_HBM_BRIDGE_PROBE")
    entrypoint_name = (
        "backward_dq_dk_streaming_live_qk_saved_lse_fused_mxfp4_live_dp_pair_ds_col_bridge_out"
        if pair_ds_col_hbm_bridge
        else "backward_dq_dk_streaming_live_qk_saved_lse_fused_mxfp4_live_dp_pair_out"
    )
    entrypoint = getattr(ext, entrypoint_name, None)
    if entrypoint is None:
        raise RuntimeError(f"backward extension is missing {entrypoint_name}")
    batch, heads, seqlen = _check_fp4_attention_inputs(q, q_sc, q_sg, k, k_sc, k_sg)
    _check_mxfp4_gemm_artifact(
        k_col_packed,
        k_col_scale,
        name="k_col",
        batch=batch,
        heads=heads,
        rows=_D_QK_GEMM_PAD,
        cols=seqlen,
    )
    _check_mxfp4_gemm_artifact(
        q_col_packed,
        q_col_scale,
        name="q_col",
        batch=batch,
        heads=heads,
        rows=_D_QK_GEMM_PAD,
        cols=seqlen,
    )
    _check_mxfp4_gemm_artifact(dout_row_fp4, dout_row_sc, name="dout_row", batch=batch, heads=heads, rows=seqlen, cols=_D_VO)
    _check_mxfp4_gemm_artifact(v_row_fp4, v_row_sc, name="v_row", batch=batch, heads=heads, rows=seqlen, cols=_D_VO)
    _check_cuda_contiguous(delta_bhs, "delta_bhs")
    _check_cuda_contiguous(dq_pad_out, "dq_pad_out")
    _check_cuda_contiguous(dk_pad_out, "dk_pad_out")
    expected_pad_shape = (batch, heads, seqlen, _D_QK_GEMM_PAD)
    if delta_bhs.dtype != torch.float32 or tuple(delta_bhs.shape) != (batch, heads, seqlen):
        raise ValueError(f"delta_bhs must be float32 with shape {(batch, heads, seqlen)}")
    if dq_pad_out.dtype != torch.bfloat16 or tuple(dq_pad_out.shape) != expected_pad_shape:
        raise ValueError(f"dq_pad_out must be BF16 with shape {expected_pad_shape}")
    if dk_pad_out.dtype != torch.bfloat16 or tuple(dk_pad_out.shape) != expected_pad_shape:
        raise ValueError(f"dk_pad_out must be BF16 with shape {expected_pad_shape}")
    ds_col_fp4_out: torch.Tensor | None = None
    ds_col_sc_out: torch.Tensor | None = None
    if pair_ds_col_hbm_bridge:
        ds_col_fp4_out = torch.empty(
            (batch, heads, seqlen, seqlen // 2),
            dtype=torch.float4_e2m1fn_x2,
            device=q.device,
        )
        ds_col_sc_out = torch.empty(
            (batch, heads, seqlen // _TILE, seqlen // _TILE, 32, 16),
            dtype=torch.uint8,
            device=q.device,
        )
    lse_bh1s = _normalize_mxfp4_dv_lse_bh1s(lse_bhs, batch=batch, heads=heads, seqlen=seqlen)
    mode = _mxfp4_quant_mode_to_int(quant_mode)
    zero_pad_out = (
        int(debug_stage_cut) != 15
        or _env_flag("TK_FA4_MXFP4_BWD_LIVE_DP_ZERO_PAD_OUT")
    )
    if zero_pad_out:
        dq_pad_out.zero_()
        dk_pad_out.zero_()
    with _cuda_device_ctx(q.device):
        result = entrypoint(
            q,
            q_sc,
            q_sg,
            k,
            k_sc,
            k_sg,
            k_col_packed.contiguous(),
            k_col_scale.contiguous(),
            q_col_packed.contiguous(),
            q_col_scale.contiguous(),
            lse_bh1s,
            dout_row_fp4.contiguous(),
            dout_row_sc.contiguous(),
            v_row_fp4.contiguous(),
            v_row_sc.contiguous(),
            delta_bhs.contiguous(),
            dq_pad_out,
            dk_pad_out,
            *(
                (ds_col_fp4_out, ds_col_sc_out)
                if pair_ds_col_hbm_bridge
                else ()
            ),
            int(mode),
            float(softmax_scale),
            int(debug_stage_cut),
        )
    expected_result_counts = {4} if pair_ds_col_hbm_bridge else {2, 3}
    if len(result) not in expected_result_counts:
        raise ValueError(
            f"live-dP dQ+dK pair entrypoint {entrypoint_name} returned an unexpected result count"
        )
    if result[0].data_ptr() != dq_pad_out.data_ptr():
        raise ValueError("live-dP dQ+dK pair entrypoint did not return the provided dq_pad_out")
    if result[1].data_ptr() != dk_pad_out.data_ptr():
        raise ValueError("live-dP dQ+dK pair entrypoint did not return the provided dk_pad_out")
    if pair_ds_col_hbm_bridge:
        if ds_col_fp4_out is None or ds_col_sc_out is None:
            raise RuntimeError("internal pair dS_col bridge allocation was not created")
        ds_col_fp4 = result[2]
        ds_col_sc = result[3]
        if ds_col_fp4.data_ptr() != ds_col_fp4_out.data_ptr():
            raise ValueError("pair dS_col HBM bridge did not return ds_col_fp4_out")
        if ds_col_sc.data_ptr() != ds_col_sc_out.data_ptr():
            raise ValueError("pair dS_col HBM bridge did not return ds_col_sc_out")
        return dq_pad_out, dk_pad_out, ds_col_fp4_out, ds_col_sc_out
    if len(result) == 3:
        partial_debug = result[2]
        _check_cuda_contiguous(partial_debug, "no_global_dk_repack_partial_debug")
        expected_debug_shape = (batch, heads, seqlen, _D_VO // 2)
        if partial_debug.dtype != torch.bfloat16 or tuple(partial_debug.shape) != expected_debug_shape:
            raise ValueError(
                "no_global_dk_repack_partial_debug must be BF16 with shape "
                f"{expected_debug_shape}"
            )
        return dq_pad_out, dk_pad_out, partial_debug
    return dq_pad_out, dk_pad_out


def _fused_dq_bshd_and_ds_row_mxfp4_from_prequantized_saved_lse(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    k_col_packed: torch.Tensor,
    k_col_scale: torch.Tensor,
    lse_bhs: torch.Tensor,
    dP_bhss: torch.Tensor,
    delta_bhs: torch.Tensor,
    dq_bshd_out: torch.Tensor | None = None,
    ds_row_fp4_out: torch.Tensor | None = None,
    ds_row_sc_out: torch.Tensor | None = None,
    *,
    softmax_scale: float,
    quant_mode: str | None = None,
    debug_stage_cut: int = 15,
    zero_ds_row_sc: bool = True,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    ext = _load_backward_experiments_ext()
    if not hasattr(ext, "backward_dq_streaming_live_qk_saved_lse_fused_mxfp4_with_ds_row_dq_bshd"):
        dq_pad, ds_row_fp4, ds_row_sc = _fused_dq_pad_and_ds_row_mxfp4_from_prequantized_saved_lse(
            q,
            q_sc,
            q_sg,
            k,
            k_sc,
            k_sg,
            k_col_packed,
            k_col_scale,
            lse_bhs,
            dP_bhss,
            delta_bhs,
            softmax_scale=softmax_scale,
            quant_mode=quant_mode,
            debug_stage_cut=debug_stage_cut,
            zero_ds_row_sc=zero_ds_row_sc,
        )
        return _view_qk_pad_bhsd_to_bshd(dq_pad, name="dQ_pad"), ds_row_fp4, ds_row_sc

    batch, heads, seqlen = _check_fp4_attention_inputs(q, q_sc, q_sg, k, k_sc, k_sg)
    _check_mxfp4_gemm_artifact(
        k_col_packed,
        k_col_scale,
        name="k_col",
        batch=batch,
        heads=heads,
        rows=_D_QK_GEMM_PAD,
        cols=seqlen,
    )
    _check_cuda_contiguous(dP_bhss, "dP_bhss")
    _check_cuda_contiguous(delta_bhs, "delta_bhs")
    if dP_bhss.dtype != torch.bfloat16 or tuple(dP_bhss.shape) != (batch, heads, seqlen, seqlen):
        raise ValueError(f"dP_bhss must be BF16 with shape {(batch, heads, seqlen, seqlen)}")
    if delta_bhs.dtype != torch.float32 or tuple(delta_bhs.shape) != (batch, heads, seqlen):
        raise ValueError(f"delta_bhs must be float32 with shape {(batch, heads, seqlen)}")
    if dq_bshd_out is not None:
        _check_cuda_contiguous(dq_bshd_out, "dq_bshd_out")
        if dq_bshd_out.dtype != torch.bfloat16 or tuple(dq_bshd_out.shape) != (batch, seqlen, heads, _D_QK):
            raise ValueError(f"dq_bshd_out must be BF16 with shape {(batch, seqlen, heads, _D_QK)}")
    if (ds_row_fp4_out is None) != (ds_row_sc_out is None):
        raise ValueError("ds_row_fp4_out and ds_row_sc_out must be provided together")
    if ds_row_fp4_out is not None and ds_row_sc_out is not None:
        _check_cuda_contiguous(ds_row_fp4_out, "ds_row_fp4_out")
        _check_cuda_contiguous(ds_row_sc_out, "ds_row_sc_out")
        if ds_row_fp4_out.dtype != torch.float4_e2m1fn_x2 or tuple(ds_row_fp4_out.shape) != (batch, heads, seqlen, seqlen // 2):
            raise ValueError(f"ds_row_fp4_out must be float4_e2m1fn_x2 with shape {(batch, heads, seqlen, seqlen // 2)}")
        if ds_row_sc_out.dtype != torch.uint8 or tuple(ds_row_sc_out.shape) != (batch, heads, seqlen // _TILE, seqlen // _TILE, 32, 16):
            raise ValueError(
                f"ds_row_sc_out must be uint8 with shape {(batch, heads, seqlen // _TILE, seqlen // _TILE, 32, 16)}"
            )

    lse_bh1s = _normalize_mxfp4_dv_lse_bh1s(lse_bhs, batch=batch, heads=heads, seqlen=seqlen)
    mode = _mxfp4_quant_mode_to_int(quant_mode)
    with _cuda_device_ctx(q.device):
        if (
            dq_bshd_out is not None
            and ds_row_fp4_out is not None
            and ds_row_sc_out is not None
            and hasattr(ext, "backward_dq_streaming_live_qk_saved_lse_fused_mxfp4_with_ds_row_dq_bshd_out")
        ):
            out = ext.backward_dq_streaming_live_qk_saved_lse_fused_mxfp4_with_ds_row_dq_bshd_out(
                q,
                q_sc,
                q_sg,
                k,
                k_sc,
                k_sg,
                k_col_packed.contiguous(),
                k_col_scale.contiguous(),
                lse_bh1s,
                dP_bhss.contiguous(),
                delta_bhs.contiguous(),
                dq_bshd_out,
                ds_row_fp4_out,
                ds_row_sc_out,
                int(mode),
                float(softmax_scale),
                int(debug_stage_cut),
                bool(zero_ds_row_sc),
            )
        else:
            out = ext.backward_dq_streaming_live_qk_saved_lse_fused_mxfp4_with_ds_row_dq_bshd(
                q,
                q_sc,
                q_sg,
                k,
                k_sc,
                k_sg,
                k_col_packed.contiguous(),
                k_col_scale.contiguous(),
                lse_bh1s,
                dP_bhss.contiguous(),
                delta_bhs.contiguous(),
                int(mode),
                float(softmax_scale),
                int(debug_stage_cut),
                bool(zero_ds_row_sc),
            )
    if len(out) != 3:
        raise ValueError("fused dQ-final+dS_row entrypoint returned an unexpected result count")
    dq, ds_row_fp4, ds_row_sc = out
    if dq_bshd_out is not None and dq.data_ptr() != dq_bshd_out.data_ptr():
        raise ValueError("preallocated fused dQ-final+dS_row entrypoint did not return dq_bshd_out")
    if ds_row_fp4_out is not None and ds_row_fp4.data_ptr() != ds_row_fp4_out.data_ptr():
        raise ValueError("preallocated fused dQ-final+dS_row entrypoint did not return ds_row_fp4_out")
    if ds_row_sc_out is not None and ds_row_sc.data_ptr() != ds_row_sc_out.data_ptr():
        raise ValueError("preallocated fused dQ-final+dS_row entrypoint did not return ds_row_sc_out")
    _check_cuda_contiguous(dq, "fused_dq")
    if dq.dtype != torch.bfloat16 or tuple(dq.shape) != (batch, seqlen, heads, _D_QK):
        raise ValueError("fused dQ-final+dS_row entrypoint returned an unexpected dQ tensor")
    _check_mxfp4_gemm_artifact(
        ds_row_fp4,
        ds_row_sc,
        name="dS_row_direct_bshd",
        batch=batch,
        heads=heads,
        rows=seqlen,
        cols=seqlen,
    )
    return dq, ds_row_fp4, ds_row_sc


def _mxfp4_transpose_row_artifact_for_gemm(
    p_fp4: torch.Tensor,
    p_sc: torch.Tensor,
    *,
    quant_mode: str | None = None,
) -> tuple[torch.Tensor, torch.Tensor]:
    batch, heads, seqlen, packed_cols = p_fp4.shape
    if packed_cols != seqlen // 2:
        raise ValueError("p_fp4 must have shape (batch, heads, seqlen, seqlen/2)")
    _check_mxfp4_gemm_artifact(p_fp4, p_sc, name="row_mxfp4_transpose_src", batch=batch, heads=heads, rows=seqlen, cols=seqlen)
    ext = _load_backward_experiments_ext()
    if not hasattr(ext, "row_mxfp4_transpose_to_mxfp4"):
        raise RuntimeError(
            "experiments extension is missing row_mxfp4_transpose_to_mxfp4; "
            "rebuild tk_fa4/b300_causal_fp4_experiments or use the BF16 validation fallback"
        )
    mode = _mxfp4_quant_mode_to_int(quant_mode)
    with _cuda_device_ctx(p_fp4.device):
        out = ext.row_mxfp4_transpose_to_mxfp4(p_fp4.contiguous(), p_sc.contiguous(), int(mode))
    if len(out) != 2:
        raise ValueError("row_mxfp4_transpose_to_mxfp4 returned an unexpected result count")
    pt_fp4, pt_sc = (t.contiguous() for t in out)
    _check_mxfp4_gemm_artifact(pt_fp4, pt_sc, name="dS_col_from_row_mxfp4", batch=batch, heads=heads, rows=seqlen, cols=seqlen)
    return pt_fp4, pt_sc


def _mxfp4_quantize_p_col_for_gemm(
    p_bf16: torch.Tensor,
    *,
    quant_mode: str | None = None,
) -> tuple[torch.Tensor, torch.Tensor]:
    batch, heads, seqlen = _check_stored_p(p_bf16)
    mode = _mxfp4_quant_mode_to_int(quant_mode)
    ext = _load_backward_experiments_ext()
    if hasattr(ext, "bf16_transpose_to_mxfp4"):
        with _cuda_device_ctx(p_bf16.device):
            out = ext.bf16_transpose_to_mxfp4(p_bf16.contiguous(), int(mode))
        if len(out) != 2:
            raise ValueError("bf16_transpose_to_mxfp4 returned an unexpected result count")
        pt_fp4, pt_sc = (t.contiguous() for t in out)
        _check_mxfp4_gemm_artifact(pt_fp4, pt_sc, name="dS_col_direct", batch=batch, heads=heads, rows=seqlen, cols=seqlen)
        return pt_fp4, pt_sc
    pt_fp4 = torch.empty((batch, heads, seqlen, seqlen // 2), device=p_bf16.device, dtype=torch.float4_e2m1fn_x2)
    pt_sc = torch.empty((batch, heads, seqlen // 128, seqlen // 128, 32, 16), device=p_bf16.device, dtype=torch.uint8)
    mod = _load_mxfp4_v3_quant()
    with _cuda_device_ctx(p_bf16.device):
        for b in range(batch):
            for h in range(heads):
                col_fp4, col_sc = mod.mxfp4_quantize_for_gemm(p_bf16[b, h].transpose(0, 1).contiguous(), mode)
                _copy_fp4_tensor_(pt_fp4[b, h], col_fp4.contiguous())
                pt_sc[b, h].copy_(col_sc.contiguous())
    return pt_fp4.contiguous(), pt_sc.contiguous()


def _bf16_delta_bhs_from_out_dout(out: torch.Tensor, dout: torch.Tensor) -> torch.Tensor:
    _check_cuda_contiguous(out, "out")
    _check_cuda_contiguous(dout, "dout")
    if out.dtype != torch.bfloat16 or dout.dtype != torch.bfloat16:
        raise ValueError("out and dout must be BF16")
    if out.ndim != 4 or tuple(out.shape) != tuple(dout.shape):
        raise ValueError("out and dout must both have shape (batch, seqlen, heads, 128)")
    if int(out.shape[-1]) != _D_VO:
        raise ValueError(f"out/dout last dimension must be {_D_VO}")
    # Keep this as a direct correctness reference. Some local extension builds
    # expose bf16_row_dot_delta_bshd but return zeros for the BSHD path.
    return (out.float() * dout.float()).sum(dim=-1).permute(0, 2, 1).contiguous()


def _resolve_mxfp4_backward_ds_window(row_tiles: int) -> int:
    if row_tiles <= 0:
        raise ValueError("row_tiles must be positive")
    default_window = 8 if _use_mxfp4_bwd_single_live_ds_col_schedule_default() else 16
    raw = os.environ.get("TK_FA4_MXFP4_DS_WINDOW")
    if raw is not None:
        value = raw.strip().lower()
        if value in ("full",):
            return row_tiles
        if value in ("", "auto", "default"):
            return min(default_window, row_tiles)
        elif value == "conservative":
            return min(3, row_tiles)
        elif value == "fast":
            return min(8, row_tiles)
        else:
            try:
                window = int(value, 10)
            except ValueError as exc:
                raise ValueError(
                    "TK_FA4_MXFP4_DS_WINDOW must be an integer, 'auto', 'default', "
                    "'full', 'conservative', or 'fast'"
                ) from exc
            if window < 1:
                raise ValueError(
                    f"TK_FA4_MXFP4_DS_WINDOW={window} is outside [1, {row_tiles}]"
                )
            return min(window, row_tiles)
    return min(default_window, row_tiles)


def _mxfp4_bh_gemm(
    a_fp4: torch.Tensor,
    a_sc: torch.Tensor,
    b_fp4: torch.Tensor,
    b_sc: torch.Tensor,
    *,
    name: str,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    _check_cuda_contiguous(a_fp4, f"{name}_a_fp4")
    _check_cuda_contiguous(a_sc, f"{name}_a_sc")
    _check_cuda_contiguous(b_fp4, f"{name}_b_fp4")
    _check_cuda_contiguous(b_sc, f"{name}_b_sc")
    if a_fp4.dtype != torch.float4_e2m1fn_x2 or b_fp4.dtype != torch.float4_e2m1fn_x2:
        raise ValueError(f"{name} MXFP4 GEMM expects float4_e2m1fn_x2 payloads")
    if a_sc.dtype != torch.uint8 or b_sc.dtype != torch.uint8:
        raise ValueError(f"{name} MXFP4 GEMM expects uint8 E8M0 scales")
    if a_fp4.ndim != 4 or b_fp4.ndim != 4:
        raise ValueError(f"{name} MXFP4 GEMM expects payloads shaped (B,H,rows,K/2)")
    batch, heads, m, packed_k = (int(v) for v in a_fp4.shape)
    if b_fp4.shape[:2] != (batch, heads) or int(b_fp4.shape[3]) != packed_k:
        raise ValueError(f"{name} B operand must share B/H/K with A")
    n = int(b_fp4.shape[2])
    k = packed_k * 2
    if m % _TILE != 0 or n % _TILE != 0 or k % _TILE != 0:
        raise ValueError(f"{name} MXFP4 GEMM dimensions must be multiples of 128")
    if tuple(a_sc.shape) != (batch, heads, m // _TILE, k // _TILE, 32, 16):
        raise ValueError(f"{name} A scales have wrong shape")
    if tuple(b_sc.shape) != (batch, heads, n // _TILE, k // _TILE, 32, 16):
        raise ValueError(f"{name} B scales have wrong shape")

    gemm = _load_tk_mxfp4_gemm()
    m_launch = _next_multiple(m, 256)
    n_launch = _next_multiple(n, 256)
    k_launch = _next_multiple(k, 256)
    packed_k_launch = k_launch // 2
    if out is None:
        out = torch.empty((batch, heads, m, n), device=a_fp4.device, dtype=torch.bfloat16)
    else:
        _check_cuda_contiguous(out, f"{name}_out")
        if out.dtype != torch.bfloat16 or tuple(out.shape) != (batch, heads, m, n):
            raise ValueError(f"{name} out must be BF16 with shape {(batch, heads, m, n)}")
    num_gemms = batch * heads
    if num_gemms == 1 and m_launch == m and n_launch == n and k_launch == k:
        with _cuda_device_ctx(a_fp4.device):
            single_config_value = None
            if name == "dK":
                single_config_value = os.environ.get("TK_FA4_MXFP4_BWD_DK_SINGLE_CONFIG_ID")
                if single_config_value is not None and single_config_value.strip().lower() in {"legacy", "off", "none"}:
                    single_config_value = None
            if single_config_value is not None:
                if not hasattr(gemm, "mxfp4_gemm_config"):
                    raise RuntimeError("TK MXFP4 GEMM extension is missing mxfp4_gemm_config")
                try:
                    single_config_id = int(single_config_value)
                except ValueError as exc:
                    raise ValueError("TK_FA4_MXFP4_BWD_DK_SINGLE_CONFIG_ID must be an integer in [0, 10]") from exc
                if single_config_id < 0 or single_config_id > 10:
                    raise ValueError("TK_FA4_MXFP4_BWD_DK_SINGLE_CONFIG_ID must be in [0, 10]")
                gemm.mxfp4_gemm_config(
                    a_fp4.view(m, packed_k),
                    a_sc.view(m // _TILE, k // _TILE, 32, 16),
                    b_fp4.view(n, packed_k),
                    b_sc.view(n // _TILE, k // _TILE, 32, 16),
                    out.view(m, n),
                    single_config_id,
                )
            else:
                gemm.mxfp4_gemm(
                    a_fp4.view(m, packed_k),
                    a_sc.view(m // _TILE, k // _TILE, 32, 16),
                    b_fp4.view(n, packed_k),
                    b_sc.view(n // _TILE, k // _TILE, 32, 16),
                    out.view(m, n),
                )
        return out
    if (
        num_gemms > 1
        and hasattr(gemm, "mxfp4_grouped_gemm_strided")
        and m_launch == m
        and n_launch == n
        and k_launch == k
        and m % (2 * _TILE) == 0
        and n % _TILE == 0
        and k % _TILE == 0
    ):
        a_flat = a_fp4.view(num_gemms * m, packed_k)
        a_sc_flat = a_sc.view(num_gemms * (m // _TILE), k // _TILE, 32, 16)
        b_flat = b_fp4.view(num_gemms * n, packed_k)
        b_sc_flat = b_sc.view(num_gemms * (n // _TILE), k // _TILE, 32, 16)
        with _cuda_device_ctx(a_fp4.device):
            gemm.mxfp4_grouped_gemm_strided(
                a_flat,
                a_sc_flat,
                b_flat,
                b_sc_flat,
                out.view(num_gemms * m, n),
                num_gemms,
                m,
                n,
                k,
                m,
                0,
                n,
                0,
                m,
                _mxfp4_grouped_config_id_for(name),
            )
        return out.contiguous()
    with _cuda_device_ctx(a_fp4.device):
        for b in range(batch):
            for h in range(heads):
                a_arg = a_fp4[b, h].contiguous()
                a_sc_arg = a_sc[b, h].contiguous()
                b_arg = b_fp4[b, h].contiguous()
                b_sc_arg = b_sc[b, h].contiguous()
                if m_launch != m or k_launch != k:
                    a_pad = _zeros_fp4((m_launch, packed_k_launch), a_fp4.device)
                    a_pad.view(torch.uint8)[:m, :packed_k].copy_(a_arg.view(torch.uint8))
                    a_sc_pad = torch.zeros((m_launch // _TILE, k_launch // _TILE, 32, 16), device=a_fp4.device, dtype=torch.uint8)
                    a_sc_pad[: m // _TILE, : k // _TILE].copy_(a_sc_arg)
                    a_arg = a_pad.contiguous()
                    a_sc_arg = a_sc_pad.contiguous()
                if n_launch != n or k_launch != k:
                    b_pad = _zeros_fp4((n_launch, packed_k_launch), b_fp4.device)
                    b_pad.view(torch.uint8)[:n, :packed_k].copy_(b_arg.view(torch.uint8))
                    b_sc_pad = torch.zeros((n_launch // _TILE, k_launch // _TILE, 32, 16), device=b_fp4.device, dtype=torch.uint8)
                    b_sc_pad[: n // _TILE, : k // _TILE].copy_(b_sc_arg)
                    b_arg = b_pad.contiguous()
                    b_sc_arg = b_sc_pad.contiguous()
                out_arg = out[b, h]
                if m_launch != m or n_launch != n:
                    out_arg = torch.empty((m_launch, n_launch), device=a_fp4.device, dtype=torch.bfloat16)
                gemm.mxfp4_gemm(a_arg, a_sc_arg, b_arg, b_sc_arg, out_arg)
                if m_launch != m or n_launch != n:
                    out[b, h].copy_(out_arg[:m, :n])
    return out.contiguous()


_MXFP4_CAUSAL_TILEMASK_CACHE: dict[tuple[int, int], torch.Tensor] = {}


def _causal_dk_tilemask(seqlen: int, device: torch.device) -> torch.Tensor:
    resolved = _normalize_cuda_device(device)
    if resolved.type != "cuda":
        raise ValueError(f"causal dK tilemask requires CUDA, got {resolved}")
    index = torch.cuda.current_device() if resolved.index is None else int(resolved.index)
    key = (int(seqlen), index)
    cached = _MXFP4_CAUSAL_TILEMASK_CACHE.get(key)
    if cached is not None:
        return cached
    tiles = int(seqlen) // _TILE
    with _cuda_device_ctx(torch.device("cuda", index)):
        idx = torch.arange(tiles, device=torch.device("cuda", index))
        mask = (idx[None, :] >= idx[:, None]).to(torch.uint8).contiguous()
    _MXFP4_CAUSAL_TILEMASK_CACHE[key] = mask
    return mask


def _mxfp4_grouped_causal_masked_gemm_supported(
    *,
    batch: int,
    heads: int,
    m: int,
    n: int,
    k: int,
) -> bool:
    gemm = _load_tk_mxfp4_gemm()
    return (
        batch * heads >= 1
        and hasattr(gemm, "mxfp4_grouped_gemm_strided_masked")
        and _next_multiple(m, 256) == m
        and _next_multiple(n, 256) == n
        and _next_multiple(k, 256) == k
        and m % (2 * _TILE) == 0
        and n % _TILE == 0
        and k % _TILE == 0
    )


def _use_mxfp4_causal_masked_dk_default(seqlen: int) -> bool:
    value = os.environ.get("TK_FA4_MXFP4_BWD_DK_CAUSAL_MASK")
    if value is None:
        if _use_mxfp4_bwd_single_live_ds_col_schedule_default():
            return False
        return int(seqlen) >= 2048
    return value.strip().lower() not in {
        "0",
        "false",
        "no",
        "off",
    }


def _use_mxfp4_bwd_dk_atbt_default(*, batch: int, heads: int, seqlen: int) -> bool:
    if _use_mxfp4_bwd_single_live_ds_col_schedule_default():
        return False
    value = os.environ.get("TK_FA4_MXFP4_BWD_DK_ATBT")
    if value is not None:
        return value.strip().lower() not in {
            "0",
            "false",
            "no",
            "off",
        }
    # The row-dS AtBT dK consumer is currently a diagnostic path: standalone
    # checks show the row-dS artifact is sane, but the TK AtBT contract maps
    # subtiles incorrectly for dK. Keep it opt-in until that contract is fixed.
    return False


def _use_mxfp4_bwd_dk_live_recompute_default() -> bool:
    value = os.environ.get("TK_FA4_MXFP4_BWD_DK_LIVE_RECOMPUTE")
    if value is None:
        return False
    return value.strip().lower() not in {
        "0",
        "false",
        "no",
        "off",
    }


def _use_mxfp4_bwd_transposed_ds_abt_dk_probe_default() -> bool:
    return _env_flag("TK_FA4_MXFP4_BWD_TRANSPOSED_DS_ABT_DK_PROBE")


def _mxfp4_bwd_materialized_p_synthetic_calibration_pattern_default() -> str:
    value = os.environ.get(
        "TK_FA4_MXFP4_BWD_MATERIALIZED_P_DS_SCAN_ABT_DK_SYNTHETIC_CALIBRATION_PATTERN",
        "all_ones",
    ).strip().lower()
    aliases = {
        "0": "all_ones",
        "all_ones": "all_ones",
        "1": "b_first_half_ones_second_half_zero",
        "b_first_half_ones_second_half_zero": "b_first_half_ones_second_half_zero",
        "2": "b_first_half_zero_second_half_ones",
        "b_first_half_zero_second_half_ones": "b_first_half_zero_second_half_ones",
        "3": "rank0_one_rank1_zero",
        "rank0_one_rank1_zero": "rank0_one_rank1_zero",
    }
    try:
        return aliases[value]
    except KeyError as exc:
        raise ValueError(
            "TK_FA4_MXFP4_BWD_MATERIALIZED_P_DS_SCAN_ABT_DK_SYNTHETIC_CALIBRATION_PATTERN "
            "must be one of all_ones, b_first_half_ones_second_half_zero, or "
            "b_first_half_zero_second_half_ones, or rank0_one_rank1_zero"
        ) from exc


def _mxfp4_bwd_materialized_p_synthetic_calibration_expected_reference_names(
    pattern: str,
) -> tuple[str, ...]:
    if pattern == "b_first_half_ones_second_half_zero":
        return (
            "synthetic_raw_b_first_half_direct_dcols0_32_128_dcols32_64_0",
            "synthetic_raw_b_first_half_swapped_dcols0_32_0_dcols32_64_128",
            "synthetic_raw_b_first_half_all_ones_control_expected128",
            "synthetic_raw_b_first_half_all_zero_control",
        )
    if pattern == "b_first_half_zero_second_half_ones":
        return (
            "synthetic_raw_b_second_half_direct_dcols0_32_0_dcols32_64_128",
            "synthetic_raw_b_second_half_swapped_dcols0_32_128_dcols32_64_0",
            "synthetic_raw_b_second_half_all_ones_control_expected128",
            "synthetic_raw_b_second_half_all_zero_control",
        )
    if pattern == "rank0_one_rank1_zero":
        return (
            "synthetic_rank0_one_rank1_zero_rows0_128_128_rows128_256_0",
            "synthetic_rank0_one_rank1_zero_swapped_rows0_128_0_rows128_256_128",
            "synthetic_rank0_one_rank1_zero_all_ones_control_expected128",
            "synthetic_rank0_one_rank1_zero_all_zero_control",
        )
    return (
        "synthetic_all_ones_direct_dcols0_32_128_dcols32_64_128",
        "synthetic_all_ones_swapped_dcols0_32_128_dcols32_64_128",
        "synthetic_all_ones_scale1_k128_expected128",
        "synthetic_all_ones_scale1_single_k64_expected64",
        "synthetic_all_ones_scale1_mxfp4_dequant_div6xdiv6_expected128_over36",
        "synthetic_all_ones_scale1_single_k64_div6xdiv6_expected64_over36",
    )


