    env_name = "TK_FA4_MXFP4_BWD_MATERIALIZED_P_DS_SCAN_ABT_DK_SYNTHETIC_Q_PAYLOAD_BYTE"
    value = os.environ.get(env_name, "0x22").strip().lower()
    try:
        parsed = int(value, 0)
    except ValueError as exc:
        raise ValueError(f"{env_name} must be a decimal or 0x-prefixed integer in [0,255]") from exc
