def _mxfp4_bwd_materialized_p_full128_selected_row_contract(
    *,
    batch: int,
    heads: int,
    seqlen: int,
) -> tuple[bool, str | None]:
    selected_row_env = os.environ.get("TK_FA4_MXFP4_LIVE_DP_SELECTED_ROW_TILE")
    if selected_row_env is None:
        return False, "missing TK_FA4_MXFP4_LIVE_DP_SELECTED_ROW_TILE"
    try:
        selected_row_tile = int(selected_row_env)
    except ValueError:
        return False, "TK_FA4_MXFP4_LIVE_DP_SELECTED_ROW_TILE must be an integer"
    if int(batch) != 1 or int(heads) != 1:
        return False, "selected-row full128 requires B=1,H=1"
    if int(seqlen) % 128 != 0:
        return False, "selected-row full128 requires seqlen divisible by 128"
    row_tiles = int(seqlen) // 128
    if selected_row_tile < 0 or selected_row_tile >= row_tiles:
        return False, "selected row tile is outside the sequence tile range"
    selected_row_cluster_base = _selected_row_tile_cluster_base(selected_row_tile)
    if selected_row_cluster_base + _FP4PV_CLUSTER_SIZE > row_tiles:
        return False, "selected row tile does not have a complete two-CTA cluster"
    selected_head_env = os.environ.get("TK_FA4_MXFP4_LIVE_DP_SELECTED_HEAD")
    if selected_head_env is not None:
        try:
            selected_head = int(selected_head_env)
        except ValueError:
            return False, "TK_FA4_MXFP4_LIVE_DP_SELECTED_HEAD must be an integer"
        if selected_head != 0:
            return False, "selected-row full128 requires selected head 0 for H=1"
    return True, None


def _mxfp4_bwd_materialized_p_ds_scan_probe_metadata(
    enabled: bool,
    *,
    cached_p_path_enabled: bool = False,
    downstream_consumer_probe_requested: bool = False,
    downstream_mxfp4_tmem_consumer_enabled: bool = False,
    downstream_deferred_tcgen05_probe_requested: bool = False,
    downstream_partial_store_probe_requested: bool = False,
    downstream_zero_only_store_probe_requested: bool = False,
    downstream_real_kiter_accum_probe_requested: bool = False,
    downstream_synthetic_calibration_probe_requested: bool = False,
    downstream_synthetic_calibration_pattern: str = "all_ones",
    downstream_synthetic_d_read_pattern: str = "normal",
    downstream_synthetic_issue_pattern: str = "normal",
    downstream_synthetic_cta_rank_pattern: str = "rank0_only",
    downstream_synthetic_cta_sem_pattern: str = "shared_current",
    downstream_synthetic_fill_all_ctas_before_issue: bool = False,
    downstream_synthetic_d_prefill_pattern: str = "zero",
    downstream_synthetic_d_target_pattern: str = "tail64_current",
    downstream_synthetic_mixed_operand_pattern: str = "none",
    downstream_synthetic_q_payload_byte: int = 0x22,
    downstream_synthetic_b_scale_tmem_pattern: str = "normal",
    downstream_tail64_b_view_pattern: str = "direct",
    downstream_q_col_chunk_pattern: str = "chunk0",
    downstream_real_kiter_accum_max_k_iters: int = 0,
    downstream_real_kiter_accum_start_k_iter_offset: int = 0,
    downstream_real_kiter_accum_source_k_iter_offset: int = -1,
    downstream_real_kiter_accum_slot_mode: str = "both",
    downstream_real_kiter_accum_clear_each_issue_probe: bool = False,
    downstream_real_kiter_accum_pingpong_ds_probe: bool = False,
    downstream_real_kiter_accum_pingpong_issue_cta_wait_probe: bool = False,
    downstream_real_kiter_accum_stage_audit_probe: bool = False,
    downstream_real_kiter_accum_descriptor_audit_probe: bool = False,
    downstream_real_kiter_accum_zero_a_at_issue_probe: bool = False,
    downstream_real_kiter_accum_zero_b_at_issue_probe: bool = False,
    downstream_real_kiter_accum_scale_kill_at_issue_probe: bool = False,
    downstream_real_kiter_accum_scale_tmem_kill_after_load_probe: bool = False,
    downstream_real_kiter_accum_split_vs_oneshot_abt_probe: bool = False,
    downstream_real_kiter_accum_no_issue_probe: bool = False,
    downstream_real_kiter_accum_direct_store_mode: str = "normal",
    downstream_real_kiter_accum_readback_self_prefill_mode: str = "normal",
    downstream_real_kiter_accum_pre_store_exact_clear_probe: bool = False,
    downstream_real_kiter_accum_pre_issue_exact_clear_probe: bool = False,
    downstream_real_kiter_accum_post_issue_exact_clear_probe: bool = False,
    downstream_real_kiter_accum_readback_internal_exact_clear_after_issue_probe: bool = False,
    downstream_selected_row_full128_contract: bool = False,
    downstream_selected_row_full128_contract_reason: str | None = None,
) -> dict[str, object]:
    blocker = None
    if enabled and not cached_p_path_enabled:
        blocker = (
            "materialized MXFP4 P dS scan probe was requested, but the cached-P "
            "Python path is not explicitly enabled. Set "
            "TK_FA4_MXFP4_BWD_MATERIALIZED_P_DS_SCAN_USE_CACHED_P=1 to run the "
            "cached-P wrapper."
        )
    elif enabled and downstream_real_kiter_accum_probe_requested:
        blocker = (
            "materialized-P ABt dK real-k_iter accumulation uses a slow debug-only "
            "per-k_iter completion boundary: every valid causal dS_col tile is staged, "
            "issued through the tail64 ABt helper, waited before shared A/B reuse, and "
            "accumulated into one post-store debug TMEM tile. This proves operand "
            "lifetime for real inputs but is still not production dK: rows are stored "
            "at the current debug m_tile coordinate and DK_pad_out ownership/reduction "
            "is still disabled. A positive MAX_K_ITERS debug cap restricts this to the "
            "first N valid causal k_iters for completion-boundary bisection. "
            "START_K_ITER_OFFSET is a cap-2 ping-pong pair selector used to run "
            "a later physical pair such as k2+k3 into a fresh accumulator. "
            "SOURCE_K_ITER_OFFSET optionally overrides the physical dS_col source "
            "pair while preserving the START_K_ITER_OFFSET control path, so control "
            "versus source/operand semantics can be crossed directly. "
            "CLEAR_EACH_ISSUE is diagnostic-only: it forces CLEAR_ACC=true for every "
            "local k_iter and overwrites the accumulator, so it is not an all-k "
            "correctness path. PINGPONG_DS is a cap-2/cap-4 diagnostic-only path: "
            "it stages k-pairs in separate dS payload/scale shared slots, separate "
            "dS scale TMEM slots, and separate completion semaphores before waiting "
            "for each pair. "
            "PINGPONG_ISSUE_CTA_WAIT restricts waits/readback to the shared-current "
            "issue CTA for wait-ownership diagnosis. ZERO_A_AT_ISSUE mutates the "
            "staged A/dS payload to the local MXFP4 zero word immediately before "
            "issue, and the stage audit records post-zero payload mismatch counts. "
            "ZERO_B_AT_ISSUE mutates the staged B/Q_col payload to the local MXFP4 "
            "zero word at the same issue-site boundary, reusing the stage-audit "
            "post-zero payload mismatch lane with a distinct marker. "
            "SCALE_KILL_AT_ISSUE mutates the staged dS_col and Q_col E8M0 scale "
            "tiles to byte zero immediately before the normal scale-TMEM load and "
            "split-K64 issue; the stage audit records post-kill DS/Q scale byte "
            "mismatch counts. "
            "SCALE_TMEM_KILL_AFTER_LOAD overwrites the actual dS_col/Q_col E8M0 "
            "scale TMEM operands after fp4pv_load_mxnv_scale_async_cluster and "
            "tensor_load_wait, immediately before the split-K64 issue. "
            "NO_ISSUE skips the split-K64 TCGEN05 issue/wait while preserving the "
            "same D accumulator prefill plus partial-store/readback path, so stale "
            "D/readback can be separated from A descriptor consumption. "
            "READBACK_INTERNAL_EXACT_CLEAR_AFTER_ISSUE clears the exact tcgen05.ld "
            "source addresses inside the partial-debug readback helper immediately "
            "before the issued-path load, separating caller-side D address mismatch "
            "from helper participation/readback ownership."
        )
    elif enabled and downstream_consumer_probe_requested:
        blocker = (
            "materialized-P dS scan -> MXFP4 ABt dK consumer probe has same-scope "
            "dS_col scan plus Q_col payload/scale typed contract diagnostics wired "
            "through the cached-P Q-col contract entrypoint and globals. A typed "
            "no-store ABt issue scaffold now stages the populated fp4pv_p_scan3d "
            "into a dedicated local dS_col shared payload/scale tile that does not "
            "clobber the row-dS live-dQ stage, stages Q_col chunk0 into a "
            "dedicated local shared payload tile for the B operand, and stages "
            "the matching Q_col E8M0 scale tile into a private tail64 TMEM scale "
            "slot. The private dK completion semaphore is wired. The current "
            "live-dP/dQ tail64 TMEM layout has no non-overlapping 64-column float "
            "dK accumulator slot after preserving dQ output, live-dP scale, and "
            "Q_col scale ownership. The shape-correct temporal reuse candidate is "
            "the dQ tail64 output slot. A private post-dQ-store reuse handoff "
            "marker is now wired at the tail64 dQ store-drain point, but no "
            "consumer waits on it yet. The post-store tail64 slot is now named "
            "as an inert 128x64 float dK accumulator TMEM tile, with no clear, "
            "write, wait, MMA issue, or dK store. Post-store operand availability "
            "is now proved from durable global dS_col and already-threaded Q_col "
            "sources into typed local shared/TMEM destinations, without assuming "
            "the earlier producer-hook shared stages survive. Post-store phase "
            "tracking now records the completed causal k_iter replay range and "
            "representative first/last dS_col/Q_col source addresses without "
            "loading operands or waiting on a cross-warpgroup handoff. "
            "Post-store first-valid-k_iter operand re-stage now reloads dS_col "
            "payload/scale and Q_col chunk0 payload/scale from those durable "
            "sources into local shared/TMEM operand destinations after the "
            "tail64 dQ store. The first-valid-k_iter TCGEN05 ABt issue shape is "
            "compile-clean with the reused post-store dQ P-scale TMEM slot for "
            "dS_col scales, the Q_col chunk0 tail64-compatible B view, and the "
            "private dead-tail64 dK accumulator alias. The actual "
            "fp4pv_p_stage_ABt_k64_chunk issue and wait(dk_done_sem, ...) are "
            "runtime-disabled because the bounded S=512 opt-in smoke timed out "
            "waiting on the private dK completion semaphore at this post-store "
            "hook. Existing finite BWD TCGEN05 users issue from an elected "
            "leader lane and defer semaphore waits to a later reuse or consumer "
            "phase, while the failed post-store attempt used an immediate "
            "same-hook private completion wait. No bounded runtime micro-probe "
            "is enabled by the default consumer-probe env. A separate opt-in "
            "deferred TCGEN05 probe env attempts one first-valid-k tail64 issue "
            "from the elected lane and defers the private completion wait to the "
            "next store-warpgroup tile-reuse point or loop drain. The path "
            "remains blocked on proving that runtime probe finite before dK "
            "store plus all-k_iter reduction."
        )
    elif enabled and not downstream_mxfp4_tmem_consumer_enabled:
        blocker = (
            "materialized MXFP4 P dS scan probe only validates the row-owned "
            "P -> dS -> fp4pv_p_scan3d handoff. It still needs live TMEM or "
            "explicit BF16 dP and is not a full-backward performance candidate "
            "until a downstream MXFP4/TMEM consumer reuses the scan directly."
        )
