def _mxfp4_bwd_materialized_p_ds_scan_abt_dk_real_kiter_accum_max_k_iters_default() -> int:
    raw = os.environ.get(
        "TK_FA4_MXFP4_BWD_MATERIALIZED_P_DS_SCAN_ABT_DK_REAL_KITER_ACCUM_MAX_K_ITERS",
        "0",
    )
