def _mxfp4_bwd_materialized_p_ds_scan_abt_dk_real_kiter_accum_slot_mode_default() -> str:
    raw = os.environ.get(
        "TK_FA4_MXFP4_BWD_MATERIALIZED_P_DS_SCAN_ABT_DK_REAL_KITER_ACCUM_SLOT_MODE",
        "both",
    )
    value = str(raw).strip().lower().replace("-", "_")
    aliases = {
        "0": "both",
        "both": "both",
        "1": "slot0_only",
        "slot0": "slot0_only",
        "slot0_only": "slot0_only",
        "2": "slot1_only",
        "slot1": "slot1_only",
        "slot1_only": "slot1_only",
        "3": "slot1_via_slot0",
        "slot1_as_slot0": "slot1_via_slot0",
        "slot1_via_slot0": "slot1_via_slot0",
    }
    return aliases.get(value, value)


