def _mxfp4_bwd_full_rewrite_mode_normalized() -> str | None:
    mode = os.environ.get("TK_FA4_MXFP4_BWD_FULL_REWRITE")
    if mode is None:
        return None
    return mode.strip().lower()


def _use_mxfp4_bwd_auto_schedule_mode() -> bool:
    mode = _mxfp4_bwd_full_rewrite_mode_normalized()
    return mode in _MXFP4_BWD_AUTO_SCHEDULE_MODES


def _mxfp4_bwd_auto_single_live_ds_col_max_seqlen() -> int:
    raw = os.environ.get("TK_FA4_MXFP4_BWD_AUTO_SINGLE_DS_COL_MAX_SEQLEN", "16384")
    try:
        value = int(raw.strip(), 10)
    except ValueError as exc:
        raise ValueError(
            "TK_FA4_MXFP4_BWD_AUTO_SINGLE_DS_COL_MAX_SEQLEN must be an integer"
        ) from exc
    if value < 0:
        raise ValueError("TK_FA4_MXFP4_BWD_AUTO_SINGLE_DS_COL_MAX_SEQLEN must be non-negative")
    return value


def _mxfp4_bwd_auto_row_atbt_min_seqlen() -> int:
    raw = os.environ.get("TK_FA4_MXFP4_BWD_AUTO_ROW_ATBT_MIN_SEQLEN", "4096")
    try:
        value = int(raw.strip(), 10)
    except ValueError as exc:
        raise ValueError(
            "TK_FA4_MXFP4_BWD_AUTO_ROW_ATBT_MIN_SEQLEN must be an integer"
        ) from exc
    if value < 0:
        raise ValueError("TK_FA4_MXFP4_BWD_AUTO_ROW_ATBT_MIN_SEQLEN must be non-negative")
    return value


def _resolve_mxfp4_bwd_auto_full_rewrite_mode(*, seqlen: int) -> str | None:
    mode = _mxfp4_bwd_full_rewrite_mode_normalized()
    if mode is None:
        return None
    row_atbt_min_seqlen = _mxfp4_bwd_auto_row_atbt_min_seqlen()
    if mode in _MXFP4_BWD_AUTO_SCHEDULE_MODES and row_atbt_min_seqlen and int(seqlen) >= row_atbt_min_seqlen:
        return "0"
    if int(seqlen) <= _mxfp4_bwd_auto_single_live_ds_col_max_seqlen():
        if mode in _MXFP4_BWD_AUTO_SCHEDULE_MODES:
            return "single_live_ds_col"
        if mode in _MXFP4_BWD_BOOL_TRUE_MODES and _env_flag(
            "TK_FA4_MXFP4_BWD_FULL_REWRITE_SINGLE_DS_COL_DEFAULT",
            True,
        ):
            return "single_live_ds_col"
    if mode in _MXFP4_BWD_AUTO_SCHEDULE_MODES:
        return "key_owned_schedule"
    return None


def _use_mxfp4_bwd_single_live_ds_col_schedule_default() -> bool:
    mode = _mxfp4_bwd_full_rewrite_mode_normalized()
    if mode is None:
        return False
    return mode in _MXFP4_BWD_SINGLE_LIVE_DS_COL_MODES or mode in _MXFP4_BWD_AUTO_SCHEDULE_MODES


