def _resolve_mxfp4_bwd_shape_p_quant_mode(
    p_quant_mode: str | None,
    *,
    batch: int,
    heads: int,
    seqlen: int,
) -> str | None:
    if p_quant_mode is not None:
        return p_quant_mode
    if (
        _env_flag("TK_FA4_MXFP4_BWD_DECODE_S1024H4_GUARD_FIX", True)
        and int(batch) == 1
        and int(heads) == 4
        and int(seqlen) == 1024
    ):
        return "decode"
    if (
        _env_flag("TK_FA4_MXFP4_BWD_DECODE_S2048_LONG_GUARD_FIX", True)
        and int(batch) == 1
        and int(heads) in {1, 2}
        and int(seqlen) == 2048
    ):
        return "decode"
    return None


def _use_mxfp4_bwd_overlap_dv_default(*, batch: int, heads: int, seqlen: int) -> bool:
    value = os.environ.get("TK_FA4_MXFP4_BWD_OVERLAP_DV")
    if value is None:
        resolved_mode = _resolve_mxfp4_bwd_auto_full_rewrite_mode(seqlen=seqlen)
        default_or_single_live_ds_col = (
            _mxfp4_bwd_full_rewrite_mode_normalized() is None
            or _use_mxfp4_bwd_single_live_ds_col_schedule_default()
            or resolved_mode in _MXFP4_BWD_SINGLE_LIVE_DS_COL_MODES
        )
        if default_or_single_live_ds_col:
            return int(seqlen) <= 4096
        # dV is independent after dO column quantization. The staged row-dS
        # path only amortizes overlap reliably at larger sequence lengths; on
        # B=1,H=1 it loses at 2K/4K and wins at 8K.
        return (
            int(seqlen) == 512
            or int(seqlen) >= 8192
            or (int(batch) == 1 and int(heads) == 16 and int(seqlen) == 1024)
        )
    return value.strip().lower() not in {
        "0",
        "false",
        "no",
        "off",
    }


def _resolve_mxfp4_bwd_dv_pv_issue_mode(pv_issue_mode: int | str | None, *, batch: int, heads: int, seqlen: int) -> int:
    resolved = _resolve_mxfp4_dv_pv_issue_mode(pv_issue_mode, seqlen)
    auto_requested = pv_issue_mode is None or (
        isinstance(pv_issue_mode, str) and pv_issue_mode.lower() in {"auto", "production"}
    )
    if auto_requested and int(batch) == 1 and int(heads) == 16 and int(seqlen) == 512:
        return 393
    if auto_requested and int(batch) == 1 and int(heads) == 1 and int(seqlen) == 4096:
        return 128
    return resolved


