def _mxfp4_bh_gemm_causal_masked(
    a_fp4: torch.Tensor,
    a_sc: torch.Tensor,
    b_fp4: torch.Tensor,
    b_sc: torch.Tensor,
    *,
    name: str,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    _check_cuda_contiguous(a_fp4, f"{name}_a_fp4")
    _check_cuda_contiguous(a_sc, f"{name}_a_sc")
    _check_cuda_contiguous(b_fp4, f"{name}_b_fp4")
    _check_cuda_contiguous(b_sc, f"{name}_b_sc")
    batch, heads, m, packed_k = (int(v) for v in a_fp4.shape)
    n = int(b_fp4.shape[2])
    k = packed_k * 2
    gemm = _load_tk_mxfp4_gemm()
    if not _mxfp4_grouped_causal_masked_gemm_supported(
        batch=batch,
        heads=heads,
        m=m,
        n=n,
        k=k,
    ):
        return _mxfp4_bh_gemm(a_fp4, a_sc, b_fp4, b_sc, name=name, out=out)
    _check_mxfp4_gemm_artifact(a_fp4, a_sc, name=f"{name}_a", batch=batch, heads=heads, rows=m, cols=k)
    _check_mxfp4_gemm_artifact(b_fp4, b_sc, name=f"{name}_b", batch=batch, heads=heads, rows=n, cols=k)
    num_gemms = batch * heads
    if out is None:
        out = torch.empty((batch, heads, m, n), device=a_fp4.device, dtype=torch.bfloat16)
    else:
        _check_cuda_contiguous(out, f"{name}_out")
        if out.dtype != torch.bfloat16 or tuple(out.shape) != (batch, heads, m, n):
            raise ValueError(f"{name} out must be BF16 with shape {(batch, heads, m, n)}")
    mask = _causal_dk_tilemask(m, a_fp4.device)
    with _cuda_device_ctx(a_fp4.device):
        gemm.mxfp4_grouped_gemm_strided_masked(
            a_fp4.view(num_gemms * m, packed_k),
            a_sc.view(num_gemms * (m // _TILE), k // _TILE, 32, 16),
            b_fp4.view(num_gemms * n, packed_k),
            b_sc.view(num_gemms * (n // _TILE), k // _TILE, 32, 16),
            mask,
            False,
            out.view(num_gemms * m, n),
            num_gemms,
            m,
            n,
            k,
            m,
            0,
            n,
            0,
            m,
            _mxfp4_grouped_config_id_for(name),
        )
    return out


def _mxfp4_transposed_ds_abt_dk_probe(
    ds_col_fp4: torch.Tensor,
    ds_col_sc: torch.Tensor,
    q_col_fp4: torch.Tensor,
    q_col_sc: torch.Tensor,
    *,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    """Compute dK_pad = dS_col @ Q_col^T using the MXFP4 ABt GEMM path.

    Store/accumulation contract: the dQ producer emits ``ds_col_*`` as the
    transposed score-gradient artifact with rows owned by K positions and K
    dimension owned by Q positions.  ``q_col_*`` has 256 padded rows: the first
    192 columns of the BF16 output are the real dK head dimension and the final
    64 columns are padding retained for tensorcore shape compatibility.
    """
    batch, heads, seqlen, packed_cols = (int(v) for v in ds_col_fp4.shape)
    if packed_cols != seqlen // 2:
        raise ValueError("dS_col payload must have shape (B,H,S,S/2)")
    _check_mxfp4_gemm_artifact(
        ds_col_fp4,
        ds_col_sc,
        name="transposed_ds_abt_dk_probe_ds_col",
        batch=batch,
        heads=heads,
        rows=seqlen,
        cols=seqlen,
    )
    _check_mxfp4_gemm_artifact(
        q_col_fp4,
        q_col_sc,
        name="transposed_ds_abt_dk_probe_q_col",
        batch=batch,
        heads=heads,
        rows=_D_QK_GEMM_PAD,
        cols=seqlen,
    )
    return _mxfp4_bh_gemm(
        ds_col_fp4,
        ds_col_sc,
        q_col_fp4,
        q_col_sc,
        name="dK",
        out=out,
    )


def _mxfp4_bh_gemm_atbt(
    a_fp4: torch.Tensor,
    a_sc: torch.Tensor,
    b_fp4: torch.Tensor,
    b_sc: torch.Tensor,
    *,
    name: str,
    out: torch.Tensor | None = None,
    causal_masked: bool = False,
) -> torch.Tensor:
    _check_cuda_contiguous(a_fp4, f"{name}_a_fp4")
    _check_cuda_contiguous(a_sc, f"{name}_a_sc")
    _check_cuda_contiguous(b_fp4, f"{name}_b_fp4")
    _check_cuda_contiguous(b_sc, f"{name}_b_sc")
    if a_fp4.dtype != torch.float4_e2m1fn_x2 or b_fp4.dtype != torch.float4_e2m1fn_x2:
        raise ValueError(f"{name} MXFP4 AtBt GEMM expects float4_e2m1fn_x2 payloads")
    if a_sc.dtype != torch.uint8 or b_sc.dtype != torch.uint8:
        raise ValueError(f"{name} MXFP4 AtBt GEMM expects uint8 E8M0 scales")
    if a_fp4.ndim != 4 or b_fp4.ndim != 4:
        raise ValueError(f"{name} MXFP4 AtBt GEMM expects payloads shaped (B,H,rows,K/2)")
    batch, heads, red, packed_m = (int(v) for v in a_fp4.shape)
    if b_fp4.shape[:2] != (batch, heads) or int(b_fp4.shape[3]) != red // 2:
        raise ValueError(f"{name} B operand must have shape (B,H,N,A_rows/2)")
    m = packed_m * 2
    n = int(b_fp4.shape[2])
    if red % _TILE != 0 or m % _TILE != 0 or n % _TILE != 0:
        raise ValueError(f"{name} MXFP4 AtBt GEMM dimensions must be multiples of 128")
    if tuple(a_sc.shape) != (batch, heads, red // _TILE, m // _TILE, 32, 16):
        raise ValueError(f"{name} A scales have wrong shape")
    if tuple(b_sc.shape) != (batch, heads, n // _TILE, red // _TILE, 32, 16):
        raise ValueError(f"{name} B scales have wrong shape")

    gemm = _load_tk_mxfp4_gemm()
    if not hasattr(gemm, "mxfp4_gemm_atbt"):
        raise RuntimeError(
            "TK MXFP4 GEMM extension is missing mxfp4_gemm_atbt; rebuild ThunderKittens/kernels/gemm/mxfp4_gb200"
        )
    red_launch = _next_multiple(red, 256)
    m_launch = _next_multiple(m, 256)
    n_launch = _next_multiple(n, 256)
    if out is None:
        out = torch.empty((batch, heads, m, n), device=a_fp4.device, dtype=torch.bfloat16)
    else:
        _check_cuda_contiguous(out, f"{name}_out")
        if out.dtype != torch.bfloat16 or tuple(out.shape) != (batch, heads, m, n):
            raise ValueError(f"{name} out must be BF16 with shape {(batch, heads, m, n)}")
    num_gemms = batch * heads
    if (
        num_gemms > 1
        and hasattr(gemm, "mxfp4_grouped_gemm_atbt_strided")
        and red_launch == red
        and m_launch == m
        and n_launch == n
    ):
        with _cuda_device_ctx(a_fp4.device):
            if causal_masked and hasattr(gemm, "mxfp4_grouped_gemm_atbt_strided_masked") and red == n:
                mask = _causal_dk_tilemask(n, a_fp4.device)
                gemm.mxfp4_grouped_gemm_atbt_strided_masked(
                    a_fp4.view(num_gemms * red, packed_m),
                    a_sc.view(num_gemms * (red // _TILE), m // _TILE, 32, 16),
                    b_fp4.view(num_gemms * n, red // 2),
                    b_sc.view(num_gemms * (n // _TILE), red // _TILE, 32, 16),
                    mask,
                    False,
                    out.view(num_gemms * m, n),
                    num_gemms,
                    m,
                    n,
                    red,
                    red,
                    0,
                    n,
                    0,
                    m,
                    _mxfp4_grouped_config_id_for(
                        name,
                        op="atbt",
                        batch=batch,
                        heads=heads,
                        m=m,
                        n=n,
                        red=red,
                    ),
                )
            else:
                gemm.mxfp4_grouped_gemm_atbt_strided(
                    a_fp4.view(num_gemms * red, packed_m),
                    a_sc.view(num_gemms * (red // _TILE), m // _TILE, 32, 16),
                    b_fp4.view(num_gemms * n, red // 2),
                    b_sc.view(num_gemms * (n // _TILE), red // _TILE, 32, 16),
                    out.view(num_gemms * m, n),
                    num_gemms,
                    m,
                    n,
                    red,
                    red,
                    0,
                    n,
                    0,
                    m,
                    _mxfp4_grouped_config_id_for(
                        name,
                        op="atbt",
                        batch=batch,
                        heads=heads,
                        m=m,
                        n=n,
                        red=red,
                    ),
                )
        return out.contiguous()
    with _cuda_device_ctx(a_fp4.device):
        for b in range(batch):
            for h in range(heads):
                a_arg = a_fp4[b, h].contiguous()
                a_sc_arg = a_sc[b, h].contiguous()
                b_arg = b_fp4[b, h].contiguous()
                b_sc_arg = b_sc[b, h].contiguous()
                if red_launch != red or m_launch != m:
                    a_pad = _zeros_fp4((red_launch, m_launch // 2), a_fp4.device)
                    _copy_fp4_tensor_(a_pad[:red, : packed_m], a_arg)
                    a_sc_pad = torch.zeros(
                        (red_launch // _TILE, m_launch // _TILE, 32, 16),
                        device=a_fp4.device,
                        dtype=torch.uint8,
                    )
                    a_sc_pad[: red // _TILE, : m // _TILE].copy_(a_sc_arg)
                    a_arg = a_pad.contiguous()
                    a_sc_arg = a_sc_pad.contiguous()
                if n_launch != n or red_launch != red:
                    b_pad = _zeros_fp4((n_launch, red_launch // 2), b_fp4.device)
                    _copy_fp4_tensor_(b_pad[:n, : red // 2], b_arg)
                    b_sc_pad = torch.zeros(
                        (n_launch // _TILE, red_launch // _TILE, 32, 16),
                        device=b_fp4.device,
                        dtype=torch.uint8,
                    )
                    b_sc_pad[: n // _TILE, : red // _TILE].copy_(b_sc_arg)
                    b_arg = b_pad.contiguous()
                    b_sc_arg = b_sc_pad.contiguous()
                out_pad = torch.empty((m_launch, n_launch), device=a_fp4.device, dtype=torch.bfloat16)
                gemm.mxfp4_gemm_atbt(a_arg, a_sc_arg, b_arg, b_sc_arg, out_pad)
                out[b, h].copy_(out_pad[:m, :n])
    return out.contiguous()


def _mxfp4_bh_gemm_k128(
    a_fp4: torch.Tensor,
    a_sc: torch.Tensor,
    b_fp4: torch.Tensor,
    b_sc: torch.Tensor,
    *,
    name: str,
    output_causal: bool = False,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    _check_cuda_contiguous(a_fp4, f"{name}_a_fp4")
    _check_cuda_contiguous(a_sc, f"{name}_a_sc")
    _check_cuda_contiguous(b_fp4, f"{name}_b_fp4")
    _check_cuda_contiguous(b_sc, f"{name}_b_sc")
    if a_fp4.dtype != torch.float4_e2m1fn_x2 or b_fp4.dtype != torch.float4_e2m1fn_x2:
        raise ValueError(f"{name} MXFP4 GEMM expects float4_e2m1fn_x2 payloads")
    if a_sc.dtype != torch.uint8 or b_sc.dtype != torch.uint8:
        raise ValueError(f"{name} MXFP4 GEMM expects uint8 E8M0 scales")
    if a_fp4.ndim != 4 or b_fp4.ndim != 4:
        raise ValueError(f"{name} MXFP4 GEMM expects payloads shaped (B,H,rows,K/2)")
    batch, heads, m, packed_k = (int(v) for v in a_fp4.shape)
    if b_fp4.shape[:2] != (batch, heads) or int(b_fp4.shape[3]) != packed_k:
        raise ValueError(f"{name} B operand must share B/H/K with A")
    n = int(b_fp4.shape[2])
    k = packed_k * 2
    if k != _D_VO:
        raise ValueError(f"{name} prototype is wired for K={_D_VO}")
    if a_sc.shape != (batch, heads, m // _TILE, k // _TILE, 32, 16):
        raise ValueError(f"{name} A scales have wrong shape")
    if b_sc.shape != (batch, heads, n // _TILE, k // _TILE, 32, 16):
        raise ValueError(f"{name} B scales have wrong shape")
    if out is None:
        out = torch.empty((batch, heads, m, n), device=a_fp4.device, dtype=torch.bfloat16)
    else:
        _check_cuda_contiguous(out, f"{name}_out")
        if out.dtype != torch.bfloat16 or tuple(out.shape) != (batch, heads, m, n):
            raise ValueError(f"{name} out must be BF16 with shape {(batch, heads, m, n)}")
    gemm = _load_tk_mxfp4_gemm()
    supports_output_causal = output_causal and hasattr(gemm, "mxfp4_gemm_k128_output_causal")
    supports_grouped_output_causal = output_causal and hasattr(gemm, "mxfp4_grouped_gemm_strided_output_causal")
    m_launch = _next_multiple(m, 256)
    n_launch = _next_multiple(n, 256)
    num_gemms = batch * heads
    if num_gemms == 1 and m_launch == m and n_launch == n:
        gemm_entry = (
            gemm.mxfp4_gemm_k128_output_causal
            if supports_output_causal
            else gemm.mxfp4_gemm_k128
        )
        with _cuda_device_ctx(a_fp4.device):
            gemm_entry(
                a_fp4.view(m, packed_k),
                a_sc.view(m // _TILE, k // _TILE, 32, 16),
                b_fp4.view(n, packed_k),
                b_sc.view(n // _TILE, k // _TILE, 32, 16),
                out.view(m, n),
            )
        return out
    if (
        ((not output_causal) or supports_grouped_output_causal)
        and num_gemms > 1
        and hasattr(gemm, "mxfp4_grouped_gemm_strided")
        and m_launch == m
        and n_launch == n
        and m % (2 * _TILE) == 0
        and n % _TILE == 0
    ):
        a_flat = a_fp4.view(num_gemms * m, packed_k)
        a_sc_flat = a_sc.view(num_gemms * (m // _TILE), k // _TILE, 32, 16)
        b_flat = b_fp4.view(num_gemms * n, packed_k)
        b_sc_flat = b_sc.view(num_gemms * (n // _TILE), k // _TILE, 32, 16)
        with _cuda_device_ctx(a_fp4.device):
            grouped_gemm = (
                gemm.mxfp4_grouped_gemm_strided_output_causal
                if supports_grouped_output_causal
                else gemm.mxfp4_grouped_gemm_strided
            )
            grouped_gemm(
                a_flat,
                a_sc_flat,
                b_flat,
                b_sc_flat,
                out.view(num_gemms * m, n),
                num_gemms,
                m,
                n,
                k,
                m,
                0,
                n,
                0,
                m,
                _MXFP4_PV_GROUPED_CONFIG_ID,
            )
        return out.contiguous()
    with _cuda_device_ctx(a_fp4.device):
        for b in range(batch):
            for h in range(heads):
                a_arg = a_fp4[b, h].contiguous()
                a_sc_arg = a_sc[b, h].contiguous()
                b_arg = b_fp4[b, h].contiguous()
                b_sc_arg = b_sc[b, h].contiguous()
                out_arg = out[b, h]
                if m_launch != m:
                    a_pad = _zeros_fp4((m_launch, packed_k), a_fp4.device)
                    a_sc_pad = torch.zeros((m_launch // _TILE, k // _TILE, 32, 16), device=a_fp4.device, dtype=torch.uint8)
                    _copy_fp4_tensor_(a_pad[:m], a_arg)
                    a_sc_pad[: m // _TILE].copy_(a_sc_arg)
                    a_arg = a_pad.contiguous()
                    a_sc_arg = a_sc_pad.contiguous()
                if n_launch != n:
                    b_pad = _zeros_fp4((n_launch, packed_k), b_fp4.device)
                    b_sc_pad = torch.zeros((n_launch // _TILE, k // _TILE, 32, 16), device=b_fp4.device, dtype=torch.uint8)
                    _copy_fp4_tensor_(b_pad[:n], b_arg)
                    b_sc_pad[: n // _TILE].copy_(b_sc_arg)
                    b_arg = b_pad.contiguous()
                    b_sc_arg = b_sc_pad.contiguous()
                if m_launch != m or n_launch != n:
                    out_pad = torch.empty((m_launch, n_launch), device=a_fp4.device, dtype=torch.bfloat16)
                    out_arg = out_pad
                gemm_entry = (
                    gemm.mxfp4_gemm_k128_output_causal
                    if supports_output_causal
                    else gemm.mxfp4_gemm_k128
                )
                gemm_entry(
                    a_arg,
                    a_sc_arg,
                    b_arg,
                    b_sc_arg,
                    out_arg,
                )
                if m_launch != m or n_launch != n:
                    out[b, h].copy_(out_arg[:m, :n])
    return out.contiguous()


def _use_mxfp4_bwd_dp_causal_output_default() -> bool:
    value = os.environ.get("TK_FA4_MXFP4_BWD_DP_CAUSAL_OUTPUT")
    if value is None:
        return False
    return value.strip().lower() not in {
        "0",
        "false",
        "no",
        "off",
    }


def _mxfp4_bwd_dq_stage_cut_default(
    *,
    batch: int | None = None,
    heads: int | None = None,
    seqlen: int | None = None,
) -> int:
    value = os.environ.get("TK_FA4_MXFP4_BWD_DQ_STAGE_CUT")
    if value is None:
        return 15
    try:
        cut = int(value.strip())
    except ValueError as exc:
        raise ValueError("TK_FA4_MXFP4_BWD_DQ_STAGE_CUT must be an integer") from exc
    if cut != 15 and not (100 <= cut <= 111):
        raise ValueError("TK_FA4_MXFP4_BWD_DQ_STAGE_CUT must be 15 or a fused-dQ debug cut in [100, 111]")
    return cut


def _use_mxfp4_bwd_split_dout_quant_default() -> bool:
    return os.environ.get("TK_FA4_MXFP4_BWD_DOUT_SPLIT_QUANT", "1").strip().lower() not in {
        "0",
        "false",
        "no",
        "off",
    }


def _use_mxfp4_bwd_lean_timed_record_default() -> bool:
    return os.environ.get("TK_FA4_MXFP4_BWD_LEAN_TIMED_RECORD", "0").strip().lower() not in {
        "0",
        "false",
        "no",
        "off",
    }


def _use_mxfp4_bwd_live_dp_default() -> bool:
    return os.environ.get("TK_FA4_MXFP4_BWD_LIVE_DP", "1").strip().lower() not in {
        "0",
        "false",
        "no",
        "off",
    }


def _allow_mxfp4_bwd_live_dp_odd_row_tiles_default() -> bool:
    return os.environ.get("TK_FA4_MXFP4_BWD_LIVE_DP_ODD_ROW_TILES", "0").strip().lower() not in {
        "0",
        "false",
        "no",
        "off",
    }


def _run_mxfp4_full_backward_tensorcore_once(
    q: torch.Tensor,
    q_sc: torch.Tensor,
    q_sg: torch.Tensor,
    k: torch.Tensor,
    k_sc: torch.Tensor,
    k_sg: torch.Tensor,
    q_col_packed: torch.Tensor,
    q_col_scale: torch.Tensor,
    k_col_packed: torch.Tensor,
    k_col_scale: torch.Tensor,
    v_fp4: torch.Tensor,
    v_sc_prepared: torch.Tensor,
    v_row_fp4: torch.Tensor,
    v_row_sc: torch.Tensor,
    v_col_fp4: torch.Tensor,
    v_col_sc: torch.Tensor,
    out: torch.Tensor,
    lse_bhs: torch.Tensor,
    dout: torch.Tensor,
    *,
    softmax_scale: float | None = None,
    dout_quant_backend: str = "localcta",
    launch_mode: str = "auto",
    p_payload_scale: float = _SAGEATTN3_FP4_RECON_SCALE,
    p_quant_mode: str | None = None,
    pv_issue_mode: int | str | None = "auto",
    timeout_ms: float | None = _CUDA_EVENT_TIMEOUT_MS,
    dv_k_as_q_sc: torch.Tensor | None = None,
    dv_q_as_k_sc: torch.Tensor | None = None,
    dP_out: torch.Tensor | None = None,
    dQ_pad_out: torch.Tensor | None = None,
    dQ_bshd_out: torch.Tensor | None = None,
    dS_col_fp4_out: torch.Tensor | None = None,
    dS_col_sc_out: torch.Tensor | None = None,
    dS_row_sc_prezeroed: bool = False,
    dK_pad_out: torch.Tensor | None = None,
    dV_out: torch.Tensor | None = None,
    dout_row_fp4_out: torch.Tensor | None = None,
    dout_row_sc_out: torch.Tensor | None = None,
    dout_col_fp4_out: torch.Tensor | None = None,
    dout_col_sc_out: torch.Tensor | None = None,
    delta_out: torch.Tensor | None = None,
) -> tuple[
    torch.Tensor,
    torch.Tensor,
    torch.Tensor,
    torch.Tensor | None,
    dict[str, float],
    dict[str, Any] | None,
    torch.Tensor | None,
    torch.Tensor | None,
    torch.Tensor | None,
    torch.Tensor | None,
    torch.Tensor | None,
    torch.Tensor | None,
    dict[str, Any],
]:
    """Executable staged MXFP4 backward prototype; no Q/K/V dequant fallback."""
    batch, heads, seqlen = _check_fp4_attention_inputs(q, q_sc, q_sg, k, k_sc, k_sg)
    auto_mode = _resolve_mxfp4_bwd_auto_full_rewrite_mode(seqlen=seqlen)
    mode = _mxfp4_bwd_full_rewrite_mode_normalized()
    key_owned_correct_dk_fallback_source_mode = None
    if (
        auto_mode is None
        and mode in _MXFP4_BWD_KEY_OWNED_SCHEDULE_MODES
        and _env_flag("TK_FA4_MXFP4_BWD_KEY_OWNED_CORRECT_DK_FALLBACK")
        and not _env_flag("TK_FA4_MXFP4_BWD_KEY_OWNED_CORRECT_DK_FALLBACK_ACTIVE")
        and not (
            _use_mxfp4_bwd_key_owned_dk_replay_probe_default()
            or _use_mxfp4_bwd_key_owned_dk_replay_mxfp4_abt_probe_default()
            or _use_mxfp4_bwd_key_owned_dk_replay_chunked_abt_probe_default()
            or _use_mxfp4_bwd_key_owned_dk_replay_padded128_abt_probe_default()
            or _use_mxfp4_bwd_key_owned_dk_replay_padded128_abt_issue_probe_default()
            or _use_mxfp4_bwd_key_owned_dk_replay_native_m64k64_abt_probe_default()
            or _use_mxfp4_bwd_key_owned_dk_replay_native_m64k64_abt_issue_probe_default()
            or _use_mxfp4_bwd_key_owned_dk_replay_native_m64k64_abt_runtime_probe_default()
            or _use_mxfp4_bwd_key_owned_dk_replay_native_m64k64_abt_accum_vis_probe_default()
            or _use_mxfp4_bwd_key_owned_dk_replay_native_m64k64_abt_accum_clear_readback_probe_default()
        )
    ):
        auto_mode = "single_live_ds_col"
        key_owned_correct_dk_fallback_source_mode = mode
    if auto_mode is not None:
        env_updates = {"TK_FA4_MXFP4_BWD_FULL_REWRITE": auto_mode}
        if key_owned_correct_dk_fallback_source_mode is not None:
            env_updates["TK_FA4_MXFP4_BWD_KEY_OWNED_CORRECT_DK_FALLBACK_ACTIVE"] = "1"
            if dQ_pad_out is None:
                dQ_pad_out = torch.empty(
                    (batch, heads, seqlen, _D_QK_GEMM_PAD),
                    dtype=torch.bfloat16,
                    device=q.device,
                )
            if dS_col_fp4_out is None:
                dS_col_fp4_out = torch.empty(
                    (batch, heads, seqlen, seqlen // 2),
                    dtype=torch.float4_e2m1fn_x2,
                    device=q.device,
                )
            if dS_col_sc_out is None:
                dS_col_sc_out = torch.empty(
                    (batch, heads, seqlen // _TILE, seqlen // _TILE, 32, 16),
                    dtype=torch.uint8,
                    device=q.device,
                )
            if dK_pad_out is None:
                dK_pad_out = torch.empty(
                    (batch, heads, seqlen, _D_QK_GEMM_PAD),
                    dtype=torch.bfloat16,
                    device=q.device,
                )
        with _temporary_environ(env_updates):
            result = _run_mxfp4_full_backward_tensorcore_once(
                q,
                q_sc,
                q_sg,
                k,
                k_sc,
                k_sg,
                q_col_packed,
                q_col_scale,
                k_col_packed,
                k_col_scale,
                v_fp4,
                v_sc_prepared,
                v_row_fp4,
                v_row_sc,
                v_col_fp4,
                v_col_sc,
                out,
                lse_bhs,
                dout,
                softmax_scale=softmax_scale,
                dout_quant_backend=dout_quant_backend,
                launch_mode=launch_mode,
                p_payload_scale=p_payload_scale,
                p_quant_mode=p_quant_mode,
                pv_issue_mode=pv_issue_mode,
                timeout_ms=timeout_ms,
                dv_k_as_q_sc=dv_k_as_q_sc,
                dv_q_as_k_sc=dv_q_as_k_sc,
                dP_out=dP_out,
                dQ_pad_out=dQ_pad_out,
                dQ_bshd_out=dQ_bshd_out,
                dS_col_fp4_out=dS_col_fp4_out,
                dS_col_sc_out=dS_col_sc_out,
                dS_row_sc_prezeroed=dS_row_sc_prezeroed,
                dK_pad_out=dK_pad_out,
                dV_out=dV_out,
                dout_row_fp4_out=dout_row_fp4_out,
                dout_row_sc_out=dout_row_sc_out,
                dout_col_fp4_out=dout_col_fp4_out,
                dout_col_sc_out=dout_col_sc_out,
                delta_out=delta_out,
            )
        if key_owned_correct_dk_fallback_source_mode is not None:
            metrics = dict(result[-1])
            metrics.update(
                {
                    "key_owned_correct_dk_fallback_enabled": True,
                    "key_owned_correct_dk_fallback_source_mode": (
                        key_owned_correct_dk_fallback_source_mode
                    ),
                    "key_owned_correct_dk_fallback_target_mode": auto_mode,
                    "key_owned_correct_dk_fallback_blocker": (
                        "diagnostic-only: key-owned schedule dK is rerouted through "
                        "the staged single-live-dS-col dK GEMM path because the "
                        "no-global pair/recompute dS^T@Q consumer fails correctness"
                    ),
                }
            )
            result = (*result[:-1], metrics)
        return result
    single_live_ds_col_limit = _mxfp4_bwd_auto_single_live_ds_col_max_seqlen()
    if (
        mode in _MXFP4_BWD_SINGLE_LIVE_DS_COL_MODES
        and int(seqlen) > single_live_ds_col_limit
        and not _env_flag("TK_FA4_MXFP4_BWD_SINGLE_DS_COL_ALLOW_LONG")
    ):
        raise RuntimeError(
            "TK_FA4_MXFP4_BWD_FULL_REWRITE=single_live_ds_col is only validated up to "
            f"seqlen {single_live_ds_col_limit}; use key_owned_schedule for longer contexts "
            "or set TK_FA4_MXFP4_BWD_SINGLE_DS_COL_ALLOW_LONG=1 to debug the long-context path"
        )
