                            k_sc,
                            k_sg,
                            k_col_packed,
                            k_col_scale,
                            lse,
                            dP.contiguous(),
                            delta.contiguous(),
                            dQ_pad_out,
                            dS_col_fp4_out,
                            dS_col_sc_out,
