def measure_pv_variant_repeatability(
    *,
    seqlens: tuple[int, ...] = (2048, 4096),
    input_modes: tuple[str, ...] = ("random_live_fp4", "zero_qk_random_v"),
    variants: tuple[str | tuple[str, str], ...] = (
        "qk_pv_nvfp4_production",
        "regular_fa4_fused",
        "streaming_live_localcta_direct",
        "streaming_live_localcta_direct_tcgenaccum",
        "streaming_live_localcta_prod_tcgen",
    ),
    batch: int = 1,
    heads: int = 1,
    device: str | torch.device = "cuda:1",
    fallback_devices: tuple[str | torch.device, ...] = ("cuda:1", "cuda:2", "cuda:3"),
    seed: int = 0,
    repeats: int = 5,
) -> list[dict[str, Any]]:
    import statistics

    device = _benchmark_cuda_preflight_with_fallback(
        device,
        fallback_devices=fallback_devices,
        what="measure_pv_variant_repeatability",
    )
    if repeats < 2:
        raise ValueError("repeats must be at least 2")

    rows: list[dict[str, Any]] = []

    def _make_inputs(seqlen: int, input_mode: str) -> tuple[torch.Tensor, ...]:
        if input_mode == "random_live_fp4":
            return make_random_live_fp4_attention_inputs(
                seqlen,
                seed=seed,
                batch=batch,
                heads=heads,
                device=device,
            )
        if input_mode == "zero_qk_random_v":
            return _make_zero_qk_random_v_inputs(
                seqlen,
                seed=seed,
                batch=batch,
                heads=heads,
                device=device,
            )
        raise ValueError(f"unsupported input_mode: {input_mode}")

    for seqlen in seqlens:
        for input_mode in input_modes:
            inputs = _make_inputs(int(seqlen), input_mode)
            for variant in variants:
                variant_name, launch_mode = _resolve_pv_variant_and_launch_mode(variant)
                effective_launch_mode = launch_mode
                last_streaming_record: dict[str, Any] | None = None
                outputs: list[torch.Tensor] = []
                lses: list[torch.Tensor] = []
                for _ in range(repeats):
                    if variant_name == "qk_pv_nvfp4_production":
                        out, lse = _run_production_fp4pv(*inputs)
                    elif variant_name == "qk_pv_nvfp4_production_fullgrid":
                        out, lse = _run_fp4pv_fullgrid(*inputs)
                    elif variant_name in _STREAMING_LIVE_VARIANTS:
                        record = run_streaming_live_pv_variant(
                            *inputs,
                            variant=variant_name,
                            launch_mode=launch_mode,
                        )
                        last_streaming_record = record
                        effective_launch_mode = str(record.get("launch_mode", launch_mode))
                        out, lse = record["out"], record["lse"]
                    else:
                        record = run_variant(*inputs, variant=variant_name)
                        out, lse = record["out"], record["lse"]
                    outputs.append(out.float().cpu())
                    lses.append(lse.float().cpu())

                ref_out = outputs[0]
                ref_lse = lses[0]
                out_mean_diffs: list[float] = []
                out_max_diffs: list[float] = []
                lse_max_diffs: list[float] = []
                for out, lse in zip(outputs[1:], lses[1:]):
                    out_diff = (out - ref_out).abs()
                    out_mean_diffs.append(float(out_diff.mean()))
                    out_max_diffs.append(float(out_diff.max()))
                    lse_max_diffs.append(float((lse - ref_lse).abs().max()))

                rows.append(
                    {
                        "sweep": "pv_variant_repeatability",
                        "seqlen": int(seqlen),
                        "input_mode": input_mode,
                        "variant": variant_name,
                        "launch_mode": effective_launch_mode,
                        "requested_launch_mode": None if last_streaming_record is None else last_streaming_record.get("requested_launch_mode"),
                        "launch_execution_mode": None if last_streaming_record is None else last_streaming_record.get("launch_execution_mode"),
                        **_benchmark_row_meta(variant_name),
                        "repeats": int(repeats),
                        "device": str(device),
                        "head_chunk_size": None if last_streaming_record is None else last_streaming_record.get("head_chunk_size"),
                        "head_chunks": None if last_streaming_record is None else last_streaming_record.get("head_chunks"),
                        "max_bids_cap": None if last_streaming_record is None else last_streaming_record.get("max_bids_cap"),
                        "total_bids": None if last_streaming_record is None else last_streaming_record.get("total_bids"),
                        "bids_per_launch": None if last_streaming_record is None else last_streaming_record.get("bids_per_launch"),
                        "persistent_cap_limited": None if last_streaming_record is None else last_streaming_record.get("persistent_cap_limited"),
                        "launch_fallback_reason": None if last_streaming_record is None else last_streaming_record.get("launch_fallback_reason"),
                        "out_mean_abs_diff_vs_run0_avg": float(statistics.mean(out_mean_diffs)),
                        "out_mean_abs_diff_vs_run0_median": float(statistics.median(out_mean_diffs)),
                        "out_max_abs_diff_vs_run0_avg": float(statistics.mean(out_max_diffs)),
                        "out_max_abs_diff_vs_run0_median": float(statistics.median(out_max_diffs)),
                        "lse_max_abs_diff_vs_run0_avg": float(statistics.mean(lse_max_diffs)),
                        "lse_max_abs_diff_vs_run0_median": float(statistics.median(lse_max_diffs)),
                    }
                )

    return rows


def measure_pv_variant_row_block_profiles(
    *,
    seqlens: tuple[int, ...] = (2048, 4096),
    input_modes: tuple[str, ...] = ("random_live_fp4", "zero_qk_random_v"),
    variants: tuple[str | tuple[str, str], ...] = (
        "qk_pv_nvfp4_production",
        "regular_fa4_fused",
        "streaming_live_localcta_direct",
    ),
    batch: int = 1,
    heads: int = 1,
    device: str | torch.device = "cuda:1",
    fallback_devices: tuple[str | torch.device, ...] = ("cuda:1", "cuda:2", "cuda:3"),
    seed: int = 0,
    block_rows: int = 128,
) -> list[dict[str, Any]]:
    device = _benchmark_cuda_preflight_with_fallback(
        device,
        fallback_devices=fallback_devices,
        what="measure_pv_variant_row_block_profiles",
    )

    def _make_inputs(seqlen: int, input_mode: str) -> tuple[torch.Tensor, ...]:
        if input_mode == "random_live_fp4":
            return make_random_live_fp4_attention_inputs(
                seqlen,
                seed=seed,
                batch=batch,
                heads=heads,
                device=device,
            )
        if input_mode == "zero_qk_random_v":
            return _make_zero_qk_random_v_inputs(
                seqlen,
                seed=seed,
                batch=batch,
                heads=heads,
                device=device,
            )
        raise ValueError(f"unsupported input_mode: {input_mode}")

    rows: list[dict[str, Any]] = []
    for seqlen in seqlens:
        for input_mode in input_modes:
            inputs = _make_inputs(int(seqlen), input_mode)
            ref_out, ref_lse, _, _ = _run_variant_alt1(*inputs)
            ref_out = ref_out.float().cpu()
            ref_lse = ref_lse.float().cpu()

            for variant in variants:
                variant_name, launch_mode = _resolve_pv_variant_and_launch_mode(variant)
                effective_launch_mode = launch_mode
                last_streaming_record: dict[str, Any] | None = None
                if variant_name == "qk_pv_nvfp4_production":
                    out0, lse0 = _run_production_fp4pv(*inputs)
                    out1, lse1 = _run_production_fp4pv(*inputs)
                elif variant_name == "qk_pv_nvfp4_production_fullgrid":
                    out0, lse0 = _run_fp4pv_fullgrid(*inputs)
                    out1, lse1 = _run_fp4pv_fullgrid(*inputs)
                elif variant_name in _STREAMING_LIVE_VARIANTS:
                    rec0 = run_streaming_live_pv_variant(
                        *inputs,
                        variant=variant_name,
                        launch_mode=launch_mode,
                    )
                    rec1 = run_streaming_live_pv_variant(
                        *inputs,
                        variant=variant_name,
                        launch_mode=launch_mode,
                    )
                    last_streaming_record = rec1
                    effective_launch_mode = str(rec0.get("launch_mode", launch_mode))
                    out0, lse0 = rec0["out"], rec0["lse"]
                    out1, lse1 = rec1["out"], rec1["lse"]
                else:
                    rec0 = run_variant(*inputs, variant=variant_name)
                    rec1 = run_variant(*inputs, variant=variant_name)
                    out0, lse0 = rec0["out"], rec0["lse"]
                    out1, lse1 = rec1["out"], rec1["lse"]

                out0_cpu = out0.float().cpu()
                out1_cpu = out1.float().cpu()
                lse0_cpu = lse0.float().cpu()
                lse1_cpu = lse1.float().cpu()
                rows.append(
                    {
                        "sweep": "pv_variant_row_block_profiles",
                        "seqlen": int(seqlen),
                        "input_mode": input_mode,
                        "variant": variant_name,
                        "launch_mode": effective_launch_mode,
                        "requested_launch_mode": None if last_streaming_record is None else last_streaming_record.get("requested_launch_mode"),
                        "launch_execution_mode": None if last_streaming_record is None else last_streaming_record.get("launch_execution_mode"),
                        **_benchmark_row_meta(variant_name),
                        "device": str(device),
                        "block_rows": int(block_rows),
                        "head_chunk_size": None if last_streaming_record is None else last_streaming_record.get("head_chunk_size"),
                        "head_chunks": None if last_streaming_record is None else last_streaming_record.get("head_chunks"),
                        "max_bids_cap": None if last_streaming_record is None else last_streaming_record.get("max_bids_cap"),
                        "total_bids": None if last_streaming_record is None else last_streaming_record.get("total_bids"),
                        "bids_per_launch": None if last_streaming_record is None else last_streaming_record.get("bids_per_launch"),
                        "persistent_cap_limited": None if last_streaming_record is None else last_streaming_record.get("persistent_cap_limited"),
                        "launch_fallback_reason": None if last_streaming_record is None else last_streaming_record.get("launch_fallback_reason"),
                        "run01_mean_abs_diff": float((out0_cpu - out1_cpu).abs().mean().item()),
                        "run01_max_abs_diff": float((out0_cpu - out1_cpu).abs().max().item()),
                        "ref_mean_abs_diff": float((out0_cpu - ref_out).abs().mean().item()),
                        "ref_max_abs_diff": float((out0_cpu - ref_out).abs().max().item()),
                        "lse_run01_max_abs_diff": float((lse0_cpu - lse1_cpu).abs().max().item()),
                        "lse_ref_max_abs_diff": float((lse0_cpu - ref_lse).abs().max().item()),
                        "row_block_run01": _row_block_drift_summary(out0_cpu, out1_cpu, block_rows=block_rows),
                        "row_block_vs_ref": _row_block_drift_summary(out0_cpu, ref_out, block_rows=block_rows),
                    }
                )

    return rows


