def _iter_online_probability_study_configs(
    *,
    p_modes: tuple[str, ...],
    pv_backends: tuple[str, ...],
    pv_execution_mode: str,
    sa3_payload_target_max_values: tuple[float, ...],
    sa3_recon_scale_base_values: tuple[float, ...],
    localcta_global_scale_num_values: tuple[float, ...],
    fixed_nvfp4_scale_num_values: tuple[float, ...],
) -> list[dict[str, Any]]:
    configs: list[dict[str, Any]] = []
    baseline_only = _normalize_pv_execution_mode(pv_execution_mode) == "real_kernel"
    for p_mode in p_modes:
        for pv_backend in pv_backends:
            backend = _normalize_forward_matrix_backend(pv_backend)
            if p_mode == "live_mxfp4_pv" and backend != "mxfp4_v3":
                continue
            if p_mode == "live_nvfp4_fixed_scale_pv" and backend not in _REAL_NVFP4_PV_BACKENDS:
                continue
            quant_mode_choices = (
                (_default_quant_mode_for_backend(backend),)
                if baseline_only
                else _quant_mode_choices_for_backend(backend)
            )
            if p_mode == "live_sa3_baseline":
                sa3_payloads = (6.0,) if baseline_only else tuple(float(v) for v in sa3_payload_target_max_values)
                sa3_recons = (448.0,) if baseline_only else tuple(float(v) for v in sa3_recon_scale_base_values)
                localcta_globals = (float(_FP4PV_LOCALCTA_GLOBAL_SCALE_NUM),)
                fixed_nvfp4_scales = (float(_FP4PV_LOCALCTA_GLOBAL_SCALE_NUM),)
            elif p_mode == "live_localcta_cta_amax_experimental":
                sa3_payloads = (6.0,)
                sa3_recons = (448.0,)
                localcta_globals = (
                    (float(_FP4PV_LOCALCTA_GLOBAL_SCALE_NUM),)
                    if baseline_only
                    else tuple(float(v) for v in localcta_global_scale_num_values)
                )
                fixed_nvfp4_scales = (float(_FP4PV_LOCALCTA_GLOBAL_SCALE_NUM),)
            elif p_mode == "live_nvfp4_fixed_scale_pv":
                sa3_payloads = (6.0,)
                sa3_recons = (448.0,)
                localcta_globals = (float(_FP4PV_LOCALCTA_GLOBAL_SCALE_NUM),)
                fixed_nvfp4_scales = (
                    (float(_FP4PV_LOCALCTA_GLOBAL_SCALE_NUM),)
                    if baseline_only
                    else tuple(float(v) for v in fixed_nvfp4_scale_num_values)
                )
            else:
                sa3_payloads = (6.0,)
                sa3_recons = (448.0,)
                localcta_globals = (float(_FP4PV_LOCALCTA_GLOBAL_SCALE_NUM),)
                fixed_nvfp4_scales = (float(_FP4PV_LOCALCTA_GLOBAL_SCALE_NUM),)
            for p_quant_mode in quant_mode_choices:
                for v_quant_mode in quant_mode_choices:
                    for sa3_payload_target_max in sa3_payloads:
                        for sa3_recon_scale_base in sa3_recons:
                            for localcta_global_scale_num in localcta_globals:
                                for fixed_nvfp4_scale_num in fixed_nvfp4_scales:
                                    configs.append(
                                        {
                                            "p_mode": p_mode,
                                            "pv_backend": backend,
                                            "p_quant_mode": _normalize_quant_mode_for_backend(backend, p_quant_mode),
                                            "v_quant_mode": _normalize_quant_mode_for_backend(backend, v_quant_mode),
                                            "sa3_payload_target_max": float(sa3_payload_target_max),
                                            "sa3_recon_scale_base": float(sa3_recon_scale_base),
                                            "localcta_global_scale_num": float(localcta_global_scale_num),
                                            "fixed_nvfp4_scale_num": float(fixed_nvfp4_scale_num),
                                        }
                                    )
    return configs


def _run_online_probability_strategy_combo_only(
    q_bf16: torch.Tensor,
    k_bf16: torch.Tensor,
    v_bf16: torch.Tensor,
    *,
    p_mode: str,
    pv_backend: str,
    pv_execution_mode: str = "qdq_proxy",
    p_quant_mode: str | None = None,
    v_quant_mode: str | None = None,
    sa3_payload_target_max: float = 6.0,
    sa3_recon_scale_base: float = 448.0,
    localcta_global_scale_num: float = _FP4PV_LOCALCTA_GLOBAL_SCALE_NUM,
    fixed_nvfp4_scale_num: float = _FP4PV_LOCALCTA_GLOBAL_SCALE_NUM,
    softmax_scale: float | None = None,
) -> tuple[torch.Tensor, torch.Tensor]:
    p_mode = _normalize_forward_p_mode(p_mode)
    pv_backend = _normalize_forward_matrix_backend(pv_backend)
    pv_execution_mode = _normalize_pv_execution_mode(pv_execution_mode)
    batch, seqlen, heads = _check_bf16_exact_qkv_inputs(q_bf16, k_bf16, v_bf16)
    scale = float(softmax_scale) if softmax_scale is not None else 1.0 / math.sqrt(float(_D_QK))
    clear_between_heads = _should_clear_cuda_between_combo_heads(seqlen)
    out = torch.empty((batch, seqlen, heads, _D_VO), dtype=torch.bfloat16, device=q_bf16.device)
    lse = torch.empty((batch, heads, seqlen), dtype=torch.float32, device=q_bf16.device)
    for b in range(batch):
        for h in range(heads):
            logits_2d = torch.matmul(
                q_bf16[b, :, h, :].float(),
                k_bf16[b, :, h, :].float().transpose(0, 1),
            ).mul_(scale)
            if p_mode == "stored_p":
                out_2d, lse_1d = _stored_p_forward_from_logits_2d(
                    logits_2d,
                    v_bf16[b, :, h, :].contiguous(),
                    pv_backend=pv_backend,
                    pv_execution_mode=pv_execution_mode,
                )
            else:
                out_2d, lse_1d = _run_online_probability_strategy_from_logits_2d(
                    logits_2d,
                    v_bf16[b, :, h, :].contiguous(),
                    p_mode=p_mode,
                    pv_backend=pv_backend,
                    pv_execution_mode=pv_execution_mode,
                    p_quant_mode=p_quant_mode,
                    v_quant_mode=v_quant_mode,
                    sa3_payload_target_max=sa3_payload_target_max,
                    sa3_recon_scale_base=sa3_recon_scale_base,
                    localcta_global_scale_num=localcta_global_scale_num,
                    fixed_nvfp4_scale_num=fixed_nvfp4_scale_num,
                )
            out[b, :, h, :].copy_(out_2d)
            lse[b, h].copy_(lse_1d)
            if clear_between_heads:
                del logits_2d, out_2d, lse_1d
                _clear_cuda_after_combo_head(q_bf16.device)
    return out.contiguous(), lse.contiguous()


def benchmark_online_probability_quantization_study(
    *,
    seqlens: tuple[int, ...] = _ONLINE_STRATEGY_STUDY_DEFAULT_SEQLENS,
    input_mode: str = "random_live_fp4",
    p_modes: tuple[str, ...] = _ONLINE_STRATEGY_STUDY_P_MODES,
    pv_backends: tuple[str, ...] = _ONLINE_STRATEGY_STUDY_BACKENDS,
    pv_execution_modes: tuple[str, ...] = ("qdq_proxy",),
    distributions: tuple[str, ...] = _ONLINE_STRATEGY_STUDY_DEFAULT_DISTRIBUTIONS,
    batch: int = 1,
    heads: int = 8,
    device: str | torch.device = "cuda",
    seed: int = 0,
    q_distribution: str | None = None,
    k_distribution: str | None = None,
    v_distribution: str | None = None,
    warmup: int = 1,
    iters: int = 3,
    timeout_ms: float | None = 20_000.0,
    sa3_payload_target_max_values: tuple[float, ...] = _ONLINE_STRATEGY_STUDY_SA3_PAYLOAD_TARGETS,
    sa3_recon_scale_base_values: tuple[float, ...] = _ONLINE_STRATEGY_STUDY_SA3_RECON_BASES,
    localcta_global_scale_num_values: tuple[float, ...] = _ONLINE_STRATEGY_STUDY_LOCALCTA_GLOBAL_SCALE_NUMS,
    fixed_nvfp4_scale_num_values: tuple[float, ...] = _ONLINE_STRATEGY_STUDY_FIXED_NVFP4_SCALE_NUMS,
) -> dict[str, Any]:
    if iters < 1:
        raise ValueError("iters must be >= 1")
    if input_mode != "random_live_fp4":
        raise ValueError("benchmark_online_probability_quantization_study currently supports input_mode='random_live_fp4' only")
    device = _benchmark_cuda_preflight(device, what="benchmark_online_probability_quantization_study")
    _check_power_of_two_seqlens(seqlens, name="seqlens")
    rows: list[dict[str, Any]] = []

    for distribution in distributions:
        _check_choice("distribution", distribution, _QKV_DISTRIBUTION_PRESETS)
        for seqlen in seqlens:
            case_seed = int(seed) + int(seqlen) + sum(ord(ch) for ch in distribution) * 131
            q_bf16, k_bf16, v_bf16 = _make_forward_matrix_bf16_inputs(
                seqlen,
                input_mode=input_mode,
                seed=case_seed,
                batch=batch,
                heads=heads,
                device=device,
                distribution=distribution,
                q_distribution=q_distribution,
                k_distribution=k_distribution,
                v_distribution=v_distribution,
            )
            bf16_record = run_forward_precision_reference_baseline(q_bf16, k_bf16, v_bf16, timeout_ms=timeout_ms)
            bf16_out = bf16_record["out"].cpu()
            bf16_lse = bf16_record["lse"].cpu()
            bf16_ms = float(bf16_record["timing_ms"])
            del bf16_record["out"], bf16_record["lse"]
            gc.collect()
            torch.cuda.empty_cache()
            torch.cuda.synchronize(device)

            for pv_execution_mode in pv_execution_modes:
                pv_execution_mode = _normalize_pv_execution_mode(pv_execution_mode)
                configs = _iter_online_probability_study_configs(
                    p_modes=tuple(_normalize_forward_p_mode(mode) for mode in p_modes),
                    pv_backends=tuple(_normalize_forward_matrix_backend(backend) for backend in pv_backends),
                    pv_execution_mode=pv_execution_mode,
                    sa3_payload_target_max_values=sa3_payload_target_max_values,
                    sa3_recon_scale_base_values=sa3_recon_scale_base_values,
                    localcta_global_scale_num_values=localcta_global_scale_num_values,
                    fixed_nvfp4_scale_num_values=fixed_nvfp4_scale_num_values,
                )
                for config in configs:
                    samples: list[float] = []
                    for _ in range(int(max(warmup, 0))):
                        _run_online_probability_strategy_combo_only(
                            q_bf16,
                            k_bf16,
                            v_bf16,
                            pv_execution_mode=pv_execution_mode,
                            **config,
                        )
                        gc.collect()
                        torch.cuda.empty_cache()
                        torch.cuda.synchronize(device)
                    for _ in range(int(max(iters, 1))):
                        (_, _), ms = _run_with_host_ms(
                            _run_online_probability_strategy_combo_only,
                            q_bf16,
                            k_bf16,
                            v_bf16,
                            pv_execution_mode=pv_execution_mode,
                            **config,
                        )
                        samples.append(float(ms))
                        gc.collect()
                        torch.cuda.empty_cache()
                        torch.cuda.synchronize(device)
                    out, lse = _run_online_probability_strategy_combo_only(
                        q_bf16,
                        k_bf16,
                        v_bf16,
                        pv_execution_mode=pv_execution_mode,
                        **config,
                    )
                    compare = _compare_outputs(out.cpu(), lse.cpu(), bf16_out, bf16_lse)
                    assessment = _assess_pv_precision_result(out.cpu(), bf16_out, pv_execution_mode=pv_execution_mode)
                    rows.append(
                        {
                            "seqlen": int(seqlen),
                            "input_mode": input_mode,
                            "distribution": distribution,
                            "q_distribution": q_distribution if q_distribution is not None else distribution,
                            "k_distribution": k_distribution if k_distribution is not None else distribution,
                            "v_distribution": v_distribution if v_distribution is not None else distribution,
                            "qk_backend": "bf16_exact",
                            "p_mode": str(config["p_mode"]),
                            "strategy_family": str(config["p_mode"]),
                            "pv_backend": str(config["pv_backend"]),
                            "pv_execution_mode": pv_execution_mode,
                            "p_quant_mode": str(config["p_quant_mode"]),
                            "v_quant_mode": str(config["v_quant_mode"]),
                            "sa3_payload_target_max": float(config["sa3_payload_target_max"]),
                            "sa3_recon_scale_base": float(config["sa3_recon_scale_base"]),
                            "localcta_global_scale_num": float(config["localcta_global_scale_num"]),
                            "fixed_nvfp4_scale_num": float(config["fixed_nvfp4_scale_num"]),
                            "is_reference_row": False,
                            "launch_mode": "orchestrated",
                            "kernel_contract_mode": _infer_pv_kernel_contract_mode(
                                p_mode=str(config["p_mode"]),
                                pv_backend=str(config["pv_backend"]),
                                pv_execution_mode=pv_execution_mode,
                            ),
                            "bf16_baseline_ms": bf16_ms,
                            "timing_ms": float(_median(samples)),
                            "ratio_vs_bf16_baseline": float(_median(samples) / bf16_ms) if bf16_ms > 0 else float("nan"),
                            "mean_abs_diff_vs_bf16": compare["mean_abs_diff"],
                            "max_abs_diff_vs_bf16": compare["max_abs_diff"],
                            "mse_vs_bf16": compare["mse"],
                            "rmse_vs_bf16": compare["rmse"],
                            "normalized_mean_abs_diff_vs_bf16": compare["normalized_mean_abs_diff"],
                            "normalized_rmse_vs_bf16": compare["normalized_rmse"],
                            "max_rel_diff_vs_bf16": compare["max_rel_diff"],
                            "lse_max_abs_diff_vs_bf16": compare["lse_max_abs_diff"],
                            "output_has_nonfinite": compare["output_has_nonfinite"],
                            "reference_has_nonfinite": compare["reference_has_nonfinite"],
                            "lse_has_nonfinite": compare["lse_has_nonfinite"],
                            "reference_lse_has_nonfinite": compare["reference_lse_has_nonfinite"],
                            "uses_real_qk_backend": False,
                            "uses_real_pv_backend": True,
                            "finite_out": not compare["output_has_nonfinite"] and not compare["reference_has_nonfinite"],
                            "finite_lse": not compare["lse_has_nonfinite"] and not compare["reference_lse_has_nonfinite"],
                            "experimental": str(config["p_mode"]) != "live_direct",
                            **assessment,
                        }
                    )
                reference_backend = "mxfp4_v3"
                reference_mode = _default_quant_mode_for_backend(reference_backend)
                ref_samples: list[float] = []
                for _ in range(int(max(warmup, 0))):
                    _run_online_probability_strategy_combo_only(
                        q_bf16,
                        k_bf16,
                        v_bf16,
                        p_mode="stored_p",
                        pv_backend=reference_backend,
                        pv_execution_mode=pv_execution_mode,
                    )
                    gc.collect()
                    torch.cuda.empty_cache()
                    torch.cuda.synchronize(device)
                for _ in range(int(max(iters, 1))):
                    (_, _), ms = _run_with_host_ms(
                        _run_online_probability_strategy_combo_only,
                        q_bf16,
                        k_bf16,
                        v_bf16,
                        p_mode="stored_p",
                        pv_backend=reference_backend,
                        pv_execution_mode=pv_execution_mode,
                    )
                    ref_samples.append(float(ms))
                    gc.collect()
                    torch.cuda.empty_cache()
                    torch.cuda.synchronize(device)
                out, lse = _run_online_probability_strategy_combo_only(
                    q_bf16,
                    k_bf16,
                    v_bf16,
                    p_mode="stored_p",
                    pv_backend=reference_backend,
                    pv_execution_mode=pv_execution_mode,
                )
                compare = _compare_outputs(out.cpu(), lse.cpu(), bf16_out, bf16_lse)
                assessment = _assess_pv_precision_result(out.cpu(), bf16_out, pv_execution_mode=pv_execution_mode)
                rows.append(
                    {
                        "seqlen": int(seqlen),
                        "input_mode": input_mode,
                        "distribution": distribution,
                        "q_distribution": q_distribution if q_distribution is not None else distribution,
                        "k_distribution": k_distribution if k_distribution is not None else distribution,
                        "v_distribution": v_distribution if v_distribution is not None else distribution,
                        "qk_backend": "bf16_exact",
                        "p_mode": "stored_p",
                        "strategy_family": "stored_reference",
                        "pv_backend": reference_backend,
                        "pv_execution_mode": pv_execution_mode,
                        "p_quant_mode": reference_mode,
                        "v_quant_mode": reference_mode,
                        "sa3_payload_target_max": 6.0,
                        "sa3_recon_scale_base": 448.0,
                        "localcta_global_scale_num": float(_FP4PV_LOCALCTA_GLOBAL_SCALE_NUM),
                        "fixed_nvfp4_scale_num": float(_FP4PV_LOCALCTA_GLOBAL_SCALE_NUM),
                        "is_reference_row": True,
                        "launch_mode": "orchestrated",
                        "kernel_contract_mode": _infer_pv_kernel_contract_mode(
                            p_mode="stored_p",
                            pv_backend=reference_backend,
                            pv_execution_mode=pv_execution_mode,
                        ),
                        "bf16_baseline_ms": bf16_ms,
                        "timing_ms": float(_median(ref_samples)),
                        "ratio_vs_bf16_baseline": float(_median(ref_samples) / bf16_ms) if bf16_ms > 0 else float("nan"),
                        "mean_abs_diff_vs_bf16": compare["mean_abs_diff"],
                        "max_abs_diff_vs_bf16": compare["max_abs_diff"],
                        "mse_vs_bf16": compare["mse"],
                        "rmse_vs_bf16": compare["rmse"],
                        "normalized_mean_abs_diff_vs_bf16": compare["normalized_mean_abs_diff"],
                        "normalized_rmse_vs_bf16": compare["normalized_rmse"],
                        "max_rel_diff_vs_bf16": compare["max_rel_diff"],
                        "lse_max_abs_diff_vs_bf16": compare["lse_max_abs_diff"],
                        "output_has_nonfinite": compare["output_has_nonfinite"],
                        "reference_has_nonfinite": compare["reference_has_nonfinite"],
                        "lse_has_nonfinite": compare["lse_has_nonfinite"],
                        "reference_lse_has_nonfinite": compare["reference_lse_has_nonfinite"],
                        "uses_real_qk_backend": False,
                        "uses_real_pv_backend": True,
                        "finite_out": not compare["output_has_nonfinite"] and not compare["reference_has_nonfinite"],
                        "finite_lse": not compare["lse_has_nonfinite"] and not compare["reference_lse_has_nonfinite"],
                        "experimental": False,
                        **assessment,
                    }
                )
    return {
        "metadata": {
            "study": "online_probability_quantization",
            "seqlens": tuple(int(v) for v in seqlens),
            "input_mode": input_mode,
            "p_modes": tuple(str(_normalize_forward_p_mode(mode)) for mode in p_modes),
            "pv_backends": tuple(str(_normalize_forward_matrix_backend(backend)) for backend in pv_backends),
            "pv_execution_modes": tuple(_normalize_pv_execution_mode(mode) for mode in pv_execution_modes),
            "distributions": tuple(str(dist) for dist in distributions),
            "batch": int(batch),
            "heads": int(heads),
            "device": str(device),
            "seed": int(seed),
            "q_distribution": q_distribution,
            "k_distribution": k_distribution,
            "v_distribution": v_distribution,
            "warmup": int(warmup),
            "iters": int(iters),
            "timeout_ms": float(timeout_ms if timeout_ms is not None else _CUDA_EVENT_TIMEOUT_MS),
            "sa3_payload_target_max_values": tuple(float(v) for v in sa3_payload_target_max_values),
            "sa3_recon_scale_base_values": tuple(float(v) for v in sa3_recon_scale_base_values),
            "localcta_global_scale_num_values": tuple(float(v) for v in localcta_global_scale_num_values),
            "fixed_nvfp4_scale_num_values": tuple(float(v) for v in fixed_nvfp4_scale_num_values),
        },
        "rows": rows,
    }


def _summarize_online_probability_quantization_rows(rows: list[dict[str, Any]]) -> dict[str, Any]:
    valid_rows = [row for row in rows if _is_valid_pv_precision_row(row)]
    online_rows = [row for row in valid_rows if not bool(row.get("is_reference_row", False))]
    reference_rows = [row for row in valid_rows if bool(row.get("is_reference_row", False))]
    case_keys = sorted(
        {
            (int(row["seqlen"]), str(row["distribution"]), str(row["pv_execution_mode"]))
            for row in rows
        }
    )
    case_summaries: list[dict[str, Any]] = []
    canonical_winner_counts = {
        "mxfp4_online": 0,
        "mxfp4_fixed_scale": 0,
        "sa3_baseline": 0,
        "nvfp4_fixed_scale": 0,
        "localcta_cta_amax": 0,
    }
    winner_counts: dict[str, int] = {}

    def _best(rows_subset: list[dict[str, Any]]) -> dict[str, Any] | None:
        return min(rows_subset, key=_online_probability_study_sort_key) if rows_subset else None

    for seqlen, distribution, pv_execution_mode in case_keys:
        case_online = [
            row for row in online_rows
            if int(row["seqlen"]) == seqlen
            and str(row["distribution"]) == distribution
            and str(row["pv_execution_mode"]) == pv_execution_mode
        ]
        case_reference = [
            row for row in reference_rows
            if int(row["seqlen"]) == seqlen
            and str(row["distribution"]) == distribution
            and str(row["pv_execution_mode"]) == pv_execution_mode
        ]
        winner = _best(case_online)
        canonical = {
            "mxfp4_online": _best([row for row in case_online if row["p_mode"] == "live_direct" and row["pv_backend"] == "mxfp4_v3"]),
            "mxfp4_fixed_scale": _best([row for row in case_online if row["p_mode"] == "live_mxfp4_pv" and row["pv_backend"] == "mxfp4_v3"]),
            "sa3_baseline": _best([row for row in case_online if row["p_mode"] == "live_sa3_baseline" and row["pv_backend"] == "localcta"]),
            "nvfp4_fixed_scale": _best([row for row in case_online if row["p_mode"] == "live_nvfp4_fixed_scale_pv" and row["pv_backend"] == "localcta"]),
            "localcta_cta_amax": _best([row for row in case_online if row["p_mode"] == "live_localcta_cta_amax_experimental" and row["pv_backend"] == "localcta"]),
        }
        canonical_winner = _best([row for row in canonical.values() if row is not None])
        if winner is not None:
            winner_key = f"{winner['p_mode']}/{winner['pv_backend']}"
            winner_counts[winner_key] = winner_counts.get(winner_key, 0) + 1
        if canonical_winner is not None:
            for label, row in canonical.items():
                if row is canonical_winner:
                    canonical_winner_counts[label] += 1
                    break
        case_summaries.append(
            {
                "seqlen": seqlen,
                "distribution": distribution,
                "pv_execution_mode": pv_execution_mode,
                "winner": None if winner is None else {
                    "p_mode": str(winner["p_mode"]),
                    "pv_backend": str(winner["pv_backend"]),
                    "p_quant_mode": str(winner["p_quant_mode"]),
                    "v_quant_mode": str(winner["v_quant_mode"]),
                    "sa3_payload_target_max": float(winner["sa3_payload_target_max"]),
                    "sa3_recon_scale_base": float(winner["sa3_recon_scale_base"]),
                    "localcta_global_scale_num": float(winner["localcta_global_scale_num"]),
                    "fixed_nvfp4_scale_num": float(winner.get("fixed_nvfp4_scale_num", _FP4PV_LOCALCTA_GLOBAL_SCALE_NUM)),
                    "normalized_mean_abs_diff_vs_bf16": float(winner["normalized_mean_abs_diff_vs_bf16"]),
                    "normalized_rmse_vs_bf16": float(winner["normalized_rmse_vs_bf16"]),
                    "mean_abs_diff_vs_bf16": float(winner["mean_abs_diff_vs_bf16"]),
                },
                "canonical": {
                    label: None if row is None else {
                        "p_quant_mode": str(row["p_quant_mode"]),
                        "v_quant_mode": str(row["v_quant_mode"]),
                        "sa3_payload_target_max": float(row["sa3_payload_target_max"]),
                        "sa3_recon_scale_base": float(row["sa3_recon_scale_base"]),
                        "localcta_global_scale_num": float(row["localcta_global_scale_num"]),
                        "fixed_nvfp4_scale_num": float(row.get("fixed_nvfp4_scale_num", _FP4PV_LOCALCTA_GLOBAL_SCALE_NUM)),
                        "normalized_mean_abs_diff_vs_bf16": float(row["normalized_mean_abs_diff_vs_bf16"]),
                        "normalized_rmse_vs_bf16": float(row["normalized_rmse_vs_bf16"]),
                        "mean_abs_diff_vs_bf16": float(row["mean_abs_diff_vs_bf16"]),
                    }
                    for label, row in canonical.items()
                },
                "stored_reference": None if not case_reference else {
                    "normalized_mean_abs_diff_vs_bf16": float(_best(case_reference)["normalized_mean_abs_diff_vs_bf16"]),
                    "normalized_rmse_vs_bf16": float(_best(case_reference)["normalized_rmse_vs_bf16"]),
                    "mean_abs_diff_vs_bf16": float(_best(case_reference)["mean_abs_diff_vs_bf16"]),
                },
            }
        )

    def _mean_metric(rows_subset: list[dict[str, Any]], metric: str) -> float:
        return float(sum(float(row[metric]) for row in rows_subset) / len(rows_subset)) if rows_subset else float("nan")

    p_mode_marginals: list[dict[str, Any]] = []
    for strategy_family in _ONLINE_STRATEGY_STUDY_P_MODES:
        for backend in _ONLINE_STRATEGY_STUDY_BACKENDS:
            for p_quant_mode in _quant_mode_choices_for_backend(backend):
                subset = [
                    row for row in online_rows
                    if row["p_mode"] == strategy_family and row["pv_backend"] == backend and row["p_quant_mode"] == p_quant_mode
                ]
                if subset:
                    p_mode_marginals.append(
                        {
                            "strategy_family": strategy_family,
                            "pv_backend": backend,
                            "p_quant_mode": p_quant_mode,
                            "mean_normalized_mae": _mean_metric(subset, "normalized_mean_abs_diff_vs_bf16"),
                            "mean_normalized_rmse": _mean_metric(subset, "normalized_rmse_vs_bf16"),
                        }
                    )

    v_mode_marginals: list[dict[str, Any]] = []
    for strategy_family in _ONLINE_STRATEGY_STUDY_P_MODES:
        for backend in _ONLINE_STRATEGY_STUDY_BACKENDS:
            for v_quant_mode in _quant_mode_choices_for_backend(backend):
                subset = [
                    row for row in online_rows
                    if row["p_mode"] == strategy_family and row["pv_backend"] == backend and row["v_quant_mode"] == v_quant_mode
                ]
                if subset:
                    v_mode_marginals.append(
                        {
                            "strategy_family": strategy_family,
                            "pv_backend": backend,
                            "v_quant_mode": v_quant_mode,
                            "mean_normalized_mae": _mean_metric(subset, "normalized_mean_abs_diff_vs_bf16"),
                            "mean_normalized_rmse": _mean_metric(subset, "normalized_rmse_vs_bf16"),
                        }
                    )

    return {
        "case_summaries": case_summaries,
        "aggregate": {
            "winner_counts": winner_counts,
            "canonical_winner_counts": canonical_winner_counts,
            "p_mode_marginals": p_mode_marginals,
            "v_mode_marginals": v_mode_marginals,
        },
    }


def write_online_probability_quantization_study(
    *,
    output_dir: str | os.PathLike[str] | None = None,
    seqlens: tuple[int, ...] = _ONLINE_STRATEGY_STUDY_DEFAULT_SEQLENS,
    input_mode: str = "random_live_fp4",
    p_modes: tuple[str, ...] = _ONLINE_STRATEGY_STUDY_P_MODES,
    pv_backends: tuple[str, ...] = _ONLINE_STRATEGY_STUDY_BACKENDS,
    pv_execution_modes: tuple[str, ...] = ("qdq_proxy",),
    distributions: tuple[str, ...] = _ONLINE_STRATEGY_STUDY_DEFAULT_DISTRIBUTIONS,
    batch: int = 1,
    heads: int = 8,
    device: str | torch.device = "cuda",
    seed: int = 0,
    q_distribution: str | None = None,
    k_distribution: str | None = None,
    v_distribution: str | None = None,
    warmup: int = 1,
    iters: int = 3,
    timeout_ms: float | None = 20_000.0,
    sa3_payload_target_max_values: tuple[float, ...] = _ONLINE_STRATEGY_STUDY_SA3_PAYLOAD_TARGETS,
    sa3_recon_scale_base_values: tuple[float, ...] = _ONLINE_STRATEGY_STUDY_SA3_RECON_BASES,
    localcta_global_scale_num_values: tuple[float, ...] = _ONLINE_STRATEGY_STUDY_LOCALCTA_GLOBAL_SCALE_NUMS,
    fixed_nvfp4_scale_num_values: tuple[float, ...] = _ONLINE_STRATEGY_STUDY_FIXED_NVFP4_SCALE_NUMS,
) -> dict[str, Any]:
    study = benchmark_online_probability_quantization_study(
        seqlens=seqlens,
        input_mode=input_mode,
        p_modes=p_modes,
        pv_backends=pv_backends,
        pv_execution_modes=pv_execution_modes,
        distributions=distributions,
        batch=batch,
        heads=heads,
        device=device,
        seed=seed,
        q_distribution=q_distribution,
        k_distribution=k_distribution,
        v_distribution=v_distribution,
        warmup=warmup,
        iters=iters,
        timeout_ms=timeout_ms,
        sa3_payload_target_max_values=sa3_payload_target_max_values,
        sa3_recon_scale_base_values=sa3_recon_scale_base_values,
        localcta_global_scale_num_values=localcta_global_scale_num_values,
        fixed_nvfp4_scale_num_values=fixed_nvfp4_scale_num_values,
    )
    summary = _summarize_online_probability_quantization_rows(study["rows"])
    timestamp = time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())
    resolved_output_dir = Path(output_dir) if output_dir is not None else (_ROOT / "results" / f"online_probability_quantization_{timestamp}")
    resolved_output_dir.mkdir(parents=True, exist_ok=True)
    rows_path = resolved_output_dir / "rows.jsonl"
    summary_path = resolved_output_dir / "summary.json"
    readme_path = resolved_output_dir / "README.md"
    with rows_path.open("w", encoding="utf-8") as f:
        for row in study["rows"]:
            f.write(json.dumps(row) + "\n")
    with summary_path.open("w", encoding="utf-8") as f:
        json.dump({"metadata": study["metadata"], **summary}, f, indent=2)

    lines = [
        "# Online probability quantization study",
        "",
        f"- Device: `{study['metadata']['device']}`",
        f"- Seqlens: `{study['metadata']['seqlens']}`",
        f"- Heads: `{study['metadata']['heads']}`",
        f"- Execution modes: `{study['metadata']['pv_execution_modes']}`",
        f"- Backends: `{study['metadata']['pv_backends']}`",
        f"- Distributions: `{study['metadata']['distributions']}`",
        "",
        "## Canonical winner counts",
        "",
    ]
    for label, count in sorted(summary["aggregate"]["canonical_winner_counts"].items()):
        lines.append(f"- `{label}`: `{count}`")
    lines.extend(["", "## Case winners", ""])
    for case in summary["case_summaries"]:
        if case["winner"] is None:
            lines.append(f"- `S={case['seqlen']}` `{case['distribution']}` `{case['pv_execution_mode']}`: no valid winner")
        else:
            lines.append(
                f"- `S={case['seqlen']}` `{case['distribution']}` `{case['pv_execution_mode']}`: "
                f"`{case['winner']['p_mode']}/{case['winner']['pv_backend']}` "
                f"norm-MAE `{case['winner']['normalized_mean_abs_diff_vs_bf16']:.9f}` "
                f"P-mode `{case['winner']['p_quant_mode']}` V-mode `{case['winner']['v_quant_mode']}`"
            )
    readme_path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return {
        "output_dir": str(resolved_output_dir),
        "rows_path": str(rows_path),
        "summary_path": str(summary_path),
        "readme_path": str(readme_path),
        "metadata": study["metadata"],
        **summary,
    }


